        public void SetUndoRedoStacks(List<PresentationRoot> undo, List<PresentationRoot> redo)
        {
            _undoStack.Clear();
            if (undo != null) _undoStack.AddRange(undo);
            _redoStack.Clear();
            if (redo != null) _redoStack.AddRange(redo);
        }

