        public int GetEffectiveNotesPaneHeight()
        {
            if (ViewMode == ImpressViewMode.Normal && !IsPresenting && IsNotesPaneOpen)
            {
                return Math.Max(40, Math.Min(260, NotesPaneHeight));
            }
            return 0;
        }

