        public void ToggleFormatBackgroundPane()
        {
            if (SidebarPanel == SidebarPanelType.FormatBackground && IsSidebarOpen)
            {
                IsSidebarOpen = false;
            }
            else
            {
                SidebarPanel = SidebarPanelType.FormatBackground;
                IsSidebarOpen = true;
            }
        }

        // =========================================================================
        // POWERPOINT 365 DESIGNER (Ý TƯỞNG THIẾT KẾ) & ZOOM (THU PHÓNG)
        // =========================================================================
        public void ToggleDesignerPane()
        {
            if (SidebarPanel == SidebarPanelType.Designer && IsSidebarOpen)
            {
                IsSidebarOpen = false;
            }
            else
            {
                SidebarPanel = SidebarPanelType.Designer;
                IsSidebarOpen = true;
                SidebarScrollY = 0;
                _cachedDesignerIdeas = null;
            }
            if (InvalidateCallback != null) InvalidateCallback();
        }

        private List<SlideDesignIdea> _cachedDesignerIdeas = null;
        private string _cachedDesignerSlideId = null;
        private int _hoveredDesignerIdeaIndex = -1;

        public List<SlideDesignIdea> GetDesignIdeasForCurrentSlide()
        {
            if (ActiveSlide == null) return new List<SlideDesignIdea>();
            if (_cachedDesignerIdeas != null && _cachedDesignerSlideId == ActiveSlide.Id)
            {
                return _cachedDesignerIdeas;
            }

            float cw = (Presentation != null && Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation != null && Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;
            _cachedDesignerIdeas = SlideDesignerEngine.GenerateIdeas(ActiveSlide, cw, ch);
            _cachedDesignerSlideId = ActiveSlide.Id;
            return _cachedDesignerIdeas;
        }

        public void ApplyDesignIdea(int index)
        {
            if (ActiveSlide == null) return;
            var ideas = GetDesignIdeasForCurrentSlide();
            if (index < 0 || index >= ideas.Count) return;

            SaveUndoState();
            float cw = (Presentation != null && Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation != null && Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;

            ideas[index].Apply?.Invoke(ActiveSlide, cw, ch);
            ActiveSlide.IsThumbnailDirty = true;
            SelectedShapeIndex = -1;
            SelectedShapeIndices.Clear();
            _cachedDesignerIdeas = null;
            if (InvalidateCallback != null) InvalidateCallback();
        }

        public ShapeNode InsertSlideZoom(int targetSlideIndex = -1)
        {
            if (ActiveSlide == null || Presentation == null || Presentation.Slides.Count == 0) return null;
            SaveUndoState();

            if (targetSlideIndex < 0)
            {
                targetSlideIndex = (ActiveSlideIndex + 1 < Presentation.Slides.Count) ? (ActiveSlideIndex + 1) : 0;
            }

            float cw = (Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;

            float zoomW = cw * 0.32f;
            float zoomH = zoomW * (ch / cw);
            float zoomX = (cw - zoomW) / 2f;
            float zoomY = (ch - zoomH) / 2f;

            var zoomShape = new ShapeNode
            {
                Id = Guid.NewGuid().ToString(),
                Name = $"Slide Zoom - Slide {targetSlideIndex + 1}",
                Type = ShapeType.SlideZoom,
                ZoomTargetSlideIndex = targetSlideIndex,
                ZoomReturnToSlide = true,
                ZoomShowBorder = true,
                HasShadow = true,
                ShadowColor = 0x94A3B8,
                ShadowOffsetY = 6f,
                ShadowBlur = 12f,
                Transform = new Transform2D
                {
                    X = zoomX,
                    Y = zoomY,
                    Width = zoomW,
                    Height = zoomH
                }
            };

            ActiveSlide.Shapes.Add(zoomShape);
            SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;
            SelectedShapeIndices.Clear();
            SelectedShapeIndices.Add(SelectedShapeIndex);
            ActiveSlide.IsThumbnailDirty = true;
            if (InvalidateCallback != null) InvalidateCallback();
            return zoomShape;
        }

        public ShapeNode InsertSectionZoom(int targetSectionSlideIndex = -1)
        {
            if (ActiveSlide == null || Presentation == null || Presentation.Slides.Count == 0) return null;
            SaveUndoState();

            if (targetSectionSlideIndex < 0)
            {
                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    if (Presentation.Slides[i].IsSectionHeader)
                    {
                        targetSectionSlideIndex = i;
                        break;
                    }
                }
                if (targetSectionSlideIndex < 0) targetSectionSlideIndex = 0;
            }

            float cw = (Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;

            float zoomW = cw * 0.35f;
            float zoomH = zoomW * (ch / cw);
            float zoomX = (cw - zoomW) / 2f;
            float zoomY = (ch - zoomH) / 2f;

            string secTitle = !string.IsNullOrEmpty(Presentation.Slides[targetSectionSlideIndex].SectionName)
                ? Presentation.Slides[targetSectionSlideIndex].SectionName
                : $"Phân phần {targetSectionSlideIndex + 1}";

            var zoomShape = new ShapeNode
            {
                Id = Guid.NewGuid().ToString(),
                Name = $"Section Zoom - {secTitle}",
                Type = ShapeType.SectionZoom,
                ZoomTargetSlideIndex = targetSectionSlideIndex,
                ZoomReturnToSlide = true,
                ZoomShowBorder = true,
                HasShadow = true,
                ShadowColor = 0x94A3B8,
                ShadowOffsetY = 6f,
                ShadowBlur = 12f,
                Transform = new Transform2D
                {
                    X = zoomX,
                    Y = zoomY,
                    Width = zoomW,
                    Height = zoomH
                }
            };

            ActiveSlide.Shapes.Add(zoomShape);
            SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;
            SelectedShapeIndices.Clear();
            SelectedShapeIndices.Add(SelectedShapeIndex);
            ActiveSlide.IsThumbnailDirty = true;
            if (InvalidateCallback != null) InvalidateCallback();
            return zoomShape;
        }

        public SlideNode InsertSummaryZoom()
        {
            if (Presentation == null) return null;
            SaveUndoState();

            SlideNode summarySlide = new SlideNode
            {
                Id = Guid.NewGuid().ToString(),
                Title = "Mục Lục Tóm Tắt (Summary Zoom)",
                BgColor = 0xF8FAFC,
                IsGradientBg = false
            };

            float cw = (Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;

            summarySlide.Shapes.Add(new ShapeNode
            {
                Id = Guid.NewGuid().ToString(),
                Name = "Summary_Title",
                Type = ShapeType.TextBox,
                PlaceholderType = "Title",
                Text = "MỤC LỤC TRÌNH CHIẾU TÓM TẮT",
                FontName = "Segoe UI",
                FontSize = 38f,
                Bold = true,
                TextColor = 0x0F172A,
                Transform = new Transform2D { X = 80, Y = 60, Width = cw - 160, Height = 65 },
                Alignment = TextAlignment.Center
            });

            summarySlide.Shapes.Add(new ShapeNode
            {
                Id = Guid.NewGuid().ToString(),
                Name = "Summary_Subtitle",
                Type = ShapeType.TextBox,
                PlaceholderType = "Subtitle",
                Text = "Nhấp vào bất kỳ trang chiếu nào để phóng to và trình bày chi tiết",
                FontName = "Segoe UI",
                FontSize = 18f,
                TextColor = 0x64748B,
                Transform = new Transform2D { X = 80, Y = 130, Width = cw - 160, Height = 40 },
                Alignment = TextAlignment.Center
            });

            int totalSlides = Presentation.Slides.Count;
            int cols = totalSlides <= 4 ? totalSlides : (totalSlides <= 6 ? 3 : 4);
            cols = Math.Max(1, Math.Min(4, cols));

            float startY = 220f;
            float availW = cw - 160;
            float gapX = 36f;
            float gapY = 36f;

            float cardW = (availW - (cols - 1) * gapX) / cols;
            float cardH = cardW * (ch / cw);

            for (int i = 0; i < totalSlides; i++)
            {
                int r = i / cols;
                int c = i % cols;
                float zx = 80 + c * (cardW + gapX);
                float zy = startY + r * (cardH + gapY);

                var zShape = new ShapeNode
                {
                    Id = Guid.NewGuid().ToString(),
                    Name = $"SummaryZoom_Item_{i + 1}",
                    Type = ShapeType.SlideZoom,
                    ZoomTargetSlideIndex = i,
                    ZoomReturnToSlide = true,
                    ZoomShowBorder = true,
                    HasShadow = true,
                    ShadowColor = 0xCBD5E1,
                    ShadowOffsetY = 4f,
                    ShadowBlur = 8f,
                    Transform = new Transform2D
                    {
                        X = zx,
                        Y = zy,
                        Width = cardW,
                        Height = cardH
                    }
                };
                summarySlide.Shapes.Add(zShape);
            }

            int insertIdx = ActiveSlideIndex >= 0 ? ActiveSlideIndex + 1 : 0;
            Presentation.Slides.Insert(insertIdx, summarySlide);
            ActiveSlideIndex = insertIdx;
            summarySlide.IsThumbnailDirty = true;
            if (InvalidateCallback != null) InvalidateCallback();
            return summarySlide;
        }

        public int ZoomReturnSlideIndex { get; set; } = -1;
        public bool ZoomReturnEnabled { get; set; } = false;

        public void TriggerZoomNavigation(int targetIndex, bool returnToSlide)
        {
            if (Presentation == null || targetIndex < 0 || targetIndex >= Presentation.Slides.Count) return;
            ZoomReturnSlideIndex = ActiveSlideIndex;
            ZoomReturnEnabled = returnToSlide;

            int prev = ActiveSlideIndex;
            ActiveSlideIndex = targetIndex;
            TriggerTransition(prev, ActiveSlideIndex, false);
            if (InvalidateCallback != null) InvalidateCallback();
        }

        public void ApplyThemeVariant(int variantIdx)
        {
            SelectedVariantIndex = variantIdx;
            int[] variantColors = new int[] { 0xD24726, 0x0D9488, 0x2563EB, 0x9333EA };
            if (variantIdx >= 0 && variantIdx < variantColors.Length)
            {
                Presentation.ThemePrimaryColor = variantColors[variantIdx];
                if (ActiveSlide != null)
                {
                    foreach (ShapeNode shape in ActiveSlide.Shapes)
                    {
                        if (shape.PlaceholderType == "Title" || shape.StrokeWidth > 1.0f)
                        {
                            shape.TextColor = variantColors[variantIdx];
                            shape.StrokeColor = variantColors[variantIdx];
                        }
                    }
                }
            }
        }

        public void SetSlideSize(bool widescreen)
        {
            if (Presentation != null)
            {
                Presentation.SetSlideSize(widescreen);
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
            }
        }

        public void SetCustomSlideSize(float width, float height)
        {
            if (Presentation != null && width > 50f && height > 50f)
            {
                SaveUndoState();
                Presentation.SetCustomSlideSize(width, height);
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
            }
        }

        public ShapeNode InsertImageBitmap(Image image, string name = null)
        {
            if (ActiveSlide == null || Presentation == null || image == null) return null;
            SaveUndoState();

            float cw = (Presentation.CanvasWidth > 0) ? Presentation.CanvasWidth : 1920f;
            float ch = (Presentation.CanvasHeight > 0) ? Presentation.CanvasHeight : 1080f;

            float origW = image.Width;
            float origH = image.Height;

            float maxW = cw * 0.65f;
            float maxH = ch * 0.65f;

            float fitW = origW;
            float fitH = origH;
            if (fitW > maxW || fitH > maxH)
            {
                float ratio = Math.Min(maxW / fitW, maxH / fitH);
                fitW *= ratio;
                fitH *= ratio;
            }

            float posX = (cw - fitW) / 2f;
            float posY = (ch - fitH) / 2f;

            string imgName = !string.IsNullOrEmpty(name) ? name : ("Hình ảnh " + (ActiveSlide.Shapes.Count + 1));

            var shape = new ShapeNode
            {
                Id = Guid.NewGuid().ToString(),
                Name = imgName,
                Type = ShapeType.Image,
                CachedImage = new Bitmap(image),
                Transform = new Transform2D(posX, posY, fitW, fitH),
                OriginalWidth = origW,
                OriginalHeight = origH,
                IsVisible = true
            };

            ActiveSlide.Shapes.Add(shape);
            SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;
            SelectedShapeIndices.Clear();
            SelectedShapeIndices.Add(SelectedShapeIndex);
            ActiveSlide.IsThumbnailDirty = true;
            if (InvalidateCallback != null) InvalidateCallback();
            return shape;
        }

        public void TakeScreenshot(IWin32Window owner = null)
        {
            using (var snip = new ScreenSnippingForm())
            {
                if (snip.ShowDialog(owner) == DialogResult.OK && snip.CapturedBitmap != null)
                {
                    InsertImageBitmap(snip.CapturedBitmap, "Screenshot_" + DateTime.Now.ToString("yyyyMMdd_HHmmss"));
                }
            }
        }

        public void ExportToVideo(string targetPath = null, IWin32Window owner = null)
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0)
            {
                MessageBox.Show("Không có trang chiếu nào để xuất video!", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            if (string.IsNullOrEmpty(targetPath))
            {
                using (SaveFileDialog sfd = new SaveFileDialog())
                {
                    sfd.Title = "Xuất bài trình chiếu sang Video (Export to Video)";
                    sfd.Filter = "Video File (*.avi)|*.avi|All Files (*.*)|*.*";
                    sfd.FileName = System.IO.Path.GetFileNameWithoutExtension(Presentation.Title ?? "Presentation") + ".avi";
                    if (sfd.ShowDialog(owner) != DialogResult.OK) return;
                    targetPath = sfd.FileName;
                }
            }

            using (var recForm = new RecordSlideShowForm(this, 0))
            {
                recForm.ExportVideoDirect(targetPath, true);
            }
        }

        public Bitmap RenderSlideToBitmap(SlideNode slide, int targetW = 0, int targetH = 0)
        {
            if (slide == null || Presentation == null) return null;
            int canvasW = (int)Presentation.CanvasWidth;
            int canvasH = (int)Presentation.CanvasHeight;
            if (canvasW <= 0) canvasW = 1920;
            if (canvasH <= 0) canvasH = 1080;

            if (targetW <= 0 || targetH <= 0)
            {
                targetW = canvasW;
                targetH = canvasH;
            }

            Bitmap bmp = new Bitmap(targetW, targetH, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;

                using (D2DGraphics d2d = new D2DGraphics(g, targetW, targetH))
                {
                    RectangleF targetRect = new RectangleF(0, 0, targetW, targetH);
                    float scale = (float)targetW / canvasW;
                    DrawSlideFull(d2d, targetRect, slide, scale);
                }
            }
            return bmp;
        }

        public bool ExportToPdf(string filePath)
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0)
                return false;

            try
            {
                var pdfDoc = new ZenQOffice.Core.PdfDocument(System.IO.Path.GetFileName(filePath));
                pdfDoc.Pages.Clear();

                int canvasW = (int)Presentation.CanvasWidth;
                int canvasH = (int)Presentation.CanvasHeight;
                if (canvasW <= 0) canvasW = 1920;
                if (canvasH <= 0) canvasH = 1080;

                // Standard PDF landscape page: 841.89 x 595.28 (A4 Landscape) or proportional ratio
                float pdfW = 841.89f;
                float pdfH = pdfW * ((float)canvasH / canvasW);

                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    var slide = Presentation.Slides[i];
                    Bitmap slideBmp = RenderSlideToBitmap(slide, canvasW, canvasH);
                    if (slideBmp != null)
                    {
                        var page = new ZenQOffice.Core.PdfPageModel(i + 1, pdfW, pdfH);
                        page.ImageElements.Add(new ZenQOffice.Core.PdfImageElement(slideBmp, new RectangleF(0, 0, pdfW, pdfH)));
                        pdfDoc.Pages.Add(page);
                    }
                }

                return ZenQOffice.Format.PdfHandler.SavePdf(pdfDoc, filePath);
            }
            catch (Exception ex)
            {
                Console.WriteLine("SlidesView.ExportToPdf error: " + ex.Message);
                return false;
            }
        }

        public bool ExportToImages(string targetPath, bool allSlides = true, bool isJpeg = false)
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0)
                return false;

            try
            {
                int canvasW = (int)Presentation.CanvasWidth;
                int canvasH = (int)Presentation.CanvasHeight;
                if (canvasW <= 0) canvasW = 1920;
                if (canvasH <= 0) canvasH = 1080;

                var imgFormat = isJpeg ? System.Drawing.Imaging.ImageFormat.Jpeg : System.Drawing.Imaging.ImageFormat.Png;

                if (!allSlides)
                {
                    var slide = ActiveSlide ?? Presentation.Slides[0];
                    using (Bitmap bmp = RenderSlideToBitmap(slide, canvasW, canvasH))
                    {
                        if (bmp != null) bmp.Save(targetPath, imgFormat);
                    }
                    return true;
                }
                else
                {
                    string folder = System.IO.Path.GetDirectoryName(targetPath);
                    string baseName = System.IO.Path.GetFileNameWithoutExtension(targetPath);
                    string ext = isJpeg ? ".jpg" : ".png";

                    for (int i = 0; i < Presentation.Slides.Count; i++)
                    {
                        var slide = Presentation.Slides[i];
                        string slidePath = System.IO.Path.Combine(folder, $"{baseName}_Slide_{i + 1}{ext}");
                        using (Bitmap bmp = RenderSlideToBitmap(slide, canvasW, canvasH))
                        {
                            if (bmp != null) bmp.Save(slidePath, imgFormat);
                        }
                    }
                    return true;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("SlidesView.ExportToImages error: " + ex.Message);
                return false;
            }
        }
        #endregion

        #region Transition & Morph Engine
        public void SetTransition(TransitionType transType)
        {
            SlideNode slide = ActiveSlide;
            if (slide != null)
            {
                slide.Transition = transType;
                if (transType == TransitionType.GenOffice_SmoothFlow)
                {
                    slide.TransitionDuration = 2.20f; // Mặc định 2.20s chuẩn xác cho hiệu ứng Chảy tràn
                }
                else if (transType == TransitionType.Morph && slide.TransitionDuration <= 1.0f)
                {
                    slide.TransitionDuration = 2.0f;
                }
            }
        }

        public void SetTransitionDuration(float duration)
        {
            SlideNode slide = ActiveSlide;
            if (slide != null)
            {
                slide.TransitionDuration = Math.Max(0.1f, Math.Min(10.0f, duration));
            }
        }

        public void SetTransitionDirection(TransitionDirection direction)
        {
            SlideNode slide = ActiveSlide;
            if (slide != null)
            {
                slide.TransitionDirection = direction;
            }
        }

        public void SetMorphMode(MorphType mode)
        {
            SlideNode slide = ActiveSlide;
            if (slide != null)
            {
                slide.MorphMode = mode;
                slide.Transition = TransitionType.Morph;
            }
        }

        public void ApplyTransitionToAll()
        {
            SlideNode active = ActiveSlide;
            if (active == null || Presentation == null) return;
            foreach (SlideNode s in Presentation.Slides)
            {
                s.Transition = active.Transition;
                s.TransitionDuration = active.TransitionDuration;
                s.TransitionDirection = active.TransitionDirection;
                s.MorphMode = active.MorphMode;
                s.AdvanceOnClick = active.AdvanceOnClick;
                s.AutoAdvance = active.AutoAdvance;
                s.AutoAdvanceSeconds = active.AutoAdvanceSeconds;
            }
        }

        private System.Diagnostics.Stopwatch _transitionStopwatch = new System.Diagnostics.Stopwatch();
        private System.Diagnostics.Stopwatch _animStopwatch = new System.Diagnostics.Stopwatch();
        private Dictionary<ShapeNode, Bitmap> _morphShapeTextureCache = new Dictionary<ShapeNode, Bitmap>();

        // Cached morph pair lists - rebuilt only when fromSlide/toSlide change, not every frame
        private List<KeyValuePair<ShapeNode, ShapeNode>> _cachedMorphPairs = null;
        private HashSet<ShapeNode> _cachedMorphFromUnpaired = null;
        private HashSet<ShapeNode> _cachedMorphToUnpaired = null;
        private int _cachedMorphFromIdx = -1;
        private int _cachedMorphToIdx = -1;

        // Slide Transition Fast Texture Cache (Eliminates CPU 4K image re-draw lag on every transition frame)
        private bool _isBuildingTransitionCache = false;
        private Bitmap _cachedTransBmpA = null;
        private Bitmap _cachedTransBmpB = null;
        private int _cachedTransFromIdx = -1;
        private int _cachedTransToIdx = -1;
        private Size _cachedTransSize = Size.Empty;
        private Bitmap _elementsDrawerBmp = null;

        public void ClearTransitionCache()
        {
            if (_cachedTransBmpA != null)
            {
                try { D2DGraphics.InvalidateBitmapCache(_cachedTransBmpA); } catch { }
                try { _cachedTransBmpA.Dispose(); } catch { }
                _cachedTransBmpA = null;
            }
            if (_cachedTransBmpB != null)
            {
                try { D2DGraphics.InvalidateBitmapCache(_cachedTransBmpB); } catch { }
                try { _cachedTransBmpB.Dispose(); } catch { }
                _cachedTransBmpB = null;
            }
            _cachedTransFromIdx = -1;
            _cachedTransToIdx = -1;
            _cachedTransSize = Size.Empty;
        }

        private void EnsureTransitionCache(Rectangle rect, SlideNode fromSlide, SlideNode toSlide, float scale)
        {
            if (rect.Width <= 0 || rect.Height <= 0) return;
            if (_cachedTransBmpA != null && _cachedTransBmpB != null &&
                _cachedTransFromIdx == TransitionFromSlideIndex &&
                _cachedTransToIdx == TransitionToSlideIndex &&
                _cachedTransSize == rect.Size)
            {
                return;
            }

            ClearTransitionCache();
            _cachedTransSize = rect.Size;
            _cachedTransFromIdx = TransitionFromSlideIndex;
            _cachedTransToIdx = TransitionToSlideIndex;

            try
            {
                _isBuildingTransitionCache = true;

                // 1. Bake fromSlide
                _cachedTransBmpA = new Bitmap(rect.Width, rect.Height, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
                using (Graphics gA = Graphics.FromImage(_cachedTransBmpA))
                using (D2DGraphics d2dA = new D2DGraphics(gA, rect.Width, rect.Height))
                {
                    Rectangle originRect = new Rectangle(0, 0, rect.Width, rect.Height);
                    DrawSlideFull(d2dA, originRect, fromSlide, scale, 1.0f, true);
                }

                // 2. Bake toSlide
                _cachedTransBmpB = new Bitmap(rect.Width, rect.Height, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
                using (Graphics gB = Graphics.FromImage(_cachedTransBmpB))
                using (D2DGraphics d2dB = new D2DGraphics(gB, rect.Width, rect.Height))
                {
                    Rectangle originRect = new Rectangle(0, 0, rect.Width, rect.Height);
                    DrawSlideFull(d2dB, originRect, toSlide, scale, 1.0f, false);
                }
                if (IsTransitioning)
                {
                    _transitionStopwatch.Restart();
                    TransitionProgress = 0.0f;
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[Transition Cache Error] {ex.Message}");
                ClearTransitionCache();
            }
            finally
            {
                _isBuildingTransitionCache = false;
            }
        }

        private static void DrawCachedSlideBitmap(D2DGraphics g, RectangleF targetRect, Bitmap bmp, float opacity)
        {
            if (bmp == null || opacity <= 0.005f || targetRect.Width <= 0 || targetRect.Height <= 0) return;

            int ix = (int)Math.Round(targetRect.X);
            int iy = (int)Math.Round(targetRect.Y);
            int iw = (int)Math.Round(targetRect.Width);
            int ih = (int)Math.Round(targetRect.Height);

            bool isIntegerPos = Math.Abs(targetRect.X - ix) < 0.05f && Math.Abs(targetRect.Y - iy) < 0.05f;

            // 1:1 pixel-exact BitBlt khi kích thước tương đương và tọa độ nguyên: triệt tiêu hoàn toàn mờ bicubic và giật subpixel
            if (isIntegerPos && Math.Abs(iw - bmp.Width) <= 1 && Math.Abs(ih - bmp.Height) <= 1)
            {
                InterpolationMode prevInterp = g.InterpolationMode;
                PixelOffsetMode prevOffset = g.PixelOffsetMode;
                g.InterpolationMode = InterpolationMode.NearestNeighbor;
                // Giữ nguyên g.PixelOffsetMode (PixelOffsetMode.Half) - tuyệt đối không gán PixelOffsetMode.None
                // vì sẽ làm lệch tọa độ -0.5px so với khi kết thúc chuyển cảnh dẫn đến giật hình!

                if (opacity >= 0.995f)
                {
                    g.DrawImage(bmp, new Rectangle(ix, iy, bmp.Width, bmp.Height), 0, 0, bmp.Width, bmp.Height, GraphicsUnit.Pixel);
                }
                else
                {
                    using (System.Drawing.Imaging.ImageAttributes ia = new System.Drawing.Imaging.ImageAttributes())
                    {
                        System.Drawing.Imaging.ColorMatrix cm = new System.Drawing.Imaging.ColorMatrix
                        {
                            Matrix33 = Math.Max(0f, Math.Min(1.0f, opacity))
                        };
                        ia.SetColorMatrix(cm, System.Drawing.Imaging.ColorMatrixFlag.Default, System.Drawing.Imaging.ColorAdjustType.Bitmap);
                        g.DrawImage(bmp, new Rectangle(ix, iy, bmp.Width, bmp.Height), 0, 0, bmp.Width, bmp.Height, GraphicsUnit.Pixel, ia, opacity);
                    }
                }

                g.InterpolationMode = prevInterp;
                g.PixelOffsetMode = prevOffset;
                return;
            }

            if (opacity >= 0.995f)
            {
                g.DrawImage(bmp, targetRect.X, targetRect.Y, targetRect.Width, targetRect.Height);
                return;
            }

            using (System.Drawing.Imaging.ImageAttributes ia = new System.Drawing.Imaging.ImageAttributes())
            {
                System.Drawing.Imaging.ColorMatrix cm = new System.Drawing.Imaging.ColorMatrix
                {
                    Matrix33 = Math.Max(0f, Math.Min(1.0f, opacity))
                };
                ia.SetColorMatrix(cm, System.Drawing.Imaging.ColorMatrixFlag.Default, System.Drawing.Imaging.ColorAdjustType.Bitmap);
                PointF[] destPoints = new PointF[] {
                    new PointF(targetRect.X, targetRect.Y),
                    new PointF(targetRect.Right, targetRect.Y),
                    new PointF(targetRect.X, targetRect.Bottom)
                };
                g.DrawImage(bmp, destPoints, new RectangleF(0, 0, bmp.Width, bmp.Height), GraphicsUnit.Pixel, ia, opacity);
            }
        }

        public void ClearMorphTextureCache()
        {
            ClearTransitionCache();
            foreach (KeyValuePair<ShapeNode, Bitmap> kvp in _morphShapeTextureCache)
            {
                try
                {
                    if (kvp.Value != null)
                    {
                        kvp.Value.Dispose();
                    }
                }
                catch { }
            }
            _morphShapeTextureCache.Clear();
            // Also invalidate cached pair lists so they are rebuilt for the next transition
            _cachedMorphPairs = null;
            _cachedMorphFromUnpaired = null;
            _cachedMorphToUnpaired = null;
            _cachedMorphFromIdx = -1;
            _cachedMorphToIdx = -1;
        }

        public void TriggerTransition(int fromIdx, int toIdx, bool isPreview = false)
        {
            if (Presentation == null || Presentation.Slides.Count == 0) return;
            // Khi chưa trình chiếu và không chủ động xem trước (Preview): không chạy hiệu ứng để tránh lag
            if (!IsPresenting && !isPreview) return;
            ClearMorphTextureCache();
            TransitionFromSlideIndex = fromIdx;
            TransitionToSlideIndex = Math.Max(0, Math.Min(Presentation.Slides.Count - 1, toIdx));

            SlideNode toSlide = Presentation.Slides[TransitionToSlideIndex];

            // Xử lý âm thanh khi chuyển slide (Audio playback across slides & auto-start)
            if (SlideAudioPlayerManager.Instance.IsPlaying)
            {
                var activeAudio = SlideAudioPlayerManager.Instance.ActiveShape;
                if (activeAudio != null && !activeAudio.AudioPlayAcrossSlides)
                {
                    SlideAudioPlayerManager.Instance.Pause();
                }
            }

            if (toSlide != null && toSlide.Shapes != null && IsPresenting)
            {
                for (int i = 0; i < toSlide.Shapes.Count; i++)
                {
                    var sh = toSlide.Shapes[i];
                    if (sh == null) continue;
                    if (sh.Type == ShapeType.Video || !string.IsNullOrEmpty(sh.VideoPath))
                    {
                        if (sh.VideoStartMode == VideoStartMode.Automatically && !sh.IsVideoPlaying)
                        {
                            Control parent = (Application.OpenForms.Count > 0) ? Application.OpenForms[0] : null;
                            PlayVideoPreview(sh, parent);
                            _playedMediaShapesInPresentation.Add(sh);
                            break;
                        }
                    }
                    else if (sh.Type == ShapeType.Audio || !string.IsNullOrEmpty(sh.AudioPath))
                    {
                        if (sh.AudioStartMode == VideoStartMode.Automatically && !sh.IsAudioPlaying)
                        {
                            Control parent = (Application.OpenForms.Count > 0) ? Application.OpenForms[0] : null;
                            SlideAudioPlayerManager.Instance.Play(sh, parent);
                            _playedMediaShapesInPresentation.Add(sh);
                            break;
                        }
                    }
                }
            }

            if (toSlide != null && toSlide.Transition != TransitionType.None)
            {
                IsTransitioning = true;
                IsPreviewingTransition = isPreview;
                TransitionProgress = 0.0f;
                _transitionStopwatch.Restart();
            }
            else
            {
                IsTransitioning = false;
                IsPreviewingTransition = false;
                TransitionProgress = 1.0f;
            }
        }

        public void PlayTransitionPreview()
        {
            if (Presentation == null || Presentation.Slides.Count == 0) return;
            SelectedShapeIndex = -1;
            EndInlineEditing();
            int fromIdx = (ActiveSlideIndex > 0) ? (ActiveSlideIndex - 1) : -1;
            TriggerTransition(fromIdx, ActiveSlideIndex, true);
        }
        #endregion

        #region Animations Engine
        public void AddShapeAnimation(AnimationType animType)
        {
            ApplyOrAddShapeAnimation(animType, false);
        }

        public void AddNewAdditionalShapeAnimation(AnimationType animType)
        {
            ApplyOrAddShapeAnimation(animType, true);
        }

        public void StartFreehandMotionPathDrawing(ShapeNode shape)
        {
            if (shape == null && SelectedShape != null) shape = SelectedShape;
            if (shape == null)
            {
                MessageBox.Show("Vui lòng chọn đối tượng trước khi vẽ đường chuyển động.", "ZenQ Slides", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            IsDrawingMotionPathMode = true;
            IsDrawingMotionPathActive = false;
            ActiveDrawingMotionShape = shape;
            CurrentDrawingMotionPoints.Clear();
            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
        }

        public void ApplyOrAddShapeAnimation(AnimationType animType, bool isAddAdditional)
        {
            SlideNode slide = ActiveSlide;
            if (slide == null) return;

            List<string> targetShapeIds = new List<string>();

            if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0)
            {
                foreach (int idx in SelectedShapeIndices)
                {
                    if (idx >= 0 && idx < slide.Shapes.Count)
                    {
                        targetShapeIds.Add(slide.Shapes[idx].Id);
                    }
                }
            }
            else if (SelectedShapeIndex >= 0 && SelectedShapeIndex < slide.Shapes.Count)
            {
                targetShapeIds.Add(slide.Shapes[SelectedShapeIndex].Id);
            }
            else if (SelectedShape != null)
            {
                targetShapeIds.Add(SelectedShape.Id);
            }

            if (targetShapeIds.Count == 0)
            {
                MessageBox.Show("Vui lòng chọn một hoặc nhiều hình vẽ / hộp văn bản trên trang chiếu để áp dụng hoạt họa.", "ZenQ Hoạt họa", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            // Xóa hiệu ứng nếu chọn None
            if (animType == AnimationType.None)
            {
                foreach (string shapeId in targetShapeIds)
                {
                    slide.Animations.RemoveAll(a => a.ShapeId == shapeId);
                }
                SelectedAnimationIndex = -1;
                return;
            }

            // Nếu người dùng chọn nhiều vật phẩm (bằng Ctrl+Click): vật phẩm đầu tiên kích hoạt OnClick, các vật phẩm tiếp theo chung tầng WithPrevious
            for (int k = 0; k < targetShapeIds.Count; k++)
            {
                string shapeId = targetShapeIds[k];

                // Nếu không phải là nút 'Thêm Hoạt Họa' (Add Animation) và hình này đã có hoạt họa trên slide -> Cập nhật/Thay thế hiệu ứng hiện có của hình (không tạo thêm hàng loạt không xác định)
                if (!isAddAdditional)
                {
                    bool replaced = false;
                    for (int aIdx = 0; aIdx < slide.Animations.Count; aIdx++)
                    {
                        if (slide.Animations[aIdx].ShapeId == shapeId)
                        {
                            slide.Animations[aIdx].Type = animType;
                            SelectedAnimationIndex = aIdx;
                            replaced = true;
                            break;
                        }
                    }
                    if (replaced) continue;
                }

                AnimationTrigger trigger = (k == 0) ? AnimationTrigger.OnClick : AnimationTrigger.WithPrevious;

                ShapeAnimation anim = new ShapeAnimation
                {
                    ShapeId = shapeId,
                    Type = animType,
                    Trigger = trigger,
                    Duration = 0.5f,
                    Delay = 0.0f,
                    OrderIndex = slide.Animations.Count
                };
                slide.Animations.Add(anim);
                SelectedAnimationIndex = slide.Animations.Count - 1;
            }

            // Lưu ý: Không tự động mở khung hoạt họa (Animation Pane), chỉ mở khi người dùng chủ động bấm nút mở
        }

        public void SetSelectedAnimationTrigger(AnimationTrigger trigger)
        {
            ShapeAnimation anim = SelectedAnimation;
            if (anim != null)
            {
                anim.Trigger = trigger;
            }
        }

        public void SetSelectedAnimationDirection(TransitionDirection direction)
        {
            ShapeAnimation anim = SelectedAnimation;
            if (anim != null)
            {
                anim.Direction = direction;
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
            }
        }

        public void SetSelectedAnimationDuration(float duration)
        {
            ShapeAnimation anim = SelectedAnimation;
            if (anim != null)
            {
                anim.Duration = Math.Max(0.1f, Math.Min(60.0f, duration));
            }
        }

        public void SetSelectedAnimationDelay(float delay)
        {
            ShapeAnimation anim = SelectedAnimation;
            if (anim != null)
            {
                anim.Delay = Math.Max(0.0f, Math.Min(60.0f, delay));
            }
        }

        public void MoveAnimationEarlier(int animIndex = -1)
        {
            SlideNode slide = ActiveSlide;
            if (slide == null || slide.Animations.Count <= 1) return;
            int idx = (animIndex >= 0) ? animIndex : SelectedAnimationIndex;
            if (idx > 0 && idx < slide.Animations.Count)
            {
                ShapeAnimation a = slide.Animations[idx];
                slide.Animations.RemoveAt(idx);
                slide.Animations.Insert(idx - 1, a);
                SelectedAnimationIndex = idx - 1;
            }
        }

        public void MoveAnimationLater(int animIndex = -1)
        {
            SlideNode slide = ActiveSlide;
            if (slide == null || slide.Animations.Count <= 1) return;
            int idx = (animIndex >= 0) ? animIndex : SelectedAnimationIndex;
            if (idx >= 0 && idx < slide.Animations.Count - 1)
            {
                ShapeAnimation a = slide.Animations[idx];
                slide.Animations.RemoveAt(idx);
                slide.Animations.Insert(idx + 1, a);
                SelectedAnimationIndex = idx + 1;
            }
        }

        public void RemoveAnimation(int animIndex = -1)
        {
            SlideNode slide = ActiveSlide;
            if (slide == null || slide.Animations.Count == 0) return;
            int idx = (animIndex >= 0) ? animIndex : SelectedAnimationIndex;
            if (idx >= 0 && idx < slide.Animations.Count)
            {
                slide.Animations.RemoveAt(idx);
                SelectedAnimationIndex = Math.Min(slide.Animations.Count - 1, idx);
            }
        }

        public void GetAnimationTimeline(SlideNode slide, out float[] startOffsets, out float[] durations, out int[] stepIndices)
        {
            if (slide == null || slide.Animations == null || slide.Animations.Count == 0)
            {
                startOffsets = new float[0];
                durations = new float[0];
                stepIndices = new int[0];
                return;
            }

            int n = slide.Animations.Count;
            startOffsets = new float[n];
            durations = new float[n];
            stepIndices = new int[n];

            int currentStep = 0;

            for (int i = 0; i < n; i++)
            {
                ShapeAnimation a = slide.Animations[i];
                float dur = (a.Duration > 0.05f) ? a.Duration : 0.5f;
                durations[i] = dur;

                if (a.Trigger == AnimationTrigger.OnClick || (i == 0 && a.Trigger != AnimationTrigger.WithPrevious && a.Trigger != AnimationTrigger.AfterPrevious))
                {
                    currentStep++;
                    stepIndices[i] = currentStep;
                    startOffsets[i] = a.Delay;
                }
                else if (a.Trigger == AnimationTrigger.WithPrevious)
                {
                    stepIndices[i] = Math.Max(1, currentStep);
                    float prevStart = (i > 0) ? startOffsets[i - 1] : 0f;
                    startOffsets[i] = prevStart + a.Delay;
                }
                else // AfterPrevious
                {
                    stepIndices[i] = Math.Max(1, currentStep);
                    float prevEnd = (i > 0) ? (startOffsets[i - 1] + durations[i - 1]) : 0f;
                    startOffsets[i] = prevEnd + a.Delay;
                }
            }
        }

        public int GetTotalAnimationSteps(SlideNode slide)
        {
            if (slide == null || slide.Animations == null || slide.Animations.Count == 0) return 0;
            float[] startOffsets, durations;
            int[] stepIndices;
            GetAnimationTimeline(slide, out startOffsets, out durations, out stepIndices);
            int maxStep = 0;
            for (int i = 0; i < stepIndices.Length; i++)
            {
                if (stepIndices[i] > maxStep) maxStep = stepIndices[i];
            }
            return maxStep;
        }

        public int GetAnimationStepIndex(SlideNode slide, int animIndex)
        {
            if (slide == null || slide.Animations == null || animIndex < 0 || animIndex >= slide.Animations.Count) return 0;
            float[] startOffsets, durations;
            int[] stepIndices;
            GetAnimationTimeline(slide, out startOffsets, out durations, out stepIndices);
            return (animIndex < stepIndices.Length) ? stepIndices[animIndex] : 0;
        }

        public float GetCurrentStepMaxDuration(SlideNode slide, int step)
        {
            if (slide == null || slide.Animations == null || slide.Animations.Count == 0 || step <= 0) return 0.5f;
            float[] startOffsets, durations;
            int[] stepIndices;
            GetAnimationTimeline(slide, out startOffsets, out durations, out stepIndices);

            float maxEndTime = 0.5f;
            for (int i = 0; i < stepIndices.Length; i++)
            {
                if (stepIndices[i] == step)
                {
                    float endTime = startOffsets[i] + durations[i];
                    if (endTime > maxEndTime) maxEndTime = endTime;
                }
            }
            return Math.Max(0.2f, maxEndTime);
        }

        public void PlayCurrentStepAnimation(int step)
        {
            IsPlayingSlideAnimation = true;
            AnimationProgress = 0.0f;
            _animStopwatch.Restart();
        }

        public void PlayAnimationPreview()
        {
            SlideNode slide = ActiveSlide;
            if (slide == null || slide.Animations.Count == 0) return;

            IsPlayingAnimationPreview = true;
            ActivePlayingAnimIndex = 0;
            AnimationProgress = 0.0f;
            _animStopwatch.Restart();
        }

        public void ToggleAnimationPane()
        {
            if (SidebarPanel == SidebarPanelType.AnimationPane && IsSidebarOpen)
            {
                IsSidebarOpen = false;
            }
            else
            {
                SidebarPanel = SidebarPanelType.AnimationPane;
                IsSidebarOpen = true;
            }
        }
        #endregion

        #region 60 FPS Update Loop (High Precision Stopwatch Delta-Time)
        public bool UpdateAnimationAndTransition()
        {
            // Cập nhật hoạt ảnh cuộn mượt phong cách MS Office 365
            bool scrollAnim = UpdateSmoothScroll();

            // Khi chưa trình chiếu và không ở chế độ xem trước (Preview) hay quét laser:
            // Tuyệt đối không chạy hiệu ứng để tránh gây lag giao diện khi chỉnh sửa/cuộn
            if (!IsPresenting && !IsPreviewingTransition && !IsPlayingAnimationPreview && !IsScanningActive)
            {
                bool hasPlayingVideo = false;
                if (ActiveSlide != null && ActiveSlide.Shapes != null)
                {
                    for (int i = 0; i < ActiveSlide.Shapes.Count; i++)
                    {
                        ShapeNode shape = ActiveSlide.Shapes[i];
                        if (shape != null && shape.Type == ShapeType.Video && shape.IsVideoPlaying)
                        {
                            shape.VideoCurrentTime += 0.016f;
                            if (shape.VideoCurrentTime >= shape.VideoTotalTime)
                            {
                                shape.VideoCurrentTime = shape.VideoTotalTime;
                                shape.IsVideoPlaying = false;
                            }
                            hasPlayingVideo = true;
                        }
                    }
                }
                return hasPlayingVideo || scrollAnim;
            }

            bool needRedraw = false;

            // 1. Update Slide Transition Progress (High Precision Stopwatch Timing)
            if (IsTransitioning)
            {
                SlideNode targetSlide = (TransitionToSlideIndex >= 0 && TransitionToSlideIndex < Presentation.Slides.Count)
                    ? Presentation.Slides[TransitionToSlideIndex] : ActiveSlide;
                float duration = 1.0f;
                if (targetSlide != null)
                {
                    if (targetSlide.Transition == TransitionType.GenOffice_SmoothFlow && targetSlide.TransitionDuration <= 1.0f)
                        duration = 2.20f;
                    else if (targetSlide.Transition == TransitionType.Morph && targetSlide.TransitionDuration <= 1.0f)
                        duration = 2.0f;
                    else if (targetSlide.TransitionDuration > 0.05f)
                        duration = targetSlide.TransitionDuration;
                }

                float elapsedSec = (float)_transitionStopwatch.Elapsed.TotalSeconds;
                float rawProgress = elapsedSec / duration;

                if (rawProgress >= 1.0f)
                {
                    if (TransitionProgress < 1.0f)
                    {
                        // Đảm bảo vẽ ít nhất 1 khung hình ở đúng tọa độ tĩnh 1.0f hoàn tất
                        TransitionProgress = 1.0f;
                        needRedraw = true;
                    }
                    else
                    {
                        // Đã vẽ xong khung 1.0f hoàn tất, giờ mới kết thúc chuyển cảnh sạch sẽ không bao giờ bị giật
                        IsTransitioning = false;
                        IsPreviewingTransition = false;
                        _transitionStopwatch.Stop();
                        ClearMorphTextureCache();
                        needRedraw = true;
                    }
                }
                else
                {
                    TransitionProgress = rawProgress;
                    needRedraw = true;
                }
            }

            // 2. Update Animation Preview or Slide Show Step Progress
            if ((IsPlayingAnimationPreview || (IsPresenting && IsPlayingSlideAnimation)) && ActiveSlide != null && ActiveSlide.Animations.Count > 0)
            {
                if (!_animStopwatch.IsRunning) _animStopwatch.Restart();

                float elapsedSec = (float)_animStopwatch.Elapsed.TotalSeconds;

                if (IsPlayingAnimationPreview)
                {
                    if (ActivePlayingAnimIndex >= 0 && ActivePlayingAnimIndex < ActiveSlide.Animations.Count)
                    {
                        ShapeAnimation currentAnim = ActiveSlide.Animations[ActivePlayingAnimIndex];
                        float duration = (currentAnim.Duration > 0.05f) ? currentAnim.Duration : 0.5f;
                        float p = elapsedSec / duration;

                        if (p >= 1.0f)
                        {
                            if (AnimationProgress < 1.0f)
                            {
                                AnimationProgress = 1.0f;
                                needRedraw = true;
                            }
                            else
                            {
                                AnimationProgress = 0.0f;
                                _animStopwatch.Restart();
                                ActivePlayingAnimIndex++;
                                if (ActivePlayingAnimIndex >= ActiveSlide.Animations.Count)
                                {
                                    IsPlayingAnimationPreview = false;
                                    ActivePlayingAnimIndex = -1;
                                    _animStopwatch.Stop();
                                }
                                needRedraw = true;
                            }
                        }
                        else
                        {
                            AnimationProgress = p;
                            needRedraw = true;
                        }
                    }
                    else
                    {
                        IsPlayingAnimationPreview = false;
                        ActivePlayingAnimIndex = -1;
                        _animStopwatch.Stop();
                    }
                }
                else if (IsPresenting && IsPlayingSlideAnimation)
                {
                    float duration = GetCurrentStepMaxDuration(ActiveSlide, CurrentAnimationStep);
                    float p = elapsedSec / duration;

                    if (p >= 1.0f)
                    {
                        if (AnimationProgress < 1.0f)
                        {
                            AnimationProgress = 1.0f;
                            needRedraw = true;
                        }
                        else
                        {
                            IsPlayingSlideAnimation = false;
                            _animStopwatch.Stop();
                            needRedraw = true;
                        }
                    }
                    else
                    {
                        AnimationProgress = p;
                        needRedraw = true;
                    }
                }
            }

            // 3. Update Background Removal AI Laser Scan Animation (Hiệu ứng quét sáng Laser đa lớp chuyên nghiệp)
            if (IsScanningActive)
            {
                ScanProgress += 0.024f; // Quét mượt mà liên tục ~42 frames (khoảng 0.7s)
                if (ScanProgress >= 1.0f)
                {
                    ScanProgress = 1.0f;
                    IsScanningActive = false;

                    // Quét xong là áp dụng kết quả xóa nền hoàn tất vào hình ảnh
                    if (ScanTargetShape != null && ScanPendingResultBitmap != null)
                    {
                        if (ScanTargetShape.CachedImage != null)
                        {
                            try { ScanTargetShape.CachedImage.Dispose(); } catch { }
                        }
                        ScanTargetShape.CachedImage = ScanPendingResultBitmap;
                        ScanPendingResultBitmap = null;
                    }
                    if (ScanSourceOriginalBitmap != null)
                    {
                        try { ScanSourceOriginalBitmap.Dispose(); } catch { }
                        ScanSourceOriginalBitmap = null;
                    }
                    ScanTargetShape = null;
                }
                needRedraw = true;
            }
            // 4. Update Video Playback Time
            if (ActiveSlide != null && ActiveSlide.Shapes != null)
            {
                foreach (ShapeNode shape in ActiveSlide.Shapes)
                {
                    if (shape.Type == ShapeType.Video && shape.IsVideoPlaying)
                    {
                        shape.VideoCurrentTime += 0.016f; // approx 16ms frame
                        if (shape.VideoCurrentTime >= shape.VideoTotalTime)
                        {
                            shape.VideoCurrentTime = shape.VideoTotalTime;
                            shape.IsVideoPlaying = false; // Auto pause/stop at end
                        }
                        needRedraw = true;
                    }
                }
            }

            // 5. Update Ambient Infinite Animations (e.g. Neon Pulse Infinite Breathing Loop)
            if (IsPresenting && ActiveSlide != null && ActiveSlide.Animations != null)
            {
                foreach (ShapeAnimation anim in ActiveSlide.Animations)
                {
                    if (anim.Type == AnimationType.GenOffice_NeonPulse && anim.NeonInfiniteLoop)
                    {
                        needRedraw = true;
                        break;
                    }
                }
            }

            return needRedraw || scrollAnim;
        }
        #endregion

        #region Transition Sub-Routines
        private void RenderTransitionFrame(D2DGraphics g, Rectangle rect, SlideNode fromSlide, SlideNode toSlide, TransitionType type, float progress, float scale)
        {
            GraphicsState gState = g.Save();
            g.SmoothingMode = SmoothingMode.AntiAlias;
            // HighQualityBicubic produces smooth scaled images for Zoom; Bilinear can show block artifacts
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            // PixelOffsetMode.Half applies a 0.5-pixel sub-pixel offset so coordinates render without
            // integer-grid snapping. HighSpeed rounds to integers every frame → direct jitter source.
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;

            float t = (type == TransitionType.Morph)
                ? EaseInOutCubic(progress)  // Morph needs zero-velocity start/end to hide frame-timing jitter
                : SmoothEase(progress);

            if (type != TransitionType.Morph)
            {
                EnsureTransitionCache(rect, fromSlide, toSlide, scale);
            }

            // Khi tiến độ thực tế đạt 100% hoàn tất: Khóa chặt slide đích tại đúng hình chữ nhật chuẩn 1:1
            // Không ngắt sớm ở t >= 0.999f (vốn đạt được từ khi progress mới 96.5% do đường cong Sin) làm giật hình
            if (progress >= 0.9999f)
            {
                DrawSlideFull(g, rect, toSlide, scale);
                g.Restore(gState);
                return;
            }

            switch (type)
            {
                case TransitionType.Morph:
                    RenderMorphTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Fade:
                    RenderFadeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Push:
                    RenderPushTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Wipe:
                    RenderWipeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Split:
                    RenderSplitTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Reveal:
                    RenderRevealTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Cut:
                    RenderCutTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.RandomBars:
                    RenderRandomBarsTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Shape:
                    RenderShapeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Uncover:
                    RenderUncoverTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Cover:
                    RenderCoverTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Flash:
                    RenderFlashTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.FallOver:
                    RenderFallOverTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Curtains:
                    RenderCurtainsTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Wind:
                    RenderWindTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Prestige:
                    RenderPrestigeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Fracture:
                    RenderFractureTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Crush:
                    RenderCrushTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.PeelOff:
                    RenderPeelOffTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.PageCurl:
                    RenderPageCurlTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Airplane:
                    RenderAirplaneTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Origami:
                    RenderOrigamiTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Dissolve:
                    RenderDissolveTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Checker:
                    RenderCheckerTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Blinds:
                    RenderBlindsTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Clock:
                case TransitionType.Wheel:
                    RenderClockTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Ripple:
                    RenderRippleTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Honeycomb:
                    RenderHoneycombTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Glitter:
                    RenderGlitterTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Vortex:
                    RenderVortexTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Shred:
                    RenderShredTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Switch:
                    RenderSwitchTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Flip:
                    RenderFlipTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Gallery:
                    RenderGalleryTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Cube:
                    RenderCubeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Doors:
                    RenderDoorsTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Box:
                    RenderBoxTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Comb:
                    RenderCombTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Zoom:
                    RenderZoomTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Pan:
                    RenderPanTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.FerrisWheel:
                    RenderFerrisWheelTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Conveyor:
                    RenderConveyorTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Rotate:
                    RenderRotateTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Window:
                    RenderWindowTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.Orbit:
                    RenderOrbitTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.FlyThrough:
                    RenderFlyThroughTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                // ==================== 10 Hiệu ứng Chuyển cảnh Độc quyền GenOffice ====================
                case TransitionType.GenOffice_CinematicPrism:
                    RenderCinematicPrismTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_LiquidFluid:
                    RenderLiquidFluidTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_MatrixRain:
                    RenderMatrixRainTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_NeonPulse:
                    RenderNeonPulseTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_PortalWarp:
                    RenderPortalWarpTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_Supernova:
                    RenderSupernovaTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_HologramGlitch:
                    RenderHologramGlitchTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_Kaleidoscope:
                    RenderKaleidoscopeTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_Starlight:
                    RenderStarlightTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_GoldenRibbon:
                    RenderGoldenRibbonTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.GenOffice_SmoothFlow:
                    RenderSmoothFlowTransition(g, rect, fromSlide, toSlide, t, scale);
                    break;
                case TransitionType.None:
                default:
                    DrawSlideFull(g, rect, toSlide, scale);
                    break;
            }

            g.Restore(gState);
        }

        private static readonly System.Text.RegularExpressions.Regex _defaultGenericShapeRegex = new System.Text.RegularExpressions.Regex(
            @"^(freeform(\s*shape)?|rectangle|rounded\s*rectangle|oval|ellipse|textbox|text\s*box|picture|image|graphic|graphicframe|group|line|straight\s*connector|shape|placeholder|title|subtitle|content|h[iì]nh(\s*t[uự]\s*do)?|h[oộ]p(\s*v[aă]n\s*b[aả]n|\s*ch[uữ])?|nh[oó]m|ti[eê]u\s*[dđ][eề])(\s*\d+)?$",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Compiled);

        private static bool IsDefaultGenericShapeName(string name)
        {
            if (string.IsNullOrWhiteSpace(name)) return true;
            return _defaultGenericShapeRegex.IsMatch(name.Trim());
        }

        private static bool AreSameImage(ShapeNode a, ShapeNode b)
        {
            if (a == null || b == null) return false;

            // 1. If ImagePath is set, compare paths (case-insensitive)
            if (!string.IsNullOrEmpty(a.ImagePath) && !string.IsNullOrEmpty(b.ImagePath))
            {
                if (string.Equals(a.ImagePath, b.ImagePath, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            // 2. If CachedImage references match
            if (a.CachedImage != null && b.CachedImage != null)
            {
                if (object.ReferenceEquals(a.CachedImage, b.CachedImage))
                    return true;

                if (a.CachedImage.Width == b.CachedImage.Width && a.CachedImage.Height == b.CachedImage.Height)
                {
                    try
                    {
                        Bitmap bmpA = a.CachedImage as Bitmap;
                        Bitmap bmpB = b.CachedImage as Bitmap;
                        if (bmpA != null && bmpB != null)
                        {
                            int w = bmpA.Width;
                            int h = bmpA.Height;
                            int[] xs = { w / 4, w / 2, 3 * w / 4 };
                            int[] ys = { h / 4, h / 2, 3 * h / 4 };
                            bool match = true;
                            foreach (int x in xs)
                            {
                                foreach (int y in ys)
                                {
                                    if (bmpA.GetPixel(x, y) != bmpB.GetPixel(x, y))
                                    {
                                        match = false;
                                        break;
                                    }
                                }
                                if (!match) break;
                            }
                            if (match) return true;
                        }
                    }
                    catch { }
                }
            }

            return false;
        }

        private void RenderMorphTransition(D2DGraphics g, Rectangle rect, SlideNode fromSlide, SlideNode toSlide, float t, float scale)
        {
            // Tránh chớp trắng khi xem trước slide 1 hoặc slide trước không có hình ảnh/đối tượng
            if (TransitionFromSlideIndex < 0 || fromSlide == null || fromSlide.Shapes == null || fromSlide.Shapes.Count == 0)
            {
                DrawSlideFull(g, rect, toSlide, scale);
                return;
            }
            if (toSlide == null || toSlide.Shapes == null)
            {
                return;
            }

            // Thresholds raised so the interpolated morph runs for the full visible range.
            // 0.999 was reached at only ~97% raw progress (SmoothEase), causing an early snap.
            if (t >= 0.9999f)
            {
                DrawSlideFull(g, rect, toSlide, scale);
                return;
            }
            if (t <= 0.0001f)
            {
                DrawSlideFull(g, rect, fromSlide, scale);
                return;
            }

            // Background morph
            if (toSlide.IsGradientBg || fromSlide.IsGradientBg)
            {
                Color bgA1 = Color.FromArgb(fromSlide.BgColor | unchecked((int)0xFF000000));
                Color bgA2 = fromSlide.IsGradientBg ? Color.FromArgb(fromSlide.BgColor2 | unchecked((int)0xFF000000)) : bgA1;
                Color bgB1 = Color.FromArgb(toSlide.BgColor | unchecked((int)0xFF000000));
                Color bgB2 = toSlide.IsGradientBg ? Color.FromArgb(toSlide.BgColor2 | unchecked((int)0xFF000000)) : bgB1;

                Color currBg1 = InterpolateColor(bgA1, bgB1, t);
                Color currBg2 = InterpolateColor(bgA2, bgB2, t);
                float angle = fromSlide.BgGradientAngle + (toSlide.BgGradientAngle - fromSlide.BgGradientAngle) * t;

                using (LinearGradientBrush lgb = new LinearGradientBrush(rect, currBg1, currBg2, angle))
                {
                    g.FillRectangle(lgb, rect);
                }
            }
            else
            {
                Color bgA = Color.FromArgb(fromSlide.BgColor | unchecked((int)0xFF000000));
                Color bgB = Color.FromArgb(toSlide.BgColor | unchecked((int)0xFF000000));
                Color currBg = InterpolateColor(bgA, bgB, t);
                using (SolidBrush bgBrush = new SolidBrush(currBg))
                {
                    g.FillRectangle(bgBrush, rect);
                }
            }

            // --- Build / reuse cached pair lists (avoid O(n²) HashSet alloc every frame) ---
            if (_cachedMorphFromIdx != TransitionFromSlideIndex || _cachedMorphToIdx != TransitionToSlideIndex
                || _cachedMorphPairs == null)
            {
                _cachedMorphPairs = new List<KeyValuePair<ShapeNode, ShapeNode>>();
                _cachedMorphFromUnpaired = new HashSet<ShapeNode>();
                _cachedMorphToUnpaired = new HashSet<ShapeNode>();

                HashSet<ShapeNode> usedFromShapes = new HashSet<ShapeNode>();
                HashSet<ShapeNode> usedToShapes = new HashSet<ShapeNode>();

                // Priority 1: Match by explicit MorphName or Name starting with !! (official PowerPoint 365 exclamation morph)
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB)) continue;
                    string mNameB = !string.IsNullOrEmpty(shapeB.MorphName)
                        ? shapeB.MorphName.TrimStart('!')
                        : ((shapeB.Name != null && shapeB.Name.StartsWith("!!")) ? shapeB.Name.TrimStart('!') : null);
                    if (!string.IsNullOrEmpty(mNameB))
                    {
                        for (int a = 0; a < fromSlide.Shapes.Count; a++)
                        {
                            ShapeNode shapeA = fromSlide.Shapes[a];
                            if (!usedFromShapes.Contains(shapeA))
                            {
                                string mNameA = !string.IsNullOrEmpty(shapeA.MorphName)
                                    ? shapeA.MorphName.TrimStart('!')
                                    : ((shapeA.Name != null && shapeA.Name.StartsWith("!!")) ? shapeA.Name.TrimStart('!') : null);
                                if (!string.IsNullOrEmpty(mNameA) && string.Equals(mNameA, mNameB, StringComparison.OrdinalIgnoreCase))
                                {
                                    _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(shapeA, shapeB));
                                    usedFromShapes.Add(shapeA); usedToShapes.Add(shapeB); break;
                                }
                            }
                        }
                    }
                }

                // Priority 2: Cloned / Copied shapes across slides sharing persistent shape.Id
                // (When user copies/pastes shapes across slides or duplicates slides, Id is preserved!)
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB) || string.IsNullOrEmpty(shapeB.Id)) continue;
                    for (int a = 0; a < fromSlide.Shapes.Count; a++)
                    {
                        ShapeNode shapeA = fromSlide.Shapes[a];
                        if (usedFromShapes.Contains(shapeA) || string.IsNullOrEmpty(shapeA.Id)) continue;
                        if (string.Equals(shapeA.Id, shapeB.Id, StringComparison.Ordinal))
                        {
                            _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(shapeA, shapeB));
                            usedFromShapes.Add(shapeA); usedToShapes.Add(shapeB); break;
                        }
                    }
                }

                // Priority 3: Match by Image Identity (ImagePath or identical CachedImage)
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB)) continue;
                    if (shapeB.Type != ShapeType.Image && shapeB.CachedImage == null && string.IsNullOrEmpty(shapeB.ImagePath)) continue;
                    for (int a = 0; a < fromSlide.Shapes.Count; a++)
                    {
                        ShapeNode shapeA = fromSlide.Shapes[a];
                        if (usedFromShapes.Contains(shapeA)) continue;
                        if (AreSameImage(shapeA, shapeB))
                        {
                            _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(shapeA, shapeB));
                            usedFromShapes.Add(shapeA); usedToShapes.Add(shapeB); break;
                        }
                    }
                }

                // Priority 4: Match by exact non-empty Text
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB) || string.IsNullOrWhiteSpace(shapeB.Text)) continue;
                    for (int a = 0; a < fromSlide.Shapes.Count; a++)
                    {
                        ShapeNode shapeA = fromSlide.Shapes[a];
                        if (usedFromShapes.Contains(shapeA)) continue;
                        if (string.Equals(shapeA.Text != null ? shapeA.Text.Trim() : "", shapeB.Text != null ? shapeB.Text.Trim() : "", StringComparison.Ordinal))
                        {
                            _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(shapeA, shapeB));
                            usedFromShapes.Add(shapeA); usedToShapes.Add(shapeB); break;
                        }
                    }
                }

                // Priority 5: Match by Custom Non-Generic Name
                // (PowerPoint only matches by Name if the name is NOT a default auto-generated name like "Freeform 6" or "Rectangle 1")
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB) || string.IsNullOrEmpty(shapeB.Name)) continue;
                    if (IsDefaultGenericShapeName(shapeB.Name)) continue;
                    for (int a = 0; a < fromSlide.Shapes.Count; a++)
                    {
                        ShapeNode shapeA = fromSlide.Shapes[a];
                        if (usedFromShapes.Contains(shapeA) || string.IsNullOrEmpty(shapeA.Name)) continue;
                        if (IsDefaultGenericShapeName(shapeA.Name)) continue;
                        if (string.Equals(shapeA.Name, shapeB.Name, StringComparison.OrdinalIgnoreCase))
                        {
                            _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(shapeA, shapeB));
                            usedFromShapes.Add(shapeA); usedToShapes.Add(shapeB); break;
                        }
                    }
                }

                // Priority 6: Smart Geometric & Type Proximity Matching (PowerPoint 365 Auto-Matching)
                // For any remaining unpaired shapes, pair shapes of the same type (or textboxes/shapes) with closest positions
                for (int b = 0; b < toSlide.Shapes.Count; b++)
                {
                    ShapeNode shapeB = toSlide.Shapes[b];
                    if (usedToShapes.Contains(shapeB)) continue;

                    ShapeNode bestMatchA = null;
                    float minDistanceSq = float.MaxValue;

                    for (int a = 0; a < fromSlide.Shapes.Count; a++)
                    {
                        ShapeNode shapeA = fromSlide.Shapes[a];
                        if (usedFromShapes.Contains(shapeA)) continue;

                        // Must be compatible types: exact match OR both are text containers
                        bool typeCompatible = (shapeA.Type == shapeB.Type) ||
                            ((shapeA.Type == ShapeType.TextBox || shapeA.Type == ShapeType.Rectangle) &&
                             (shapeB.Type == ShapeType.TextBox || shapeB.Type == ShapeType.Rectangle));

                        if (!typeCompatible) continue;

                        float cxA = shapeA.Transform.X + shapeA.Transform.Width / 2f;
                        float cyA = shapeA.Transform.Y + shapeA.Transform.Height / 2f;
                        float cxB = shapeB.Transform.X + shapeB.Transform.Width / 2f;
                        float cyB = shapeB.Transform.Y + shapeB.Transform.Height / 2f;

                        float dx = cxB - cxA;
                        float dy = cyB - cyA;
                        float distSq = dx * dx + dy * dy;

                        // Give bonus if text shares common words
                        if (!string.IsNullOrEmpty(shapeA.Text) && !string.IsNullOrEmpty(shapeB.Text))
                        {
                            var wordsA = shapeA.Text.Split(new[] { ' ', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                            var wordsB = shapeB.Text.Split(new[] { ' ', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                            int common = wordsA.Intersect(wordsB, StringComparer.OrdinalIgnoreCase).Count();
                            if (common > 0)
                            {
                                distSq *= 0.5f; // prioritize shapes sharing words
                            }
                        }

                        if (distSq < minDistanceSq)
                        {
                            minDistanceSq = distSq;
                            bestMatchA = shapeA;
                        }
                    }

                    if (bestMatchA != null)
                    {
                        _cachedMorphPairs.Add(new KeyValuePair<ShapeNode, ShapeNode>(bestMatchA, shapeB));
                        usedFromShapes.Add(bestMatchA);
                        usedToShapes.Add(shapeB);
                    }
                }

                foreach (ShapeNode s in fromSlide.Shapes) if (!usedFromShapes.Contains(s)) _cachedMorphFromUnpaired.Add(s);
                foreach (ShapeNode s in toSlide.Shapes)   if (!usedToShapes.Contains(s))   _cachedMorphToUnpaired.Add(s);

                _cachedMorphFromIdx = TransitionFromSlideIndex;
                _cachedMorphToIdx   = TransitionToSlideIndex;
            }

            // --- Render using cached pairs ---

            // Render Unpaired shapes from Slide A (Smooth continuous Fade Out)
            // No Clone() needed - pass fadeOut as opacityMultiplier directly.
            // Original opacity is preserved; op = shape.FillOpacity * fadeOut (linear, correct).
            for (int a = 0; a < fromSlide.Shapes.Count; a++)
            {
                ShapeNode shapeA = fromSlide.Shapes[a];
                if (!_cachedMorphFromUnpaired.Contains(shapeA)) continue;
                float fadeOut = Math.Max(0.0f, 1.0f - t);
                if (fadeOut > 0.005f)
                    DrawShape(g, rect.X, rect.Y, scale, shapeA, false, fadeOut);
            }

            // Render Paired Shapes with Pure Vector Matrix Interpolation
            foreach (KeyValuePair<ShapeNode, ShapeNode> pair in _cachedMorphPairs)
            {
                ShapeNode sA = pair.Key;
                ShapeNode sB = pair.Value;

                if (IsPresenting || IsPreviewingTransition)
                {
                    bool isVis;
                    float offX, offY, scX, scY, rDelta, opMul;
                    GetShapeAnimationTransform(sB, toSlide, 0, true, false, -1, 0f, out isVis, out offX, out offY, out scX, out scY, out rDelta, out opMul);
                    if (!isVis)
                    {
                        // sB có hiệu ứng Entrance trên toSlide -> không morph thành sB mà sA chỉ fade out
                        float fadeOut = Math.Max(0.0f, 1.0f - t) * sA.FillOpacity;
                        if (fadeOut > 0.005f)
                        {
                            ShapeNode morphedA = sA.Clone();
                            morphedA.FillOpacity = fadeOut;
                            DrawShape(g, rect.X, rect.Y, scale, morphedA, false, fadeOut);
                        }
                        continue;
                    }
                }

                DrawMorphingShape(g, rect.X, rect.Y, scale, sA, sB, t, toSlide.MorphMode);
            }

            // Render Unpaired shapes from Slide B (Fade In synchronized with movement)
            // No Clone() needed - pass fadeIn as opacityMultiplier directly.
            for (int b = 0; b < toSlide.Shapes.Count; b++)
            {
                ShapeNode shapeB = toSlide.Shapes[b];
                if (!_cachedMorphToUnpaired.Contains(shapeB)) continue;
                if (IsPresenting || IsPreviewingTransition)
                {
                    bool isVis;
                    float offX, offY, scX, scY, rDelta, opMul;
                    GetShapeAnimationTransform(shapeB, toSlide, 0, true, false, -1, 0f, out isVis, out offX, out offY, out scX, out scY, out rDelta, out opMul);
                    if (!isVis) continue;
                }
                float fadeIn = Math.Max(0.0f, Math.Min(1.0f, t));
                if (fadeIn > 0.005f)
                    DrawShape(g, rect.X, rect.Y, scale, shapeB, false, fadeIn);
            }
        }

        // PowerPoint-style smooth cubic ease-in-out: velocity=0 at both ends, peak at midpoint.
        // Critical for Morph: when velocity=0 a late/early timer tick causes zero visible displacement.
        private static float EaseInOutCubic(float p)
        {
            if (p <= 0f) return 0f;
            if (p >= 1f) return 1f;
            return p < 0.5f
                ? 4f * p * p * p
                : 1f - (float)Math.Pow(-2f * p + 2f, 3) / 2f;
        }

        public static float SmoothEase(float p)
        {
            if (p <= 0.0f) return 0.0f;
            if (p >= 1.0f) return 1.0f;
            // PowerPoint 365 Standard Smooth Sine Deceleration Easing (Cubic-Bezier 0.25, 0.1, 0.25, 1.0)
            return (float)Math.Sin(p * Math.PI / 2.0);
        }

        private void DrawMorphingShape(D2DGraphics g, float slideX, float slideY, float scale, ShapeNode sA, ShapeNode sB, float t, MorphType morphMode = MorphType.Objects)
        {
            // 0.999f threshold caused a snap at ~97% raw progress (SmoothEase(0.97) ≈ 0.999).
            // Raising to 0.9998f means the snap only triggers at 99.97% raw — imperceptible.
            if (t >= 0.9998f)
            {
                DrawShape(g, slideX, slideY, scale, sB, false);
                return;
            }
            if (t <= 0.0002f)
            {
                DrawShape(g, slideX, slideY, scale, sA, false);
                return;
            }

            bool sameText = string.Equals(sA.Text, sB.Text, StringComparison.Ordinal);

            // Interpolate CornerRadius
            float crA = sA.CornerRadius >= 0f ? sA.CornerRadius : 0f;
            float crB = sB.CornerRadius >= 0f ? sB.CornerRadius : 0f;
            float morphedCR = (sA.CornerRadius < 0f && sB.CornerRadius < 0f) ? -1f : (crA + (crB - crA) * t);

            // Interpolate CustomPath vertex by vertex if point counts match
            GraphicsPath interpolatedPath = null;
            if (sA.CustomPath != null && sB.CustomPath != null &&
                sA.CustomPath.PointCount == sB.CustomPath.PointCount &&
                sA.CustomPath.PointCount > 0)
            {
                try
                {
                    PointF[] ptsA = sA.CustomPath.PathPoints;
                    PointF[] ptsB = sB.CustomPath.PathPoints;
                    byte[] types = sB.CustomPath.PathTypes;
                    PointF[] interpPts = new PointF[ptsA.Length];
                    for (int i = 0; i < ptsA.Length; i++)
                    {
                        interpPts[i] = new PointF(
                            ptsA[i].X + (ptsB[i].X - ptsA[i].X) * t,
                            ptsA[i].Y + (ptsB[i].Y - ptsA[i].Y) * t
                        );
                    }
                    interpolatedPath = new GraphicsPath(interpPts, types);
                }
                catch { }
            }

            ShapeNode morphed = new ShapeNode
            {
                Id = sB.Id,
                Type = (t < 0.5f) ? sA.Type : sB.Type,
                FontName = (t < 0.5f) ? sA.FontName : sB.FontName,
                Bold = (t < 0.5f) ? sA.Bold : sB.Bold,
                Italic = (t < 0.5f) ? sA.Italic : sB.Italic,
                Underline = (t < 0.5f) ? sA.Underline : sB.Underline,
                Text = "", // Background container drawn without text first
                Alignment = (t < 0.5f) ? sA.Alignment : sB.Alignment,
                VerticalAlignment = (t < 0.5f) ? sA.VerticalAlignment : sB.VerticalAlignment,
                StrokeWidth = sA.StrokeWidth + (sB.StrokeWidth - sA.StrokeWidth) * t,
                FontSize = sA.FontSize + (sB.FontSize - sA.FontSize) * t,
                FillOpacity = sA.FillOpacity + (sB.FillOpacity - sA.FillOpacity) * t,
                CornerRadius = morphedCR,
                CropLeft = sA.CropLeft + (sB.CropLeft - sA.CropLeft) * t,
                CropTop = sA.CropTop + (sB.CropTop - sA.CropTop) * t,
                CropRight = sA.CropRight + (sB.CropRight - sA.CropRight) * t,
                CropBottom = sA.CropBottom + (sB.CropBottom - sA.CropBottom) * t,
                CropShapeType = (t < 0.5f) ? (sA.CropShapeType ?? "Rectangle") : (sB.CropShapeType ?? "Rectangle"),
                CustomPath = interpolatedPath ?? ((t < 0.5f) ? (sA.CustomPath ?? sB.CustomPath) : (sB.CustomPath ?? sA.CustomPath)),
                PathWidth = sA.PathWidth + (sB.PathWidth - sA.PathWidth) * t,
                PathHeight = sA.PathHeight + (sB.PathHeight - sA.PathHeight) * t,
                CachedImage = sB.CachedImage ?? sA.CachedImage,
                ImagePath = !string.IsNullOrEmpty(sB.ImagePath) ? sB.ImagePath : sA.ImagePath,
                OriginalWidth = sB.OriginalWidth > 0 ? sB.OriginalWidth : sA.OriginalWidth,
                OriginalHeight = sB.OriginalHeight > 0 ? sB.OriginalHeight : sA.OriginalHeight,
                DashStyle = (t < 0.5f) ? sA.DashStyle : sB.DashStyle
            };

            morphed.Transform.X = sA.Transform.X + (sB.Transform.X - sA.Transform.X) * t;
            morphed.Transform.Y = sA.Transform.Y + (sB.Transform.Y - sA.Transform.Y) * t;
            morphed.Transform.Width = sA.Transform.Width + (sB.Transform.Width - sA.Transform.Width) * t;
            morphed.Transform.Height = sA.Transform.Height + (sB.Transform.Height - sA.Transform.Height) * t;
            morphed.Transform.Rotation = sA.Transform.Rotation + (sB.Transform.Rotation - sA.Transform.Rotation) * t;
            morphed.Transform.FlipHorizontal = (t < 0.5f) ? sA.Transform.FlipHorizontal : sB.Transform.FlipHorizontal;
            morphed.Transform.FlipVertical = (t < 0.5f) ? sA.Transform.FlipVertical : sB.Transform.FlipVertical;

            Color cFillA = Color.FromArgb(sA.FillColor | unchecked((int)0xFF000000));
            Color cFillB = Color.FromArgb(sB.FillColor | unchecked((int)0xFF000000));
            morphed.FillColor = InterpolateColor(cFillA, cFillB, t).ToArgb() & 0xFFFFFF;

            Color cStrokeA = Color.FromArgb(sA.StrokeColor | unchecked((int)0xFF000000));
            Color cStrokeB = Color.FromArgb(sB.StrokeColor | unchecked((int)0xFF000000));
            morphed.StrokeColor = InterpolateColor(cStrokeA, cStrokeB, t).ToArgb() & 0xFFFFFF;

            Color cTextA = Color.FromArgb(sA.TextColor | unchecked((int)0xFF000000));
            Color cTextB = Color.FromArgb(sB.TextColor | unchecked((int)0xFF000000));
            morphed.TextColor = InterpolateColor(cTextA, cTextB, t).ToArgb() & 0xFFFFFF;

            // 1. Draw morphing base container (Fill + Stroke + CustomPath) without duplicate text
            string origText = morphed.Text;
            morphed.Text = "";
            DrawShape(g, slideX, slideY, scale, morphed, false);
            morphed.Text = origText;

            // 2. Render Text cleanly
            if (morphMode == MorphType.Words)
            {
                DrawMorphingTextWords(g, slideX, slideY, scale, sA, sB, t, morphed);
            }
            else if (morphMode == MorphType.Characters)
            {
                DrawMorphingTextCharacters(g, slideX, slideY, scale, sA, sB, t, morphed);
            }
            else if (sameText && !string.IsNullOrEmpty(sB.Text))
            {
                // Text renders at the SAME interpolated size as the background (morphed.Transform.W/H).
                // Using sB.W caused text to be offset from the background center as the shape grew,
                // creating a "heat-haze" shimmer. Interpolated size keeps text locked inside the shape.
                ShapeNode txtSame = morphed.Clone();
                txtSame.FillOpacity = 0f;      // text-only pass: no fill drawn over morphed background
                txtSame.FillColor = 0;
                txtSame.StrokeColor = 0;
                txtSame.StrokeWidth = 0;
                txtSame.Text = sB.Text;
                txtSame.FontSize = sA.FontSize + (sB.FontSize - sA.FontSize) * t;
                txtSame.TextColor = morphed.TextColor;
                DrawShape(g, slideX, slideY, scale, txtSame, false, 1.0f);
            }
            else
            {
                // Text A smoothly fades out — keep same interpolated container size as background
                float fadeOutText = Math.Max(0.0f, 1.0f - t);
                if (fadeOutText > 0.01f && !string.IsNullOrEmpty(sA.Text))
                {
                    ShapeNode txtA = morphed.Clone();
                    txtA.FillOpacity = 0f;  // text-only pass: no fill rectangle
                    txtA.FillColor = 0;
                    txtA.StrokeColor = 0;
                    txtA.StrokeWidth = 0;
                    txtA.Text = sA.Text;
                    txtA.FontName = sA.FontName;
                    txtA.FontSize = sA.FontSize + (sB.FontSize - sA.FontSize) * t;
                    txtA.Bold = sA.Bold;
                    txtA.Italic = sA.Italic;
                    txtA.Underline = sA.Underline;
                    txtA.Alignment = sA.Alignment;
                    txtA.VerticalAlignment = sA.VerticalAlignment;
                    txtA.TextColor = sA.TextColor;
                    DrawShape(g, slideX, slideY, scale, txtA, false, fadeOutText);
                }

                // Text B smoothly fades in — keep same interpolated container size as background
                float fadeInText = Math.Max(0.0f, t);
                if (fadeInText > 0.01f && !string.IsNullOrEmpty(sB.Text))
                {
                    ShapeNode txtB = morphed.Clone();
                    txtB.FillOpacity = 0f;  // text-only pass: no fill rectangle
                    txtB.FillColor = 0;
                    txtB.StrokeColor = 0;
                    txtB.StrokeWidth = 0;
                    txtB.Text = sB.Text;
                    txtB.FontName = sB.FontName;
                    txtB.FontSize = sA.FontSize + (sB.FontSize - sA.FontSize) * t;
                    txtB.Bold = sB.Bold;
                    txtB.Italic = sB.Italic;
                    txtB.Underline = sB.Underline;
                    txtB.Alignment = sB.Alignment;
                    txtB.VerticalAlignment = sB.VerticalAlignment;
                    txtB.TextColor = sB.TextColor;
                    DrawShape(g, slideX, slideY, scale, txtB, false, fadeInText);
                }
            }

            if (interpolatedPath != null)
            {
                morphed.CustomPath = null;
                interpolatedPath.Dispose();
            }
        }

        private struct MorphTextToken
        {
            public string Word;
            public char Character;
            public PointF ScreenPos;
        }

        private void DrawMorphingTextWords(D2DGraphics g, float slideX, float slideY, float scale, ShapeNode sA, ShapeNode sB, float t, ShapeNode morphedContainer)
        {
            string textA = sA.Text ?? "";
            string textB = sB.Text ?? "";

            if (string.IsNullOrWhiteSpace(textA) && string.IsNullOrWhiteSpace(textB)) return;

            float fsA = (sA.FontSize > 0 ? sA.FontSize : 18f) * scale;
            float fsB = (sB.FontSize > 0 ? sB.FontSize : 18f) * scale;
            string fontNameA = string.IsNullOrEmpty(sA.FontName) ? "Segoe UI" : sA.FontName;
            string fontNameB = string.IsNullOrEmpty(sB.FontName) ? "Segoe UI" : sB.FontName;

            var tokensA = MeasureTextWordTokens(g, sA, textA, fontNameA, fsA, scale);
            var tokensB = MeasureTextWordTokens(g, sB, textB, fontNameB, fsB, scale);

            HashSet<int> matchedA = new HashSet<int>();
            HashSet<int> matchedB = new HashSet<int>();

            // Pair identical words between A and B (Kinetic typography flight)
            for (int b = 0; b < tokensB.Count; b++)
            {
                for (int a = 0; a < tokensA.Count; a++)
                {
                    if (matchedA.Contains(a)) continue;
                    if (string.Equals(tokensA[a].Word, tokensB[b].Word, StringComparison.OrdinalIgnoreCase))
                    {
                        matchedA.Add(a);
                        matchedB.Add(b);

                        var tA = tokensA[a];
                        var tB = tokensB[b];

                        float curX = tA.ScreenPos.X + (tB.ScreenPos.X - tA.ScreenPos.X) * t;
                        float curY = tA.ScreenPos.Y + (tB.ScreenPos.Y - tA.ScreenPos.Y) * t;
                        float curFs = fsA + (fsB - fsA) * t;

                        Color colA = Color.FromArgb(sA.TextColor | unchecked((int)0xFF000000));
                        Color colB = Color.FromArgb(sB.TextColor | unchecked((int)0xFF000000));
                        Color curCol = InterpolateColor(colA, colB, t);

                        FontStyle curStyle = (t < 0.5f)
                            ? ((sA.Bold ? FontStyle.Bold : FontStyle.Regular) | (sA.Italic ? FontStyle.Italic : FontStyle.Regular))
                            : ((sB.Bold ? FontStyle.Bold : FontStyle.Regular) | (sB.Italic ? FontStyle.Italic : FontStyle.Regular));

                        using (Font curFont = new Font(t < 0.5f ? fontNameA : fontNameB, Math.Max(4f, curFs), curStyle))
                        using (SolidBrush brush = new SolidBrush(curCol))
                        {
                            g.DrawString(tB.Word, curFont, brush, slideX + curX, slideY + curY);
                        }
                        break;
                    }
                }
            }

            // Unmatched words in A fade out (smooth fade out with subtle drift)
            float fadeOut = Math.Max(0f, 1f - t);
            if (fadeOut > 0.01f)
            {
                for (int a = 0; a < tokensA.Count; a++)
                {
                    if (matchedA.Contains(a)) continue;
                    var tA = tokensA[a];
                    float driftX = tA.ScreenPos.X + (morphedContainer.Transform.X * scale - sA.Transform.X * scale) * t * 0.35f;
                    float driftY = tA.ScreenPos.Y + (morphedContainer.Transform.Y * scale - sA.Transform.Y * scale) * t * 0.35f;

                    Color colA = Color.FromArgb(sA.TextColor | unchecked((int)0xFF000000));
                    Color fadeCol = Color.FromArgb((int)(fadeOut * 255f), colA);

                    FontStyle styleA = (sA.Bold ? FontStyle.Bold : FontStyle.Regular) | (sA.Italic ? FontStyle.Italic : FontStyle.Regular);
                    using (Font fontA = new Font(fontNameA, Math.Max(4f, fsA), styleA))
                    using (SolidBrush brush = new SolidBrush(fadeCol))
                    {
                        g.DrawString(tA.Word, fontA, brush, slideX + driftX, slideY + driftY);
                    }
                }
            }

            // Unmatched words in B fade in (smooth fade in with subtle drift)
            float fadeIn = Math.Max(0f, t);
            if (fadeIn > 0.01f)
            {
                for (int b = 0; b < tokensB.Count; b++)
                {
                    if (matchedB.Contains(b)) continue;
                    var tB = tokensB[b];
                    float driftX = tB.ScreenPos.X - (sB.Transform.X * scale - morphedContainer.Transform.X * scale) * (1f - t) * 0.35f;
                    float driftY = tB.ScreenPos.Y - (sB.Transform.Y * scale - morphedContainer.Transform.Y * scale) * (1f - t) * 0.35f;

                    Color colB = Color.FromArgb(sB.TextColor | unchecked((int)0xFF000000));
                    Color fadeCol = Color.FromArgb((int)(fadeIn * 255f), colB);

                    FontStyle styleB = (sB.Bold ? FontStyle.Bold : FontStyle.Regular) | (sB.Italic ? FontStyle.Italic : FontStyle.Regular);
                    using (Font fontB = new Font(fontNameB, Math.Max(4f, fsB), styleB))
                    using (SolidBrush brush = new SolidBrush(fadeCol))
                    {
                        g.DrawString(tB.Word, fontB, brush, slideX + driftX, slideY + driftY);
                    }
                }
            }
        }

        private void DrawMorphingTextCharacters(D2DGraphics g, float slideX, float slideY, float scale, ShapeNode sA, ShapeNode sB, float t, ShapeNode morphedContainer)
        {
            string textA = sA.Text ?? "";
            string textB = sB.Text ?? "";

            if (string.IsNullOrWhiteSpace(textA) && string.IsNullOrWhiteSpace(textB)) return;

            float fsA = (sA.FontSize > 0 ? sA.FontSize : 18f) * scale;
            float fsB = (sB.FontSize > 0 ? sB.FontSize : 18f) * scale;
            string fontNameA = string.IsNullOrEmpty(sA.FontName) ? "Segoe UI" : sA.FontName;
            string fontNameB = string.IsNullOrEmpty(sB.FontName) ? "Segoe UI" : sB.FontName;

            var tokensA = MeasureTextCharTokens(g, sA, textA, fontNameA, fsA, scale);
            var tokensB = MeasureTextCharTokens(g, sB, textB, fontNameB, fsB, scale);

            HashSet<int> matchedA = new HashSet<int>();
            HashSet<int> matchedB = new HashSet<int>();

            // Pair identical characters (Kinetic character flight)
            for (int b = 0; b < tokensB.Count; b++)
            {
                for (int a = 0; a < tokensA.Count; a++)
                {
                    if (matchedA.Contains(a)) continue;
                    if (char.ToUpperInvariant(tokensA[a].Character) == char.ToUpperInvariant(tokensB[b].Character))
                    {
                        matchedA.Add(a);
                        matchedB.Add(b);

                        var tA = tokensA[a];
                        var tB = tokensB[b];

                        float curX = tA.ScreenPos.X + (tB.ScreenPos.X - tA.ScreenPos.X) * t;
                        float curY = tA.ScreenPos.Y + (tB.ScreenPos.Y - tA.ScreenPos.Y) * t;
                        float curFs = fsA + (fsB - fsA) * t;

                        Color colA = Color.FromArgb(sA.TextColor | unchecked((int)0xFF000000));
                        Color colB = Color.FromArgb(sB.TextColor | unchecked((int)0xFF000000));
                        Color curCol = InterpolateColor(colA, colB, t);

                        FontStyle curStyle = (t < 0.5f)
                            ? ((sA.Bold ? FontStyle.Bold : FontStyle.Regular) | (sA.Italic ? FontStyle.Italic : FontStyle.Regular))
                            : ((sB.Bold ? FontStyle.Bold : FontStyle.Regular) | (sB.Italic ? FontStyle.Italic : FontStyle.Regular));

                        using (Font curFont = new Font(t < 0.5f ? fontNameA : fontNameB, Math.Max(4f, curFs), curStyle))
                        using (SolidBrush brush = new SolidBrush(curCol))
                        {
                            g.DrawString(tB.Character.ToString(), curFont, brush, slideX + curX, slideY + curY);
                        }
                        break;
                    }
                }
            }

            // Unmatched characters fade out
            float fadeOut = Math.Max(0f, 1f - t);
            if (fadeOut > 0.01f)
            {
                for (int a = 0; a < tokensA.Count; a++)
                {
                    if (matchedA.Contains(a)) continue;
                    var tA = tokensA[a];
                    float driftX = tA.ScreenPos.X + (morphedContainer.Transform.X * scale - sA.Transform.X * scale) * t * 0.35f;
                    float driftY = tA.ScreenPos.Y + (morphedContainer.Transform.Y * scale - sA.Transform.Y * scale) * t * 0.35f;

                    Color colA = Color.FromArgb(sA.TextColor | unchecked((int)0xFF000000));
                    Color fadeCol = Color.FromArgb((int)(fadeOut * 255f), colA);

                    FontStyle styleA = (sA.Bold ? FontStyle.Bold : FontStyle.Regular) | (sA.Italic ? FontStyle.Italic : FontStyle.Regular);
                    using (Font fontA = new Font(fontNameA, Math.Max(4f, fsA), styleA))
                    using (SolidBrush brush = new SolidBrush(fadeCol))
                    {
                        g.DrawString(tA.Character.ToString(), fontA, brush, slideX + driftX, slideY + driftY);
                    }
                }
            }

            // Unmatched characters fade in
            float fadeIn = Math.Max(0f, t);
            if (fadeIn > 0.01f)
            {
                for (int b = 0; b < tokensB.Count; b++)
                {
                    if (matchedB.Contains(b)) continue;
                    var tB = tokensB[b];
                    float driftX = tB.ScreenPos.X - (sB.Transform.X * scale - morphedContainer.Transform.X * scale) * (1f - t) * 0.35f;
                    float driftY = tB.ScreenPos.Y - (sB.Transform.Y * scale - morphedContainer.Transform.Y * scale) * (1f - t) * 0.35f;

                    Color colB = Color.FromArgb(sB.TextColor | unchecked((int)0xFF000000));
                    Color fadeCol = Color.FromArgb((int)(fadeIn * 255f), colB);

                    FontStyle styleB = (sB.Bold ? FontStyle.Bold : FontStyle.Regular) | (sB.Italic ? FontStyle.Italic : FontStyle.Regular);
                    using (Font fontB = new Font(fontNameB, Math.Max(4f, fsB), styleB))
                    using (SolidBrush brush = new SolidBrush(fadeCol))
                    {
                        g.DrawString(tB.Character.ToString(), fontB, brush, slideX + driftX, slideY + driftY);
                    }
                }
            }
        }

        private List<MorphTextToken> MeasureTextWordTokens(D2DGraphics g, ShapeNode shape, string text, string fontName, float fontSize, float scale)
        {
            List<MorphTextToken> tokens = new List<MorphTextToken>();
            if (string.IsNullOrWhiteSpace(text)) return tokens;

            FontStyle style = (shape.Bold ? FontStyle.Bold : FontStyle.Regular) | (shape.Italic ? FontStyle.Italic : FontStyle.Regular);
            using (Font font = new Font(fontName, Math.Max(4f, fontSize), style))
            {
                float padL = Math.Max(0f, shape.MarginLeft ?? 0f) * scale;
                float padT = Math.Max(0f, shape.MarginTop ?? 0f) * scale;
                float padR = Math.Max(0f, shape.MarginRight ?? 0f) * scale;
                float padB = Math.Max(0f, shape.MarginBottom ?? 0f) * scale;

                float shapeX = shape.Transform.X * scale;
                float shapeY = shape.Transform.Y * scale;
                float shapeW = Math.Max(10f, shape.Transform.Width * scale);
                float shapeH = Math.Max(10f, shape.Transform.Height * scale);

                float availW = Math.Max(10f, shapeW - padL - padR);
                float lineHeight = font.GetHeight(g.DpiY > 0 ? g.DpiY : 96f) * shape.LineSpacing;
                if (lineHeight <= 1f) lineHeight = fontSize * 1.25f;

                string[] rawLines = text.Replace("\r", "").Split('\n');
                float spaceW = g.MeasureString(" ", font).Width;

                float totalH = rawLines.Length * lineHeight;
                float startY = shapeY + padT;
                if (shape.VerticalAlignment == VerticalTextAlignment.Middle)
                    startY = shapeY + padT + Math.Max(0f, (shapeH - padT - padB - totalH) / 2f);
                else if (shape.VerticalAlignment == VerticalTextAlignment.Bottom)
                    startY = shapeY + shapeH - padB - totalH;

                float curY = startY;
                for (int l = 0; l < rawLines.Length; l++)
                {
                    string line = rawLines[l];
                    string[] words = line.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                    if (words.Length == 0)
                    {
                        curY += lineHeight;
                        continue;
                    }

                    float lineW = 0f;
                    for (int w = 0; w < words.Length; w++)
                    {
                        lineW += g.MeasureString(words[w], font).Width;
                        if (w < words.Length - 1) lineW += spaceW;
                    }

                    float curX = shapeX + padL;
                    if (shape.Alignment == TextAlignment.Center)
                        curX = shapeX + padL + Math.Max(0f, (availW - lineW) / 2f);
                    else if (shape.Alignment == TextAlignment.Right)
                        curX = shapeX + shapeW - padR - lineW;

                    for (int w = 0; w < words.Length; w++)
                    {
                        float wordW = g.MeasureString(words[w], font).Width;
                        tokens.Add(new MorphTextToken
                        {
                            Word = words[w],
                            ScreenPos = new PointF(curX, curY)
                        });
                        curX += wordW + spaceW;
                    }

                    curY += lineHeight;
                }
            }
            return tokens;
        }

        private List<MorphTextToken> MeasureTextCharTokens(D2DGraphics g, ShapeNode shape, string text, string fontName, float fontSize, float scale)
        {
            List<MorphTextToken> tokens = new List<MorphTextToken>();
            if (string.IsNullOrWhiteSpace(text)) return tokens;

            FontStyle style = (shape.Bold ? FontStyle.Bold : FontStyle.Regular) | (shape.Italic ? FontStyle.Italic : FontStyle.Regular);
            using (Font font = new Font(fontName, Math.Max(4f, fontSize), style))
            {
                float padL = Math.Max(0f, shape.MarginLeft ?? 0f) * scale;
                float padT = Math.Max(0f, shape.MarginTop ?? 0f) * scale;
                float padR = Math.Max(0f, shape.MarginRight ?? 0f) * scale;
                float padB = Math.Max(0f, shape.MarginBottom ?? 0f) * scale;

                float shapeX = shape.Transform.X * scale;
                float shapeY = shape.Transform.Y * scale;
                float shapeW = Math.Max(10f, shape.Transform.Width * scale);
                float shapeH = Math.Max(10f, shape.Transform.Height * scale);

                float availW = Math.Max(10f, shapeW - padL - padR);
                float lineHeight = font.GetHeight(g.DpiY > 0 ? g.DpiY : 96f) * shape.LineSpacing;
                if (lineHeight <= 1f) lineHeight = fontSize * 1.25f;

                string[] rawLines = text.Replace("\r", "").Split('\n');
                float totalH = rawLines.Length * lineHeight;
                float startY = shapeY + padT;
                if (shape.VerticalAlignment == VerticalTextAlignment.Middle)
                    startY = shapeY + padT + Math.Max(0f, (shapeH - padT - padB - totalH) / 2f);
                else if (shape.VerticalAlignment == VerticalTextAlignment.Bottom)
                    startY = shapeY + shapeH - padB - totalH;

                float curY = startY;
                for (int l = 0; l < rawLines.Length; l++)
                {
                    string line = rawLines[l];
                    float lineW = g.MeasureString(line, font).Width;

                    float curX = shapeX + padL;
                    if (shape.Alignment == TextAlignment.Center)
                        curX = shapeX + padL + Math.Max(0f, (availW - lineW) / 2f);
                    else if (shape.Alignment == TextAlignment.Right)
                        curX = shapeX + shapeW - padR - lineW;

                    for (int c = 0; c < line.Length; c++)
                    {
                        char ch = line[c];
                        float chW = g.MeasureString(ch.ToString(), font).Width;
                        if (!char.IsWhiteSpace(ch))
                        {
                            tokens.Add(new MorphTextToken
                            {
                                Character = ch,
                                Word = ch.ToString(),
                                ScreenPos = new PointF(curX, curY)
                            });
                        }
                        curX += chW;
                    }

                    curY += lineHeight;
                }
            }
            return tokens;
        }
        #endregion

        #region Model Actions
        public void AddSlide(SlideLayoutType layout = SlideLayoutType.Blank)
        {
            SaveUndoState();
            SlideNode slide = Presentation.AddSlide(SlideLayoutType.Blank);
            slide.Shapes.Clear();
            slide.BgColor = 0xFFFFFF;
            slide.IsGradientBg = false;
            slide.Transition = TransitionType.None;
            slide.TransitionDuration = 0f;
            ActiveSlideIndex = Presentation.Slides.Count - 1;
            SelectedShapeIndex = -1;
            CurrentAnimationStep = 0;
        }

        public void InsertTextFromAI(string text)
        {
            if (string.IsNullOrEmpty(text) || Presentation == null || Presentation.Slides.Count == 0) return;
            SaveUndoState();
            int curIdx = Math.Max(0, Math.Min(Presentation.Slides.Count - 1, ActiveSlideIndex));
            var slide = Presentation.Slides[curIdx];

            if (SelectedShape != null)
            {
                SelectedShape.Text = (SelectedShape.Text ?? "") + (string.IsNullOrEmpty(SelectedShape.Text) ? "" : "\n") + text;
                return;
            }

            float canvasW = Presentation.CanvasWidth > 0 ? Presentation.CanvasWidth : 1920f;
            float canvasH = Presentation.CanvasHeight > 0 ? Presentation.CanvasHeight : 1080f;

            var shape = new ShapeNode
            {
                Type = ShapeType.TextBox,
                Text = text,
                FontName = "Segoe UI",
                FontSize = 24f,
                TextColor = unchecked((int)0xFF1E293B),
                FillColor = 0x00FFFFFF,
                FillOpacity = 0f,
                StrokeColor = 0x00FFFFFF,
                StrokeWidth = 0f,
                Transform = new Transform2D(120f, 200f, canvasW - 240f, 400f)
            };
            slide.Shapes.Add(shape);
            SelectedShapeIndex = slide.Shapes.Count - 1;
        }

        public void DuplicateActiveSlide()
        {
            if (ActiveSlideIndex >= 0 && ActiveSlideIndex < Presentation.Slides.Count)
            {
                SaveUndoState();
                Presentation.DuplicateSlide(ActiveSlideIndex);
                ActiveSlideIndex++;
                SelectedShapeIndex = -1;
                CurrentAnimationStep = 0;
            }
        }

        public void DeleteActiveSlide()
        {
            if (Presentation.Slides.Count > 1 && ActiveSlideIndex >= 0)
            {
                SaveUndoState();
                Presentation.DeleteSlide(ActiveSlideIndex);
                if (ActiveSlideIndex >= Presentation.Slides.Count)
                    ActiveSlideIndex = Presentation.Slides.Count - 1;
                SelectedShapeIndex = -1;
                CurrentAnimationStep = 0;
            }
        }

        public void StartShapeDrawMode(ShapeType shapeType)
        {
            if (shapeType == ShapeType.CustomPath)
            {
                StartFreeformShapeMode();
                return;
            }
            IsDrawingShapeMode = true;
            PendingShapeType = shapeType;
            IsScribbleMode = false;
            IsFreeformShapeMode = false;
            ScribblePoints.Clear();
            SelectedShapeIndex = -1;
            SelectedShapeIndices.Clear();
            EndInlineEditing();
        }

        public void StartFreeformShapeMode(Color strokeColor, float strokeWidth = 2.0f)
        {
            int colorRgb = (strokeColor.R << 16) | (strokeColor.G << 8) | strokeColor.B;
            StartFreeformShapeMode(colorRgb, strokeWidth);
        }

        public void StartFreeformShapeMode(int strokeColor = 0x222222, float strokeWidth = 2.0f)
        {
            IsDrawingShapeMode = true;
            PendingShapeType = ShapeType.CustomPath;
            IsScribbleMode = true;
            IsFreeformShapeMode = true;
            IsDrawingActive = false;
            ScribbleStrokeColor = strokeColor;
            ScribbleStrokeWidth = strokeWidth;
            ScribblePoints.Clear();
            ScribbleHoverPoint = null;
            SelectedShapeIndex = -1;
            SelectedShapeIndices.Clear();
            EndInlineEditing();
            if (InvalidateCallback != null) InvalidateCallback();
        }

        public void StartFreeformScribbleMode(Color strokeColor, float strokeWidth = 2.0f)
        {
            int colorRgb = (strokeColor.R << 16) | (strokeColor.G << 8) | strokeColor.B;
            StartFreeformScribbleMode(colorRgb, strokeWidth);
        }

        public void StartFreeformScribbleMode(int strokeColor = 0x222222, float strokeWidth = 2.0f)
        {
            IsDrawingShapeMode = true;
            PendingShapeType = ShapeType.CustomPath;
            IsScribbleMode = true;
            IsFreeformShapeMode = false;
            IsDrawingActive = false;
            ScribbleStrokeColor = strokeColor;
            ScribbleStrokeWidth = strokeWidth;
            ScribblePoints.Clear();
            ScribbleHoverPoint = null;
            SelectedShapeIndex = -1;
            SelectedShapeIndices.Clear();
            EndInlineEditing();
            if (InvalidateCallback != null) InvalidateCallback();
        }

        public void CancelShapeDrawMode()
        {
            IsDrawingShapeMode = false;
            IsDrawingActive = false;
            IsScribbleMode = false;
            IsFreeformShapeMode = false;
            ScribblePoints.Clear();
            ScribbleHoverPoint = null;
            if (InvalidateCallback != null) InvalidateCallback();
        }

        public void FinalizeScribbleShape(bool shouldClose)
        {
            if (ScribblePoints == null || ScribblePoints.Count < 2 || ActiveSlide == null)
            {
                CancelShapeDrawMode();
                return;
            }

            float minX = float.MaxValue, minY = float.MaxValue;
            float maxX = float.MinValue, maxY = float.MinValue;
            for (int i = 0; i < ScribblePoints.Count; i++)
            {
                if (ScribblePoints[i].X < minX) minX = ScribblePoints[i].X;
                if (ScribblePoints[i].Y < minY) minY = ScribblePoints[i].Y;
                if (ScribblePoints[i].X > maxX) maxX = ScribblePoints[i].X;
                if (ScribblePoints[i].Y > maxY) maxY = ScribblePoints[i].Y;
            }

            float w = Math.Max(10f, maxX - minX);
            float h = Math.Max(10f, maxY - minY);

            GraphicsPath path = new GraphicsPath();
            PointF[] localPts = new PointF[ScribblePoints.Count];
            for (int i = 0; i < ScribblePoints.Count; i++)
            {
                localPts[i] = new PointF(ScribblePoints[i].X - minX, ScribblePoints[i].Y - minY);
            }
            path.AddLines(localPts);
            if (shouldClose)
            {
                path.CloseFigure();
            }

            SaveUndoState();
            ShapeNode newShape = new ShapeNode
            {
                Id = Guid.NewGuid().ToString("N"),
                Name = (IsFreeformShapeMode ? "Freeform " : "Scribble ") + (ActiveSlide.Shapes.Count + 1),
                Type = ShapeType.CustomPath,
                CustomPath = path,
                PathWidth = w,
                PathHeight = h,
                Transform = new Transform2D(minX, minY, w, h),
                FillColor = shouldClose ? 0x4472C4 : 0x00FFFFFF,
                StrokeColor = (ScribbleStrokeColor != 0) ? ScribbleStrokeColor : 0x4472C4,
                StrokeWidth = Math.Max(1.5f, ScribbleStrokeWidth),
                FillOpacity = 1.0f,
                Text = ""
            };

            ActiveSlide.AddShape(newShape);
            SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;
            SelectedShapeIndices.Clear();
            SelectedShapeIndices.Add(SelectedShapeIndex);

            CancelShapeDrawMode();
        }

        public void StartEditShapePoints(ShapeNode shape = null)
        {
            if (shape == null) shape = SelectedShape;
            if (shape == null) return;

            SaveUndoState();
            IsEditingShapePoints = true;
            if (ActiveSlide != null && shape != null)
            {
                int sIdx = ActiveSlide.Shapes.IndexOf(shape);
                if (sIdx >= 0)
                {
                    SelectedShapeIndex = sIdx;
                    if (SelectedShapeIndices == null) SelectedShapeIndices = new List<int>();
                    SelectedShapeIndices.Clear();
                    SelectedShapeIndices.Add(sIdx);
                }
            }
            SelectedEditPointIndex = -1;
            HoveredEditSegmentIndex = -1;
            HoveredEditSegmentPoint = null;
            IsDraggingEditPoint = false;

            float sw = shape.Transform.Width;
            float sh = shape.Transform.Height;
            ShapeEditPoints.Clear();

            if (shape.CustomPath != null && shape.CustomPath.PointCount >= 2)
            {
                PointF[] pts = shape.CustomPath.PathPoints;
                float pw = shape.PathWidth > 0 ? shape.PathWidth : sw;
                float ph = shape.PathHeight > 0 ? shape.PathHeight : sh;
                float scaleX = pw > 0 ? sw / pw : 1f;
                float scaleY = ph > 0 ? sh / ph : 1f;
                for (int i = 0; i < pts.Length; i++)
                {
                    ShapeEditPoints.Add(new PointF(pts[i].X * scaleX, pts[i].Y * scaleY));
                }
                if (ShapeEditPoints.Count > 3)
                {
                    PointF p0 = ShapeEditPoints[0];
                    PointF pEnd = ShapeEditPoints[ShapeEditPoints.Count - 1];
                    if (Math.Abs(p0.X - pEnd.X) < 1.0f && Math.Abs(p0.Y - pEnd.Y) < 1.0f)
                    {
                        ShapeEditPoints.RemoveAt(ShapeEditPoints.Count - 1);
                    }
                }
            }
            else
            {
                // Convert basic shapes into editable vector points
                ShapeType prevType = shape.Type;
                shape.Type = ShapeType.CustomPath;
                try
                {
                    using (GraphicsPath geomPath = CreateShapePath(prevType, 0, 0, sw, sh, shape.CornerRadius))
                    {
                        geomPath.Flatten(null, 2.5f);
                        PointF[] pts = geomPath.PathPoints;
                        if (pts != null && pts.Length >= 3)
                        {
                            for (int i = 0; i < pts.Length; i++)
                            {
                                if (i > 0 && Math.Abs(pts[i].X - pts[i - 1].X) < 0.5f && Math.Abs(pts[i].Y - pts[i - 1].Y) < 0.5f)
                                    continue;
                                ShapeEditPoints.Add(pts[i]);
                            }
                            if (ShapeEditPoints.Count > 3)
                            {
                                PointF p0 = ShapeEditPoints[0];
                                PointF pEnd = ShapeEditPoints[ShapeEditPoints.Count - 1];
                                if (Math.Abs(p0.X - pEnd.X) < 1.0f && Math.Abs(p0.Y - pEnd.Y) < 1.0f)
                                {
                                    ShapeEditPoints.RemoveAt(ShapeEditPoints.Count - 1);
                                }
                            }
                        }
                    }
                }
                catch { }

                if (ShapeEditPoints.Count < 3)
                {
                    ShapeEditPoints.Clear();
                    ShapeEditPoints.Add(new PointF(0, 0));
                    ShapeEditPoints.Add(new PointF(sw, 0));
                    ShapeEditPoints.Add(new PointF(sw, sh));
                    ShapeEditPoints.Add(new PointF(0, sh));
                }

                RebuildCustomPathFromEditPoints();
            }

            if (InvalidateCallback != null) InvalidateCallback();
        }

        public void RebuildCustomPathFromEditPoints()
        {
            if (EditingPointsShape == null || ShapeEditPoints.Count < 2) return;

            GraphicsPath path = new GraphicsPath();
            path.AddLines(ShapeEditPoints.ToArray());
            path.CloseFigure();

            EditingPointsShape.CustomPath = path;
            EditingPointsShape.PathWidth = EditingPointsShape.Transform.Width;
            EditingPointsShape.PathHeight = EditingPointsShape.Transform.Height;
            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
        }

        public void NormalizeShapeEditPointsBounds()
        {
            if (EditingPointsShape == null || ShapeEditPoints.Count < 2) return;

            float minX = float.MaxValue, minY = float.MaxValue;
            float maxX = float.MinValue, maxY = float.MinValue;
            for (int i = 0; i < ShapeEditPoints.Count; i++)
            {
                if (ShapeEditPoints[i].X < minX) minX = ShapeEditPoints[i].X;
                if (ShapeEditPoints[i].X > maxX) maxX = ShapeEditPoints[i].X;
                if (ShapeEditPoints[i].Y < minY) minY = ShapeEditPoints[i].Y;
                if (ShapeEditPoints[i].Y > maxY) maxY = ShapeEditPoints[i].Y;
            }

            float newW = Math.Max(10f, maxX - minX);
            float newH = Math.Max(10f, maxY - minY);
            float oldW = EditingPointsShape.Transform.Width;
            float oldH = EditingPointsShape.Transform.Height;
            float rot = EditingPointsShape.Transform.Rotation;

            if (Math.Abs(rot) > 0.01f)
            {
                float rad = rot * (float)(Math.PI / 180.0);
                float cos = (float)Math.Cos(rad);
                float sin = (float)Math.Sin(rad);

                float dLocalCenterX = minX + (newW - oldW) / 2f;
                float dLocalCenterY = minY + (newH - oldH) / 2f;

                float dWorldCenterX = dLocalCenterX * cos - dLocalCenterY * sin;
                float dWorldCenterY = dLocalCenterX * sin + dLocalCenterY * cos;

                float oldCenterX = EditingPointsShape.Transform.X + oldW / 2f;
                float oldCenterY = EditingPointsShape.Transform.Y + oldH / 2f;

                float newCenterX = oldCenterX + dWorldCenterX;
                float newCenterY = oldCenterY + dWorldCenterY;

                EditingPointsShape.Transform.X = newCenterX - newW / 2f;
                EditingPointsShape.Transform.Y = newCenterY - newH / 2f;
            }
            else
            {
                EditingPointsShape.Transform.X += minX;
                EditingPointsShape.Transform.Y += minY;
            }

            EditingPointsShape.Transform.Width = newW;
            EditingPointsShape.Transform.Height = newH;

            for (int i = 0; i < ShapeEditPoints.Count; i++)
            {
                ShapeEditPoints[i] = new PointF(ShapeEditPoints[i].X - minX, ShapeEditPoints[i].Y - minY);
            }

            EditingPointsShape.PathWidth = newW;
            EditingPointsShape.PathHeight = newH;
            RebuildCustomPathFromEditPoints();
        }

        public void EndEditShapePoints()
        {
            if (!IsEditingShapePoints) return;

            if (EditingPointsShape != null && ShapeEditPoints.Count >= 2)
            {
                NormalizeShapeEditPointsBounds();
                SaveUndoState();
            }

            IsEditingShapePoints = false;
            EditingPointsShape = null;
            HoveredEditPointIndex = -1;
            SelectedEditPointIndex = -1;
            HoveredEditSegmentIndex = -1;
            HoveredEditSegmentPoint = null;
            IsDraggingEditPoint = false;
            if (InvalidateCallback != null) InvalidateCallback();
        }

        private PointF ShapeLocalToScreen(ShapeNode sh, PointF localPt, int slideX, int slideY, float scale)
        {
            float sx = slideX + (sh.Transform.X + localPt.X) * scale;
            float sy = slideY + (sh.Transform.Y + localPt.Y) * scale;
            if (Math.Abs(sh.Transform.Rotation) > 0.01f)
            {
                PointF center = new PointF(
                    slideX + (sh.Transform.X + sh.Transform.Width / 2f) * scale,
                    slideY + (sh.Transform.Y + sh.Transform.Height / 2f) * scale
                );
                return RotatePoint(new PointF(sx, sy), center, sh.Transform.Rotation);
            }
            return new PointF(sx, sy);
        }

        private PointF ScreenToShapeLocal(ShapeNode sh, PointF screenPt, int slideX, int slideY, float scale)
        {
            PointF pt = screenPt;
            if (Math.Abs(sh.Transform.Rotation) > 0.01f)
            {
                PointF center = new PointF(
                    slideX + (sh.Transform.X + sh.Transform.Width / 2f) * scale,
                    slideY + (sh.Transform.Y + sh.Transform.Height / 2f) * scale
                );
                pt = RotatePoint(screenPt, center, -sh.Transform.Rotation);
            }
            return new PointF(
                (pt.X - slideX) / scale - sh.Transform.X,
                (pt.Y - slideY) / scale - sh.Transform.Y
            );
        }

        private float GetDistanceToSegment(PointF p, PointF a, PointF b, out PointF closest)
        {
            float dx = b.X - a.X;
            float dy = b.Y - a.Y;
            float l2 = dx * dx + dy * dy;
            if (l2 < 0.0001f)
            {
                closest = a;
                float dX = p.X - a.X;
                float dY = p.Y - a.Y;
                return (float)Math.Sqrt(dX * dX + dY * dY);
            }
            float t = Math.Max(0f, Math.Min(1f, ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / l2));
            closest = new PointF(a.X + t * dx, a.Y + t * dy);
            float cdx = p.X - closest.X;
            float cdy = p.Y - closest.Y;
            return (float)Math.Sqrt(cdx * cdx + cdy * cdy);
        }

        private void DrawEditShapePointsOverlay(D2DGraphics g, int slideX, int slideY, float scale)
        {
            if (!IsEditingShapePoints || EditingPointsShape == null || ShapeEditPoints.Count < 2) return;

            ShapeNode sh = EditingPointsShape;
            PointF[] screenPts = new PointF[ShapeEditPoints.Count];
            for (int i = 0; i < ShapeEditPoints.Count; i++)
            {
                screenPts[i] = ShapeLocalToScreen(sh, ShapeEditPoints[i], slideX, slideY, scale);
            }

            g.SmoothingMode = SmoothingMode.AntiAlias;

            // 1. Draw red contour outline (PowerPoint red editing path)
            using (Pen pathPen = new Pen(Color.FromArgb(239, 68, 68), 1.5f))
            {
                g.DrawPolygon(pathPen, screenPts);
            }

            // 2. Draw ghost add-point preview on hovered segment
            if (HoveredEditSegmentIndex >= 0 && HoveredEditSegmentPoint.HasValue)
            {
                PointF segPt = ShapeLocalToScreen(sh, HoveredEditSegmentPoint.Value, slideX, slideY, scale);
                using (SolidBrush ghostB = new SolidBrush(Color.FromArgb(180, 59, 130, 246)))
                using (Pen ghostP = new Pen(Color.White, 1.5f))
                {
                    g.FillEllipse(ghostB, segPt.X - 5, segPt.Y - 5, 10, 10);
                    g.DrawEllipse(ghostP, segPt.X - 5, segPt.Y - 5, 10, 10);
                }
            }

            // 3. Draw black vertex squares on each node
            float handleSize = 7f;
            using (SolidBrush blackB = new SolidBrush(Color.Black))
            using (SolidBrush whiteB = new SolidBrush(Color.White))
            using (Pen whiteP = new Pen(Color.White, 1.2f))
            using (Pen redP = new Pen(Color.FromArgb(239, 68, 68), 1.8f))
            {
                for (int i = 0; i < screenPts.Length; i++)
                {
                    PointF pt = screenPts[i];
                    RectangleF r = new RectangleF(pt.X - handleSize / 2f, pt.Y - handleSize / 2f, handleSize, handleSize);

                    if (i == SelectedEditPointIndex || i == HoveredEditPointIndex)
                    {
                        RectangleF hr = new RectangleF(pt.X - 5, pt.Y - 5, 10, 10);
                        g.FillRectangle(whiteB, hr);
                        g.DrawRectangle(redP, hr.X, hr.Y, hr.Width, hr.Height);
                    }
                    else
                    {
                        g.FillRectangle(blackB, r);
                        g.DrawRectangle(whiteP, r.X, r.Y, r.Width, r.Height);
                    }
                }
            }
        }

        public void StartDrawingCustomMotionPath(ShapeNode shape = null)
        {
            if (shape == null) shape = SelectedShape;
            if (shape == null && ActiveSlide != null && ActiveSlide.Shapes.Count > 0)
            {
                shape = ActiveSlide.Shapes[ActiveSlide.Shapes.Count - 1];
                SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;
            }
            if (shape == null)
            {
                MessageBox.Show("Vui lòng chọn một hình vẽ hoặc hộp văn bản trước khi vẽ đường chuyển động.", "Đường chuyển động tự vẽ", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            IsDrawingMotionPathMode = true;
            IsDrawingMotionPathActive = false;
            ActiveDrawingMotionShape = shape;
            CurrentDrawingMotionPoints.Clear();
            EndInlineEditing();
        }

        public void StartInlineEditing(ShapeNode shape)
        {
            if (shape == null) return;
            if (shape.Type == ShapeType.Image) return;
            IsInlineEditing = true;
            EditingShape = shape;
            if (shape.TextRuns != null && shape.TextRuns.Count > 0 && shape.TextRuns[0].ParaAlignment.HasValue)
            {
                shape.Alignment = shape.TextRuns[0].ParaAlignment.Value;
            }
            if (shape.Type != ShapeType.TextBox && string.IsNullOrEmpty(shape.Text))
            {
                if (shape.Alignment != TextAlignment.Left && shape.Alignment != TextAlignment.Right && shape.Alignment != TextAlignment.Justify)
                {
                    shape.Alignment = TextAlignment.Center;
                }
                shape.VerticalAlignment = VerticalTextAlignment.Middle;
                if ((shape.TextColor == 0x222222 || shape.TextColor == 0x0F172A) && shape.FillColor != 0x00FFFFFF && shape.FillColor != 0xFFFFFF)
                {
                    shape.TextColor = 0xFFFFFF;
                }
            }
            EditingTextBuffer = shape.Text ?? "";
            CaretIndex = EditingTextBuffer.Length;
            TextSelectionStart = 0;
            TextSelectionLength = 0;
            IsSelectingText = false;
            shape.IsEditingText = true;
        }

        public void SyncEditingShapeText()
        {
            if (EditingShape == null) return;
            EditingShape.Text = EditingTextBuffer ?? "";
            if (EditingShape.TextRuns != null && EditingShape.TextRuns.Count > 0)
            {
                SlideTextRun proto = EditingShape.TextRuns[0];
                EditingShape.TextRuns.Clear();
                if (!string.IsNullOrEmpty(EditingShape.Text))
                {
                    EditingShape.TextRuns.Add(new SlideTextRun(EditingShape.Text, EditingShape.TextColor, EditingShape.FontSize, EditingShape.Bold, EditingShape.FontName)
                    {
                        Italic = EditingShape.Italic,
                        Underline = EditingShape.Underline,
                        Strikethrough = EditingShape.Strikethrough,
                        HasGradient = proto.HasGradient,
                        GradientColor2 = proto.GradientColor2,
                        GradientAngle = proto.GradientAngle,
                        GradientStops = proto.GradientStops != null ? new List<GradientStop>(proto.GradientStops) : null,
                        HasHighlight = EditingShape.HasHighlight,
                        HighlightColor = EditingShape.HighlightColor,
                        ParaLineSpacing = proto.ParaLineSpacing,
                        ParaSpaceBefore = proto.ParaSpaceBefore,
                        ParaSpaceAfter = proto.ParaSpaceAfter,
                        ParaAlignment = EditingShape.Alignment
                    });
                }
            }
            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
        }

        public void EndInlineEditing()
        {
            if (IsInlineEditing && EditingShape != null)
            {
                if (VietnameseAutoCorrect.IsEnabled && !string.IsNullOrEmpty(EditingTextBuffer))
                {
                    EditingTextBuffer = VietnameseAutoCorrect.CorrectText(EditingTextBuffer);
                }
                SyncEditingShapeText();
                EditingShape.IsEditingText = false;
            }
            IsInlineEditing = false;
            EditingShape = null;
            EditingTextBuffer = "";
            TextSelectionStart = 0;
            TextSelectionLength = 0;
            IsSelectingText = false;

            EndTableInlineEditing();
        }

        public void StartTableInlineEditing(ShapeNode shape, int r, int c)
        {
            if (shape == null || shape.Type != ShapeType.Table) return;
            EndInlineEditing();

            if (shape.TableData == null) shape.TableData = new List<List<string>>();
            while (shape.TableData.Count <= r) shape.TableData.Add(new List<string>());
            while (shape.TableData[r].Count <= c) shape.TableData[r].Add("");

            IsEditingTableCell = true;
            EditingTableShape = shape;
            EditingTableRow = r;
            EditingTableCol = c;
            EditingTableCellBuffer = shape.TableData[r][c] ?? "";
            TableCaretIndex = EditingTableCellBuffer.Length;

            shape.TableSelectedCellRow = r;
            shape.TableSelectedCellCol = c;
            shape.TableSelectedEndRow = r;
            shape.TableSelectedEndCol = c;
        }

        public void EndTableInlineEditing()
        {
            if (IsEditingTableCell && EditingTableShape != null && EditingTableShape.TableData != null)
            {
                int r = EditingTableRow;
                int c = EditingTableCol;
                if (r >= 0 && r < EditingTableShape.TableRows && c >= 0 && c < EditingTableShape.TableColumns)
                {
                    while (EditingTableShape.TableData.Count <= r) EditingTableShape.TableData.Add(new List<string>());
                    while (EditingTableShape.TableData[r].Count <= c) EditingTableShape.TableData[r].Add("");
                    string cellVal = EditingTableCellBuffer ?? "";
                    if (VietnameseAutoCorrect.IsEnabled && !string.IsNullOrEmpty(cellVal))
                    {
                        cellVal = VietnameseAutoCorrect.CorrectText(cellVal);
                    }
                    EditingTableShape.TableData[r][c] = cellVal;
                }
            }
            IsEditingTableCell = false;
            EditingTableShape = null;
            EditingTableRow = -1;
            EditingTableCol = -1;
            EditingTableCellBuffer = "";
            TableCaretIndex = 0;
        }

        public void SetSelectedTableCellFillColor(int argbColor)
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = SelectedShape;
            if (shape.TableCellFillColors == null) shape.TableCellFillColors = new Dictionary<string, int>();

            int minR = Math.Max(0, Math.Min(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int maxR = Math.Min(shape.TableRows - 1, Math.Max(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int minC = Math.Max(0, Math.Min(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));
            int maxC = Math.Min(shape.TableColumns - 1, Math.Max(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));

            if (shape.TableSelectedCellRow < 0)
            {
                minR = 0; maxR = shape.TableRows - 1;
                minC = 0; maxC = shape.TableColumns - 1;
            }

            for (int r = minR; r <= maxR; r++)
            {
                for (int c = minC; c <= maxC; c++)
                {
                    shape.TableCellFillColors[r + "," + c] = argbColor;
                }
            }
        }

        public void SetSelectedTableCellTextColor(int argbColor)
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = SelectedShape;
            if (shape.TableCellTextColors == null) shape.TableCellTextColors = new Dictionary<string, int>();

            int minR = Math.Max(0, Math.Min(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int maxR = Math.Min(shape.TableRows - 1, Math.Max(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int minC = Math.Max(0, Math.Min(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));
            int maxC = Math.Min(shape.TableColumns - 1, Math.Max(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));

            if (shape.TableSelectedCellRow < 0)
            {
                minR = 0; maxR = shape.TableRows - 1;
                minC = 0; maxC = shape.TableColumns - 1;
            }

            for (int r = minR; r <= maxR; r++)
            {
                for (int c = minC; c <= maxC; c++)
                {
                    shape.TableCellTextColors[r + "," + c] = argbColor;
                }
            }
        }

        public void SetSelectedTableCellBold(bool bold)
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = SelectedShape;
            if (shape.TableCellBolds == null) shape.TableCellBolds = new Dictionary<string, bool>();

            int minR = Math.Max(0, Math.Min(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int maxR = Math.Min(shape.TableRows - 1, Math.Max(shape.TableSelectedCellRow, shape.TableSelectedEndRow >= 0 ? shape.TableSelectedEndRow : shape.TableSelectedCellRow));
            int minC = Math.Max(0, Math.Min(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));
            int maxC = Math.Min(shape.TableColumns - 1, Math.Max(shape.TableSelectedCellCol, shape.TableSelectedEndCol >= 0 ? shape.TableSelectedEndCol : shape.TableSelectedCellCol));

            for (int r = minR; r <= maxR; r++)
            {
                for (int c = minC; c <= maxC; c++)
                {
                    shape.TableCellBolds[r + "," + c] = bold;
                }
            }
        }

        public void InsertTableRow(bool above)
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = SelectedShape;
            int targetR = shape.TableSelectedCellRow >= 0 ? shape.TableSelectedCellRow : shape.TableRows - 1;
            if (!above) targetR++;
            targetR = Math.Max(0, Math.Min(shape.TableRows, targetR));

            List<string> newRow = new List<string>();
            for (int c = 0; c < shape.TableColumns; c++) newRow.Add("");

            if (shape.TableData == null) shape.TableData = new List<List<string>>();
            while (shape.TableData.Count < shape.TableRows)
            {
                List<string> r = new List<string>();
                for (int c = 0; c < shape.TableColumns; c++) r.Add("");
                shape.TableData.Add(r);
            }

            shape.TableData.Insert(targetR, newRow);
            shape.TableRows++;
            shape.Transform.Height += 40f;
            shape.TableSelectedCellRow = targetR;
            shape.TableSelectedEndRow = targetR;
        }

        public void InsertTableColumn(bool left)
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = SelectedShape;
            int targetC = shape.TableSelectedCellCol >= 0 ? shape.TableSelectedCellCol : shape.TableColumns - 1;
            if (!left) targetC++;
            targetC = Math.Max(0, Math.Min(shape.TableColumns, targetC));

            if (shape.TableData == null) shape.TableData = new List<List<string>>();
            for (int r = 0; r < shape.TableRows; r++)
            {
                while (shape.TableData.Count <= r) shape.TableData.Add(new List<string>());
                while (shape.TableData[r].Count < shape.TableColumns) shape.TableData[r].Add("");
                shape.TableData[r].Insert(targetC, "");
            }
            shape.TableColumns++;
            shape.Transform.Width += 120f;
            shape.TableSelectedCellCol = targetC;
            shape.TableSelectedEndCol = targetC;
        }

        public void DeleteTableRow()
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table || SelectedShape.TableRows <= 1) return;
            ShapeNode shape = SelectedShape;
            int r = shape.TableSelectedCellRow >= 0 ? shape.TableSelectedCellRow : shape.TableRows - 1;
            if (r >= 0 && r < shape.TableRows)
            {
                if (shape.TableData != null && r < shape.TableData.Count)
                {
                    shape.TableData.RemoveAt(r);
                }
                shape.TableRows--;
                shape.Transform.Height = Math.Max(60f, shape.Transform.Height - 40f);
                shape.TableSelectedCellRow = Math.Min(shape.TableRows - 1, r);
                shape.TableSelectedEndRow = shape.TableSelectedCellRow;
            }
        }

        public void DeleteTableColumn()
        {
            if (SelectedShape == null || SelectedShape.Type != ShapeType.Table || SelectedShape.TableColumns <= 1) return;
            ShapeNode shape = SelectedShape;
            int c = shape.TableSelectedCellCol >= 0 ? shape.TableSelectedCellCol : shape.TableColumns - 1;
            if (c >= 0 && c < shape.TableColumns)
            {
                if (shape.TableData != null)
                {
                    for (int r = 0; r < shape.TableData.Count; r++)
                    {
                        if (c < shape.TableData[r].Count)
                        {
                            shape.TableData[r].RemoveAt(c);
                        }
                    }
                }
                shape.TableColumns--;
                shape.Transform.Width = Math.Max(120f, shape.Transform.Width - 100f);
                shape.TableSelectedCellCol = Math.Min(shape.TableColumns - 1, c);
                shape.TableSelectedEndCol = shape.TableSelectedCellCol;
            }
        }

        public void ShowTableContextMenu(Control parentControl, Point screenPos, int shapeIndex, int cellR, int cellC)
