            int[] fillPalette = new int[] {
                0x00FFFFFF, // Không màu
                0x2563EB, // Xanh dương
                0x38BDF8, // Xanh da trời
                0x10B981, // Xanh lá
                0x84CC16, // Xanh cốm
                0xEF4444, // Đỏ tươi
                0xF43F5E, // Hồng
