        #region Main Workspace Drawing Logic
        public void Draw(Graphics g, int width, int height)
        {
            using (D2DGraphics d2d = new D2DGraphics(g, width, height))
            {
                Draw(d2d, width, height);
            }
        }

        public void Draw(D2DGraphics g, int width, int height)
        {
            LastViewportWidth = width;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.InterpolationMode = InterpolationMode.Bilinear;
            g.PixelOffsetMode = PixelOffsetMode.HighSpeed;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;

            if (IsPresenting)
            {
                DrawFullscreenPresenter(g, width, height);
                return;
            }

            int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
            GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);
            Rectangle centerViewportRect = new Rectangle(canvasX, contentY, canvasW, contentH);

            // 1. Draw Center Viewport with Clipping
            GraphicsState origState = g.Save();
            try
            {
                g.SetClip(centerViewportRect);

                switch (ViewMode)
                {
                    case ImpressViewMode.Normal:
                    case ImpressViewMode.ReadingView:
                        DrawNormalCanvasView(g, canvasX, contentY, canvasW, contentH);
                        break;
                    case ImpressViewMode.Outline:
                        DrawOutlineView(g, canvasX, contentY, canvasW, contentH);
                        break;
                    case ImpressViewMode.Notes:
                        DrawNotesView(g, canvasX, contentY, canvasW, contentH);
                        break;
                    case ImpressViewMode.SlideSorter:
                        DrawSlideSorterView(g, 0, contentY, width - ((IsSidebarOpen && SidebarPanel != SidebarPanelType.None && !IsPresenting) ? 280 : 0), contentH);
                        break;
                    case ImpressViewMode.SlideMaster:
                        DrawSlideMasterView(g, canvasX, contentY, canvasW, contentH);
                        break;
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("[SlidesView] Center viewport render error: " + ex);
            }
            finally
            {
                g.Restore(origState);
            }

            // 2. Draw Left Pane OR Elements Drawer ON TOP
            try
            {
                if (IsElementsDrawerOpen)
                {
                    DrawElementsDrawerPanel(g, leftSidebarW, contentY, height - contentY - 26);
                    DrawBottomSlideThumbnailStrip(g, canvasX, height - 26 - bottomThumbH, canvasW, bottomThumbH);
                }
                else if (leftSidebarW > 0)
                {
                    DrawLeftSlidePane(g, leftSidebarW, contentY, contentH);
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("[SlidesView] Left pane render error: " + ex);
            }

            // 3. Draw Right Sidebar Task Pane (Animation Pane / Properties) ON TOP
            try
            {
                int rightSidebarW = (IsSidebarOpen && SidebarPanel != SidebarPanelType.None && !IsPresenting) ? 280 : 0;
                if (rightSidebarW > 0)
                {
                    DrawRightSidebarPanel(g, width - rightSidebarW, contentY, rightSidebarW, contentH);
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("[SlidesView] Right pane render error: " + ex);
            }
        }

        private void DrawNormalCanvasView(D2DGraphics g, int x, int y, int w, int h)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;

            using (SolidBrush stageBg = new SolidBrush(Color.FromArgb(240, 240, 240)))
            {
                g.FillRectangle(stageBg, x, y, w, h);
            }

            int slideX, slideY, slideW, slideH;
            float scale;
            GetSlideCanvasBounds(x, y, w, h, out slideX, out slideY, out slideW, out slideH, out scale);

            if (!IsPresenting && SlideVideoPlayerManager.Instance.IsPlaying && SlideVideoPlayerManager.Instance.ActiveShape != null)
            {
                if (IsDraggingShape || IsResizingShape || IsRotatingShape || IsPanningCanvas)
                {
                    SlideVideoPlayerManager.Instance.Stop();
                }
                else
                {
                    ShapeNode vs = SlideVideoPlayerManager.Instance.ActiveShape;
                    int vsx = slideX + (int)(vs.Transform.X * scale);
                    int vsy = slideY + (int)(vs.Transform.Y * scale);
                    int vsw = (int)(vs.Transform.Width * scale);
                    int vsh = (int)(vs.Transform.Height * scale);
                    SlideVideoPlayerManager.Instance.UpdateBounds(new Rectangle(vsx, vsy, Math.Max(100, vsw), Math.Max(60, vsh)));
                }
            }

            Rectangle slideRect = new Rectangle(slideX, slideY, slideW, slideH);

            // If Transition Preview is running in normal canvas
            if (IsPreviewingTransition && IsTransitioning)
            {
                SlideNode toSlide = (TransitionToSlideIndex >= 0 && TransitionToSlideIndex < Presentation.Slides.Count) ? Presentation.Slides[TransitionToSlideIndex] : ActiveSlide;
                SlideNode fromSlide = (TransitionFromSlideIndex >= 0 && TransitionFromSlideIndex < Presentation.Slides.Count && TransitionFromSlideIndex != TransitionToSlideIndex)
                    ? Presentation.Slides[TransitionFromSlideIndex]
                    : new SlideNode { BgColor = toSlide.BgColor, IsGradientBg = toSlide.IsGradientBg, BgColor2 = toSlide.BgColor2 };
                RenderTransitionFrame(g, slideRect, fromSlide, toSlide, toSlide.Transition, TransitionProgress, scale);
            }
            else
            {
                // 1. Draw Slide Background & Gridlines clipped to slide canvas
                GraphicsState slideClipState = g.Save();
                g.IntersectClip(slideRect);

                SlideNode slide = ActiveSlide;
                if (slide != null)
                {
                    DrawSlideBackground(g, slideRect, slide);
                }
                else
                {
                    g.FillRectangle(Brushes.White, slideRect);
                }

                // Render Gridlines (Đường lưới)
                DrawGridlines(g, slideRect, scale);

                // Render Guides (Đường dẫn hướng tâm)
                DrawGuides(g, slideRect);

                g.Restore(slideClipState);

                // Border around slide canvas (chuẩn PowerPoint canvas edge)
                using (Pen borderPen = new Pen(Color.FromArgb(215, 215, 215), 1.0f))
                {
                    g.DrawRectangle(borderPen, slideRect);
                }

                // 2. Render Shapes: In Normal view, shapes bleed freely onto the pasteboard canvas like PowerPoint.
                // In ReadingView, shapes are clipped to slide canvas.
                GraphicsState shapesClipState = null;
                if (ViewMode == ImpressViewMode.ReadingView)
                {
                    shapesClipState = g.Save();
                    g.IntersectClip(slideRect);
                }

                if (slide != null)
                {
                    for (int i = 0; i < slide.Shapes.Count; i++)
                    {
                        ShapeNode shape = slide.Shapes[i];
                        if (shape == null || !shape.IsVisible || (shape.Name != null && shape.Name.StartsWith("__morph_ghost__"))) continue;

                        bool isSel = (i == SelectedShapeIndex) || (SelectedShapeIndices != null && SelectedShapeIndices.Contains(i));

                        bool isVis;
                        float offX, offY, scX, scY, rDelta, opMul;
                        ShapeAnimation activeAnim;
                        float activeP;
                        GetShapeAnimationTransform(shape, slide, CurrentAnimationStep, false, IsPlayingAnimationPreview, ActivePlayingAnimIndex, AnimationProgress, out isVis, out offX, out offY, out scX, out scY, out rDelta, out opMul, out activeAnim, out activeP);

                        if (isVis)
                        {
                            try
                            {
                                DrawShape(g, slideX, slideY, scale, shape, isSel, opMul, offX, offY, scX, scY, rDelta, activeAnim, activeP);
                            }
                            catch { }
                        }
                    }

                    // Render Motion Paths Trajectory & Ghost Silhouettes in Design Mode
                    try { DrawMotionPathsOverlay(g, slideX, slideY, scale, slide); } catch { }
                }

                // Render Table Insert Live Preview (Ghost Overlay)
                try { DrawTableInsertPreviewOverlay(g, slideX, slideY, scale); } catch { }

                if (shapesClipState != null)
                {
                    g.Restore(shapesClipState);
                }
            }

            // Render Pending Drawing Overlay
            if (IsDrawingActive || (IsDrawingShapeMode && IsScribbleMode))
            {
                DrawPendingShapeOverlay(g, slideX, slideY, scale);
            }

            // Render Edit Shape Points Overlay (PowerPoint Edit Points)
            if (IsEditingShapePoints && EditingPointsShape != null)
            {
                DrawEditShapePointsOverlay(g, slideX, slideY, scale);
            }

            // Render Smart Snap Guides & Equidistant Spacing Indicators
            DrawSmartGuidesAndSpacingIndicators(g, slideX, slideY, scale);

            // Render Rubberband / Marquee Selection Box (Quét khối chọn đối tượng)
            if (IsRubberbandSelecting)
            {
                int rx = Math.Min(RubberbandStartPoint.X, RubberbandCurrentPoint.X);
                int ry = Math.Min(RubberbandStartPoint.Y, RubberbandCurrentPoint.Y);
                int rw = Math.Abs(RubberbandStartPoint.X - RubberbandCurrentPoint.X);
                int rh = Math.Abs(RubberbandStartPoint.Y - RubberbandCurrentPoint.Y);

                if (rw > 1 && rh > 1)
                {
                    Rectangle boxRect = new Rectangle(rx, ry, rw, rh);
                    using (SolidBrush boxBrush = new SolidBrush(Color.FromArgb(40, 0, 120, 215)))
                    using (Pen boxPen = new Pen(Color.FromArgb(200, 0, 120, 215), 1.0f))
                    {
                        g.FillRectangle(boxBrush, boxRect);
                        g.DrawRectangle(boxPen, boxRect);
                    }
                }
            }

            int notesPaneH = GetEffectiveNotesPaneHeight();
            int stageH = Math.Max(80, h - notesPaneH);

            // Render Rulers
            if (ShowRuler)
            {
                DrawSlideRulers(g, x, y, w, stageH, slideX, slideY, slideW, slideH, scale);
            }

            // Draw Workspace Scrollbars (Thanh cuộn ngang & dọc chuẩn PowerPoint / Office 365)
            int minScrollX, maxScrollX, minScrollY, maxScrollY;
            GetScrollLimits(w, h, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);

            bool hasVScroll = (minScrollY < maxScrollY);
            bool hasHScroll = (minScrollX < maxScrollX);
            int sbH = 14;
            int sbW = 14;

            if (hasHScroll)
            {
                int hTrackW = hasVScroll ? (w - sbW) : w;
                int hTrackX = x;
                int hTrackY = y + stageH - sbH;
                Rectangle hTrackRect = new Rectangle(hTrackX, hTrackY, hTrackW, sbH);

                // Track Background & Top subtle border
                using (SolidBrush trackBg = new SolidBrush(Color.FromArgb(243, 243, 243)))
                using (Pen trackBorder = new Pen(Color.FromArgb(226, 226, 226), 1.0f))
                {
                    g.FillRectangle(trackBg, hTrackRect);
                    g.DrawLine(trackBorder, hTrackX, hTrackY, hTrackX + hTrackW, hTrackY);
                }

                // Thumb Pill Calculation
                int totalW = maxScrollX - minScrollX + w;
                int thumbW = Math.Max(40, (int)((float)w / totalW * hTrackW));
                thumbW = Math.Min(thumbW, hTrackW);
                float fracX = (float)(CanvasScrollX - minScrollX) / Math.Max(1, maxScrollX - minScrollX);
                int thumbX = hTrackX + (int)(fracX * (hTrackW - thumbW));
                Rectangle hThumbRect = new Rectangle(thumbX + 2, hTrackY + 2, Math.Max(20, thumbW - 4), sbH - 4);

                // Thumb Colors (Active Drag / Hover / Default)
                Color thumbCol = IsDraggingHScrollBar ? Color.FromArgb(100, 100, 100) : (IsHoverHScrollBarThumb ? Color.FromArgb(145, 145, 145) : Color.FromArgb(188, 188, 188));
                using (SolidBrush thumbBrush = new SolidBrush(thumbCol))
                {
                    FillRoundedPill(g, thumbBrush, hThumbRect);
                }
            }

            if (hasVScroll)
            {
                int vTrackH = hasHScroll ? (stageH - sbH) : stageH;
                int vTrackX = x + w - sbW;
                int vTrackY = y;
                Rectangle vTrackRect = new Rectangle(vTrackX, vTrackY, sbW, vTrackH);

                // Track Background & Left subtle border
                using (SolidBrush trackBg = new SolidBrush(Color.FromArgb(243, 243, 243)))
                using (Pen trackBorder = new Pen(Color.FromArgb(226, 226, 226), 1.0f))
                {
                    g.FillRectangle(trackBg, vTrackRect);
                    g.DrawLine(trackBorder, vTrackX, vTrackY, vTrackX, vTrackY + vTrackH);
                }

                // Thumb Pill Calculation
                int totalH = maxScrollY - minScrollY + stageH;
                int thumbH = Math.Max(40, (int)((float)stageH / totalH * vTrackH));
                thumbH = Math.Min(thumbH, vTrackH);
                float fracY = (float)(CanvasScrollY - minScrollY) / Math.Max(1, maxScrollY - minScrollY);
                int thumbY = vTrackY + (int)(fracY * (vTrackH - thumbH));
                Rectangle vThumbRect = new Rectangle(vTrackX + 2, thumbY + 2, sbW - 4, Math.Max(20, thumbH - 4));

                // Thumb Colors (Active Drag / Hover / Default)
                Color thumbCol = IsDraggingVScrollBar ? Color.FromArgb(100, 100, 100) : (IsHoverVScrollBarThumb ? Color.FromArgb(145, 145, 145) : Color.FromArgb(188, 188, 188));
                using (SolidBrush thumbBrush = new SolidBrush(thumbCol))
                {
                    FillRoundedPill(g, thumbBrush, vThumbRect);
                }
            }

            if (hasHScroll && hasVScroll)
            {
                Rectangle cornerRect = new Rectangle(x + w - sbW, y + stageH - sbH, sbW, sbH);
                using (SolidBrush cornerBg = new SolidBrush(Color.FromArgb(243, 243, 243)))
                {
                    g.FillRectangle(cornerBg, cornerRect);
                }
            }

            // Render PowerPoint-Style Bottom Speaker Notes Pane (Khung Ghi chú cho người thuyết trình)
            if (notesPaneH > 0)
            {
                Rectangle notesPaneRect = new Rectangle(x, y + stageH, w, notesPaneH);
                using (SolidBrush notesBg = new SolidBrush(IsEditingSpeakerNotes ? Color.White : Color.FromArgb(250, 251, 253)))
                {
                    g.FillRectangle(notesBg, notesPaneRect);
                }

                bool splitterActive = IsDraggingNotesSplitter || IsHoverNotesSplitter;
                Color splitterCol = splitterActive ? Color.FromArgb(210, 71, 38) : Color.FromArgb(214, 218, 224);
                using (Pen splitPen = new Pen(splitterCol, splitterActive ? 2.0f : 1.0f))
                {
                    g.DrawLine(splitPen, x, notesPaneRect.Y, x + w, notesPaneRect.Y);
                }

                // Centered grab pill on top splitter
                Rectangle pillRect = new Rectangle(x + w / 2 - 18, notesPaneRect.Y + 2, 36, 3);
                using (SolidBrush pillBrush = new SolidBrush(splitterActive ? Color.FromArgb(210, 71, 38) : Color.FromArgb(196, 202, 212)))
                {
                    FillRoundedPill(g, pillBrush, pillRect);
                }

                if (IsEditingSpeakerNotes)
                {
                    using (SolidBrush activeBar = new SolidBrush(Color.FromArgb(210, 71, 38)))
                    {
                        g.FillRectangle(activeBar, x, notesPaneRect.Y + 1, 3, notesPaneH - 1);
                    }
                }

                using (Font iconFont = new Font("Segoe UI", 9.5f, FontStyle.Regular))
                using (SolidBrush iconBrush = new SolidBrush(IsEditingSpeakerNotes ? Color.FromArgb(210, 71, 38) : Color.FromArgb(100, 116, 139)))
                {
                    g.DrawString("📝", iconFont, iconBrush, x + 10, notesPaneRect.Y + 8);
                }

                Rectangle notesTextRect = new Rectangle(x + 34, notesPaneRect.Y + 8, Math.Max(60, w - 46), Math.Max(18, notesPaneH - 12));
                DrawInteractiveSpeakerNotesContent(
                    g,
                    notesTextRect,
                    10.0f,
                    Color.FromArgb(30, 41, 59),
                    Color.FromArgb(148, 163, 184),
                    Color.FromArgb(210, 71, 38),
                    "Nhấp để thêm ghi chú");
            }

            // Render Chroma Key Eyedropper Loupe on Top
            if (IsColorPickingMode && HasColorPickHover)
            {
                DrawColorPickLoupe(g, ColorPickMouseCanvasPos, ColorPickHoverColor);
            }
        }

        public void DrawInteractiveSpeakerNotesContent(D2DGraphics g, RectangleF textBounds, float fontSize, bool isDark)
        {
            Rectangle r = new Rectangle((int)textBounds.X, (int)textBounds.Y, (int)textBounds.Width, (int)textBounds.Height);
            if (isDark)
            {
                DrawInteractiveSpeakerNotesContent(
                    g,
                    r,
                    fontSize,
                    Color.FromArgb(241, 245, 249),
                    Color.FromArgb(148, 163, 184),
                    Color.FromArgb(249, 115, 22),
                    "(Nhấp vào đây để nhập ghi chú cho người thuyết trình...)");
            }
            else
            {
                DrawInteractiveSpeakerNotesContent(
                    g,
                    r,
                    fontSize,
                    Color.FromArgb(30, 41, 59),
                    Color.FromArgb(148, 163, 184),
                    Color.FromArgb(210, 71, 38),
                    "(Nhấp vào đây để thêm ghi chú diễn giả...)");
            }
        }

        public void DrawInteractiveSpeakerNotesContent(D2DGraphics g, Rectangle textAreaRect, float fontSize, Color textColor, Color placeholderColor, Color caretColor, string placeholderText)
        {
            if (textAreaRect.Width <= 4 || textAreaRect.Height <= 4) return;
            LastNotesTextRect = textAreaRect;
            LastNotesFontSize = fontSize;

            string notes = (ActiveSlide != null && ActiveSlide.SpeakerNotes != null) ? ActiveSlide.SpeakerNotes : "";
            bool hasText = !string.IsNullOrEmpty(notes);

            GraphicsState clipState = g.Save();
            g.IntersectClip(textAreaRect);

            try
            {
                using (Font notesFont = new Font("Segoe UI", fontSize, FontStyle.Regular))
                {
                    if (!hasText && !IsEditingSpeakerNotes)
                    {
                        using (SolidBrush phBrush = new SolidBrush(placeholderColor))
                        {
                            g.DrawString(placeholderText, notesFont, phBrush, textAreaRect.X, textAreaRect.Y);
                        }
                        return;
                    }

                    float wrapW = Math.Max(40f, textAreaRect.Width - 6f);
                    List<VisualTextLine> visualLines = GetVisualWrappedLines(g, notes, notesFont, wrapW);
                    float lineHeight = Math.Max(16f, notesFont.Height);
                    int maxScrollY = Math.Max(0, (int)(visualLines.Count * lineHeight - textAreaRect.Height + 6));
                    NotesScrollY = Math.Max(0, Math.Min(maxScrollY, NotesScrollY));
                    float startY = textAreaRect.Y - NotesScrollY;

                    if (IsEditingSpeakerNotes && SpeakerNotesSelectionLength != 0)
                    {
                        int selStart = Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength);
                        int selEnd = Math.Max(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength);
                        using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(95, 59, 130, 246)))
                        {
                            for (int li = 0; li < visualLines.Count; li++)
                            {
                                VisualTextLine vl = visualLines[li];
                                int lineStart = vl.StartCharIndex;
                                int lineEnd = vl.StartCharIndex + vl.Length;
                                if (selEnd > lineStart && selStart < lineEnd)
                                {
                                    int subStart = Math.Max(0, selStart - lineStart);
                                    int subEnd = Math.Min(vl.Length, selEnd - lineStart);
                                    string pre = vl.Text.Substring(0, Math.Min(subStart, vl.Text.Length));
                                    string selTxt = vl.Text.Substring(subStart, Math.Min(subEnd - subStart, vl.Text.Length - subStart));
                                    float preW = g.MeasureString(pre, notesFont, PointF.Empty, StringFormat.GenericTypographic).Width;
                                    float selW = Math.Max(4f, g.MeasureString(selTxt, notesFont, PointF.Empty, StringFormat.GenericTypographic).Width);
                                    float curY = startY + li * lineHeight;
                                    g.FillRectangle(selBrush, textAreaRect.X + preW, curY, selW, lineHeight);
                                }
                            }
                        }
                    }

                    if (hasText)
                    {
                        using (SolidBrush txtBrush = new SolidBrush(textColor))
                        {
                            for (int li = 0; li < visualLines.Count; li++)
                            {
                                float curY = startY + li * lineHeight;
                                if (curY + lineHeight < textAreaRect.Top - 4 || curY > textAreaRect.Bottom + 4) continue;
                                string lineText = visualLines[li].Text;
                                if (string.IsNullOrEmpty(lineText)) continue;
                                g.DrawString(lineText.TrimEnd('\r', '\n'), notesFont, txtBrush, textAreaRect.X, curY, StringFormat.GenericTypographic);
                            }
                        }
                    }

                    if (IsEditingSpeakerNotes)
                    {
                        int caret = Math.Max(0, Math.Min(SpeakerNotesCaretIndex, notes.Length));
                        int curLineIdx = Math.Max(0, visualLines.Count - 1);
                        int colInLine = visualLines.Count > 0 ? visualLines[curLineIdx].Length : 0;
                        for (int i = 0; i < visualLines.Count; i++)
                        {
                            if (caret <= visualLines[i].StartCharIndex + visualLines[i].Length)
                            {
                                curLineIdx = i;
                                colInLine = caret - visualLines[i].StartCharIndex;
                                break;
                            }
                        }

                        string cLineText = (curLineIdx < visualLines.Count) ? visualLines[curLineIdx].Text : "";
                        string beforeCaret = cLineText.Substring(0, Math.Min(colInLine, cLineText.Length));
                        float beforeWidth = g.MeasureString(beforeCaret, notesFont, PointF.Empty, StringFormat.GenericTypographic).Width;
                        float caretX = textAreaRect.X + beforeWidth;
                        float caretY = startY + curLineIdx * lineHeight;

                        using (Pen caretPen = new Pen(caretColor, 1.8f))
                        {
                            g.DrawLine(caretPen, caretX, caretY + 1f, caretX, caretY + lineHeight - 1f);
                        }
                    }
                }
            }
            finally
            {
                g.Restore(clipState);
            }
        }

        public int GetSpeakerNotesCharIndexFromPoint(Point mousePos, RectangleF textBounds, float fontSize)
        {
            return GetSpeakerNotesCharIndexFromPoint(mousePos, new Rectangle((int)textBounds.X, (int)textBounds.Y, (int)textBounds.Width, (int)textBounds.Height), fontSize);
        }

        public int GetSpeakerNotesCharIndexFromPoint(Point mousePos, Rectangle textAreaRect, float fontSize)
        {
            string notes = (ActiveSlide != null && ActiveSlide.SpeakerNotes != null) ? ActiveSlide.SpeakerNotes : "";
            if (string.IsNullOrEmpty(notes)) return 0;

            using (Font notesFont = new Font("Segoe UI", fontSize, FontStyle.Regular))
            using (D2DGraphics g = new D2DGraphics())
            {
                float wrapW = Math.Max(40f, textAreaRect.Width - 6f);
                List<VisualTextLine> visualLines = GetVisualWrappedLines(g, notes, notesFont, wrapW);
                if (visualLines.Count == 0) return 0;

                float lineHeight = Math.Max(16f, notesFont.Height);
                float startY = textAreaRect.Y - NotesScrollY;
                int lineIdx = (int)((mousePos.Y - startY) / lineHeight);
                lineIdx = Math.Max(0, Math.Min(visualLines.Count - 1, lineIdx));

                VisualTextLine vLine = visualLines[lineIdx];
                string lineText = vLine.Text ?? "";
                float clickRelX = mousePos.X - textAreaRect.X;
                if (clickRelX <= 0) return vLine.StartCharIndex;

                float cLineWidth = g.MeasureString(lineText, notesFont, PointF.Empty, StringFormat.GenericTypographic).Width;
                if (clickRelX >= cLineWidth) return vLine.StartCharIndex + vLine.Length;

                int bestCol = 0;
                float bestDist = float.MaxValue;
                for (int c = 0; c <= lineText.Length; c++)
                {
                    string sub = lineText.Substring(0, c);
                    float subW = g.MeasureString(sub, notesFont, PointF.Empty, StringFormat.GenericTypographic).Width;
                    float dist = Math.Abs(subW - clickRelX);
                    if (dist < bestDist)
                    {
                        bestDist = dist;
                        bestCol = c;
                    }
                }
                return vLine.StartCharIndex + bestCol;
            }
        }

        public void EnsureSpeakerNotesCaretVisible()
        {
            if (LastNotesTextRect.Width <= 4 || LastNotesTextRect.Height <= 4) return;
            string notes = (ActiveSlide != null && ActiveSlide.SpeakerNotes != null) ? ActiveSlide.SpeakerNotes : "";
            using (Font notesFont = new Font("Segoe UI", LastNotesFontSize > 0 ? LastNotesFontSize : 10.0f, FontStyle.Regular))
            using (D2DGraphics g = new D2DGraphics())
            {
                float wrapW = Math.Max(40f, LastNotesTextRect.Width - 6f);
                List<VisualTextLine> visualLines = GetVisualWrappedLines(g, notes, notesFont, wrapW);
                float lineHeight = Math.Max(16f, notesFont.Height);
                int caret = Math.Max(0, Math.Min(SpeakerNotesCaretIndex, notes.Length));
                int curLineIdx = Math.Max(0, visualLines.Count - 1);
                for (int i = 0; i < visualLines.Count; i++)
                {
                    if (caret <= visualLines[i].StartCharIndex + visualLines[i].Length)
                    {
                        curLineIdx = i;
                        break;
                    }
                }
                float caretTop = curLineIdx * lineHeight;
                float caretBottom = caretTop + lineHeight;
                if (caretTop < NotesScrollY)
                {
                    NotesScrollY = Math.Max(0, (int)caretTop);
                }
                else if (caretBottom > NotesScrollY + LastNotesTextRect.Height - 4)
                {
                    NotesScrollY = Math.Max(0, (int)(caretBottom - LastNotesTextRect.Height + 6));
                }
            }
        }

        private static void FillRoundedPill(D2DGraphics g, Brush brush, Rectangle r)
        {
            if (r.Width <= 0 || r.Height <= 0) return;
            int radius = Math.Min(r.Width, r.Height) / 2;
            if (radius <= 1)
            {
                g.FillRectangle(brush, r);
                return;
            }
            int d = radius * 2;
            using (GraphicsPath path = new GraphicsPath())
            {
                path.AddArc(r.X, r.Y, d, d, 180, 90);
                path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
                path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
                path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
                path.CloseFigure();
                g.FillPath(brush, path);
            }
        }

        public int GetTotalThumbContentHeight(int sidebarW = 210)
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0) return 0;
            int thumbX, thumbW, thumbH;
            GetThumbnailMetrics(sidebarW, out thumbX, out thumbW, out thumbH);
            int totalH = 10;
            bool currentCollapsed = false;
            for (int i = 0; i < Presentation.Slides.Count; i++)
            {
                SlideNode s = Presentation.Slides[i];
                if (s.IsSectionHeader || (i == 0 && HasAnySections() && string.IsNullOrEmpty(s.SectionName)))
                {
                    totalH += 24;
                    currentCollapsed = s.IsSectionCollapsed;
                }
                if (currentCollapsed) continue;
                totalH += thumbH + 14;
            }
            totalH += 30; // bottom comfort spacing
            return totalH;
        }

        public int GetMaxThumbScrollY()
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0) return 0;
            bool isIslandMode = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
            int paneW = isIslandMode ? 200 : 210;
            int viewH = (LastThumbViewportHeight > 0) ? LastThumbViewportHeight : Math.Max(100, 500);
            int totalH = GetTotalThumbContentHeight(paneW);
            return Math.Max(0, totalH - viewH);
        }

        public int GetSlideIndexFromScrollY(int scrollY, int sidebarW = 210)
        {
            if (Presentation == null || Presentation.Slides == null || Presentation.Slides.Count == 0) return 0;
            int thumbX, thumbW, thumbH;
            GetThumbnailMetrics(sidebarW, out thumbX, out thumbW, out thumbH);
            int curY = 10;
            bool currentCollapsed = false;
            for (int i = 0; i < Presentation.Slides.Count; i++)
            {
                SlideNode s = Presentation.Slides[i];
                if (s.IsSectionHeader || (i == 0 && HasAnySections() && string.IsNullOrEmpty(s.SectionName)))
                {
                    curY += 24;
                    currentCollapsed = s.IsSectionCollapsed;
                }
                if (currentCollapsed) continue;
                if (curY + thumbH / 2 >= scrollY)
                {
                    return i;
                }
                curY += thumbH + 14;
            }
            return Math.Max(0, Presentation.Slides.Count - 1);
        }

        public string GetSlideTitle(int slideIndex)
        {
            if (Presentation == null || Presentation.Slides == null || slideIndex < 0 || slideIndex >= Presentation.Slides.Count) return "";
            SlideNode slide = Presentation.Slides[slideIndex];
            if (slide == null || slide.Shapes == null) return "";
            foreach (ShapeNode sh in slide.Shapes)
            {
                if (sh == null) continue;
                if (!string.IsNullOrWhiteSpace(sh.Text))
                {
                    string t = sh.Text.Trim();
                    int nl = t.IndexOfAny(new char[] { '\r', '\n' });
                    if (nl >= 0) t = t.Substring(0, nl).Trim();
                    if (!string.IsNullOrWhiteSpace(t)) return t;
                }
            }
            return "Slide " + (slideIndex + 1);
        }

        public void EnsureSlideVisibleInThumbnails(int slideIndex)
        {
            if (_isDraggingThumbScrollBar) return;
            if (Presentation == null || Presentation.Slides == null || slideIndex < 0 || slideIndex >= Presentation.Slides.Count) return;
            bool isIslandMode = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
            int paneW = isIslandMode ? 200 : 210;
            int viewH = (LastThumbViewportHeight > 0) ? LastThumbViewportHeight : 500;
            int thumbX, thumbW, thumbH;
            GetThumbnailMetrics(paneW, out thumbX, out thumbW, out thumbH);

            int itemY = 10;
            bool currentCollapsed = false;
            for (int i = 0; i < slideIndex; i++)
            {
                SlideNode s = Presentation.Slides[i];
                if (s.IsSectionHeader || (i == 0 && HasAnySections() && string.IsNullOrEmpty(s.SectionName)))
                {
                    itemY += 24;
                    currentCollapsed = s.IsSectionCollapsed;
                }
                if (!currentCollapsed) itemY += thumbH + 14;
            }

            int targetY = (int)TargetThumbScrollY;
            if (itemY < targetY)
            {
                targetY = Math.Max(0, itemY - 10);
            }
            else if (itemY + thumbH > targetY + viewH)
            {
                targetY = itemY + thumbH - viewH + 20;
            }

            int maxScroll = GetMaxThumbScrollY();
            TargetThumbScrollY = Math.Max(0, Math.Min(maxScroll, targetY));
        }

        public void EnsureSlideVisibleInBottomStrip(int slideIndex, int canvasW = 800)
        {
            if (Presentation == null || Presentation.Slides == null || slideIndex < 0 || slideIndex >= Presentation.Slides.Count) return;
            int trackW = Math.Max(200, canvasW - 16 - 130);
            int cardW = 96;
            int itemX = slideIndex * cardW;
            int targetX = (int)TargetBottomThumbScrollX;
            if (itemX < targetX)
            {
                targetX = Math.Max(0, itemX - 20);
            }
            else if (itemX + cardW > targetX + trackW)
            {
                targetX = itemX + cardW - trackW + 30;
            }
            int totalBottomWidth = Presentation.Slides.Count * cardW + 60;
            int maxScroll = Math.Max(0, totalBottomWidth - trackW);
            TargetBottomThumbScrollX = Math.Max(0, Math.Min(maxScroll, targetX));
        }

        public bool UpdateSmoothScroll()
        {
            bool animating = false;

            // 1. Left Thumbnail Pane (ThumbScrollY) - Hiệu ứng cuộn siêu nhẹ, êm mượt chuẩn MS Office PowerPoint
            int maxThumbScroll = GetMaxThumbScrollY();
            TargetThumbScrollY = Math.Max(0, Math.Min(maxThumbScroll, (float)Math.Round(TargetThumbScrollY)));
            int prevThumbInt = (int)Math.Round(SmoothThumbScrollY);
            int targetThumbInt = (int)TargetThumbScrollY;

            if (prevThumbInt == targetThumbInt)
            {
                if (SmoothThumbScrollY != TargetThumbScrollY || ThumbScrollY != targetThumbInt)
                {
                    SmoothThumbScrollY = TargetThumbScrollY;
                    ThumbScrollY = targetThumbInt;
                }
            }
            else
            {
                float diffThumb = TargetThumbScrollY - SmoothThumbScrollY;
                float step = diffThumb * 0.24f; // Damping siêu nhẹ êm ái
                float maxStep = 60f; // Giới hạn tốc độ không bị giật dồn dập
                if (Math.Abs(step) > maxStep) step = Math.Sign(step) * maxStep;

                float nextSmooth = SmoothThumbScrollY + step;
                int nextInt = (int)Math.Round(nextSmooth);

                // Luôn tiến tối thiểu 1 pixel mỗi frame, triệt tiêu 100% hiện tượng dừng 1 rồi 0 rồi 1
                if (nextInt == prevThumbInt)
                {
                    nextInt = prevThumbInt + Math.Sign(diffThumb);
                    nextSmooth = nextInt;
                }

                if ((diffThumb > 0 && nextInt >= targetThumbInt) || (diffThumb < 0 && nextInt <= targetThumbInt))
                {
                    SmoothThumbScrollY = TargetThumbScrollY;
                    ThumbScrollY = targetThumbInt;
                }
                else
                {
                    SmoothThumbScrollY = Math.Max(0, Math.Min(maxThumbScroll, nextSmooth));
                    ThumbScrollY = nextInt;
                }
                animating = true;
            }

            // 2. Bottom Filmstrip (BottomThumbScrollX)
            TargetBottomThumbScrollX = (float)Math.Round(TargetBottomThumbScrollX);
            int prevBottomInt = (int)Math.Round(SmoothBottomThumbScrollX);
            int targetBottomInt = (int)TargetBottomThumbScrollX;

            if (prevBottomInt == targetBottomInt)
            {
                if (SmoothBottomThumbScrollX != TargetBottomThumbScrollX || BottomThumbScrollX != targetBottomInt)
                {
                    SmoothBottomThumbScrollX = TargetBottomThumbScrollX;
                    BottomThumbScrollX = targetBottomInt;
                }
            }
            else
            {
                float diffBottom = TargetBottomThumbScrollX - SmoothBottomThumbScrollX;
                float step = diffBottom * 0.24f;
                float maxStep = 60f;
                if (Math.Abs(step) > maxStep) step = Math.Sign(step) * maxStep;

                float nextSmooth = SmoothBottomThumbScrollX + step;
                int nextInt = (int)Math.Round(nextSmooth);

                if (nextInt == prevBottomInt)
                {
                    nextInt = prevBottomInt + Math.Sign(diffBottom);
                    nextSmooth = nextInt;
                }

                if ((diffBottom > 0 && nextInt >= targetBottomInt) || (diffBottom < 0 && nextInt <= targetBottomInt))
                {
                    SmoothBottomThumbScrollX = TargetBottomThumbScrollX;
                    BottomThumbScrollX = targetBottomInt;
                }
                else
                {
                    SmoothBottomThumbScrollX = nextSmooth;
                    BottomThumbScrollX = nextInt;
                }
                animating = true;
            }

            // 3. Canvas Scroll Y (CanvasScrollY)
            TargetCanvasScrollY = (float)Math.Round(TargetCanvasScrollY);
            int prevCanvasYInt = (int)Math.Round(SmoothCanvasScrollY);
            int targetCanvasYInt = (int)TargetCanvasScrollY;

            if (prevCanvasYInt == targetCanvasYInt)
            {
                if (SmoothCanvasScrollY != TargetCanvasScrollY || CanvasScrollY != targetCanvasYInt)
                {
                    SmoothCanvasScrollY = TargetCanvasScrollY;
                    CanvasScrollY = targetCanvasYInt;
                }
            }
            else
            {
                float diffCanvasY = TargetCanvasScrollY - SmoothCanvasScrollY;
                float step = diffCanvasY * 0.25f;
                float maxStep = 80f;
                if (Math.Abs(step) > maxStep) step = Math.Sign(step) * maxStep;

                float nextSmooth = SmoothCanvasScrollY + step;
                int nextInt = (int)Math.Round(nextSmooth);

                if (nextInt == prevCanvasYInt)
                {
                    nextInt = prevCanvasYInt + Math.Sign(diffCanvasY);
                    nextSmooth = nextInt;
                }

                if ((diffCanvasY > 0 && nextInt >= targetCanvasYInt) || (diffCanvasY < 0 && nextInt <= targetCanvasYInt))
                {
                    SmoothCanvasScrollY = TargetCanvasScrollY;
                    CanvasScrollY = targetCanvasYInt;
                }
                else
                {
                    SmoothCanvasScrollY = nextSmooth;
                    CanvasScrollY = nextInt;
                }
                animating = true;
            }

            // 4. Canvas Scroll X (CanvasScrollX)
            TargetCanvasScrollX = (float)Math.Round(TargetCanvasScrollX);
            int prevCanvasXInt = (int)Math.Round(SmoothCanvasScrollX);
            int targetCanvasXInt = (int)TargetCanvasScrollX;

            if (prevCanvasXInt == targetCanvasXInt)
            {
                if (SmoothCanvasScrollX != TargetCanvasScrollX || CanvasScrollX != targetCanvasXInt)
                {
                    SmoothCanvasScrollX = TargetCanvasScrollX;
                    CanvasScrollX = targetCanvasXInt;
                }
            }
            else
            {
                float diffCanvasX = TargetCanvasScrollX - SmoothCanvasScrollX;
                float step = diffCanvasX * 0.25f;
                float maxStep = 80f;
                if (Math.Abs(step) > maxStep) step = Math.Sign(step) * maxStep;

                float nextSmooth = SmoothCanvasScrollX + step;
                int nextInt = (int)Math.Round(nextSmooth);

                if (nextInt == prevCanvasXInt)
                {
                    nextInt = prevCanvasXInt + Math.Sign(diffCanvasX);
                    nextSmooth = nextInt;
                }

                if ((diffCanvasX > 0 && nextInt >= targetCanvasXInt) || (diffCanvasX < 0 && nextInt <= targetCanvasXInt))
                {
                    SmoothCanvasScrollX = TargetCanvasScrollX;
                    CanvasScrollX = targetCanvasXInt;
                }
                else
                {
                    SmoothCanvasScrollX = nextSmooth;
                    CanvasScrollX = nextInt;
                }
                animating = true;
            }

            // 5. Elements Drawer (ElementsScrollY)
            TargetElementsScrollY = (float)Math.Round(TargetElementsScrollY);
            int prevElemInt = (int)Math.Round(SmoothElementsScrollY);
            int targetElemInt = (int)TargetElementsScrollY;

            if (prevElemInt == targetElemInt)
            {
                if (SmoothElementsScrollY != TargetElementsScrollY || ElementsScrollY != targetElemInt)
                {
                    SmoothElementsScrollY = TargetElementsScrollY;
                    ElementsScrollY = targetElemInt;
                }
            }
            else
            {
                float diffElem = TargetElementsScrollY - SmoothElementsScrollY;
                float step = diffElem * 0.25f;
                float maxStep = 80f;
                if (Math.Abs(step) > maxStep) step = Math.Sign(step) * maxStep;

                float nextSmooth = SmoothElementsScrollY + step;
                int nextInt = (int)Math.Round(nextSmooth);

                if (nextInt == prevElemInt)
                {
                    nextInt = prevElemInt + Math.Sign(diffElem);
                    nextSmooth = nextInt;
                }

                if ((diffElem > 0 && nextInt >= targetElemInt) || (diffElem < 0 && nextInt <= targetElemInt))
                {
                    SmoothElementsScrollY = TargetElementsScrollY;
                    ElementsScrollY = targetElemInt;
                }
                else
                {
                    SmoothElementsScrollY = nextSmooth;
                    ElementsScrollY = nextInt;
                }
                animating = true;
            }

            // 6. ShapeTaskPane
            if (ShapeTaskPane != null && ShapeTaskPane.UpdateSmoothScroll())
            {
                animating = true;
            }

            return animating;
        }

        private void DrawLeftSlidePane(D2DGraphics g, int sidebarW, int y, int h)
        {
            bool isIsland = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
            int islandMarginX = 10;
            int islandMarginTop = 3;
            int islandMarginBtm = 8;

            Rectangle paneRect = isIsland
                ? new Rectangle(islandMarginX, y + islandMarginTop, sidebarW - islandMarginX, h - islandMarginTop - islandMarginBtm)
                : new Rectangle(0, y, sidebarW, h);

            if (isIsland)
            {
                // Fill behind island panel with workspace background so margins are seamless
                using (SolidBrush wsBrush = new SolidBrush(Color.FromArgb(240, 240, 240)))
                {
                    g.FillRectangle(wsBrush, 0, y, sidebarW, h);
                }

                // Island Card: Fluent 2 drop shadows for authentic floating card elevation
                using (GraphicsPath sp1 = CreateRoundedRectPath(new RectangleF(paneRect.X, paneRect.Y + 1.5f, paneRect.Width, paneRect.Height), 8f))
                using (SolidBrush sb1 = new SolidBrush(Color.FromArgb(8, 0, 0, 0)))
                {
                    g.FillPath(sb1, sp1);
                }
                using (GraphicsPath sp2 = CreateRoundedRectPath(new RectangleF(paneRect.X, paneRect.Y + 3.5f, paneRect.Width, paneRect.Height), 9f))
                using (SolidBrush sb2 = new SolidBrush(Color.FromArgb(12, 0, 0, 0)))
                {
                    g.FillPath(sb2, sp2);
                }

                // Island Card Surface (Pure White with subtle border)
                using (GraphicsPath cardPath = CreateRoundedRectPath(new RectangleF(paneRect.X, paneRect.Y, paneRect.Width, paneRect.Height), 8f))
                using (SolidBrush cardBg = new SolidBrush(Color.White))
                using (Pen cardBorder = new Pen(Color.FromArgb(218, 224, 233), 1.0f))
                {
                    g.FillPath(cardBg, cardPath);
                    g.DrawPath(cardBorder, cardPath);
                }
            }
            else
            {
                // Standard Classic Full-Height Left Sidebar
                using (SolidBrush leftBg = new SolidBrush(Color.FromArgb(248, 249, 250)))
                {
                    g.FillRectangle(leftBg, paneRect);
                }
                using (Pen borderPen = new Pen(Color.FromArgb(229, 231, 235), 1.0f))
                {
                    g.DrawLine(borderPen, sidebarW, y, sidebarW, y + h);
                }
            }

            // 1. Scrollable Thumbnail & Section Region
            int viewTop = paneRect.Y + 44;
            int viewH = Math.Max(10, paneRect.Height - 48);
            LastThumbViewportHeight = viewH;
            Rectangle scrollClipRect = new Rectangle(paneRect.X, viewTop, paneRect.Width, viewH);

            GraphicsState paneState = g.Save();
            g.SetClip(scrollClipRect);

            int thumbX, thumbW, thumbH;
            GetThumbnailMetrics(paneRect.Width, out thumbX, out thumbW, out thumbH);
            int actualThumbX = paneRect.X + thumbX;
            int thumbY = viewTop + 10 - ThumbScrollY;

            bool currentSectionCollapsed = false;

            using (Font numFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Font secFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font starFont = new Font("Segoe UI Emoji", 8.0f, FontStyle.Regular))
            {
                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    SlideNode s = Presentation.Slides[i];

                    // Section Header Check & Render
                    if (s.IsSectionHeader || (i == 0 && HasAnySections() && string.IsNullOrEmpty(s.SectionName)))
                    {
                        string secName = !string.IsNullOrEmpty(s.SectionName) ? s.SectionName : "Default Section";

                        // Check if active slide is in this section
                        int nextSecIdx = i + 1;
                        while (nextSecIdx < Presentation.Slides.Count && !Presentation.Slides[nextSecIdx].IsSectionHeader)
                        {
                            nextSecIdx++;
                        }
                        bool isCurrentSectionActive = (ActiveSlideIndex >= i && ActiveSlideIndex < nextSecIdx);

                        if (thumbY + 22 >= viewTop - 10 && thumbY <= viewTop + viewH + 20)
                        {
                            Color secCol = isCurrentSectionActive ? Color.FromArgb(185, 28, 28) : Color.FromArgb(51, 65, 85);
                            using (SolidBrush secBrush = new SolidBrush(secCol))
                            {
                                string tri = s.IsSectionCollapsed ? "▶" : "▲";
                                string countSuffix = s.IsSectionCollapsed ? (" (" + (nextSecIdx - i) + ")") : "";
                                g.DrawString(tri, secFont, secBrush, paneRect.X + 8, thumbY + 1);
                                g.DrawString(secName + countSuffix, secFont, secBrush, paneRect.X + 22, thumbY + 1);
                            }
                        }

                        currentSectionCollapsed = s.IsSectionCollapsed;
                        thumbY += 24;
                    }

                    if (currentSectionCollapsed)
                    {
                        continue;
                    }

                    Rectangle frameRect = new Rectangle(actualThumbX, thumbY, thumbW, thumbH);

                    if (thumbY + thumbH >= viewTop - 10 && thumbY <= viewTop + viewH + 20)
                    {
                        // Slide number badge
                        Brush numBrush = (i == ActiveSlideIndex) ? new SolidBrush(Color.FromArgb(210, 71, 38)) : Brushes.Gray;
                        g.DrawString((i + 1).ToString(), numFont, numBrush, paneRect.X + 8, thumbY + thumbH / 2 - 8);

                        // Hidden Slide Number Slashed Box (chuẩn PowerPoint)
                        if (s.IsHidden)
                        {
                            Rectangle numBox = new Rectangle(paneRect.X + 5, thumbY + thumbH / 2 - 10, 20, 18);
                            using (Pen slashPen = new Pen(Color.FromArgb(140, 140, 140), 1.2f))
                            {
                                g.DrawRectangle(slashPen, numBox);
                                g.DrawLine(slashPen, numBox.Left + 2, numBox.Bottom - 2, numBox.Right - 2, numBox.Top + 2);
                            }
                        }

                        // Star badge if transition is set
                        if (s.Transition != TransitionType.None)
                        {
                            g.DrawString("⭐", starFont, Brushes.Goldenrod, paneRect.X + 6, thumbY + thumbH / 2 + 8);
                        }

                        // Thumbnail slide canvas
                        g.FillRectangle((i == ActiveSlideIndex) ? Brushes.White : Brushes.WhiteSmoke, frameRect);

                        // Mini shape rendering chuẩn 100% như slide chính
                        EnsureSlideThumbnail(s);
                        if (s.ThumbnailCache != null)
                        {
                            g.DrawImage(s.ThumbnailCache, frameRect);
                        }

                        // Active PowerPoint Orange Border (drawn ON TOP to frame content cleanly)
                        Color frameCol = (i == ActiveSlideIndex) ? Color.FromArgb(210, 71, 38) : Color.FromArgb(220, 220, 220);
                        using (Pen framePen = new Pen(frameCol, (i == ActiveSlideIndex) ? 2.5f : 1.0f))
                        {
                            g.DrawRectangle(framePen, frameRect);
                        }

                        // Hidden Slide Badge & Dimming
                        if (s.IsHidden)
                        {
                            using (Pen slashPen = new Pen(Color.FromArgb(220, 239, 68, 68), 2.0f))
                            {
                                g.DrawLine(slashPen, paneRect.X + 6, thumbY + thumbH / 2 - 8, paneRect.X + 22, thumbY + thumbH / 2 + 8);
                            }
                            using (SolidBrush dimBg = new SolidBrush(Color.FromArgb(90, 0, 0, 0)))
                            {
                                g.FillRectangle(dimBg, frameRect);
                            }
                        }
                    }

                    thumbY += thumbH + 14;
                }
            }

            g.Restore(paneState);

            // 2. Fixed Top Header Bar with "+ Slide Mới" & "Nhân Bản" (Drawn ON TOP of scrolling thumbnails)
            if (isIsland)
            {
                using (Pen sepPen = new Pen(Color.FromArgb(241, 245, 249), 1.0f))
                {
                    g.DrawLine(sepPen, paneRect.X + 8, paneRect.Y + 43, paneRect.Right - 8, paneRect.Y + 43);
                }
                int btnW = (paneRect.Width - 24) / 2;
                BtnAddSlideBounds = new Rectangle(paneRect.X + 8, paneRect.Y + 8, btnW, 28);
                BtnDupSlideBounds = new Rectangle(BtnAddSlideBounds.Right + 8, paneRect.Y + 8, btnW, 28);
            }
            else
            {
                using (SolidBrush topHeaderBg = new SolidBrush(Color.FromArgb(248, 249, 250)))
                {
                    g.FillRectangle(topHeaderBg, 0, y, sidebarW, 44);
                }
                using (Pen sepPen = new Pen(Color.FromArgb(229, 231, 235), 1.0f))
                {
                    g.DrawLine(sepPen, 0, y + 43, sidebarW, y + 43);
                }
                BtnAddSlideBounds = new Rectangle(8, y + 8, 92, 28);
                BtnDupSlideBounds = new Rectangle(106, y + 8, 92, 28);
            }

            using (GraphicsPath ap = CreateRoundedRectPath(new RectangleF(BtnAddSlideBounds.X, BtnAddSlideBounds.Y, BtnAddSlideBounds.Width, BtnAddSlideBounds.Height), 4f))
            using (SolidBrush orangeBrush = new SolidBrush(Color.FromArgb(210, 71, 38)))
            {
                g.FillPath(orangeBrush, ap);
            }
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                StringFormat sfCenter = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                g.DrawString("➕ Slide Mới", btnFont, Brushes.White, BtnAddSlideBounds, sfCenter);
            }

            using (GraphicsPath dp = CreateRoundedRectPath(new RectangleF(BtnDupSlideBounds.X, BtnDupSlideBounds.Y, BtnDupSlideBounds.Width, BtnDupSlideBounds.Height), 4f))
            using (SolidBrush dupBg = new SolidBrush(Color.White))
            using (Pen dupBorder = new Pen(Color.FromArgb(203, 213, 225), 1f))
            {
                g.FillPath(dupBg, dp);
                g.DrawPath(dupBorder, dp);
            }
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            {
                StringFormat sfCenter = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                using (SolidBrush dupTxt = new SolidBrush(Color.FromArgb(51, 65, 85)))
                {
                    g.DrawString("📋 Nhân Bản", btnFont, dupTxt, BtnDupSlideBounds, sfCenter);
                }
            }

            // 3. Fast Vertical Scrollbar (Thanh cuộn nhanh)
            int totalContentH = GetTotalThumbContentHeight(paneRect.Width);
            int trackX = paneRect.Right - 9;
            int trackY = viewTop + 2;
            int trackW = 7;
            int trackH = Math.Max(10, viewH - 4);
            int maxScroll = GetMaxThumbScrollY();

            if (maxScroll > 0)
            {
                ThumbScrollBarTrackRect = new Rectangle(trackX - 3, trackY, trackW + 6, trackH);
                int thumbBarH = Math.Max(26, (int)((float)viewH / totalContentH * trackH));
                thumbBarH = Math.Min(thumbBarH, trackH);
                int availY = trackH - thumbBarH;
                int thumbBarY = trackY + (int)((float)ThumbScrollY / maxScroll * availY);
                thumbBarY = Math.Max(trackY, Math.Min(trackY + availY, thumbBarY));
                ThumbScrollBarThumbRect = new Rectangle(trackX, thumbBarY, trackW, thumbBarH);

                // Draw Track when hovering or dragging
                if (_isHoverThumbScrollBar || _isDraggingThumbScrollBar)
                {
                    using (GraphicsPath trkPath = CreateRoundedRectPath(new RectangleF(trackX, trackY, trackW, trackH), 3.5f))
                    using (SolidBrush trkBrush = new SolidBrush(Color.FromArgb(16, 0, 0, 0)))
                    {
                        g.FillPath(trkBrush, trkPath);
                    }
                }

                // Draw Thumb Pill Capsule
                Color thumbCol;
                if (_isDraggingThumbScrollBar)
                    thumbCol = Color.FromArgb(110, 115, 128);
                else if (_isHoverThumbScrollBarThumb)
                    thumbCol = Color.FromArgb(145, 152, 165);
                else
                    thumbCol = Color.FromArgb(195, 200, 208);

                using (GraphicsPath thumbPath = CreateRoundedRectPath(new RectangleF(trackX, thumbBarY, trackW, thumbBarH), 3.5f))
                using (SolidBrush thumbBrush = new SolidBrush(thumbCol))
                {
                    g.FillPath(thumbBrush, thumbPath);
                }

                // 4. Fast Scroll Callout Badge Tooltip (PowerPoint Signature Feature)
                if (_isDraggingThumbScrollBar)
                {
                    int previewIdx = GetSlideIndexFromScrollY(ThumbScrollY, paneRect.Width);
                    string slideNumStr = string.Format("Slide {0} / {1}", previewIdx + 1, Presentation.Slides.Count);
                    string slideTitle = GetSlideTitle(previewIdx);

                    int badgeW = 210;
                    int badgeH = 46;
                    int badgeX = isIsland ? (paneRect.Right + 8) : (sidebarW + 8);
                    int badgeY = thumbBarY - badgeH / 2 + thumbBarH / 2;
                    badgeY = Math.Max(viewTop, Math.Min(viewTop + viewH - badgeH, badgeY));

                    Rectangle badgeRect = new Rectangle(badgeX, badgeY, badgeW, badgeH);

                    // Badge Drop Shadow
                    using (GraphicsPath sPath = CreateRoundedRectPath(new RectangleF(badgeRect.X + 2, badgeRect.Y + 2, badgeRect.Width, badgeRect.Height), 6f))
                    using (SolidBrush sBrush = new SolidBrush(Color.FromArgb(45, 0, 0, 0)))
                    {
                        g.FillPath(sBrush, sPath);
                    }

                    // Badge Container
                    using (GraphicsPath bPath = CreateRoundedRectPath(new RectangleF(badgeRect.X, badgeRect.Y, badgeRect.Width, badgeRect.Height), 6f))
                    using (SolidBrush bBg = new SolidBrush(Color.FromArgb(235, 28, 33, 44)))
                    using (Pen bPen = new Pen(Color.FromArgb(60, 255, 255, 255), 1.0f))
                    {
                        g.FillPath(bBg, bPath);
                        g.DrawPath(bPen, bPath);
                    }

                    // Pointing Arrow
                    PointF[] arrowPts = new PointF[]
                    {
                        new PointF(badgeX, thumbBarY + thumbBarH / 2),
                        new PointF(badgeX + 6, thumbBarY + thumbBarH / 2 - 5),
                        new PointF(badgeX + 6, thumbBarY + thumbBarH / 2 + 5)
                    };
                    using (SolidBrush arrowBrush = new SolidBrush(Color.FromArgb(235, 28, 33, 44)))
                    {
                        g.FillPolygon(arrowBrush, arrowPts);
                    }

                    using (Font bTitleFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
                    using (Font bSubFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
                    {
                        g.DrawString(slideNumStr, bTitleFont, Brushes.White, badgeRect.X + 10, badgeRect.Y + 6);
                        using (SolidBrush subBrush = new SolidBrush(Color.FromArgb(200, 210, 225)))
                        using (StringFormat sfSub = new StringFormat { Trimming = StringTrimming.EllipsisCharacter, FormatFlags = StringFormatFlags.NoWrap })
                        {
                            RectangleF subRect = new RectangleF(badgeRect.X + 10, badgeRect.Y + 24, badgeRect.Width - 20, 16);
                            g.DrawString(slideTitle, bSubFont, subBrush, subRect, sfSub);
                        }
                    }
                }
            }
            else
            {
                ThumbScrollBarTrackRect = Rectangle.Empty;
                ThumbScrollBarThumbRect = Rectangle.Empty;
            }
        }

        public bool HasAnySections()
        {
            if (Presentation == null) return false;
            for (int i = 0; i < Presentation.Slides.Count; i++)
            {
                if (Presentation.Slides[i].IsSectionHeader) return true;
            }
            return false;
        }

        private void DrawRightSidebarPanel(D2DGraphics g, int x, int y, int w, int h)
        {
            if (!IsSidebarOpen) return;

            // Task pane background
            using (SolidBrush sbBg = new SolidBrush(Color.FromArgb(250, 250, 250)))
            {
                g.FillRectangle(sbBg, x, y, w, h);
            }
            using (Pen borderPen = new Pen(Color.FromArgb(220, 220, 220), 1.0f))
            {
                g.DrawLine(borderPen, x, y, x, y + h);
            }

            // Microsoft PowerPoint Task Pane Header:
            string paneTitle = "Khung Hoạt Họa";
            if (SidebarPanel == SidebarPanelType.Properties) paneTitle = "Định Dạng Hình Dạng";
            else if (SidebarPanel == SidebarPanelType.SlideTransitions) paneTitle = "Chuyển Tiếp Trang Chiếu";
            else if (SidebarPanel == SidebarPanelType.Navigator) paneTitle = "Bộ Chọn Đối Tượng";
            else if (SidebarPanel == SidebarPanelType.FormatBackground) paneTitle = "Format Background";
            else if (SidebarPanel == SidebarPanelType.SelectionPane) paneTitle = "Lựa chọn (Selection)";
            else if (SidebarPanel == SidebarPanelType.Designer) paneTitle = "✨ Ý Tưởng Thiết Kế (Designer)";

            Rectangle headerRect = new Rectangle(x, y, w, 36);
            using (SolidBrush headerBg = new SolidBrush(Color.FromArgb(243, 243, 243)))
            {
                g.FillRectangle(headerBg, headerRect);
            }
            using (Pen headerBorder = new Pen(Color.FromArgb(225, 225, 225), 1.0f))
            {
                g.DrawLine(headerBorder, x, y + 36, x + w, y + 36);
            }

            using (Font titleHeaderFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            {
                g.DrawString(paneTitle, titleHeaderFont, Brushes.Black, x + 12, y + 9);
            }

            // Close button '✕' on top-right
            Rectangle closeBtnRect = new Rectangle(x + w - 28, y + 7, 22, 22);
            using (Font closeFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            {
                g.DrawString("✕", closeFont, Brushes.Gray, closeBtnRect.X + 4, closeBtnRect.Y + 2);
            }

            int panelY = y + 42 + SidebarScrollY;

            using (Font titleFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            using (Font labelFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                switch (SidebarPanel)
                {
                    case SidebarPanelType.AnimationPane:
                        DrawAnimationPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.SlideTransitions:
                        DrawTransitionsPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.Properties:
                        DrawFormatPropertiesPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.Navigator:
                        DrawNavigatorPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.FormatBackground:
                        DrawFormatBackgroundPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.SelectionPane:
                        DrawSelectionPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;

                    case SidebarPanelType.Designer:
                        DrawDesignerPaneContent(g, x, panelY, w, h - 42, titleFont, labelFont, boldFont);
                        break;
                }
            }
        }

        private void DrawDesignerPaneContent(D2DGraphics g, int x, int panelY, int w, int h, Font titleFont, Font labelFont, Font boldFont)
        {
            if (ActiveSlide == null) return;
            var ideas = GetDesignIdeasForCurrentSlide();

            using (SolidBrush subBrush = new SolidBrush(Color.FromArgb(100, 116, 139)))
            using (Font subFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            {
                g.DrawString("Chọn một bố cục để áp dụng ngay vào slide:", subFont, subBrush, x + 12, panelY);
            }

            int cardStartY = panelY + 22;
            int cardW = w - 24;
            int cardH = 152;
            int cardGap = 14;

            for (int i = 0; i < ideas.Count; i++)
            {
                var idea = ideas[i];
                int cy = cardStartY + i * (cardH + cardGap);
                if (cy + cardH < panelY - 40 || cy > panelY + h + 40) continue;

                Rectangle cardRect = new Rectangle(x + 12, cy, cardW, cardH);
                bool isHovered = (_hoveredDesignerIdeaIndex == i);

                using (SolidBrush bgB = new SolidBrush(isHovered ? Color.FromArgb(240, 249, 255) : Color.White))
                using (Pen borderP = new Pen(isHovered ? Color.FromArgb(37, 99, 235) : Color.FromArgb(226, 232, 240), isHovered ? 1.5f : 1.0f))
                {
                    g.FillRectangle(bgB, cardRect);
                    g.DrawRectangle(borderP, cardRect);
                }

                // Mini preview graphic on top
                RectangleF previewRect = new RectangleF(cardRect.X + 8, cardRect.Y + 8, cardW - 16, 80);
                if (idea.DrawMiniPreview != null)
                {
                    g.DrawGdi(dg => idea.DrawMiniPreview(dg, previewRect));
                }
                using (Pen pBorder = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
                {
                    g.DrawRectangle(pBorder, previewRect.X, previewRect.Y, previewRect.Width, previewRect.Height);
                }

                // Title
                int textY = cardRect.Y + 94;
                using (SolidBrush titleB = new SolidBrush(Color.FromArgb(15, 23, 42)))
                {
                    g.DrawString(idea.Title, boldFont, titleB, cardRect.X + 8, textY);
                }

                // Description
                using (SolidBrush descB = new SolidBrush(Color.FromArgb(100, 116, 139)))
                using (Font descFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
                {
                    RectangleF descRect = new RectangleF(cardRect.X + 8, textY + 18, cardW - 16, 34);
                    g.DrawString(idea.Description, descFont, descB, descRect);
                }
            }
        }

        private void DrawSelectionPaneContent(D2DGraphics g, int x, int panelY, int w, int h, Font titleFont, Font labelFont, Font boldFont)
        {
            if (ActiveSlide == null) return;

            // Top action buttons (Matching Image 3)
            Rectangle btnShowAll = new Rectangle(x + 10, panelY, 86, 25);
            Rectangle btnHideAll = new Rectangle(x + 102, panelY, 80, 25);
            Rectangle btnMoveUp = new Rectangle(x + w - 58, panelY, 22, 25);
            Rectangle btnMoveDown = new Rectangle(x + w - 32, panelY, 22, 25);

            DrawInteractiveButton(g, btnShowAll, false, 3);
            g.DrawString("Hiện tất cả", labelFont, Brushes.Black, btnShowAll.X + 10, btnShowAll.Y + 5);

            DrawInteractiveButton(g, btnHideAll, false, 3);
            g.DrawString("Ẩn tất cả", labelFont, Brushes.Black, btnHideAll.X + 12, btnHideAll.Y + 5);

            DrawInteractiveButton(g, btnMoveUp, false, 3);
            g.DrawString("▲", labelFont, Brushes.DimGray, btnMoveUp.X + 4, btnMoveUp.Y + 5);

            DrawInteractiveButton(g, btnMoveDown, false, 3);
            g.DrawString("▼", labelFont, Brushes.DimGray, btnMoveDown.X + 4, btnMoveDown.Y + 5);

            // Shape Rows
            int listStartY = panelY + 34;
            int rowH = 28;

            for (int r = 0; r < ActiveSlide.Shapes.Count; r++)
            {
                int shapeIdx = ActiveSlide.Shapes.Count - 1 - r; // Top of list = front Z-index
                ShapeNode shape = ActiveSlide.Shapes[shapeIdx];
                int rowY = listStartY + r * rowH;
                Rectangle rowRect = new Rectangle(x + 10, rowY, w - 20, 26);

                bool isSelected = (shapeIdx == SelectedShapeIndex) || (SelectedShapeIndices != null && SelectedShapeIndices.Contains(shapeIdx));

                if (isSelected)
                {
                    using (SolidBrush selBg = new SolidBrush(Color.FromArgb(254, 215, 170))) // Soft peach highlight matching Image 3
                    using (Pen selPen = new Pen(Color.FromArgb(251, 146, 60), 1.0f))
                    {
                        g.FillRectangle(selBg, rowRect);
                        g.DrawRectangle(selPen, rowRect);
                    }
                }
                else
                {
                    using (SolidBrush rowBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    {
                        g.FillRectangle(rowBg, rowRect);
                    }
                }

                // If currently dragging, draw drop indicator line
                if (DraggingSelectionPaneIndex >= 0 && DraggingSelectionPaneTargetIndex == shapeIdx)
                {
                    using (Pen dropPen = new Pen(Color.FromArgb(225, 29, 72), 2.0f))
                    {
                        g.DrawLine(dropPen, rowRect.Left, rowRect.Top, rowRect.Right, rowRect.Top);
                    }
                }

                // Display Name
                string name = shape.GetDisplayName(shapeIdx);
                g.DrawString(name, isSelected ? boldFont : labelFont, isSelected ? Brushes.DarkRed : Brushes.Black, rowRect.X + 8, rowRect.Y + 5);

                // Eye Visibility Icon (on the right)
                Rectangle eyeRect = new Rectangle(rowRect.Right - 24, rowRect.Y + 3, 20, 20);
                DrawEyeVisibilityIcon(g, eyeRect.X, eyeRect.Y, shape.IsVisible);
            }
        }

        private void DrawEyeVisibilityIcon(D2DGraphics g, int x, int y, bool isVisible)
        {
            using (Pen p = new Pen(isVisible ? Color.FromArgb(51, 65, 85) : Color.FromArgb(148, 163, 184), 1.3f))
            {
                if (isVisible)
                {
                    g.DrawArc(p, x + 2, y + 3, 14, 10, 30, 120);
                    g.DrawArc(p, x + 2, y - 1, 14, 10, 210, 120);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(51, 65, 85)))
                    {
                        g.FillEllipse(b, x + 7, y + 5, 4, 4);
                    }
                }
                else
                {
                    g.DrawLine(p, x + 3, y + 7, x + 15, y + 7);
                }
            }
        }

        private void DrawAnimationPaneContent(D2DGraphics g, int x, int panelY, int w, int h, Font titleFont, Font labelFont, Font boldFont)
        {
            // Play / Stop preview button
            Rectangle btnPlay = new Rectangle(x + 10, panelY, w - 20, 26);
            g.FillRectangle(IsPlayingAnimationPreview ? Brushes.MistyRose : Brushes.AliceBlue, btnPlay);
            g.DrawRectangle(IsPlayingAnimationPreview ? Pens.Crimson : Pens.DodgerBlue, btnPlay);
            g.DrawString(IsPlayingAnimationPreview ? "⏹ Dừng phát xem trước" : "▶ Phát tất cả (Play All)", boldFont, IsPlayingAnimationPreview ? Brushes.Crimson : Brushes.Navy, btnPlay.X + 24, btnPlay.Y + 5);
            panelY += 34;

            SlideNode slide = ActiveSlide;
            if (slide == null || slide.Animations.Count == 0)
            {
                g.DrawString("Chưa có hiệu ứng hoạt họa trên slide này.", labelFont, Brushes.Gray, x + 12, panelY);
                panelY += 20;
                g.DrawString("Chọn một hình trên slide và bấm hiệu ứng trong Tab Hoạt họa (Animations).", labelFont, Brushes.DimGray, new RectangleF(x + 12, panelY, w - 24, 60));
                return;
            }

            int stepNumber = 0;

            for (int i = 0; i < slide.Animations.Count; i++)
            {
                ShapeAnimation anim = slide.Animations[i];
                Rectangle animBox = new Rectangle(x + 8, panelY, w - 16, 32);

                bool isSelected = (i == SelectedAnimationIndex);
                bool isPlaying = (IsPlayingAnimationPreview && ActivePlayingAnimIndex == i);
                bool isBeingDragged = (DraggingAnimationPaneIndex == i);

                // Đường dóng chỉ thị vị trí thả (Drop Indicator Line)
                if (DraggingAnimationPaneIndex >= 0 && DraggingAnimationPaneTargetIndex == i && DraggingAnimationPaneIndex != DraggingAnimationPaneTargetIndex)
                {
                    using (Pen dropPen = new Pen(Color.FromArgb(210, 71, 38), 2.5f))
                    using (SolidBrush dropB = new SolidBrush(Color.FromArgb(210, 71, 38)))
                    {
                        int lineY = (DraggingAnimationPaneIndex > i) ? animBox.Top - 2 : animBox.Bottom + 2;
                        g.DrawLine(dropPen, animBox.Left, lineY, animBox.Right, lineY);
                        Point[] leftArrow = new Point[] { new Point(animBox.Left, lineY - 4), new Point(animBox.Left + 6, lineY), new Point(animBox.Left, lineY + 4) };
                        Point[] rightArrow = new Point[] { new Point(animBox.Right, lineY - 4), new Point(animBox.Right - 6, lineY), new Point(animBox.Right, lineY + 4) };
                        g.FillPolygon(dropB, leftArrow);
                        g.FillPolygon(dropB, rightArrow);
                    }
                }

                if (isPlaying)
                {
                    g.FillRectangle(Brushes.LightYellow, animBox);
                    g.DrawRectangle(Pens.Orange, animBox);
                }
                else if (isBeingDragged)
                {
                    using (SolidBrush dragBg = new SolidBrush(Color.FromArgb(241, 245, 249)))
                    using (Pen dragPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f) { DashStyle = DashStyle.Dash })
                    {
                        g.FillRectangle(dragBg, animBox);
                        g.DrawRectangle(dragPen, animBox);
                    }
                }
                else if (isSelected)
                {
                    using (SolidBrush selB = new SolidBrush(Color.FromArgb(254, 215, 170)))
                    using (Pen selP = new Pen(Color.FromArgb(251, 146, 60), 1.2f))
                    {
                        g.FillRectangle(selB, animBox);
                        g.DrawRectangle(selP, animBox);
                    }
                }
                else
                {
                    g.FillRectangle(Brushes.White, animBox);
                    g.DrawRectangle(Pens.LightGray, animBox);
                }

                // Category color badge
                Color catCol = GetAnimationColor(anim.Type);
                using (SolidBrush catBrush = new SolidBrush(catCol))
                {
                    g.FillRectangle(catBrush, animBox.X + 2, animBox.Y + 2, 4, animBox.Height - 4);
                }

                // Click Step Indicator
                if (anim.Trigger == AnimationTrigger.OnClick || i == 0)
                {
                    stepNumber++;
                    g.DrawString(stepNumber.ToString(), boldFont, Brushes.DarkSlateGray, animBox.X + 8, animBox.Y + 7);
                }
                else if (anim.Trigger == AnimationTrigger.WithPrevious)
                {
                    g.DrawString("⁝", boldFont, Brushes.Gray, animBox.X + 10, animBox.Y + 7);
                }
                else // AfterPrevious
                {
                    g.DrawString("⏱", labelFont, Brushes.Gray, animBox.X + 8, animBox.Y + 8);
                }

                // Trigger icon
                string trigIcon = (anim.Trigger == AnimationTrigger.OnClick) ? "🖱️" : ((anim.Trigger == AnimationTrigger.WithPrevious) ? "⏱️" : "⏳");
                g.DrawString(trigIcon, labelFont, Brushes.Black, animBox.X + 24, animBox.Y + 8);

                // Shape name & animation type
                string shapeName = "Hình " + (i + 1);
                if (!string.IsNullOrEmpty(anim.ShapeId))
                {
                    for (int sIdx = 0; sIdx < slide.Shapes.Count; sIdx++)
                    {
                        if (slide.Shapes[sIdx].Id == anim.ShapeId)
                        {
                            shapeName = !string.IsNullOrEmpty(slide.Shapes[sIdx].Text)
                                ? (slide.Shapes[sIdx].Text.Length > 12 ? slide.Shapes[sIdx].Text.Substring(0, 12) + "..." : slide.Shapes[sIdx].Text)
                                : slide.Shapes[sIdx].Type.ToString();
                            break;
                        }
                    }
                }

                string animName = shapeName + " (" + anim.Type.ToString() + ")";
                if (animName.Length > 20) animName = animName.Substring(0, 20) + "...";
                g.DrawString(animName, boldFont, Brushes.Black, animBox.X + 44, animBox.Y + 7);

                // Timeline duration bar on the right
                int barW = Math.Min(45, (int)(anim.Duration * 30));
                Rectangle timeBar = new Rectangle(animBox.Right - barW - 20, animBox.Y + 9, barW, 14);
                using (SolidBrush barBrush = new SolidBrush(catCol))
                {
                    g.FillRectangle(barBrush, timeBar);
                }

                // Dropdown Options Arrow ▾
                g.DrawString("▾", boldFont, isSelected ? Brushes.DarkOrange : Brushes.Gray, animBox.Right - 16, animBox.Y + 6);

                panelY += 36;
            }

            // Bottom Reorder Toolbar (Move Earlier, Move Later, Remove)
            panelY += 8;
            Rectangle btnUp = new Rectangle(x + 10, panelY, 70, 24);
            Rectangle btnDown = new Rectangle(x + 85, panelY, 70, 24);
            Rectangle btnDel = new Rectangle(x + 160, panelY, w - 170, 24);

            DrawInteractiveButton(g, btnUp, false, 3);
            g.DrawString("▲ Sớm hơn", labelFont, Brushes.Black, btnUp.X + 4, btnUp.Y + 4);

            DrawInteractiveButton(g, btnDown, false, 3);
            g.DrawString("▼ Muộn hơn", labelFont, Brushes.Black, btnDown.X + 3, btnDown.Y + 4);

            DrawInteractiveButton(g, btnDel, false, 3);
            g.DrawString("🗑 Xóa", labelFont, Brushes.Crimson, btnDel.X + 8, btnDel.Y + 4);
        }

        public void ShowAnimationItemContextMenu(Control parentControl, Point screenPos, int animIndex)
        {
            SlideNode slide = ActiveSlide;
            if (slide == null || animIndex < 0 || animIndex >= slide.Animations.Count) return;
            ShapeAnimation anim = slide.Animations[animIndex];

            ContextMenuStrip menu = new ContextMenuStrip();
            menu.Font = new Font("Segoe UI", 9.0f);

            // 1. Triggers
            ToolStripMenuItem miClick = new ToolStripMenuItem("🖱️ Bắt đầu khi nhấp chuột (Start On Click)", null, (s, e) => {
                anim.Trigger = AnimationTrigger.OnClick;
                if (parentControl != null) parentControl.Invalidate();
            }) { Checked = (anim.Trigger == AnimationTrigger.OnClick) };

            ToolStripMenuItem miWith = new ToolStripMenuItem("⏱️ Bắt đầu cùng với trước đó (Start With Previous)", null, (s, e) => {
                anim.Trigger = AnimationTrigger.WithPrevious;
                if (parentControl != null) parentControl.Invalidate();
            }) { Checked = (anim.Trigger == AnimationTrigger.WithPrevious) };

            ToolStripMenuItem miAfter = new ToolStripMenuItem("⏳ Bắt đầu sau trước đó (Start After Previous)", null, (s, e) => {
                anim.Trigger = AnimationTrigger.AfterPrevious;
                if (parentControl != null) parentControl.Invalidate();
            }) { Checked = (anim.Trigger == AnimationTrigger.AfterPrevious) };

            menu.Items.Add(miClick);
            menu.Items.Add(miWith);
            menu.Items.Add(miAfter);
            menu.Items.Add(new ToolStripSeparator());

            // 2. Duration Presets
            ToolStripMenuItem miDur = new ToolStripMenuItem("⏱️ Thời lượng (Duration)");
            float[] durPresets = new float[] { 0.25f, 0.50f, 0.75f, 1.00f, 1.50f, 2.00f, 3.00f, 5.00f };
            foreach (float d in durPresets)
            {
                float targetD = d;
                ToolStripMenuItem dItem = new ToolStripMenuItem(string.Format("{0:0.00} giây", targetD), null, (s, e) => {
                    anim.Duration = targetD;
                    if (parentControl != null) parentControl.Invalidate();
                }) { Checked = Math.Abs(anim.Duration - targetD) < 0.05f };
                miDur.DropDownItems.Add(dItem);
            }
            menu.Items.Add(miDur);

            // 3. Delay Presets
            ToolStripMenuItem miDel = new ToolStripMenuItem("⏳ Độ trễ (Delay)");
            float[] delPresets = new float[] { 0.00f, 0.25f, 0.50f, 0.75f, 1.00f, 1.50f, 2.00f };
            foreach (float del in delPresets)
            {
                float targetDel = del;
                ToolStripMenuItem delItem = new ToolStripMenuItem(string.Format("{0:0.00} giây", targetDel), null, (s, e) => {
                    anim.Delay = targetDel;
                    if (parentControl != null) parentControl.Invalidate();
                }) { Checked = Math.Abs(anim.Delay - targetDel) < 0.05f };
                miDel.DropDownItems.Add(delItem);
            }
            menu.Items.Add(miDel);
            menu.Items.Add(new ToolStripSeparator());

            // 4. Move earlier / later
            ToolStripMenuItem miUp = new ToolStripMenuItem("▲ Di chuyển sớm hơn (Move Earlier)", null, (s, e) => {
                MoveAnimationEarlier(animIndex);
                if (parentControl != null) parentControl.Invalidate();
            }) { Enabled = (animIndex > 0) };

            ToolStripMenuItem miDown = new ToolStripMenuItem("▼ Di chuyển muộn hơn (Move Later)", null, (s, e) => {
                MoveAnimationLater(animIndex);
                if (parentControl != null) parentControl.Invalidate();
            }) { Enabled = (animIndex < slide.Animations.Count - 1) };

            ToolStripMenuItem miRemove = new ToolStripMenuItem("🗑 Xóa hoạt họa này (Remove)", null, (s, e) => {
                RemoveAnimation(animIndex);
                if (parentControl != null) parentControl.Invalidate();
            });

            menu.Items.Add(miUp);
            menu.Items.Add(miDown);
            menu.Items.Add(miRemove);

            menu.Show(parentControl != null ? parentControl.PointToScreen(screenPos) : screenPos);
        }

        private void DrawTransitionsPaneContent(D2DGraphics g, int x, int panelY, int w, int h, Font titleFont, Font labelFont, Font boldFont)
        {
            g.DrawString("✨ HIỆU ỨNG CHUYỂN TRANG", titleFont, Brushes.DarkOrange, x + 10, panelY);
            panelY += 26;

            Rectangle btnPreview = new Rectangle(x + 10, panelY, w - 20, 26);
            g.FillRectangle(Brushes.AliceBlue, btnPreview);
            g.DrawRectangle(Pens.DodgerBlue, btnPreview);
            g.DrawString("⭐ Xem trước hiệu ứng", boldFont, Brushes.Navy, btnPreview.X + 16, btnPreview.Y + 5);
            panelY += 34;

            string[] topTransitions = new string[] {
                "Morph (Biến hình) ⭐",
                "Fade (Mờ dần)",
                "Push (Đẩy slide)",
                "Wipe (Quét ngang)",
                "Split (Tách đôi)",
                "Reveal (Hiển thị)",
                "Zoom (Thu phóng)",
                "RandomBars (Thanh ngẫu nhiên)",
                "Cube (Khối hộp 3D)",
                "PageCurl (Lật góc trang)"
            };

            for (int i = 0; i < topTransitions.Length; i++)
            {
                Rectangle transBox = new Rectangle(x + 10, panelY, w - 20, 24);
                string enumName = topTransitions[i].Split(' ')[0];
                bool isSel = (ActiveSlide != null && ActiveSlide.Transition.ToString() == enumName);

                g.FillRectangle(isSel ? Brushes.Moccasin : Brushes.White, transBox);
                g.DrawRectangle(isSel ? Pens.OrangeRed : Pens.LightGray, transBox);
                g.DrawString(topTransitions[i], labelFont, isSel ? Brushes.DarkRed : Brushes.Black, transBox.X + 6, transBox.Y + 4);
                panelY += 28;
            }
        }

