        #region Other Presentation Views
        private void DrawOutlineView(D2DGraphics g, int x, int y, int w, int h)
        {
            g.FillRectangle(Brushes.White, x, y, w, h);
            int py = y + 20;
            using (Font titleFont = new Font("Segoe UI", 12.0f, FontStyle.Bold))
            using (Font bodyFont = new Font("Segoe UI", 10.0f, FontStyle.Regular))
            {
                g.DrawString("📋 CHẾ ĐỘ XEM DÀN BÀI (OUTLINE VIEW)", titleFont, Brushes.DarkOrange, x + 30, py);
                py += 35;

                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    SlideNode slide = Presentation.Slides[i];
                    g.DrawString("Slide " + (i + 1) + ": " + slide.Title, titleFont, (i == ActiveSlideIndex) ? Brushes.OrangeRed : Brushes.Black, x + 40, py);
                    py += 24;

                    foreach (ShapeNode shape in slide.Shapes)
                    {
                        if (!string.IsNullOrEmpty(shape.Text))
                        {
                            foreach (string line in shape.Text.Split('\n'))
                            {
                                g.DrawString("    • " + line, bodyFont, Brushes.DimGray, x + 60, py);
                                py += 20;
                            }
                        }
                    }
                    py += 10;
                }
            }
        }

        private void DrawNotesView(D2DGraphics g, int x, int y, int w, int h)
        {
            using (SolidBrush stageBg = new SolidBrush(Color.FromArgb(240, 240, 240)))
            {
                g.FillRectangle(stageBg, x, y, w, h);
            }

            int pageW = 480;
            int pageH = 640;
            int pageX = x + (w - pageW) / 2;
            int pageY = y + 20;

            Rectangle pageRect = new Rectangle(pageX, pageY, pageW, pageH);
            g.FillRectangle(Brushes.White, pageRect);
            g.DrawRectangle(Pens.Gray, pageRect);

            int miniW = pageW - 40;
            int miniH = miniW * 9 / 16;
            Rectangle miniRect = new Rectangle(pageX + 20, pageY + 20, miniW, miniH);

            SlideNode slide = ActiveSlide;
            if (slide != null)
            {
                DrawSlideBackground(g, miniRect, slide);
                float miniScale = (float)miniW / Presentation.CanvasWidth;
                GraphicsState miniState = g.Save();
                g.SetClip(miniRect);
                foreach (ShapeNode shape in slide.Shapes)
                {
                    try
                    {
                        DrawShape(g, miniRect.X, miniRect.Y, miniScale, shape, false);
                    }
                    catch { }
                }
                g.Restore(miniState);
                g.DrawRectangle(Pens.LightGray, miniRect);
            }

            int notesY = miniRect.Bottom + 20;
            int notesH = pageH - (notesY - pageY) - 20;
            Rectangle notesRect = new Rectangle(pageX + 20, notesY, miniW, notesH);
            using (Pen notesPen = new Pen(IsEditingSpeakerNotes ? Color.FromArgb(210, 71, 38) : Color.Silver, IsEditingSpeakerNotes ? 1.5f : 1f))
            {
                g.DrawRectangle(notesPen, notesRect);
            }

            using (Font headerFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            {
                g.DrawString("GHI CHÚ DIỄN GIẢ (SPEAKER NOTES):", headerFont, Brushes.DarkOrange, notesRect.X + 8, notesRect.Y + 8);
            }
            RectangleF notesTextBounds = new RectangleF(notesRect.X + 8, notesRect.Y + 30, Math.Max(40, notesRect.Width - 16), Math.Max(20, notesRect.Height - 38));
            DrawInteractiveSpeakerNotesContent(g, notesTextBounds, 10.5f, false);
        }

        private void DrawSlideSorterView(D2DGraphics g, int x, int y, int w, int h)
        {
            using (SolidBrush stageBg = new SolidBrush(Color.FromArgb(240, 240, 240)))
            {
                g.FillRectangle(stageBg, x, y, w, h);
            }

            int cardW = 240;
            int cardH = Presentation.IsWidescreen ? (cardW * 9 / 16) : (cardW * 3 / 4);
            int padding = 30;
            int cols = Math.Max(1, (w - padding) / (cardW + padding));

            using (Font titleFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            {
                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    int row = i / cols;
                    int col = i % cols;

                    int cx = x + padding + col * (cardW + padding);
                    int cy = y + padding + row * (cardH + padding + 30);

                    Rectangle cardRect = new Rectangle(cx, cy, cardW, cardH);
                    SlideNode s = Presentation.Slides[i];

                    g.FillRectangle(Brushes.White, cardRect);
                    Color borderCol = (i == ActiveSlideIndex) ? Color.FromArgb(210, 71, 38) : Color.LightGray;
                    using (Pen bPen = new Pen(borderCol, (i == ActiveSlideIndex) ? 2.5f : 1.0f))
                    {
                        g.DrawRectangle(bPen, cardRect);
                    }

                    float miniScale = (float)cardW / Presentation.CanvasWidth;
                    GraphicsState state = g.Save();
                    g.SetClip(cardRect);

                    DrawSlideBackground(g, cardRect, s);

                    foreach (ShapeNode shape in s.Shapes)
                    {
                        int mx = cx + (int)(shape.Transform.X * miniScale);
                        int my = cy + (int)(shape.Transform.Y * miniScale);
                        int mw = Math.Max(2, (int)(shape.Transform.Width * miniScale));
                        int mh = Math.Max(2, (int)(shape.Transform.Height * miniScale));

                        Color fillCol = Color.FromArgb(shape.FillColor | unchecked((int)0xFF000000));
                        using (SolidBrush miniBrush = new SolidBrush(fillCol))
                        {
                            g.FillRectangle(miniBrush, mx, my, mw, mh);
                        }
                    }
                    g.Restore(state);

                    g.DrawString("Slide " + (i + 1) + ": " + s.Title, titleFont, (i == ActiveSlideIndex) ? Brushes.DarkOrange : Brushes.Black, cx, cy + cardH + 6);
                }
            }
        }

        private void DrawSlideMasterView(D2DGraphics g, int x, int y, int w, int h)
        {
            using (SolidBrush stageBg = new SolidBrush(Color.FromArgb(240, 240, 240)))
            {
                g.FillRectangle(stageBg, x, y, w, h);
            }

            int slideW = (int)(960 * ZoomLevel);
            int slideH = (int)(540 * ZoomLevel);
            int slideX = x + (w - slideW) / 2;
            int slideY = y + (h - slideH) / 2;

            Rectangle masterRect = new Rectangle(slideX, slideY, slideW, slideH);
            g.FillRectangle(Brushes.White, masterRect);
            g.DrawRectangle(Pens.DarkRed, masterRect);

            using (Font titleFont = new Font("Segoe UI", 16.0f, FontStyle.Bold))
            using (Font subFont = new Font("Segoe UI", 10.0f, FontStyle.Italic))
            {
                g.DrawString("🎨 CHẾ ĐỘ XEM SLIDE MASTER TEMPLATE", titleFont, Brushes.DarkRed, slideX + 40, slideY + 40);
                g.DrawString("Định hình tiêu đề toàn cục, chân trang, phông chữ và bố cục định sẵn...", subFont, Brushes.DimGray, slideX + 40, slideY + 80);
            }
        }
        #endregion

        #region Mouse & Keyboard Interaction Handlers
        public void HandleMouseDown(Point mousePos, int width, int height, MouseButtons buttons = MouseButtons.Left, Control parentControl = null)
        {
            if (!IsPresenting && parentControl != null && parentControl.CanFocus)
            {
                bool isClickInSearchBox = (IsElementsDrawerOpen && ElementsDrawerSelectedTab == 1 && ShapeTaskPane != null && ShapeTaskPane.SearchBoxBounds.Contains(mousePos));
                if (!isClickInSearchBox)
                {
                    if (_shapeSearchBox != null && _shapeSearchBox.Focused)
                    {
                        if (parentControl is Form form) form.ActiveControl = null;
                        parentControl.Focus();
                    }
                    if (!parentControl.Focused)
                    {
                        parentControl.Focus();
                    }
                }
            }

            if (IsPresenting)
            {
                // Nếu đang ở Màn hình Đen Kết thúc Slide Show (chế độ toàn màn hình thường)
                if (!IsPresenterViewMode && IsEndSlideShowScreen)
                {
                    if (buttons == MouseButtons.Right)
                    {
                        IsEndSlideShowScreen = false;
                    }
                    else
                    {
                        IsEndSlideShowScreen = false;
                        StopPresenting();
                    }
                    return;
                }

                // 1. Nếu đang mở bảng chọn tất cả Slide (Slide Sorter Modal)
                if (IsSlideSorterModalOpen)
                {
                    // Nút đóng ✕
                    if (mousePos.Y >= 15 && mousePos.Y <= 55 && mousePos.X >= width - 155 && mousePos.X <= width - 35)
                    {
                        IsSlideSorterModalOpen = false;
                        return;
                    }

                    int cols = 4;
                    int cardW = (width - 120) / cols;
                    float ratio = Presentation.IsWidescreen ? (9.0f / 16.0f) : (3.0f / 4.0f);
                    int cardH = (int)(cardW * ratio);
                    int startX = 40;
                    int startY = 80;

                    for (int i = 0; i < Presentation.Slides.Count; i++)
                    {
                        int row = i / cols;
                        int col = i % cols;
                        int cx = startX + col * (cardW + 18);
                        int cy = startY + row * (cardH + 36);

                        Rectangle cardRect = new Rectangle(cx, cy, cardW, cardH);
                        if (cardRect.Contains(mousePos))
                        {
                            int prev = ActiveSlideIndex;
                            ActiveSlideIndex = i;
                            IsSlideSorterModalOpen = false;
                            TriggerTransition(prev, ActiveSlideIndex, false);
                            return;
                        }
                    }

                    // Nhấp ra ngoài đóng modal
                    IsSlideSorterModalOpen = false;
                    return;
                }

                // 2. Nếu đang ở Chế độ Diễn giả (Presenter View)
                if (IsPresenterViewMode)
                {
                    // Top Bar clicks
                    if (mousePos.Y <= 46)
                    {
                        // Nút Tạm dừng (210..310)
                        if (mousePos.X >= 210 && mousePos.X <= 310)
                        {
                            IsPresentationTimerPaused = !IsPresentationTimerPaused;
                            if (IsPresentationTimerPaused) LastPresentationPauseTime = DateTime.Now;
                            else PresentationStartTime += (DateTime.Now - LastPresentationPauseTime);
                            return;
                        }
                        // Nút Đặt lại (320..410)
                        if (mousePos.X >= 320 && mousePos.X <= 410)
                        {
                            PresentationStartTime = DateTime.Now;
                            PresentationPausedElapsed = TimeSpan.Zero;
                            IsPresentationTimerPaused = false;
                            return;
                        }
                        // Cài đặt hiển thị (420..590)
                        if (mousePos.X >= 420 && mousePos.X <= 590)
                        {
                            ShowDisplaySettingsMenu(parentControl, mousePos);
                            return;
                        }
                        // Kết thúc trình chiếu (width - 200..width - 16)
                        if (mousePos.X >= width - 200 && mousePos.X <= width - 16)
                        {
                            StopPresenting();
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        return;
                    }

                    // Bottom Bar clicks
                    if (mousePos.Y >= height - 65)
                    {
                        // Lùi (24..70)
                        if (mousePos.X >= 24 && mousePos.X <= 70)
                        {
                            PreviousPresenterStep();
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        // Tiến (160..206)
                        if (mousePos.X >= 160 && mousePos.X <= 206)
                        {
                            AdvancePresenterStep();
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        // Bút & Laser (240..350)
                        if (mousePos.X >= 240 && mousePos.X <= 350)
                        {
                            ShowPenOptionsMenu(parentControl, new Point(mousePos.X, height - 70));
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        // Tất cả Slide Grid (360..490)
                        if (mousePos.X >= 360 && mousePos.X <= 490)
                        {
                            IsSlideSorterModalOpen = true;
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        // Zoom (500..590)
                        if (mousePos.X >= 500 && mousePos.X <= 590)
                        {
                            IsSlideZoomActive = !IsSlideZoomActive;
                            SlideZoomCenter = new Point(width / 4, height / 2);
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        // Màn đen (600..720)
                        if (mousePos.X >= 600 && mousePos.X <= 720)
                        {
                            BlackScreenMode = !BlackScreenMode;
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        return;
                    }

                    // Nút Zoom chữ A- / A+ và Khung Ghi chú người thuyết trình (Speaker Notes)
                    int topH = 46;
                    int bottomH = 65;
                    int mainY = topH + 8;
                    int mainH = height - mainY - bottomH - 8;
                    int leftW = (int)(width * 0.58f);
                    int rightW = width - leftW - 24;
                    int rightX = leftW + 12;
                    int nextH = (int)(mainH * 0.44f);
                    int notesY = mainY + nextH + 10;
                    int notesH = mainH - nextH - 14;
                    if (mousePos.Y >= notesY && mousePos.Y <= notesY + 22)
                    {
                        if (mousePos.X >= width - 80 && mousePos.X <= width - 54)
                        {
                            PresenterNotesFontSize = Math.Max(10, PresenterNotesFontSize - 2);
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        if (mousePos.X >= width - 48 && mousePos.X <= width - 22)
                        {
                            PresenterNotesFontSize = Math.Min(28, PresenterNotesFontSize + 2);
                            if (parentControl != null) parentControl.Invalidate();
                            if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                    }

                    // Nhấp vào khung Ghi chú người thuyết trình để gõ / chỉnh sửa trực tiếp ngay trong Presenter View
                    Rectangle notesRect = new Rectangle(rightX, notesY + 24, rightW - 24, notesH - 24);
                    if (notesRect.Contains(mousePos) && ActiveSlide != null)
                    {
                        IsEditingSpeakerNotes = true;
                        RectangleF notesTextBounds = new RectangleF(notesRect.X + 10, notesRect.Y + 10, Math.Max(40, notesRect.Width - 20), Math.Max(20, notesRect.Height - 20));
                        SpeakerNotesCaretIndex = GetSpeakerNotesCharIndexFromPoint(mousePos, notesTextBounds, PresenterNotesFontSize);
                        SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                        SpeakerNotesSelectionLength = 0;
                        IsSelectingSpeakerNotes = (buttons == MouseButtons.Left);
                        if (parentControl != null) parentControl.Invalidate();
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    IsEditingSpeakerNotes = false;

                    // Kiểm tra nhấp vào Thanh điều khiển Video nổi (Video Floating Playback Bar) trong Presenter View
                    ShapeNode targetVideoInPres = HoveredVideoShape ?? SlideVideoPlayerManager.Instance.ActiveShape;
                    if (buttons == MouseButtons.Left && !LastVideoPlaybackBarBounds.IsEmpty && LastVideoPlaybackBarBounds.Contains(mousePos) && targetVideoInPres != null)
                    {
                        HoveredVideoShape = targetVideoInPres;
                        float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                        float barW = LastVideoPlaybackBarBounds.Width;
                        float playBtnW = 32f;
                        float volBtnW = 32f;
                        float timeTextW = (barW > 240f) ? 80f : 0f;
                        float scrubX = playBtnW + 8f;
                        float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);

                        if (relX < playBtnW)
                        {
                            SlideVideoPlayerManager.Instance.TogglePlay(targetVideoInPres, parentControl, default(Rectangle), true, () =>
                            {
                                if (InvalidateCallback != null) InvalidateCallback();
                            });
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        else if (relX >= barW - volBtnW)
                        {
                            SlideVideoPlayerManager.Instance.ToggleVolume();
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        else if (relX >= playBtnW && relX <= barW - volBtnW - (timeTextW > 0 ? timeTextW : 0f))
                        {
                            IsDraggingVideoScrubber = true;
                            float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                            float totalSec = targetVideoInPres.VideoTotalTime > 0 ? targetVideoInPres.VideoTotalTime : 120f;
                            SlideVideoPlayerManager.Instance.Seek(frac * totalSec);
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        return; // Prevent slide advance when clicking anywhere on the floating bar
                    }

                    // Kiểm tra nhấp vào Thanh điều khiển Âm thanh nổi (Audio Floating Playback Bar) trong Presenter View
                    ShapeNode targetAudioForBar = HoveredAudioShape ?? SlideAudioPlayerManager.Instance.ActiveShape;
                    if (buttons == MouseButtons.Left && !LastAudioPlaybackBarBounds.IsEmpty && LastAudioPlaybackBarBounds.Contains(mousePos) && targetAudioForBar != null)
                    {
                        HoveredAudioShape = targetAudioForBar;
                        float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                        float barW = LastAudioPlaybackBarBounds.Width;
                        float scrubX = 74f;
                        float scrubW = barW - 74f - 88f;

                        if (relX < 28f)
                        {
                            SlideAudioPlayerManager.Instance.TogglePlay(targetAudioForBar, parentControl);
                            _playedMediaShapesInPresentation.Add(targetAudioForBar);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= 28f && relX < 48f)
                        {
                            SlideAudioPlayerManager.Instance.StepRelative(targetAudioForBar, -0.25f, parentControl);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= 48f && relX < 68f)
                        {
                            SlideAudioPlayerManager.Instance.StepRelative(targetAudioForBar, 0.25f, parentControl);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= scrubX && relX <= scrubX + scrubW)
                        {
                            IsDraggingAudioScrubber = true;
                            float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                            float totalSec = targetAudioForBar.AudioTotalTime > 0 ? targetAudioForBar.AudioTotalTime : 180f;
                            if (!SlideAudioPlayerManager.Instance.IsPlaying || SlideAudioPlayerManager.Instance.ActiveShape != targetAudioForBar)
                            {
                                SlideAudioPlayerManager.Instance.Play(targetAudioForBar, parentControl);
                            }
                            SlideAudioPlayerManager.Instance.Seek(targetAudioForBar, frac * totalSec);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= barW - 28f)
                        {
                            SlideAudioPlayerManager.Instance.ToggleMute(targetAudioForBar);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                    }

                    // Chuẩn PowerPoint: CHỈ khi nhấp chuột BÊN TRONG khung Slide hiện tại (curSlideRect) mới phát video hoặc chuyển slide!
                    // Nhấp ra ngoài vùng nền đen hoặc vùng Slide tiếp theo sẽ KHÔNG chuyển slide.
                    int presSlideX, presSlideY, presSlideW, presSlideH;
                    float scaleP;
                    GetCurrentActiveSlidePresentationMetrics(width, height, out presSlideX, out presSlideY, out presSlideW, out presSlideH, out scaleP);
                    Rectangle curSlideRect = new Rectangle(presSlideX, presSlideY, presSlideW, presSlideH);

                    if (curSlideRect.Contains(mousePos))
                    {
                        if (IsEndSlideShowScreen)
                        {
                            if (buttons == MouseButtons.Right)
                            {
                                IsEndSlideShowScreen = false;
                            }
                            else if (buttons == MouseButtons.Left)
                            {
                                IsEndSlideShowScreen = false;
                                StopPresenting();
                            }
                        }
                        else if (buttons == MouseButtons.Left)
                        {
                            bool clickedMedia = false;
                            if (ActiveSlide != null && !AnnotationPenMode && !LaserPointerMode)
                            {
                                for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
                                {
                                    ShapeNode shape = ActiveSlide.Shapes[i];
                                    if (shape == null) continue;
                                    int sx = presSlideX + (int)(shape.Transform.X * scaleP);
                                    int sy = presSlideY + (int)(shape.Transform.Y * scaleP);
                                    int sw = (int)(shape.Transform.Width * scaleP);
                                    int sh = (int)(shape.Transform.Height * scaleP);

                                    if (mousePos.X >= sx && mousePos.X <= sx + sw && mousePos.Y >= sy && mousePos.Y <= sy + sh)
                                    {
                                        if (shape.Type == ShapeType.Video || !string.IsNullOrEmpty(shape.VideoPath))
                                        {
                                            HoveredVideoShape = shape;
                                            PlayVideoPreview(shape, parentControl);
                                            _playedMediaShapesInPresentation.Add(shape);
                                            clickedMedia = true;
                                            break;
                                        }
                                        else if (shape.Type == ShapeType.Audio || !string.IsNullOrEmpty(shape.AudioPath))
                                        {
                                            HoveredAudioShape = shape;
                                            SlideAudioPlayerManager.Instance.TogglePlay(shape, parentControl);
                                            _playedMediaShapesInPresentation.Add(shape);
                                            clickedMedia = true;
                                            break;
                                        }
                                        else if (shape.Type == ShapeType.SlideZoom || shape.Type == ShapeType.SummaryZoom || shape.ZoomTargetSlideIndex >= 0)
                                        {
                                            if (shape.ZoomTargetSlideIndex >= 0 && shape.ZoomTargetSlideIndex < Presentation.Slides.Count)
                                            {
                                                TriggerZoomNavigation(shape.ZoomTargetSlideIndex, shape.ZoomReturnToSlide);
                                                clickedMedia = true;
                                                break;
                                            }
                                        }
                                    }
                                }
                            }

                            if (!clickedMedia)
                            {
                                AdvancePresenterStep();
                            }
                        }
                        else if (buttons == MouseButtons.Right)
                        {
                            PreviousPresenterStep();
                        }
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                // 3. Chế độ Chiếu Fullscreen thông thường
                // Kiểm tra nhấp vào Thanh công cụ ghi thời gian Rehearsal Floating Toolbar
                if (IsRehearsingTimings && _rehearsalToolbarRect.Contains(mousePos))
                {
                    int rx = mousePos.X - _rehearsalToolbarRect.X;
                    int ry = mousePos.Y - _rehearsalToolbarRect.Y;

                    // Close button [✕]
                    if (rx >= _rehearsalToolbarRect.Width - 24 && ry <= 20)
                    {
                        StopPresenting();
                        return;
                    }

                    // Next button [➜]
                    if (rx >= 6 && rx <= 30 && ry >= 26)
                    {
                        AdvancePresenterStep();
                        if (parentControl != null) parentControl.Invalidate();
                        if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    // Pause / Resume button [❚❚] / [▶]
                    if (rx >= 34 && rx <= 58 && ry >= 26)
                    {
                        IsRehearsalPaused = !IsRehearsalPaused;
                        if (IsRehearsalPaused)
                        {
                            RehearsalSlideElapsed += DateTime.Now - RehearsalSlideStartTime;
                            RehearsalTotalElapsed += DateTime.Now - RehearsalTotalStartTime;
                        }
                        else
                        {
                            RehearsalSlideStartTime = DateTime.Now;
                            RehearsalTotalStartTime = DateTime.Now;
                        }
                        if (parentControl != null) parentControl.Invalidate();
                        if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    // Repeat button [↺]
                    if (rx >= 136 && rx <= 160 && ry >= 26)
                    {
                        RehearsalSlideStartTime = DateTime.Now;
                        RehearsalSlideElapsed = TimeSpan.Zero;
                        if (parentControl != null) parentControl.Invalidate();
                        if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    return;
                }

                // Kiểm tra nhấp vào Thanh công cụ nổi 6 nút ở góc dưới bên trái
                int clickedBtn = GetHoverToolbarButtonAt(mousePos, height);
                if (clickedBtn >= 0)
                {
                    switch (clickedBtn)
                    {
                        case 0: // < (Prev)
                            PreviousPresenterStep();
                            break;
                        case 1: // > (Next)
                            AdvancePresenterStep();
                            break;
                        case 2: // Pen & Laser Menu
                            ShowPenOptionsMenu(parentControl, new Point(24 + 2 * 36, height - 50));
                            break;
                        case 3: // Grid Modal
                            IsSlideSorterModalOpen = true;
                            break;
                        case 4: // Zoom
                            IsSlideZoomActive = !IsSlideZoomActive;
                            SlideZoomCenter = mousePos;
                            break;
                        case 5: // ... (More Options Context Menu)
                            ShowMoreOptionsMenu(parentControl, new Point(24 + 5 * 36, height - 50));
                            break;
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                if (buttons == MouseButtons.Right)
                {
                    ShowMoreOptionsMenu(parentControl, mousePos);
                    return;
                }

                if (AnnotationPenMode)
                {
                    CurrentStroke.Clear();
                    CurrentStroke.Add(mousePos);
                    return;
                }

                // Tiến bước / slide hoặc phát video
                if (buttons == MouseButtons.Left)
                {
                    // Check if clicked the Video Floating Playback Bar in Presentation Mode
                    ShapeNode targetVideoInFs = HoveredVideoShape ?? SlideVideoPlayerManager.Instance.ActiveShape;
                    if (!LastVideoPlaybackBarBounds.IsEmpty && LastVideoPlaybackBarBounds.Contains(mousePos) && targetVideoInFs != null)
                    {
                        HoveredVideoShape = targetVideoInFs;
                        float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                        float barW = LastVideoPlaybackBarBounds.Width;
                        float playBtnW = 32f;
                        float volBtnW = 32f;
                        float timeTextW = (barW > 240f) ? 80f : 0f;
                        float scrubX = playBtnW + 8f;
                        float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);

                        if (relX < playBtnW)
                        {
                            SlideVideoPlayerManager.Instance.TogglePlay(targetVideoInFs, parentControl, default(Rectangle), true, () =>
                            {
                                if (InvalidateCallback != null) InvalidateCallback();
                            });
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        else if (relX >= barW - volBtnW)
                        {
                            SlideVideoPlayerManager.Instance.ToggleVolume();
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        else if (relX >= playBtnW && relX <= barW - volBtnW - (timeTextW > 0 ? timeTextW : 0f))
                        {
                            IsDraggingVideoScrubber = true;
                            float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                            float totalSec = targetVideoInFs.VideoTotalTime > 0 ? targetVideoInFs.VideoTotalTime : 120f;
                            SlideVideoPlayerManager.Instance.Seek(frac * totalSec);
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                        return; // Prevent slide advance when clicking anywhere on the floating bar
                    }

                    // Check if clicked the Audio Floating Playback Bar in Fullscreen Presentation Mode
                    ShapeNode targetAudioForBar = HoveredAudioShape ?? SlideAudioPlayerManager.Instance.ActiveShape;
                    if (!LastAudioPlaybackBarBounds.IsEmpty && LastAudioPlaybackBarBounds.Contains(mousePos) && targetAudioForBar != null)
                    {
                        HoveredAudioShape = targetAudioForBar;
                        float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                        float barW = LastAudioPlaybackBarBounds.Width;
                        float scrubX = 74f;
                        float scrubW = barW - 74f - 88f;

                        if (relX < 28f)
                        {
                            SlideAudioPlayerManager.Instance.TogglePlay(targetAudioForBar, parentControl);
                            _playedMediaShapesInPresentation.Add(targetAudioForBar);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= 28f && relX < 48f)
                        {
                            SlideAudioPlayerManager.Instance.StepRelative(targetAudioForBar, -0.25f, parentControl);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= 48f && relX < 68f)
                        {
                            SlideAudioPlayerManager.Instance.StepRelative(targetAudioForBar, 0.25f, parentControl);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= scrubX && relX <= scrubX + scrubW)
                        {
                            IsDraggingAudioScrubber = true;
                            float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                            float totalSec = targetAudioForBar.AudioTotalTime > 0 ? targetAudioForBar.AudioTotalTime : 180f;
                            if (!SlideAudioPlayerManager.Instance.IsPlaying || SlideAudioPlayerManager.Instance.ActiveShape != targetAudioForBar)
                            {
                                SlideAudioPlayerManager.Instance.Play(targetAudioForBar, parentControl);
                            }
                            SlideAudioPlayerManager.Instance.Seek(targetAudioForBar, frac * totalSec);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else if (relX >= barW - 28f)
                        {
                            SlideAudioPlayerManager.Instance.ToggleMute(targetAudioForBar);
                            if (parentControl != null) parentControl.Invalidate();
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                    }

                    bool clickedVideo = false;
                    if (ActiveSlide != null)
                    {
                        int presSlideX, presSlideY, presSlideW, presSlideH;
                        float scaleP;
                        GetCurrentActiveSlidePresentationMetrics(width, height, out presSlideX, out presSlideY, out presSlideW, out presSlideH, out scaleP);

                        for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
                        {
                            ShapeNode shape = ActiveSlide.Shapes[i];
                            if (shape == null) continue;
                            int sx = presSlideX + (int)(shape.Transform.X * scaleP);
                            int sy = presSlideY + (int)(shape.Transform.Y * scaleP);
                            int sw = (int)(shape.Transform.Width * scaleP);
                            int sh = (int)(shape.Transform.Height * scaleP);
                            
                            if (mousePos.X >= sx && mousePos.X <= sx + sw && mousePos.Y >= sy && mousePos.Y <= sy + sh)
                            {
                                if (shape.Type == ShapeType.Video || !string.IsNullOrEmpty(shape.VideoPath))
                                {
                                    HoveredVideoShape = shape;
                                    PlayVideoPreview(shape, parentControl);
                                    _playedMediaShapesInPresentation.Add(shape);
                                    clickedVideo = true;
                                    break;
                                }
                                else if (shape.Type == ShapeType.Audio || !string.IsNullOrEmpty(shape.AudioPath))
                                {
                                    HoveredAudioShape = shape;
                                    SlideAudioPlayerManager.Instance.TogglePlay(shape, parentControl);
                                    _playedMediaShapesInPresentation.Add(shape);
                                    clickedVideo = true; // prevent slide advance
                                    break;
                                }
                                else if (shape.Type == ShapeType.SlideZoom || shape.Type == ShapeType.SummaryZoom || shape.ZoomTargetSlideIndex >= 0)
                                {
                                    if (shape.ZoomTargetSlideIndex >= 0 && shape.ZoomTargetSlideIndex < Presentation.Slides.Count)
                                    {
                                        TriggerZoomNavigation(shape.ZoomTargetSlideIndex, shape.ZoomReturnToSlide);
                                        clickedVideo = true; // prevent slide advance
                                        break;
                                    }
                                }
                            }
                        }
                    }

                    if (!clickedVideo)
                    {
                        AdvancePresenterStep();
                    }
                }
                if (parentControl != null) parentControl.Invalidate();
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (buttons == MouseButtons.Middle)
            {
                IsPanningCanvas = true;
                PanStartMouse = mousePos;
                PanStartScroll = new Point(CanvasScrollX, CanvasScrollY);
                return;
            }

            int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
            GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);
            int rightSidebarW = (IsSidebarOpen && SidebarPanel != SidebarPanelType.None && !IsPresenting) ? 280 : 0;

            if (IsElementsDrawerOpen)
            {
                // 1. Click in Elements Rail & Drawer (X <= leftSidebarW)
                if (mousePos.X <= leftSidebarW && mousePos.Y >= contentY && mousePos.Y <= height - 26)
                {
                    if (HandleElementsDrawerClick(mousePos, leftSidebarW, contentY, height - contentY - 26, parentControl))
                        return;
                }

                // 2. Click in Chevron Collapse Button
                if (!BtnCollapseDrawerBounds.IsEmpty && BtnCollapseDrawerBounds.Contains(mousePos))
                {
                    IsElementsDrawerCollapsed = !IsElementsDrawerCollapsed;
                    ZoomToFit();
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }

                // 3. Click in Bottom Horizontal Filmstrip
                if (bottomThumbH > 0 && mousePos.Y >= height - 26 - bottomThumbH && mousePos.Y <= height - 26 && mousePos.X >= canvasX)
                {
                    if (HandleBottomThumbnailStripClick(mousePos, canvasX, height - 26 - bottomThumbH, canvasW, bottomThumbH, parentControl))
                        return;
                }
            }
            else
            {
                // 1. Left Slide Pane Click
                bool isIsland = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
                int islandMarginX = 10;
                int islandMarginTop = 3;
                int islandMarginBtm = 8;
                Rectangle paneRect = isIsland
                    ? new Rectangle(islandMarginX, contentY + islandMarginTop, leftSidebarW - islandMarginX, contentH - islandMarginTop - islandMarginBtm)
                    : new Rectangle(0, contentY, leftSidebarW, contentH);

                if (ViewMode != ImpressViewMode.SlideSorter && (isIsland ? paneRect.Contains(mousePos) : mousePos.X <= leftSidebarW))
                {
                    IsDrawingShapeMode = false;
                    IsDrawingActive = false;

                // 1. Buttons "+ Slide Mới" & "Nhân Bản"
                if (!BtnAddSlideBounds.IsEmpty && BtnAddSlideBounds.Contains(mousePos))
                {
                    AddSlide();
                    return;
                }
                if (!BtnDupSlideBounds.IsEmpty && BtnDupSlideBounds.Contains(mousePos))
                {
                    DuplicateActiveSlide();
                    return;
                }

                // 2. Fast Scrollbar Thumb click (start drag)
                if (!ThumbScrollBarThumbRect.IsEmpty && ThumbScrollBarThumbRect.Contains(mousePos))
                {
                    _isDraggingThumbScrollBar = true;
                    _thumbScrollDragStartMouseY = mousePos.Y;
                    _thumbScrollDragStartScrollY = ThumbScrollY;
                    SmoothThumbScrollY = ThumbScrollY;
                    TargetThumbScrollY = ThumbScrollY;
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }

                // 3. Fast Scrollbar Track click (jump)
                if (!ThumbScrollBarTrackRect.IsEmpty && ThumbScrollBarTrackRect.Contains(mousePos))
                {
                    int trackH = ThumbScrollBarTrackRect.Height;
                    int thumbBarH = ThumbScrollBarThumbRect.Height;
                    int availY = trackH - thumbBarH;
                    int totalContentH = GetTotalThumbContentHeight(paneRect.Width);
                    int maxScroll = GetMaxThumbScrollY();
                    if (availY > 0 && maxScroll > 0)
                    {
                        float ratio = (float)(mousePos.Y - ThumbScrollBarTrackRect.Y - thumbBarH / 2) / availY;
                        ratio = Math.Max(0f, Math.Min(1f, ratio));
                        ThumbScrollY = (int)(ratio * maxScroll);
                        SmoothThumbScrollY = ThumbScrollY;
                        TargetThumbScrollY = ThumbScrollY;
                        _isDraggingThumbScrollBar = true;
                        _thumbScrollDragStartMouseY = mousePos.Y;
                        _thumbScrollDragStartScrollY = ThumbScrollY;
                        if (parentControl != null) parentControl.Invalidate();
                        return;
                    }
                }

                // 4. Slide Thumbnails & Section Headers click
                int thumbX, thumbW, thumbH;
                GetThumbnailMetrics(paneRect.Width, out thumbX, out thumbW, out thumbH);
                int curY = paneRect.Y + 44 + 10 - ThumbScrollY;
                bool currentCollapsed = false;

                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    SlideNode s = Presentation.Slides[i];
                    if (s.IsSectionHeader || (i == 0 && HasAnySections() && string.IsNullOrEmpty(s.SectionName)))
                    {
                        Rectangle secRect = new Rectangle(paneRect.X + 6, curY, paneRect.Width - 10, 24);
                        if (secRect.Contains(mousePos))
                        {
                            if (buttons == MouseButtons.Right)
                            {
                                ShowSectionContextMenu(parentControl, mousePos, i);
                                return;
                            }
                            else
                            {
                                s.IsSectionCollapsed = !s.IsSectionCollapsed;
                                ActiveSlideIndex = i;
                                SelectedShapeIndex = -1;
                                if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                                EndInlineEditing();
                                CanvasScrollX = 0;
                                CanvasScrollY = 0;
                                if (parentControl != null) parentControl.Invalidate();
                                return;
                            }
                        }
                        currentCollapsed = s.IsSectionCollapsed;
                        curY += 24;
                    }

                    if (currentCollapsed) continue;

                    int rowTop = (i == 0) ? curY : (curY - 8);
                    int rowBottom = (i == Presentation.Slides.Count - 1) ? (curY + thumbH + 14) : (curY + thumbH + 6);

                    if (mousePos.Y >= rowTop && mousePos.Y < rowBottom)
                    {
                        if (buttons == MouseButtons.Right)
                        {
                            ShowThumbnailContextMenu(parentControl, mousePos, i);
                            return;
                        }
                        else
                        {
                            int prevIdx = ActiveSlideIndex;
                            ActiveSlideIndex = i;
                            SelectedShapeIndex = -1;
                            if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                            EndInlineEditing();
                            CanvasScrollX = 0;
                            CanvasScrollY = 0;

                            // Khi chua trinh chieu thi khong cho chay hieu ung vi se lag
                            if (IsPresenting && prevIdx != i && ActiveSlide != null && ActiveSlide.Transition != TransitionType.None)
                            {
                                TriggerTransition(prevIdx, i, false);
                            }
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                    }

                    curY += thumbH + 14;
                }

                if (buttons == MouseButtons.Right)
                {
                    ShowThumbnailContextMenu(parentControl, mousePos, Math.Max(0, Presentation.Slides.Count - 1));
                }
                return;
            }
            }

            // 2. Right Task Pane Click (if open)
            if (rightSidebarW > 0 && mousePos.X >= width - rightSidebarW)
            {
                int panelX = width - rightSidebarW;
                int sidebarY = contentY;

                // Close Button '✕' in Header
                if (mousePos.Y >= sidebarY && mousePos.Y <= sidebarY + 36)
                {
                    if (mousePos.X >= width - 32 && mousePos.X <= width - 4)
                    {
                        IsSidebarOpen = false;
                        return;
                    }
                    return;
                }

                // Interactive Controls in Animation Pane
                if (SidebarPanel == SidebarPanelType.AnimationPane)
                {
                    int btnPlayY = sidebarY + 42;
                    if (mousePos.Y >= btnPlayY && mousePos.Y <= btnPlayY + 26)
                    {
                        if (IsPlayingAnimationPreview)
                        {
                            IsPlayingAnimationPreview = false;
                            ActivePlayingAnimIndex = -1;
                        }
                        else
                        {
                            PlayAnimationPreview();
                        }
                        return;
                    }

                    SlideNode slide = ActiveSlide;
                    if (slide != null && slide.Animations.Count > 0)
                    {
                        int animStartY = btnPlayY + 34;
                        for (int i = 0; i < slide.Animations.Count; i++)
                        {
                            int aY = animStartY + i * 36;
                            Rectangle animBox = new Rectangle(panelX + 8, aY, rightSidebarW - 16, 32);
                            if (animBox.Contains(mousePos))
                            {
                                SelectedAnimationIndex = i;
                                // Highlight target shape on canvas
                                string sId = slide.Animations[i].ShapeId;
                                for (int sIdx = 0; sIdx < slide.Shapes.Count; sIdx++)
                                {
                                    if (slide.Shapes[sIdx].Id == sId)
                                    {
                                        SelectedShapeIndex = sIdx;
                                        if (SelectedShapeIndices != null) { SelectedShapeIndices.Clear(); SelectedShapeIndices.Add(sIdx); }
                                        break;
                                    }
                                }

                                if (buttons == MouseButtons.Right || mousePos.X >= animBox.Right - 22)
                                {
                                    ShowAnimationItemContextMenu(parentControl, mousePos, i);
                                }
                                else if (buttons == MouseButtons.Left)
                                {
                                    DraggingAnimationPaneIndex = i;
                                    DraggingAnimationPaneTargetIndex = i;
                                }

                                if (parentControl != null) parentControl.Invalidate();
                                return;
                            }
                        }

                        // Bottom Reorder Toolbar (Move Earlier, Move Later, Remove)
                        int bottomToolbarY = animStartY + slide.Animations.Count * 36 + 8;
                        if (mousePos.Y >= bottomToolbarY && mousePos.Y <= bottomToolbarY + 24)
                        {
                            if (mousePos.X >= panelX + 10 && mousePos.X <= panelX + 80)
                            {
                                MoveAnimationEarlier();
                                if (parentControl != null) parentControl.Invalidate();
                                return;
                            }
                            else if (mousePos.X >= panelX + 85 && mousePos.X <= panelX + 155)
                            {
                                MoveAnimationLater();
                                if (parentControl != null) parentControl.Invalidate();
                                return;
                            }
                            else if (mousePos.X >= panelX + 160 && mousePos.X <= panelX + rightSidebarW - 10)
                            {
                                RemoveAnimation();
                                if (parentControl != null) parentControl.Invalidate();
                                return;
                            }
                        }
                    }
                }

                // Interactive Controls in Transitions Pane
                if (SidebarPanel == SidebarPanelType.SlideTransitions)
                {
                    int btnPrevY = sidebarY + 42 + 26;
                    if (mousePos.Y >= btnPrevY && mousePos.Y <= btnPrevY + 26)
                    {
                        PlayTransitionPreview();
                        return;
                    }

                    int listY = btnPrevY + 34;
                    int clickedTransIdx = (mousePos.Y - listY) / 28;
                    TransitionType[] transTypes = new TransitionType[] {
                        TransitionType.Morph, TransitionType.Fade, TransitionType.Push, TransitionType.Wipe,
                        TransitionType.Split, TransitionType.Reveal, TransitionType.Zoom, TransitionType.RandomBars,
                        TransitionType.Cube, TransitionType.PageCurl
                    };
                    if (clickedTransIdx >= 0 && clickedTransIdx < transTypes.Length && ActiveSlide != null)
                    {
                        ActiveSlide.Transition = transTypes[clickedTransIdx];
                        PlayTransitionPreview();
                        return;
                    }
                }

                // Interactive Controls in Format Properties
                if (SidebarPanel == SidebarPanelType.Properties && ActiveSlide != null)
                {
                    int colorY = sidebarY + 42 + 46;
                    if (mousePos.Y >= colorY && mousePos.Y <= colorY + 24)
                    {
                        int[] bgColors = new int[] { 0xFFFFFF, 0xF8F9FA, 0xF0FDFA, 0x0F172A, 0xFEFCE8, 0xFDF4FF };
                        int colIdx = (mousePos.X - (panelX + 12)) / 38;
                        if (colIdx >= 0 && colIdx < bgColors.Length)
                        {
                            ActiveSlide.BgColor = bgColors[colIdx];
                            return;
                        }
                    }

                    int ratioY = colorY + 54;
                    if (mousePos.Y >= ratioY && mousePos.Y <= ratioY + 24)
                    {
                        if (mousePos.X >= panelX + 12 && mousePos.X <= panelX + 127) SetSlideSize(true);
                        else if (mousePos.X >= panelX + 135 && mousePos.X <= panelX + 250) SetSlideSize(false);
                        return;
                    }
                }
                else if (SidebarPanel == SidebarPanelType.FormatBackground && ActiveSlide != null)
                {
                    int sy = sidebarY + 42 + SidebarScrollY;
                    int fillHeaderY = sy + 28;
                    int curY = fillHeaderY + 28;

                    // 4 Radio buttons
                    if (mousePos.Y >= curY && mousePos.Y < curY + 24 * 4)
                    {
                        int r = (mousePos.Y - curY) / 24;
                        if (r == 0)
                        {
                            ActiveSlide.BgFillType = BackgroundFillType.Solid;
                            ActiveSlide.IsGradientBg = false;
                        }
                        else if (r == 1)
                        {
                            ActiveSlide.BgFillType = BackgroundFillType.Gradient;
                            ActiveSlide.IsGradientBg = true;
                            if (ActiveSlide.BgGradientStops == null || ActiveSlide.BgGradientStops.Count < 2)
                            {
                                ActiveSlide.BgGradientStops = new List<GradientStop>
                                {
                                    new GradientStop(ActiveSlide.BgColor, 0.0f),
                                    new GradientStop(ActiveSlide.BgColor2 != 0 ? ActiveSlide.BgColor2 : 0xF3F4F6, 1.0f)
                                };
                            }
                        }
                        else if (r == 2)
                        {
                            ActiveSlide.BgFillType = BackgroundFillType.Picture;
                            using (OpenFileDialog ofd = new OpenFileDialog())
                            {
                                ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp)|*.png;*.jpg;*.jpeg;*.bmp";
                                if (ofd.ShowDialog() == DialogResult.OK)
                                {
                                    ActiveSlide.BgImagePath = ofd.FileName;
                                    try { ActiveSlide.CachedBgImage = Image.FromFile(ofd.FileName); } catch { }
                                }
                            }
                        }
                        else if (r == 3)
                        {
                            ActiveSlide.BgFillType = BackgroundFillType.Pattern;
                        }
                        return;
                    }

                    curY += 24 * 4 + 4;

                    // Checkbox: Hide background graphics
                    if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                    {
                        ActiveSlide.HideBackgroundGraphics = !ActiveSlide.HideBackgroundGraphics;
                        return;
                    }

                    curY += 30;

                    // Details for Gradient fill
                    if (ActiveSlide.BgFillType == BackgroundFillType.Gradient || ActiveSlide.IsGradientBg)
                    {
                        // 1. Preset gradients
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                ShowPresetGradientsMenu(parentControl, Cursor.Position);
                                return;
                            }
                        }
                        curY += 30;

                        // 2. Type
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + 115)
                            {
                                ShowGradientTypeMenu(parentControl, Cursor.Position);
                                return;
                            }
                        }
                        curY += 30;

                        // 3. Direction
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                ShowGradientDirectionMenu(parentControl, Cursor.Position);
                                return;
                            }
                        }
                        curY += 30;

                        // 4. Angle
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                if (mousePos.X >= panelX + rightSidebarW - 35)
                                    ActiveSlide.BgGradientAngle = (ActiveSlide.BgGradientAngle + 45f) % 360f;
                                else
                                    ActiveSlide.BgGradientAngle = (ActiveSlide.BgGradientAngle + 315f) % 360f;
                                return;
                            }
                        }
                        curY += 30;

                        // 5. Gradient stops bar & pins
                        curY += 20;
                        int trackX = panelX + 24;
                        int trackW = rightSidebarW - 106;
                        int trackH = 14;
                        Rectangle trackRect = new Rectangle(trackX, curY, trackW, trackH);

                        // Add Stop [+] button
                        Rectangle btnAddStop = new Rectangle(panelX + rightSidebarW - 74, curY - 2, 24, 22);
                        if (btnAddStop.Contains(mousePos))
                        {
                            if (ActiveSlide.BgGradientStops == null) ActiveSlide.BgGradientStops = new List<GradientStop>();
                            float newPos = 0.5f;
                            int newCol = 0x2563EB;
                            if (ActiveSlide.BgGradientStops.Count > 0)
                            {
                                int curIdx = Math.Max(0, Math.Min(ActiveSlide.BgGradientStops.Count - 1, ActiveSlide.SelectedGradientStopIndex));
                                newPos = Math.Min(1.0f, ActiveSlide.BgGradientStops[curIdx].Position + 0.15f);
                                newCol = ActiveSlide.BgGradientStops[curIdx].Color;
                            }
                            ActiveSlide.BgGradientStops.Add(new GradientStop(newCol, newPos));
                            ActiveSlide.SelectedGradientStopIndex = ActiveSlide.BgGradientStops.Count - 1;
                            return;
                        }

                        // Remove Stop [x] button
                        Rectangle btnDelStop = new Rectangle(panelX + rightSidebarW - 44, curY - 2, 24, 22);
                        if (btnDelStop.Contains(mousePos))
                        {
                            if (ActiveSlide.BgGradientStops != null && ActiveSlide.BgGradientStops.Count > 2)
                            {
                                int curIdx = Math.Max(0, Math.Min(ActiveSlide.BgGradientStops.Count - 1, ActiveSlide.SelectedGradientStopIndex));
                                ActiveSlide.BgGradientStops.RemoveAt(curIdx);
                                ActiveSlide.SelectedGradientStopIndex = Math.Max(0, curIdx - 1);
                            }
                            return;
                        }

                        // Check Stop Pins Underneath Track
                        if (mousePos.Y >= trackRect.Bottom - 2 && mousePos.Y <= trackRect.Bottom + 20 && ActiveSlide.BgGradientStops != null)
                        {
                            for (int s = 0; s < ActiveSlide.BgGradientStops.Count; s++)
                            {
                                int pinCenterX = trackX + (int)(ActiveSlide.BgGradientStops[s].Position * trackW);
                                if (Math.Abs(mousePos.X - pinCenterX) <= 8)
                                {
                                    ActiveSlide.SelectedGradientStopIndex = s;
                                    IsDraggingGradientStop = true;
                                    return;
                                }
                            }
                        }

                        // Check Track Click
                        if (trackRect.Contains(mousePos) && ActiveSlide.BgGradientStops != null)
                        {
                            float frac = Math.Max(0f, Math.Min(1f, (float)(mousePos.X - trackX) / trackW));
                            if (ActiveSlide.SelectedGradientStopIndex >= 0 && ActiveSlide.SelectedGradientStopIndex < ActiveSlide.BgGradientStops.Count)
                            {
                                ActiveSlide.BgGradientStops[ActiveSlide.SelectedGradientStopIndex].Position = frac;
                            }
                            IsDraggingGradientStop = true;
                            return;
                        }

                        curY += 40;

                        GradientStop activeStop = (ActiveSlide.BgGradientStops != null && ActiveSlide.SelectedGradientStopIndex >= 0 && ActiveSlide.SelectedGradientStopIndex < ActiveSlide.BgGradientStops.Count)
                            ? ActiveSlide.BgGradientStops[ActiveSlide.SelectedGradientStopIndex] : null;

                        // Color button
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85 && activeStop != null)
                            {
                                Point pt = new Point(Cursor.Position.X, Cursor.Position.Y);
                                Color curC = Color.FromArgb((activeStop.Color >> 16) & 0xFF, (activeStop.Color >> 8) & 0xFF, activeStop.Color & 0xFF);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                                colDlg.OnColorSelected += (c) =>
                                {
                                    activeStop.Color = c.ToArgb() & 0xFFFFFF;
                                };
                                colDlg.Show();
                                return;
                            }
                        }
                        curY += 28;

                        // Position slider / spinner
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26 && activeStop != null)
                        {
                            int posTrackX = panelX + 115;
                            int posTrackW = 65;
                            if (mousePos.X >= posTrackX && mousePos.X <= posTrackX + posTrackW)
                            {
                                float frac = (float)(mousePos.X - posTrackX) / posTrackW;
                                activeStop.Position = Math.Max(0f, Math.Min(1f, frac));
                                DraggingBgSliderType = 2;
                                return;
                            }
                            else if (mousePos.X >= panelX + rightSidebarW - 62)
                            {
                                if (mousePos.Y < curY + 12) activeStop.Position = Math.Min(1.0f, activeStop.Position + 0.05f);
                                else activeStop.Position = Math.Max(0.0f, activeStop.Position - 0.05f);
                                return;
                            }
                        }
                        curY += 28;

                        // Transparency slider / spinner
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26 && activeStop != null)
                        {
                            int transTrackX = panelX + 115;
                            int transTrackW = 65;
                            if (mousePos.X >= transTrackX && mousePos.X <= transTrackX + transTrackW)
                            {
                                float frac = (float)(mousePos.X - transTrackX) / transTrackW;
                                activeStop.Transparency = Math.Max(0f, Math.Min(1f, frac));
                                DraggingBgSliderType = 1;
                                return;
                            }
                            else if (mousePos.X >= panelX + rightSidebarW - 62)
                            {
                                if (mousePos.Y < curY + 12) activeStop.Transparency = Math.Min(1.0f, activeStop.Transparency + 0.05f);
                                else activeStop.Transparency = Math.Max(0.0f, activeStop.Transparency - 0.05f);
                                return;
                            }
                        }
                        curY += 28;

                        // Brightness slider / spinner
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26 && activeStop != null)
                        {
                            int brTrackX = panelX + 115;
                            int brTrackW = 65;
                            if (mousePos.X >= brTrackX && mousePos.X <= brTrackX + brTrackW)
                            {
                                float frac = (float)(mousePos.X - brTrackX) / brTrackW;
                                activeStop.Brightness = (frac * 2.0f) - 1.0f;
                                DraggingBgSliderType = 3;
                                return;
                            }
                            else if (mousePos.X >= panelX + rightSidebarW - 62)
                            {
                                if (mousePos.Y < curY + 12) activeStop.Brightness = Math.Min(1.0f, activeStop.Brightness + 0.05f);
                                else activeStop.Brightness = Math.Max(-1.0f, activeStop.Brightness - 0.05f);
                                return;
                            }
                        }
                        curY += 28;
                    }
                    else if (ActiveSlide.BgFillType == BackgroundFillType.Solid)
                    {
                        // Color button
                        if (mousePos.Y >= curY && mousePos.Y < curY + 30)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                Point pt = new Point(Cursor.Position.X, Cursor.Position.Y);
                                Color curC = Color.FromArgb((ActiveSlide.BgColor >> 16) & 0xFF, (ActiveSlide.BgColor >> 8) & 0xFF, ActiveSlide.BgColor & 0xFF);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                                colDlg.OnColorSelected += (c) =>
                                {
                                    ActiveSlide.BgColor = c.ToArgb() & 0xFFFFFF;
                                };
                                colDlg.Show();
                                return;
                            }
                        }
                        curY += 34;

                        // Transparency slider
                        if (mousePos.Y >= curY && mousePos.Y < curY + 30)
                        {
                            int trackX = panelX + 115;
                            int trackW = 65;
                            if (mousePos.X >= trackX && mousePos.X <= trackX + trackW)
                            {
                                float frac = (float)(mousePos.X - trackX) / trackW;
                                ActiveSlide.BgTransparency = Math.Max(0f, Math.Min(1f, frac));
                                DraggingBgSliderType = 1;
                                return;
                            }
                        }
                        curY += 34;
                    }
                    else if (ActiveSlide.BgFillType == BackgroundFillType.Picture)
                    {
                        // File Button
                        if (mousePos.Y >= curY && mousePos.Y < curY + 32)
                        {
                            using (OpenFileDialog ofd = new OpenFileDialog())
                            {
                                ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp)|*.png;*.jpg;*.jpeg;*.bmp";
                                if (ofd.ShowDialog() == DialogResult.OK)
                                {
                                    ActiveSlide.BgImagePath = ofd.FileName;
                                    try { ActiveSlide.CachedBgImage = Image.FromFile(ofd.FileName); } catch { }
                                }
                            }
                            return;
                        }
                        curY += 36;

                        // Transparency
                        if (mousePos.Y >= curY && mousePos.Y < curY + 30)
                        {
                            int trackX = panelX + 115;
                            int trackW = 65;
                            if (mousePos.X >= trackX && mousePos.X <= trackX + trackW)
                            {
                                float frac = (float)(mousePos.X - trackX) / trackW;
                                ActiveSlide.BgTransparency = Math.Max(0f, Math.Min(1f, frac));
                                DraggingBgSliderType = 1;
                                return;
                            }
                        }
                        curY += 34;
                    }
                    else if (ActiveSlide.BgFillType == BackgroundFillType.Pattern)
                    {
                        curY += 20;
                        PatternFillStyle[] pStyles = new PatternFillStyle[] {
                            PatternFillStyle.Grid5Percent, PatternFillStyle.Grid10Percent, PatternFillStyle.HorizontalLight, PatternFillStyle.VerticalLight,
                            PatternFillStyle.DiagonalUpLight, PatternFillStyle.DiagonalDownLight, PatternFillStyle.Crosshatch, PatternFillStyle.ZigZag,
                            PatternFillStyle.Brick, PatternFillStyle.Dots, PatternFillStyle.Checker, PatternFillStyle.Waves
                        };

                        for (int pi = 0; pi < pStyles.Length; pi++)
                        {
                            int row = pi / 4;
                            int col = pi % 4;
                            Rectangle pBox = new Rectangle(panelX + 24 + col * 56, curY + row * 30, 48, 24);
                            if (pBox.Contains(mousePos))
                            {
                                ActiveSlide.BgPatternStyle = pStyles[pi];
                                return;
                            }
                        }
                        curY += 100;

                        // Foreground Color
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                Point pt = new Point(Cursor.Position.X, Cursor.Position.Y);
                                Color curC = Color.FromArgb((ActiveSlide.BgPatternForeColor >> 16) & 0xFF, (ActiveSlide.BgPatternForeColor >> 8) & 0xFF, ActiveSlide.BgPatternForeColor & 0xFF);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                                colDlg.OnColorSelected += (c) =>
                                {
                                    ActiveSlide.BgPatternForeColor = c.ToArgb() & 0xFFFFFF;
                                };
                                colDlg.Show();
                                return;
                            }
                        }
                        curY += 28;

                        // Background Color
                        if (mousePos.Y >= curY && mousePos.Y < curY + 26)
                        {
                            if (mousePos.X >= panelX + rightSidebarW - 85)
                            {
                                Point pt = new Point(Cursor.Position.X, Cursor.Position.Y);
                                Color curC = Color.FromArgb((ActiveSlide.BgPatternBackColor >> 16) & 0xFF, (ActiveSlide.BgPatternBackColor >> 8) & 0xFF, ActiveSlide.BgPatternBackColor & 0xFF);
                                ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                                colDlg.OnColorSelected += (c) =>
                                {
                                    ActiveSlide.BgPatternBackColor = c.ToArgb() & 0xFFFFFF;
                                };
                                colDlg.Show();
                                return;
                            }
                        }
                        curY += 30;
                    }

                    // Bottom Buttons (Apply to All & Reset Background)
                    int bottomBtnY = height - 45;
                    if (mousePos.Y >= bottomBtnY && mousePos.Y <= bottomBtnY + 32)
                    {
                        // Apply to All (X: panelX + 10..panelX + 130)
                        if (mousePos.X >= panelX + 10 && mousePos.X <= panelX + 130)
                        {
                            foreach (var s in Presentation.Slides)
                            {
                                s.BgColor = ActiveSlide.BgColor;
                                s.BgFillType = ActiveSlide.BgFillType;
                                s.IsGradientBg = ActiveSlide.IsGradientBg;
                                s.BgColor2 = ActiveSlide.BgColor2;
                                s.BgGradientAngle = ActiveSlide.BgGradientAngle;
                                s.BgGradientType = ActiveSlide.BgGradientType;
                                s.BgImagePath = ActiveSlide.BgImagePath;
                                s.CachedBgImage = ActiveSlide.CachedBgImage;
                                s.BgTransparency = ActiveSlide.BgTransparency;
                                s.HideBackgroundGraphics = ActiveSlide.HideBackgroundGraphics;
                                s.BgPatternStyle = ActiveSlide.BgPatternStyle;
                                s.BgPatternForeColor = ActiveSlide.BgPatternForeColor;
                                s.BgPatternBackColor = ActiveSlide.BgPatternBackColor;

                                s.BgGradientStops = new List<GradientStop>();
                                if (ActiveSlide.BgGradientStops != null)
                                {
                                    foreach (GradientStop gs in ActiveSlide.BgGradientStops)
                                    {
                                        s.BgGradientStops.Add(gs.Clone());
                                    }
                                }
                            }
                            MessageBox.Show("Đã áp dụng định dạng nền cho toàn bộ trang chiếu!", "Định dạng Nền", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return;
                        }
                        // Reset Background (X: panelX + 138..panelX + 272)
                        if (mousePos.X >= panelX + 138 && mousePos.X <= panelX + 272)
                        {
                            ApplyTheme(Presentation.CurrentTheme ?? "Office");
                            return;
                        }
                    }
                }
                else if (SidebarPanel == SidebarPanelType.SelectionPane && ActiveSlide != null)
                {
                    int sy = sidebarY + 42 + SidebarScrollY;
                    Rectangle btnShowAll = new Rectangle(panelX + 10, sy, 86, 25);
                    Rectangle btnHideAll = new Rectangle(panelX + 102, sy, 80, 25);
                    Rectangle btnMoveUp = new Rectangle(panelX + rightSidebarW - 58, sy, 22, 25);
                    Rectangle btnMoveDown = new Rectangle(panelX + rightSidebarW - 32, sy, 22, 25);

                    if (btnShowAll.Contains(mousePos))
                    {
                        foreach (var s in ActiveSlide.Shapes) s.IsVisible = true;
                        return;
                    }
                    if (btnHideAll.Contains(mousePos))
                    {
                        foreach (var s in ActiveSlide.Shapes) s.IsVisible = false;
                        return;
                    }
                    if (btnMoveUp.Contains(mousePos))
                    {
                        BringShapeForward();
                        return;
                    }
                    if (btnMoveDown.Contains(mousePos))
                    {
                        SendShapeBackward();
                        return;
                    }

                    int listStartY = sy + 34;
                    int rowH = 28;
                    int clickedRow = (mousePos.Y - listStartY) / rowH;
                    if (clickedRow >= 0 && clickedRow < ActiveSlide.Shapes.Count)
                    {
                        int shapeIdx = ActiveSlide.Shapes.Count - 1 - clickedRow;
                        Rectangle rowRect = new Rectangle(panelX + 10, listStartY + clickedRow * rowH, rightSidebarW - 20, 26);
                        Rectangle eyeRect = new Rectangle(rowRect.Right - 26, rowRect.Y + 3, 22, 22);

                        if (eyeRect.Contains(mousePos))
                        {
                            ActiveSlide.Shapes[shapeIdx].IsVisible = !ActiveSlide.Shapes[shapeIdx].IsVisible;
                            return;
                        }
                        else
                        {
                            SelectedShapeIndex = shapeIdx;
                            SelectedShapeIndices.Clear();
                            SelectedShapeIndices.Add(shapeIdx);
                            DraggingSelectionPaneIndex = shapeIdx;
                            DraggingSelectionPaneTargetIndex = shapeIdx;
                            return;
                        }
                    }
                }
                else if (SidebarPanel == SidebarPanelType.Designer && ActiveSlide != null)
                {
                    int sy = sidebarY + 42 + SidebarScrollY;
                    var ideas = GetDesignIdeasForCurrentSlide();
                    int cardStartY = sy + 22;
                    int cardW = rightSidebarW - 24;
                    int cardH = 152;
                    int cardGap = 14;

                    for (int i = 0; i < ideas.Count; i++)
                    {
                        int cy = cardStartY + i * (cardH + cardGap);
                        Rectangle cardRect = new Rectangle(panelX + 12, cy, cardW, cardH);
                        if (cardRect.Contains(mousePos))
                        {
                            ApplyDesignIdea(i);
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                    }
                }
                return;
            }

            // 3. Center Slide Viewport Interaction
            if (ViewMode == ImpressViewMode.Normal || ViewMode == ImpressViewMode.ReadingView)
            {
                int notesPaneH = GetEffectiveNotesPaneHeight();
                int stageH = Math.Max(80, contentH - notesPaneH);
                int notesTopY = contentY + stageH;

                // 3.0. Xử lý kéo thanh phân cách (Splitter) hoặc nhấp vào Khung Ghi chú người thuyết trình (Speaker Notes Pane) ở đáy Canvas
                if (notesPaneH > 0 && mousePos.X >= canvasX && mousePos.X <= canvasX + canvasW)
                {
                    if (buttons == MouseButtons.Left && mousePos.Y >= notesTopY - 4 && mousePos.Y <= notesTopY + 4)
                    {
                        IsDraggingNotesSplitter = true;
                        NotesSplitterDragStartMouseY = mousePos.Y;
                        NotesSplitterDragStartHeight = NotesPaneHeight;
                        if (parentControl != null) parentControl.Invalidate();
                        return;
                    }
                    if (mousePos.Y > notesTopY + 4 && mousePos.Y <= contentY + contentH)
                    {
                        EndInlineEditing();
                        SelectedShapeIndex = -1;
                        if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                        IsEditingSpeakerNotes = true;
                        RectangleF notesTextBounds = new RectangleF(canvasX + 34, notesTopY + 8, Math.Max(40, canvasW - 46), Math.Max(18, notesPaneH - 12));
                        SpeakerNotesCaretIndex = GetSpeakerNotesCharIndexFromPoint(mousePos, notesTextBounds, 10.0f);
                        SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                        SpeakerNotesSelectionLength = 0;
                        IsSelectingSpeakerNotes = (buttons == MouseButtons.Left);
                        if (parentControl != null) parentControl.Invalidate();
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }

                IsEditingSpeakerNotes = false;

                int minScrollX, maxScrollX, minScrollY, maxScrollY;
                GetScrollLimits(canvasW, contentH, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);

                bool hasVScroll = (minScrollY < maxScrollY);
                bool hasHScroll = (minScrollX < maxScrollX);
                int sbH = 14;
                int sbW = 14;

                // 3.1. Xử lý nhấp và kéo thanh cuộn ngang (Horizontal Scrollbar)
                if (hasHScroll && mousePos.Y >= contentY + stageH - sbH && mousePos.Y <= contentY + stageH &&
                    mousePos.X >= canvasX && mousePos.X <= canvasX + (hasVScroll ? (canvasW - sbW) : canvasW))
                {
                    int hTrackW = hasVScroll ? (canvasW - sbW) : canvasW;
                    int hTrackX = canvasX;
                    int totalW = maxScrollX - minScrollX + canvasW;
                    int thumbW = Math.Max(40, (int)((float)canvasW / totalW * hTrackW));
                    thumbW = Math.Min(thumbW, hTrackW);
                    float fracX = (float)(CanvasScrollX - minScrollX) / Math.Max(1, maxScrollX - minScrollX);
                    int thumbX = hTrackX + (int)(fracX * (hTrackW - thumbW));

                    if (mousePos.X >= thumbX && mousePos.X <= thumbX + thumbW)
                    {
                        IsDraggingHScrollBar = true;
                        ScrollBarDragStartMouseX = mousePos.X;
                        ScrollBarDragStartScrollX = CanvasScrollX;
                        SmoothCanvasScrollX = CanvasScrollX;
                        TargetCanvasScrollX = CanvasScrollX;
                    }
                    else
                    {
                        // Nhấp trực tiếp lên đường track -> Nhảy nhanh / định vị tâm thumb tới vị trí nhấp chuột
                        float targetFrac = (float)(mousePos.X - hTrackX - thumbW / 2) / Math.Max(1, hTrackW - thumbW);
                        targetFrac = Math.Max(0f, Math.Min(1f, targetFrac));
                        CanvasScrollX = minScrollX + (int)(targetFrac * (maxScrollX - minScrollX));
                        ClampScroll(canvasW, contentH);
                        SmoothCanvasScrollX = CanvasScrollX;
                        TargetCanvasScrollX = CanvasScrollX;
                        IsDraggingHScrollBar = true;
                        ScrollBarDragStartMouseX = mousePos.X;
                        ScrollBarDragStartScrollX = CanvasScrollX;
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }

                // 3.2. Xử lý nhấp và kéo thanh cuộn dọc (Vertical Scrollbar)
                int vTrackX = canvasX + canvasW - sbW;
                int vTrackY = contentY;
                int vTrackH = hasHScroll ? (stageH - sbH) : stageH;

                if (hasVScroll && mousePos.X >= vTrackX && mousePos.X <= vTrackX + sbW &&
                    mousePos.Y >= vTrackY && mousePos.Y <= vTrackY + vTrackH)
                {
                    int totalH = maxScrollY - minScrollY + stageH;
                    int thumbH = Math.Max(40, (int)((float)stageH / totalH * vTrackH));
                    thumbH = Math.Min(thumbH, vTrackH);
                    float fracY = (float)(CanvasScrollY - minScrollY) / Math.Max(1, maxScrollY - minScrollY);
                    int thumbY = vTrackY + (int)(fracY * (vTrackH - thumbH));

                    if (mousePos.Y >= thumbY && mousePos.Y <= thumbY + thumbH)
                    {
                        IsDraggingVScrollBar = true;
                        ScrollBarDragStartMouseY = mousePos.Y;
                        ScrollBarDragStartScrollY = CanvasScrollY;
                        SmoothCanvasScrollY = CanvasScrollY;
                        TargetCanvasScrollY = CanvasScrollY;
                    }
                    else
                    {
                        // Nhấp trực tiếp lên đường track -> Nhảy nhanh / định vị tâm thumb tới vị trí nhấp chuột
                        float targetFrac = (float)(mousePos.Y - vTrackY - thumbH / 2) / Math.Max(1, vTrackH - thumbH);
                        targetFrac = Math.Max(0f, Math.Min(1f, targetFrac));
                        CanvasScrollY = minScrollY + (int)(targetFrac * (maxScrollY - minScrollY));
                        ClampScroll(canvasW, contentH);
                        SmoothCanvasScrollY = CanvasScrollY;
                        TargetCanvasScrollY = CanvasScrollY;
                        IsDraggingVScrollBar = true;
                        ScrollBarDragStartMouseY = mousePos.Y;
                        ScrollBarDragStartScrollY = CanvasScrollY;
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }

                int slideX, slideY, slideW, slideH;
                float scale;
                GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out slideX, out slideY, out slideW, out slideH, out scale);

                // Xử lý Chế độ Chỉnh sửa điểm hình dạng (PowerPoint Edit Points)
                if (IsEditingShapePoints && EditingPointsShape != null)
                {
                    ShapeNode esh = EditingPointsShape;

                    // Kiểm tra nhấp vào đỉnh điểm đen hiện có
                    int hitIdx = -1;
                    for (int i = 0; i < ShapeEditPoints.Count; i++)
                    {
                        PointF sPt = ShapeLocalToScreen(esh, ShapeEditPoints[i], slideX, slideY, scale);
                        float dx = mousePos.X - sPt.X;
                        float dy = mousePos.Y - sPt.Y;
                        if (dx * dx + dy * dy <= 64f)
                        {
                            hitIdx = i;
                            break;
                        }
                    }

                    if (buttons == MouseButtons.Right)
                    {
                        if (hitIdx >= 0)
                        {
                            ContextMenuStrip pointMenu = new ContextMenuStrip();
                            pointMenu.RenderMode = ToolStripRenderMode.System;
                            int pointToDelete = hitIdx;
                            ToolStripMenuItem miDel = new ToolStripMenuItem("Xóa điểm (Delete Point)", null, (s, e) => {
                                if (ShapeEditPoints.Count > 3 && pointToDelete >= 0 && pointToDelete < ShapeEditPoints.Count)
                                {
                                    ShapeEditPoints.RemoveAt(pointToDelete);
                                    HoveredEditPointIndex = -1;
                                    SelectedEditPointIndex = -1;
                                    RebuildCustomPathFromEditPoints();
                                    SaveUndoState();
                                    if (parentControl != null) parentControl.Invalidate();
                                }
                            });
                            miDel.Enabled = (ShapeEditPoints.Count > 3);
                            pointMenu.Items.Add(miDel);
                            pointMenu.Items.Add(new ToolStripSeparator());
                            pointMenu.Items.Add("Thoát chế độ sửa điểm (Exit Edit Points)", null, (s, e) => {
                                EndEditShapePoints();
                                if (parentControl != null) parentControl.Invalidate();
                            });
                            Point screenPt = parentControl != null ? parentControl.PointToScreen(mousePos) : mousePos;
                            pointMenu.Show(screenPt);
                            return;
                        }
                        else if (HoveredEditSegmentIndex >= 0 && HoveredEditSegmentPoint.HasValue)
                        {
                            ContextMenuStrip segMenu = new ContextMenuStrip();
                            segMenu.RenderMode = ToolStripRenderMode.System;
                            PointF addPt = HoveredEditSegmentPoint.Value;
                            int insIdx = HoveredEditSegmentIndex + 1;
                            segMenu.Items.Add("Thêm điểm (Add Point)", null, (s, e) => {
                                ShapeEditPoints.Insert(insIdx, addPt);
                                SelectedEditPointIndex = insIdx;
                                RebuildCustomPathFromEditPoints();
                                SaveUndoState();
                                if (parentControl != null) parentControl.Invalidate();
                            });
                            segMenu.Items.Add(new ToolStripSeparator());
                            segMenu.Items.Add("Thoát chế độ sửa điểm (Exit Edit Points)", null, (s, e) => {
                                EndEditShapePoints();
                                if (parentControl != null) parentControl.Invalidate();
                            });
                            Point screenPt = parentControl != null ? parentControl.PointToScreen(mousePos) : mousePos;
                            segMenu.Show(screenPt);
                            return;
                        }
                    }

                    if (hitIdx >= 0)
                    {
                        SelectedEditPointIndex = hitIdx;
                        IsDraggingEditPoint = true;
                        DragStartEditPointMouse = mousePos;
                        DragStartEditPointVal = ShapeEditPoints[hitIdx];
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    // Kiểm tra nhấp vào cạnh để THÊM ĐIỂM MỚI (Add Point on edge)
                    if (HoveredEditSegmentIndex >= 0 && HoveredEditSegmentPoint.HasValue)
                    {
                        PointF newPt = HoveredEditSegmentPoint.Value;
                        int insertIdx = HoveredEditSegmentIndex + 1;
                        ShapeEditPoints.Insert(insertIdx, newPt);
                        SelectedEditPointIndex = insertIdx;
                        IsDraggingEditPoint = true;
                        DragStartEditPointMouse = mousePos;
                        DragStartEditPointVal = newPt;
                        RebuildCustomPathFromEditPoints();
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    // Nhấp chuột ra ngoài hình -> Thoát chế độ sửa điểm
                    PointF localM = ScreenToShapeLocal(esh, mousePos, slideX, slideY, scale);
                    RectangleF marginBounds = new RectangleF(-30f, -30f, esh.Transform.Width + 60f, esh.Transform.Height + 60f);
                    if (!marginBounds.Contains(localM))
                    {
                        EndEditShapePoints();
                    }
                    else
                    {
                        if (buttons == MouseButtons.Right)
                        {
                            ContextMenuStrip shapeEditMenu = new ContextMenuStrip();
                            shapeEditMenu.RenderMode = ToolStripRenderMode.System;
                            shapeEditMenu.Items.Add("Thoát chế độ sửa điểm (Exit Edit Points)", null, (s, e) => {
                                EndEditShapePoints();
                                if (parentControl != null) parentControl.Invalidate();
                            });
                            Point screenPt = parentControl != null ? parentControl.PointToScreen(mousePos) : mousePos;
                            shapeEditMenu.Show(screenPt);
                            return;
                        }
                        SelectedEditPointIndex = -1;
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }

                // Xử lý Chế độ Vẽ tự do đường chuyển động (Motion Path Freehand Drawing Mode)
                if (IsDrawingMotionPathMode)
                {
                    SaveUndoState();
                    IsDrawingMotionPathActive = true;
                    CurrentDrawingMotionPoints.Clear();
                    float mouseSlideX = (mousePos.X - slideX) / scale;
                    float mouseSlideY = (mousePos.Y - slideY) / scale;

                    ShapeNode targetShape = ActiveDrawingMotionShape ?? SelectedShape;
                    if (targetShape != null)
                    {
                        float scx = targetShape.Transform.X + targetShape.Transform.Width / 2f;
                        float scy = targetShape.Transform.Y + targetShape.Transform.Height / 2f;
                        CurrentDrawingMotionPoints.Add(new PointF(0, 0));
                        CurrentDrawingMotionPoints.Add(new PointF(mouseSlideX - scx, mouseSlideY - scy));
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }

                // Xử lý Kéo thả chấm đỏ đổi đích đến của Đường chuyển động (Motion Path End Point Handle Dragging)
                if (ActiveSlide != null && ActiveSlide.Animations != null && ActiveSlide.Animations.Count > 0)
                {
                    for (int a = 0; a < ActiveSlide.Animations.Count; a++)
                    {
                        ShapeAnimation anim = ActiveSlide.Animations[a];
                        if (anim == null || !anim.IsMotionPath) continue;

                        ShapeNode targetShape = null;
                        for (int s = 0; s < ActiveSlide.Shapes.Count; s++)
                        {
                            if (ActiveSlide.Shapes[s].Id == anim.ShapeId) { targetShape = ActiveSlide.Shapes[s]; break; }
                        }
                        if (targetShape == null) continue;

                        float scx = slideX + (targetShape.Transform.X + targetShape.Transform.Width / 2f) * scale;
                        float scy = slideY + (targetShape.Transform.Y + targetShape.Transform.Height / 2f) * scale;

                        float endOffX, endOffY;
                        EvaluateMotionPathOffset(anim, 1.0f, out endOffX, out endOffY);
                        float endPtX = scx + endOffX * scale;
                        float endPtY = scy + endOffY * scale;

                        float dX = mousePos.X - endPtX;
                        float dY = mousePos.Y - endPtY;
                        if (dX * dX + dY * dY <= 144f) // 12px hit radius
                        {
                            SaveUndoState();
                            IsDraggingMotionEndDot = true;
                            DraggingMotionAnim = anim;
                            DraggingMotionShape = targetShape;
                            DraggingMotionStartMouse = mousePos;
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }
                    }
                }

                if (IsDrawingShapeMode)
                {
                    if (IsScribbleMode)
                    {
                        float cX = (mousePos.X - slideX) / scale;
                        float cY = (mousePos.Y - slideY) / scale;
                        PointF clickPt = new PointF(cX, cY);

                        if (ScribblePoints.Count >= 3)
                        {
                            PointF pStart = ScribblePoints[0];
                            float dX = (clickPt.X - pStart.X) * scale;
                            float dY = (clickPt.Y - pStart.Y) * scale;
                            if (dX * dX + dY * dY <= 625f) // 25px radius on screen to close
                            {
                                FinalizeScribbleShape(shouldClose: true);
                                if (InvalidateCallback != null) InvalidateCallback();
                                return;
                            }
                        }

                        ScribblePoints.Add(clickPt);
                        IsDrawingActive = true;
                        ShapeDrawStart = mousePos;
                        ShapeDrawCurrent = mousePos;
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }

                    IsDrawingActive = true;
                    ShapeDrawStart = mousePos;
                    ShapeDrawCurrent = mousePos;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                // Xử lý Chế độ Chọn màu xóa (Chroma Keying / Phông xanh CapCut)
                if (IsColorPickingMode && SelectedShape != null && SelectedShape.CachedImage != null)
                {
                    ShapeNode cpShape = SelectedShape;
                    float imgX = slideX + cpShape.Transform.X * scale;
                    float imgY = slideY + cpShape.Transform.Y * scale;
                    float imgW = cpShape.Transform.Width * scale;
                    float imgH = cpShape.Transform.Height * scale;

                    if (mousePos.X >= imgX && mousePos.X <= imgX + imgW && mousePos.Y >= imgY && mousePos.Y <= imgY + imgH)
                    {
                        float normX = Math.Max(0f, Math.Min(1f, (mousePos.X - imgX) / imgW));
                        float normY = Math.Max(0f, Math.Min(1f, (mousePos.Y - imgY) / imgH));
                        Color pickedCol = GetPixelColorFromImage(cpShape.CachedImage, normX, normY);
                        ExecuteColorPickRemoval(cpShape, pickedCol, normX, normY);
                        return;
                    }
                    else
                    {
                        IsColorPickingMode = false;
                        HasColorPickHover = false;
                        if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }

                // Xử lý vẽ nét cọ đánh dấu Giữ lại (+) hoặc Xóa bỏ (-) khi đang ở Chế độ Xóa nền
                if (IsRemovingBackground && SelectedShape != null && SelectedShape.CachedImage != null)
                {
                    ShapeNode bgShape = SelectedShape;
                    float imgX = slideX + bgShape.Transform.X * scale;
                    float imgY = slideY + bgShape.Transform.Y * scale;
                    float imgW = bgShape.Transform.Width * scale;
                    float imgH = bgShape.Transform.Height * scale;

                    if (mousePos.X >= imgX && mousePos.X <= imgX + imgW && mousePos.Y >= imgY && mousePos.Y <= imgY + imgH)
                    {
                        SaveUndoState();
                        float normX = Math.Max(0f, Math.Min(1f, (mousePos.X - imgX) / imgW));
                        float normY = Math.Max(0f, Math.Min(1f, (mousePos.Y - imgY) / imgH));
                        IsDrawingBgStroke = true;
                        CurrentDrawingStroke = new BgRemovalStroke
                        {
                            IsKeep = (BgRemovalTool == "Keep"),
                            BrushRadius = BgBrushRadius
                        };
                        CurrentDrawingStroke.Points.Add(new PointF(normX, normY));
                        return;
                    }
                }

                // Xử lý Chế độ Cắt ảnh Tương tác (Interactive Crop Mode)
                if (IsCropping && SelectedShape != null)
                {
                    ShapeNode cropShape = SelectedShape;
                    int csx = slideX + (int)(cropShape.Transform.X * scale);
                    int csy = slideY + (int)(cropShape.Transform.Y * scale);
                    int csw = (int)(cropShape.Transform.Width * scale);
                    int csh = (int)(cropShape.Transform.Height * scale);
                    float hitR = Math.Max(12f, 16f * scale);

                    CropHandleType clickedHandle = CropHandleType.None;

                    if (Math.Abs(mousePos.X - csx) <= hitR && Math.Abs(mousePos.Y - csy) <= hitR) clickedHandle = CropHandleType.TopLeft;
                    else if (Math.Abs(mousePos.X - (csx + csw)) <= hitR && Math.Abs(mousePos.Y - csy) <= hitR) clickedHandle = CropHandleType.TopRight;
                    else if (Math.Abs(mousePos.X - csx) <= hitR && Math.Abs(mousePos.Y - (csy + csh)) <= hitR) clickedHandle = CropHandleType.BottomLeft;
                    else if (Math.Abs(mousePos.X - (csx + csw)) <= hitR && Math.Abs(mousePos.Y - (csy + csh)) <= hitR) clickedHandle = CropHandleType.BottomRight;
                    else if (Math.Abs(mousePos.X - (csx + csw / 2f)) <= hitR && Math.Abs(mousePos.Y - csy) <= hitR) clickedHandle = CropHandleType.Top;
                    else if (Math.Abs(mousePos.X - (csx + csw / 2f)) <= hitR && Math.Abs(mousePos.Y - (csy + csh)) <= hitR) clickedHandle = CropHandleType.Bottom;
                    else if (Math.Abs(mousePos.X - csx) <= hitR && Math.Abs(mousePos.Y - (csy + csh / 2f)) <= hitR) clickedHandle = CropHandleType.Left;
                    else if (Math.Abs(mousePos.X - (csx + csw)) <= hitR && Math.Abs(mousePos.Y - (csy + csh / 2f)) <= hitR) clickedHandle = CropHandleType.Right;
                    else if (mousePos.X >= csx && mousePos.X <= csx + csw && mousePos.Y >= csy && mousePos.Y <= csy + csh) clickedHandle = CropHandleType.PanImage;

                    if (clickedHandle != CropHandleType.None)
                    {
                        SaveUndoState();
                        ActiveCropHandle = clickedHandle;
                        CropDragStartMouse = mousePos;
                        CropInitialLeft = cropShape.CropLeft;
                        CropInitialTop = cropShape.CropTop;
                        CropInitialRight = cropShape.CropRight;
                        CropInitialBottom = cropShape.CropBottom;
                        CropInitialShapeX = cropShape.Transform.X;
                        CropInitialShapeY = cropShape.Transform.Y;
                        CropInitialShapeW = cropShape.Transform.Width;
                        CropInitialShapeH = cropShape.Transform.Height;
                        return;
                    }
                    else
                    {
                        // Nhấp vùng trống bên ngoài -> Xác nhận Cắt ảnh và thoát chế độ Crop
                        ConfirmCrop();
                        return;
                    }
                }

                SlideNode slide = ActiveSlide;
                if (slide == null) return;

                // Check 8-handles & rotation knob & table move handle for selected shape
                if (SelectedShapeIndex >= 0 && SelectedShapeIndex < slide.Shapes.Count)
                {
                    ShapeNode shape = slide.Shapes[SelectedShapeIndex];
                    int sx = slideX + (int)(shape.Transform.X * scale);
                    int sy = slideY + (int)(shape.Transform.Y * scale);
                    int sw = (int)(shape.Transform.Width * scale);
                    int sh = (int)(shape.Transform.Height * scale);

                    if (!IsEditingShapePoints || shape != EditingPointsShape)
                    {
                        // Table Move Handle (Nút kéo bảng 4 chiều ✥ ở góc trên bên trái)
                        if (shape.Type == ShapeType.Table)
                        {
                            Rectangle moveHandleRect = new Rectangle(sx - 24, sy - 24, 24, 24);
                            if (buttons == MouseButtons.Left && moveHandleRect.Contains(mousePos))
                            {
                                SaveUndoState();
                                IsDraggingShape = true;
                                IsSelectingTableCells = false;
                                DragStartMouse = mousePos;
                                DragStartTransform = shape.Transform.Clone();
                                DragStartTransforms.Clear();
                                if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0)
                                {
                                    foreach (int idx in SelectedShapeIndices)
                                    {
                                        if (idx >= 0 && idx < slide.Shapes.Count)
                                        {
                                            DragStartTransforms[idx] = slide.Shapes[idx].Transform.Clone();
                                        }
                                    }
                                }
                                return;
                            }
                        }

                        // Corner rounding knob (Icon bo góc)
                        if (CanShapeRoundCorners(shape))
                        {
                            PointF crH = GetRotatedCornerRadiusHandle(sx, sy, sw, sh, shape.Transform.Rotation);
                            float dCrX = mousePos.X - crH.X;
                            float dCrY = mousePos.Y - crH.Y;
                            if (dCrX * dCrX + dCrY * dCrY <= 196f) // 14px hit radius
                            {
                                SaveUndoState();
                                IsAdjustingCornerRadius = true;
                                DragStartMouse = mousePos;
                                DragStartTransform = shape.Transform.Clone();
                                DragStartCornerRadius = shape.GetEffectiveCornerRadius();
                                return;
                            }
                        }

                        // Rotation knob (Mũi tên xoay)
                        PointF rotH = GetRotatedRotationHandle(sx, sy, sw, sh, shape.Transform.Rotation);
                        float dRotX = mousePos.X - rotH.X;
                        float dRotY = mousePos.Y - rotH.Y;
                        if (buttons == MouseButtons.Left && dRotX * dRotX + dRotY * dRotY <= 144f) // 12px hit radius
                        {
                            if (!IsPresenting && SlideVideoPlayerManager.Instance.IsPlaying) SlideVideoPlayerManager.Instance.Stop();
                            SaveUndoState();
                            IsRotatingShape = true;
                            DragStartMouse = mousePos;
                            DragStartTransform = shape.Transform.Clone();
                            return;
                        }

                        // 8 resize handles
                        PointF[] handles = GetRotatedHandleCoordinates(sx, sy, sw, sh, shape.Transform.Rotation);
                        for (int hIdx = 0; hIdx < handles.Length; hIdx++)
                        {
                            float dHX = mousePos.X - handles[hIdx].X;
                            float dHY = mousePos.Y - handles[hIdx].Y;
                            if (buttons == MouseButtons.Left && dHX * dHX + dHY * dHY <= 64f) // 8px hit radius
                            {
                                if (!IsPresenting && SlideVideoPlayerManager.Instance.IsPlaying) SlideVideoPlayerManager.Instance.Stop();
                                SaveUndoState();
                                IsResizingShape = true;
                                DragResizeHandleIndex = hIdx;
                                DragStartMouse = mousePos;
                                DragStartTransform = shape.Transform.Clone();
                                CropInitialLeft = shape.CropLeft;
                                CropInitialTop = shape.CropTop;
                                CropInitialRight = shape.CropRight;
                                CropInitialBottom = shape.CropBottom;
                                return;
                            }
                        }
                    }
                }

                // Audio Floating Playback Bar Hit Testing (PowerPoint style)
                if (!LastAudioPlaybackBarBounds.IsEmpty && LastAudioPlaybackBarBounds.Contains(mousePos) && HoveredAudioShape != null)
                {
                    ShapeNode aShape = HoveredAudioShape;
                    float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                    float barW = LastAudioPlaybackBarBounds.Width;
                    float scrubX = 74f;
                    float scrubW = Math.Max(30f, barW - 74f - 88f);

                    if (relX < 28f)
                    {
                        // Play / Pause
                        SlideAudioPlayerManager.Instance.TogglePlay(aShape, parentControl);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= 28f && relX < 48f)
                    {
                        // Rewind / Step backward
                        SlideAudioPlayerManager.Instance.StepRelative(aShape, -0.25f, parentControl);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= 48f && relX < 68f)
                    {
                        // Fast Forward / Step forward
                        SlideAudioPlayerManager.Instance.StepRelative(aShape, 0.25f, parentControl);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= scrubX && relX <= scrubX + scrubW)
                    {
                        // Timeline scrubber click / drag
                        IsDraggingAudioScrubber = true;
                        float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                        float totalSec = aShape.AudioTotalTime > 0 ? aShape.AudioTotalTime : 180f;
                        float targetSec = frac * totalSec;
                        if (!SlideAudioPlayerManager.Instance.IsPlaying || SlideAudioPlayerManager.Instance.ActiveShape != aShape)
                        {
                            SlideAudioPlayerManager.Instance.Play(aShape, parentControl);
                        }
                        SlideAudioPlayerManager.Instance.Seek(aShape, targetSec);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= barW - 28f)
                    {
                        // Volume / Mute
                        SlideAudioPlayerManager.Instance.ToggleMute(aShape);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }

                // Video Floating Playback Bar Hit Testing in Edit Mode
                ShapeNode targetVideo = HoveredVideoShape ?? (SelectedShape != null && (SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(SelectedShape.VideoPath)) ? SelectedShape : null);
                if (!LastVideoPlaybackBarBounds.IsEmpty && LastVideoPlaybackBarBounds.Contains(mousePos) && targetVideo != null)
                {
                    ShapeNode vShape = targetVideo;
                    float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                    float barW = LastVideoPlaybackBarBounds.Width;
                    float playBtnW = 32f;
                    float volBtnW = 32f;
                    float timeTextW = (barW > 240f) ? 80f : 0f;
                    float scrubX = playBtnW + 8f;
                    float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);

                    if (relX < playBtnW)
                    {
                        // Play / Pause
                        SlideVideoPlayerManager.Instance.TogglePlay(vShape, parentControl, default(Rectangle), false, () =>
                        {
                            if (InvalidateCallback != null) InvalidateCallback();
                        });
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= scrubX && relX <= scrubX + scrubW)
                    {
                        // Scrubber seek
                        IsDraggingVideoScrubber = true;
                        float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                        float totalSec = vShape.VideoTotalTime > 0 ? vShape.VideoTotalTime : 120f;
                        float targetSec = frac * totalSec;
                        if (!SlideVideoPlayerManager.Instance.IsPlaying || SlideVideoPlayerManager.Instance.ActiveShape != vShape)
                        {
                            SlideVideoPlayerManager.Instance.Play(vShape, parentControl, default(Rectangle), false, () =>
                            {
                                if (InvalidateCallback != null) InvalidateCallback();
                            });
                        }
                        SlideVideoPlayerManager.Instance.Seek(targetSec);
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else if (relX >= barW - volBtnW)
                    {
                        // Volume / Mute
                        SlideVideoPlayerManager.Instance.ToggleVolume();
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }

                // Hit test shapes in reverse Z-order (supporting rotated shape bodies & table move handles)
                int hitIndex = -1;
                for (int i = slide.Shapes.Count - 1; i >= 0; i--)
                {
                    ShapeNode shape = slide.Shapes[i];
                    int sx = slideX + (int)(shape.Transform.X * scale);
                    int sy = slideY + (int)(shape.Transform.Y * scale);
                    int sw = (int)(shape.Transform.Width * scale);
                    int sh = (int)(shape.Transform.Height * scale);

                    if (shape.Type == ShapeType.Table)
                    {
                        Rectangle moveHandleRect = new Rectangle(sx - 24, sy - 24, 24, 24);
                        if (buttons == MouseButtons.Left && moveHandleRect.Contains(mousePos))
                        {
                            hitIndex = i;
                            break;
                        }
                    }

                    PointF center = new PointF(sx + sw / 2f, sy + sh / 2f);
                    PointF unrotatedMouse = RotatePoint(mousePos, center, -shape.Transform.Rotation);
                    RectangleF shapeBounds = (shape.Type == ShapeType.Line || (shape.Type == ShapeType.CustomPath && (sw < 14 || sh < 14)))
                        ? new RectangleF(sx - 8f, sy - 8f, Math.Max(16f, sw + 16f), Math.Max(16f, sh + 16f))
                        : new RectangleF(sx, sy, sw, sh);
                    if (shapeBounds.Contains(unrotatedMouse))
                    {
                        hitIndex = i;
                        break;
                    }
                }

                if (hitIndex >= 0)
                {
                    int prevSelectedShapeIndex = (SelectedShapeIndices != null && SelectedShapeIndices.Count == 1) ? SelectedShapeIndex : -1;
                    ShapeNode hitShape = slide.Shapes[hitIndex];
                    bool isCtrlOrShift = (Control.ModifierKeys & Keys.Control) != 0 || (Control.ModifierKeys & Keys.Shift) != 0;
                    if (isCtrlOrShift)
                    {
                        EndInlineEditing();
                        if (SelectedShapeIndices == null) SelectedShapeIndices = new List<int>();
                        if (!SelectedShapeIndices.Contains(hitIndex))
                        {
                            SelectedShapeIndices.Add(hitIndex);
                            SelectedShapeIndex = hitIndex;
                            _pendingDeselectOnMouseUp = false;
                        }
                        else
                        {
                            // Already in selection -> keep selected so mouse drag moves all of them; deselect on mouse up if clicked without drag
                            SelectedShapeIndex = hitIndex;
                            _pendingDeselectOnMouseUp = true;
                            _pendingDeselectIndex = hitIndex;
                        }
                    }
                    else
                    {
                        if (SelectedShapeIndices == null) SelectedShapeIndices = new List<int>();
                        if (!SelectedShapeIndices.Contains(hitIndex))
                        {
                            EndInlineEditing();
                            SelectedShapeIndices.Clear();
                            SelectedShapeIndices.Add(hitIndex);
                            SelectedShapeIndex = hitIndex;
                        }
                        else
                        {
                            SelectedShapeIndex = hitIndex;
                        }
                        _pendingDeselectOnMouseUp = false;
                    }

                    if (hitShape.Type == ShapeType.Table && (SelectedShapeIndices == null || SelectedShapeIndices.Count <= 1))
                    {
                        int sx = slideX + (int)(hitShape.Transform.X * scale);
                        int sy = slideY + (int)(hitShape.Transform.Y * scale);
                        int sw = (int)(hitShape.Transform.Width * scale);
                        int sh = (int)(hitShape.Transform.Height * scale);

                        Rectangle moveHandleRect = new Rectangle(sx - 24, sy - 24, 24, 24);
                        bool isMoveHandle = moveHandleRect.Contains(mousePos);
                        bool isNearOuterBorder = (mousePos.X <= sx + 6 || mousePos.X >= sx + sw - 6 || mousePos.Y <= sy + 6 || mousePos.Y >= sy + sh - 6);

                        int cols = Math.Max(1, hitShape.TableColumns);
                        int rows = Math.Max(1, hitShape.TableRows);

                        int c = hitShape.HitTestColumn(mousePos.X - sx, sw);
                        int r = hitShape.HitTestRow(mousePos.Y - sy, sh);

                        hitShape.TableSelectedCellRow = r;
                        hitShape.TableSelectedCellCol = c;
                        hitShape.TableSelectedEndRow = r;
                        hitShape.TableSelectedEndCol = c;

                        // 1. Nhấp vào Nút Kéo 4 chiều ✥ HOẶC Viền ngoài của bảng -> KÉO DI CHUYỂN BẢNG
                        if (isMoveHandle || isNearOuterBorder)
                        {
                            if (buttons == MouseButtons.Left)
                            {
                                SaveUndoState();
                                IsDraggingShape = true;
                                IsSelectingTableCells = false;
                                DragStartMouse = mousePos;
                                DragStartTransform = slide.Shapes[hitIndex].Transform.Clone();
                                DragStartTransforms.Clear();
                                if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0)
                                {
                                    foreach (int idx in SelectedShapeIndices)
                                    {
                                        if (idx >= 0 && idx < slide.Shapes.Count)
                                        {
                                            DragStartTransforms[idx] = slide.Shapes[idx].Transform.Clone();
                                        }
                                    }
                                }
                            }

                            if (buttons == MouseButtons.Right)
                            {
                                ShowTableContextMenu(parentControl, mousePos, hitIndex, r, c);
                            }
                            return;
                        }
                        else
                        {
                            // 2. Nhấp bên trong các ô của bảng -> QUÉT KHỐI CHỌN Ô NGAY LẬP TỨC!
                            IsSelectingTableCells = true;
                            IsDraggingShape = false;
                            TableDragStartRow = r;
                            TableDragStartCol = c;

                            if (buttons == MouseButtons.Right)
                            {
                                ShowTableContextMenu(parentControl, mousePos, hitIndex, r, c);
                                return;
                            }
                            return;
                        }
                    }

                    if (hitShape.Type == ShapeType.Audio || !string.IsNullOrEmpty(hitShape.AudioPath))
                    {
                        HoveredAudioShape = hitShape;
                        if (IsPresenting)
                        {
                            SlideAudioPlayerManager.Instance.TogglePlay(hitShape, parentControl);
                            return;
                        }
                    }

                    if (IsInlineEditing && EditingShape == hitShape)
                    {
                        float hsx = slideX + hitShape.Transform.X * scale;
                        float hsy = slideY + hitShape.Transform.Y * scale;
                        float hsw = hitShape.Transform.Width * scale;
                        float hsh = hitShape.Transform.Height * scale;
                        PointF hcenter = new PointF(hsx + hsw / 2f, hsy + hsh / 2f);
                        PointF hlocal = RotatePoint(mousePos, hcenter, -hitShape.Transform.Rotation);
                        float borderTol = Math.Max(7f, 10f * scale);

                        // Nhấn vào rìa / khung viền của đối tượng: thoát soạn thảo và chuyển ngay sang hành động kéo thả di chuyển!
                        if (hlocal.X <= hsx + borderTol || hlocal.X >= hsx + hsw - borderTol ||
                            hlocal.Y <= hsy + borderTol || hlocal.Y >= hsy + hsh - borderTol)
                        {
                            EndInlineEditing();
                            IsDraggingShape = true;
                            DragStartMouse = mousePos;
                            DragStartTransform = hitShape.Transform.Clone();
                            DragStartTransforms.Clear();
                            if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0)
                            {
                                foreach (int idx in SelectedShapeIndices)
                                {
                                    if (idx >= 0 && idx < slide.Shapes.Count)
                                    {
                                        DragStartTransforms[idx] = slide.Shapes[idx].Transform.Clone();
                                    }
                                }
                            }
                            if (parentControl != null) parentControl.Invalidate();
                            return;
                        }

                        IsDraggingShape = false;
                        CaretIndex = GetTextCharIndexFromPoint(mousePos, hitShape, slideX, slideY, scale);
                        TextSelectionStart = CaretIndex;
                        TextSelectionLength = 0;
                        IsSelectingText = true;
                        if (parentControl != null) parentControl.Invalidate();
                        return;
                    }

                    SyncSelectedAnimationWithShape();
                    if (buttons == MouseButtons.Left)
                    {
                        if (!IsPresenting && SlideVideoPlayerManager.Instance.IsPlaying) SlideVideoPlayerManager.Instance.Stop();
                        SaveUndoState();
                        IsDraggingShape = true;
                        DragStartMouse = mousePos;
                        DragStartTransform = slide.Shapes[hitIndex].Transform.Clone();
                        DragStartTransforms.Clear();
                        if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0)
                        {
                            foreach (int idx in SelectedShapeIndices)
                            {
                                if (idx >= 0 && idx < slide.Shapes.Count)
                                {
                                    DragStartTransforms[idx] = slide.Shapes[idx].Transform.Clone();
                                }
                            }
                        }
                    }
                }
                else
                {
                    if (!IsPresenting && SlideVideoPlayerManager.Instance.IsPlaying) SlideVideoPlayerManager.Instance.Stop();
                    bool isCtrlOrShift = (Control.ModifierKeys & Keys.Control) != 0 || (Control.ModifierKeys & Keys.Shift) != 0;
                    if (!isCtrlOrShift)
                    {
                        SelectedShapeIndex = -1;
                        SelectedShapeIndices.Clear();
                        _rubberbandInitialSelection.Clear();
                    }
                    else
                    {
                        _rubberbandInitialSelection = new HashSet<int>(SelectedShapeIndices);
                    }
                    SelectedAnimationIndex = -1;
                    EndInlineEditing();

                    if (buttons == MouseButtons.Left)
                    {
                        IsRubberbandSelecting = true;
                        RubberbandStartPoint = mousePos;
                        RubberbandCurrentPoint = mousePos;
                    }
                }

                if (buttons == MouseButtons.Right)
                {
                    if (hitIndex >= 0)
                    {
                        ShowShapeContextMenu(parentControl, mousePos, hitIndex);
                    }
                    else
                    {
                        ShowSlideContextMenu(parentControl, mousePos);
                    }
                    return;
                }
            }
            else if (ViewMode == ImpressViewMode.SlideSorter && Presentation != null)
            {
                int cardW = 240;
                int cardH = Presentation.IsWidescreen ? (cardW * 9 / 16) : (cardW * 3 / 4);
                int padding = 30;
                int cols = Math.Max(1, (width - padding) / (cardW + padding));

                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    int row = i / cols;
                    int col = i % cols;
                    int cx = padding + col * (cardW + padding);
                    int cy = contentY + padding + row * (cardH + padding + 30);
                    Rectangle cardRect = new Rectangle(cx, cy, cardW, cardH + 28);

                    if (cardRect.Contains(mousePos))
                    {
                        ActiveSlideIndex = i;
                        if (parentControl != null) parentControl.Invalidate();
                        return;
                    }
                }
            }
            else if (ViewMode == ImpressViewMode.Outline && Presentation != null)
            {
                int itemH = 50;
                for (int i = 0; i < Presentation.Slides.Count; i++)
                {
                    int itemY = contentY + 20 + i * (itemH + 10);
                    Rectangle itemRect = new Rectangle(leftSidebarW + 30, itemY, canvasW - 60, itemH);
                    if (itemRect.Contains(mousePos))
                    {
                        ActiveSlideIndex = i;
                        if (parentControl != null) parentControl.Invalidate();
                        return;
                    }
                }
            }
            else if (ViewMode == ImpressViewMode.Notes && Presentation != null)
            {
                int pageW = 480;
                int pageH = 640;
                int pageX = canvasX + (canvasW - pageW) / 2;
                int pageY = contentY + 20;
                int miniW = pageW - 40;
                int miniH = miniW * 9 / 16;
                int notesY = pageY + 20 + miniH + 20;
                int notesH = pageH - (notesY - pageY) - 20;
                Rectangle notesRect = new Rectangle(pageX + 20, notesY, miniW, notesH);

                if (notesRect.Contains(mousePos) && ActiveSlide != null)
                {
                    EndInlineEditing();
                    SelectedShapeIndex = -1;
                    if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                    IsEditingSpeakerNotes = true;
                    RectangleF notesTextBounds = new RectangleF(notesRect.X + 8, notesRect.Y + 30, Math.Max(40, notesRect.Width - 16), Math.Max(20, notesRect.Height - 38));
                    SpeakerNotesCaretIndex = GetSpeakerNotesCharIndexFromPoint(mousePos, notesTextBounds, 10.5f);
                    SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                    SpeakerNotesSelectionLength = 0;
                    IsSelectingSpeakerNotes = (buttons == MouseButtons.Left);
                }
                else
                {
                    IsEditingSpeakerNotes = false;
                }
                if (parentControl != null) parentControl.Invalidate();
                return;
            }
        }

        public void HandleDoubleClick(Point mousePos, int width, int height, Control parentControl = null)
        {
            if (IsPresenting) return;
            if (IsDrawingShapeMode && IsScribbleMode)
            {
                if (ScribblePoints.Count >= 2)
                {
                    PointF pLast = ScribblePoints[ScribblePoints.Count - 1];
                    PointF pPrev = ScribblePoints[ScribblePoints.Count - 2];
                    float dX = pLast.X - pPrev.X;
                    float dY = pLast.Y - pPrev.Y;
                    if (dX * dX + dY * dY <= 25f && ScribblePoints.Count > 2)
                    {
                        ScribblePoints.RemoveAt(ScribblePoints.Count - 1);
                    }
                    FinalizeScribbleShape(shouldClose: ScribblePoints.Count >= 3);
                }
                else
                {
                    CancelShapeDrawMode();
                }
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }
            if (ViewMode == ImpressViewMode.SlideSorter || ViewMode == ImpressViewMode.Outline)
            {
                ViewMode = ImpressViewMode.Normal;
                if (parentControl != null) parentControl.Invalidate();
                return;
            }
            if (ActiveSlide == null) return;

            int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
            GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);

            if (IsEditingSpeakerNotes && !LastNotesTextRect.IsEmpty && LastNotesTextRect.Contains(mousePos))
            {
                string notes = ActiveSlide.SpeakerNotes ?? "";
                if (notes.Length > 0)
                {
                    int idx = Math.Max(0, Math.Min(SpeakerNotesCaretIndex, notes.Length));
                    int wStart = idx;
                    while (wStart > 0 && !char.IsWhiteSpace(notes[wStart - 1])) wStart--;
                    int wEnd = idx;
                    while (wEnd < notes.Length && !char.IsWhiteSpace(notes[wEnd])) wEnd++;
                    SpeakerNotesSelectionStart = wStart;
                    SpeakerNotesSelectionLength = wEnd - wStart;
                    SpeakerNotesCaretIndex = wEnd;
                    if (parentControl != null) parentControl.Invalidate();
                }
                return;
            }

            int slideX, slideY, slideW, slideH;
            float scale;
            GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out slideX, out slideY, out slideW, out slideH, out scale);

            if (SelectedShape != null && CanShapeRoundCorners(SelectedShape))
            {
                ShapeNode selShape = SelectedShape;
                int ssx = slideX + (int)(selShape.Transform.X * scale);
                int ssy = slideY + (int)(selShape.Transform.Y * scale);
                int ssw = (int)(selShape.Transform.Width * scale);
                int ssh = (int)(selShape.Transform.Height * scale);
                PointF crH = GetRotatedCornerRadiusHandle(ssx, ssy, ssw, ssh, selShape.Transform.Rotation);
                float dCrX = mousePos.X - crH.X;
                float dCrY = mousePos.Y - crH.Y;
                if (dCrX * dCrX + dCrY * dCrY <= 196f)
                {
                    SaveUndoState();
                    if (selShape.GetEffectiveCornerRadius() > 0.5f)
                    {
                        selShape.CornerRadius = 0f;
                        selShape.Type = ShapeType.Rectangle;
                    }
                    else
                    {
                        selShape.CornerRadius = Math.Min(20f, Math.Min(selShape.Transform.Width, selShape.Transform.Height) / 2f);
                        selShape.Type = ShapeType.RoundedRectangle;
                    }
                    if (parentControl != null) parentControl.Invalidate();
                    return;
                }
            }

            for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
            {
                ShapeNode shape = ActiveSlide.Shapes[i];
                int sx = slideX + (int)(shape.Transform.X * scale);
                int sy = slideY + (int)(shape.Transform.Y * scale);
                int sw = (int)(shape.Transform.Width * scale);
                int sh = (int)(shape.Transform.Height * scale);

                Rectangle shapeBounds = new Rectangle(sx, sy, sw, sh);
                if (shapeBounds.Contains(mousePos))
                {
                    SelectedShapeIndex = i;
                    if (!string.IsNullOrEmpty(shape.SmartArtType) || (shape.Name != null && shape.Name.StartsWith("SmartArt")))
                    {
                        OpenSmartArtEditor(shape);
                        break;
                    }

                    if (shape.Type == ShapeType.Video || !string.IsNullOrEmpty(shape.VideoPath))
                    {
                        // In PowerPoint edit mode, double clicking selects the shape; playback is controlled via the playback bar
                        break;
                    }
                    else if (shape.Type == ShapeType.Chart || shape.ChartData != null)
                    {
                        DocChartData cd = shape.ChartData ?? DocChartData.CreateDefault(shape.Text);
                        shape.ChartData = cd;

                        int titleH = (int)(38 * scale);
                        Rectangle titleZone = new Rectangle(sx, sy, sw, titleH);

                        if (titleZone.Contains(mousePos))
                        {
                            // Double clicked on Chart Title -> Open Rename Form!
                            Point scrPt = parentControl != null ? parentControl.PointToScreen(new Point(sx + sw / 4, sy + 10)) : mousePos;
                            ChartTitleRenameForm renameDlg = new ChartTitleRenameForm(cd, scrPt);
                            renameDlg.OnTitleChanged = (newTitle, showTitle) =>
                            {
                                cd.Title = newTitle;
                                cd.ShowTitle = showTitle;
                                shape.Name = newTitle;
                                shape.Text = newTitle;
                                if (parentControl != null) parentControl.Invalidate();
                            };
                            renameDlg.ShowDialog(parentControl);
                        }
                        else
                        {
                            // Double clicked on Chart Body -> Open Excel Data Form!
                            ChartDataExcelForm excelForm = new ChartDataExcelForm(cd);
                            excelForm.OnDataChanged = (newData) =>
                            {
                                shape.ChartData = newData;
                                if (parentControl != null) parentControl.Invalidate();
                            };
                            excelForm.Show();
                        }
                        break;
                    }
                    else if (shape.Type == ShapeType.Table)
                    {
                        int cols = Math.Max(1, shape.TableColumns);
                        int rows = Math.Max(1, shape.TableRows);
                        float cellW = sw / (float)cols;
                        float cellH = sh / (float)rows;

                        int c = (int)((mousePos.X - sx) / cellW);
                        int r = (int)((mousePos.Y - sy) / cellH);
                        c = Math.Max(0, Math.Min(cols - 1, c));
                        r = Math.Max(0, Math.Min(rows - 1, r));

                        StartTableInlineEditing(shape, r, c);
                    }
                    else
                    {
                        StartInlineEditing(shape);
                        CaretIndex = GetTextCharIndexFromPoint(mousePos, shape, slideX, slideY, scale);
                        TextSelectionStart = CaretIndex;
                        TextSelectionLength = 0;
                        if (parentControl != null) parentControl.Invalidate();
                    }
                    break;
                }
            }
        }

        public void HandleMouseMove(Point mousePos, int width, int height)
        {
            CurrentMouseCanvasPos = mousePos;

            if (IsPresenting)
            {
                LastPresenterMouseMovePos = mousePos;
                LastPresenterMouseMoveTime = DateTime.Now;
                HoverToolbarButtonIndex = GetHoverToolbarButtonAt(mousePos, height);

                if (LaserPointerMode)
                {
                    CurrentLaserPoint = mousePos;
                }
                if (AnnotationPenMode && CurrentStroke.Count > 0)
                {
                    CurrentStroke.Add(mousePos);
                }

                // Check for Video and Audio hover in Presentation Mode!
                ShapeNode prevHoveredVideo = HoveredVideoShape;
                ShapeNode prevHoveredAudio = HoveredAudioShape;
                int prevHoveredVideoBtn = HoveredVideoButton;
                bool prevHoveredVideoScrub = IsHoveringVideoScrubber;
                int prevHoveredAudioBtn = HoveredAudioButton;
                bool prevHoveredAudioScrub = IsHoveringAudioScrubber;

                HoveredVideoShape = null;
                HoveredAudioShape = null;
                bool isOverMedia = false;

                if (IsSelectingSpeakerNotes && IsEditingSpeakerNotes && !LastNotesTextRect.IsEmpty)
                {
                    SpeakerNotesCaretIndex = GetSpeakerNotesCharIndexFromPoint(mousePos, LastNotesTextRect, LastNotesFontSize);
                    SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                    Cursor.Current = Cursors.IBeam;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                if (IsDraggingAudioScrubber && !LastAudioPlaybackBarBounds.IsEmpty)
                {
                    ShapeNode targetAudio = prevHoveredAudio ?? SlideAudioPlayerManager.Instance.ActiveShape;
                    if (targetAudio != null)
                    {
                        HoveredAudioShape = targetAudio;
                        isOverMedia = true;
                        float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                        float barW = LastAudioPlaybackBarBounds.Width;
                        float scrubX = 74f;
                        float scrubW = barW - 74f - 88f;
                        float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                        float totalSec = targetAudio.AudioTotalTime > 0 ? targetAudio.AudioTotalTime : 180f;
                        HoveredAudioScrubberTime = frac * totalSec;
                        IsHoveringAudioScrubber = true;
                        SlideAudioPlayerManager.Instance.Seek(targetAudio, HoveredAudioScrubberTime);
                        if (InvalidateCallback != null) InvalidateCallback();
                    }
                }
                else if (IsDraggingVideoScrubber && !LastVideoPlaybackBarBounds.IsEmpty)
                {
                    ShapeNode targetVideo = HoveredVideoShape ?? prevHoveredVideo ?? SlideVideoPlayerManager.Instance.ActiveShape;
                    if (targetVideo != null)
                    {
                        HoveredVideoShape = targetVideo;
                        isOverMedia = true;
                        float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                        float barW = LastVideoPlaybackBarBounds.Width;
                        float playBtnW = 32f;
                        float volBtnW = 32f;
                        float timeTextW = (barW > 240f) ? 80f : 0f;
                        float scrubX = playBtnW + 8f;
                        float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);
                        float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                        float totalSec = targetVideo.VideoTotalTime > 0 ? targetVideo.VideoTotalTime : 120f;
                        SlideVideoPlayerManager.Instance.Seek(frac * totalSec);
                        if (InvalidateCallback != null) InvalidateCallback();
                    }
                }
                else if (ActiveSlide != null && !LaserPointerMode && !AnnotationPenMode)
                {
                    int presSlideX, presSlideY, presSlideW, presSlideH;
                    float presScale;
                    GetCurrentActiveSlidePresentationMetrics(width, height, out presSlideX, out presSlideY, out presSlideW, out presSlideH, out presScale);

                    // Check if mouse is hovering over the active video floating playback bar
                    ShapeNode barVideo = HoveredVideoShape ?? prevHoveredVideo ?? SlideVideoPlayerManager.Instance.ActiveShape;
                    if (!LastVideoPlaybackBarBounds.IsEmpty && LastVideoPlaybackBarBounds.Contains(mousePos) && barVideo != null)
                    {
                        HoveredVideoShape = barVideo;
                        isOverMedia = true;
                        float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                        float barW = LastVideoPlaybackBarBounds.Width;
                        float playBtnW = 32f;
                        float volBtnW = 32f;
                        float timeTextW = (barW > 240f) ? 80f : 0f;
                        float scrubX = playBtnW + 8f;
                        float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);

                        if (relX < playBtnW)
                        {
                            HoveredVideoButton = 0;
                            IsHoveringVideoScrubber = false;
                        }
                        else if (relX >= barW - volBtnW)
                        {
                            HoveredVideoButton = 2;
                            IsHoveringVideoScrubber = false;
                        }
                        else
                        {
                            HoveredVideoButton = 1;
                            IsHoveringVideoScrubber = true;
                            float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                            float totalSec = barVideo.VideoTotalTime > 0 ? barVideo.VideoTotalTime : 120f;
                            HoveredVideoScrubberTime = frac * totalSec;
                        }
                    }
                    else
                    {
                        // Check if mouse is hovering over the active audio floating playback bar or bridging between speaker icon and bar
                        ShapeNode activeOrPrevAudio = prevHoveredAudio ?? SlideAudioPlayerManager.Instance.ActiveShape;
                        bool inAudioEnvelope = false;
                        if (activeOrPrevAudio != null && !LastAudioPlaybackBarBounds.IsEmpty)
                        {
                            float asx = presSlideX + activeOrPrevAudio.Transform.X * presScale;
                            float asy = presSlideY + activeOrPrevAudio.Transform.Y * presScale;
                            float asw = activeOrPrevAudio.Transform.Width * presScale;
                            float ash = activeOrPrevAudio.Transform.Height * presScale;
                            RectangleF iconScreenRect = new RectangleF(asx - 8f, asy - 8f, asw + 16f, ash + 16f);
                            RectangleF barScreenRect = new RectangleF(
                                LastAudioPlaybackBarBounds.X - 10f,
                                Math.Min(iconScreenRect.Bottom - 8f, LastAudioPlaybackBarBounds.Y - 12f),
                                LastAudioPlaybackBarBounds.Width + 20f,
                                (LastAudioPlaybackBarBounds.Bottom - Math.Min(iconScreenRect.Bottom - 8f, LastAudioPlaybackBarBounds.Y - 12f)) + 12f);

                            if (iconScreenRect.Contains(mousePos) || barScreenRect.Contains(mousePos))
                            {
                                inAudioEnvelope = true;
                            }
                        }

                        if (inAudioEnvelope && activeOrPrevAudio != null)
                        {
                            HoveredAudioShape = activeOrPrevAudio;
                            isOverMedia = true;
                            HoveredAudioButton = -1;
                            IsHoveringAudioScrubber = false;

                            if (!LastAudioPlaybackBarBounds.IsEmpty && LastAudioPlaybackBarBounds.Contains(mousePos))
                            {
                                float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                                float barW = LastAudioPlaybackBarBounds.Width;
                                float scrubX = 74f;
                                float scrubW = barW - 74f - 88f;

                                if (relX < 28f) HoveredAudioButton = 0; // Play/Pause
                                else if (relX >= 28f && relX < 48f) HoveredAudioButton = 1; // Rewind
                                else if (relX >= 48f && relX < 68f) HoveredAudioButton = 2; // Fast-forward
                                else if (relX >= scrubX && relX <= scrubX + scrubW)
                                {
                                    HoveredAudioButton = 3; // Scrubber
                                    IsHoveringAudioScrubber = true;
                                    float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                                    float totalSec = activeOrPrevAudio.AudioTotalTime > 0 ? activeOrPrevAudio.AudioTotalTime : 180f;
                                    HoveredAudioScrubberTime = frac * totalSec;
                                }
                                else if (relX >= barW - 28f) HoveredAudioButton = 4; // Volume
                            }
                        }
                        else
                        {
                            for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
                            {
                                ShapeNode s = ActiveSlide.Shapes[i];
                                if (s == null) continue;
                                int sx = presSlideX + (int)(s.Transform.X * presScale);
                                int sy = presSlideY + (int)(s.Transform.Y * presScale);
                                int sw = (int)(s.Transform.Width * presScale);
                                int sh = (int)(s.Transform.Height * presScale);

                                if (mousePos.X >= sx && mousePos.X <= sx + sw && mousePos.Y >= sy && mousePos.Y <= sy + sh)
                                {
                                    if (s.Type == ShapeType.Video || !string.IsNullOrEmpty(s.VideoPath))
                                    {
                                        HoveredVideoShape = s;
                                        HoveredVideoButton = -1;
                                        IsHoveringVideoScrubber = false;
                                        LastVideoHoverTime = DateTime.Now;
                                        isOverMedia = true;
                                        break;
                                    }
                                    else if (s.Type == ShapeType.Audio || !string.IsNullOrEmpty(s.AudioPath))
                                    {
                                        HoveredAudioShape = s;
                                        HoveredAudioButton = -1;
                                        IsHoveringAudioScrubber = false;
                                        isOverMedia = true;
                                        break;
                                    }
                                }
                            }
                        }

                        if (HoveredVideoShape == null)
                        {
                            LastVideoPlaybackBarBounds = RectangleF.Empty;
                            HoveredVideoButton = -1;
                            IsHoveringVideoScrubber = false;
                        }
                        if (HoveredAudioShape == null && (SlideAudioPlayerManager.Instance.ActiveShape == null || !SlideAudioPlayerManager.Instance.ActiveShape.IsAudioPlaying))
                        {
                            LastAudioPlaybackBarBounds = RectangleF.Empty;
                            HoveredAudioButton = -1;
                            IsHoveringAudioScrubber = false;
                        }
                    }
                }

                if (IsPresenterViewMode && !LastNotesTextRect.IsEmpty && LastNotesTextRect.Contains(mousePos))
                {
                    Cursor.Current = Cursors.IBeam;
                }
                else if (isOverMedia || HoverToolbarButtonIndex >= 0)
                {
                    Cursor.Current = Cursors.Hand;
                }
                else if (!LaserPointerMode && !AnnotationPenMode)
                {
                    Cursor.Current = Cursors.Default;
                }

                if (prevHoveredVideo != HoveredVideoShape || prevHoveredAudio != HoveredAudioShape ||
                    prevHoveredVideoBtn != HoveredVideoButton || prevHoveredVideoScrub != IsHoveringVideoScrubber ||
                    prevHoveredAudioBtn != HoveredAudioButton || prevHoveredAudioScrub != IsHoveringAudioScrubber)
                {
                    if (InvalidateCallback != null) InvalidateCallback();
                }

                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsDrawingShapeMode && IsScribbleMode)
            {
                int sc_sbW, sc_cX, sc_cW, sc_cY, sc_cH, sc_btmH;
                GetEffectiveLayoutMetrics(width, height, out sc_sbW, out sc_cX, out sc_cW, out sc_cY, out sc_cH, out sc_btmH);
                int sc_sX, sc_sY, sc_sW, sc_sH;
                float sc_scale;
                GetSlideCanvasBounds(sc_cX, sc_cY, sc_cW, sc_cH, out sc_sX, out sc_sY, out sc_sW, out sc_sH, out sc_scale);
                float cX = (mousePos.X - sc_sX) / sc_scale;
                float cY = (mousePos.Y - sc_sY) / sc_scale;
                ScribbleHoverPoint = new PointF(cX, cY);

                if (IsDrawingActive && ScribblePoints.Count > 0)
                {
                    ShapeDrawCurrent = mousePos;
                    PointF last = ScribblePoints[ScribblePoints.Count - 1];
                    float dx = (cX - last.X) * sc_scale;
                    float dy = (cY - last.Y) * sc_scale;
                    if (dx * dx + dy * dy >= 16f)
                    {
                        ScribblePoints.Add(new PointF(cX, cY));
                    }
                }
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsDrawingActive)
            {
                ShapeDrawCurrent = mousePos;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsElementsDrawerOpen && ElementsDrawerSelectedTab == 1 && ShapeTaskPane != null)
            {
                if (ShapeTaskPane.HandleMouseMove(mousePos))
                {
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
            }

            // Bottom Thumbnail Strip Scrollbar Dragging & Hover
            if (IsDraggingBottomThumbScrollBar && !BottomThumbScrollBarTrackRect.IsEmpty)
            {
                int trackW = BottomThumbScrollBarTrackRect.Width;
                int thumbW = BottomThumbScrollBarThumbRect.Width;
                int availX = trackW - thumbW;
                int totalBottomWidth = (Presentation != null ? Presentation.Slides.Count : 0) * (86 + 10) + 60;
                int maxScroll = Math.Max(0, totalBottomWidth - trackW);
                if (availX > 0 && maxScroll > 0)
                {
                    int deltaX = mousePos.X - _bottomThumbScrollDragStartMouseX;
                    int newScroll = _bottomThumbScrollDragStartScrollX + (int)((float)deltaX / availX * maxScroll);
                    BottomThumbScrollX = Math.Max(0, Math.Min(maxScroll, newScroll));
                    SmoothBottomThumbScrollX = BottomThumbScrollX;
                    TargetBottomThumbScrollX = BottomThumbScrollX;
                    if (InvalidateCallback != null) InvalidateCallback();
                }
                return;
            }

            bool prevHoverBtmThumb = IsHoverBottomThumbScrollBarThumb;
            IsHoverBottomThumbScrollBarThumb = !BottomThumbScrollBarThumbRect.IsEmpty && BottomThumbScrollBarThumbRect.Contains(mousePos);
            if (prevHoverBtmThumb != IsHoverBottomThumbScrollBarThumb)
            {
                if (InvalidateCallback != null) InvalidateCallback();
            }

            // Left Thumbnail Fast Scrollbar Dragging & Hover
            if (_isDraggingThumbScrollBar)
            {
                int trackH = ThumbScrollBarTrackRect.Height;
                int thumbBarH = ThumbScrollBarThumbRect.Height;
                int availY = trackH - thumbBarH;
                bool isIslandMode = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
                int paneW = isIslandMode ? 200 : 210;
                int viewH = (LastThumbViewportHeight > 0) ? LastThumbViewportHeight : 500;
                int totalContentH = GetTotalThumbContentHeight(paneW);
                int maxScroll = GetMaxThumbScrollY();
                if (availY > 0 && maxScroll > 0)
                {
                    int deltaY = mousePos.Y - _thumbScrollDragStartMouseY;
                    int newScroll = _thumbScrollDragStartScrollY + (int)((float)deltaY / availY * maxScroll);
                    ThumbScrollY = Math.Max(0, Math.Min(maxScroll, newScroll));
                    SmoothThumbScrollY = ThumbScrollY;
                    TargetThumbScrollY = ThumbScrollY;
                    if (InvalidateCallback != null) InvalidateCallback();
                }
                return;
            }

            bool prevHoverThumb = _isHoverThumbScrollBarThumb;
            bool prevHoverTrack = _isHoverThumbScrollBar;
            _isHoverThumbScrollBarThumb = !ThumbScrollBarThumbRect.IsEmpty && ThumbScrollBarThumbRect.Contains(mousePos);
            _isHoverThumbScrollBar = !ThumbScrollBarTrackRect.IsEmpty && ThumbScrollBarTrackRect.Contains(mousePos);
            if (prevHoverThumb != _isHoverThumbScrollBarThumb || prevHoverTrack != _isHoverThumbScrollBar)
            {
                if (InvalidateCallback != null) InvalidateCallback();
            }

            int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
            GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);
            int rightSidebarW = (IsSidebarOpen && SidebarPanel != SidebarPanelType.None && !IsPresenting) ? 280 : 0;

            if (IsDraggingNotesSplitter)
            {
                int deltaY = NotesSplitterDragStartMouseY - mousePos.Y;
                NotesPaneHeight = Math.Max(42, Math.Min(Math.Max(140, contentH / 2), NotesSplitterDragStartHeight + deltaY));
                Cursor.Current = Cursors.SizeNS;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsSelectingSpeakerNotes && IsEditingSpeakerNotes && !LastNotesTextRect.IsEmpty)
            {
                SpeakerNotesCaretIndex = GetSpeakerNotesCharIndexFromPoint(mousePos, LastNotesTextRect, LastNotesFontSize);
                SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                Cursor.Current = Cursors.IBeam;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            int effNotesH = GetEffectiveNotesPaneHeight();
            bool prevHoverNotesSplitter = IsHoverNotesSplitter;
            if (effNotesH > 0 && mousePos.X >= canvasX && mousePos.X <= canvasX + canvasW)
            {
                int notesTopY = contentY + Math.Max(80, contentH - effNotesH);
                IsHoverNotesSplitter = (mousePos.Y >= notesTopY - 4 && mousePos.Y <= notesTopY + 4);
            }
            else
            {
                IsHoverNotesSplitter = false;
            }
            if (prevHoverNotesSplitter != IsHoverNotesSplitter && InvalidateCallback != null)
            {
                InvalidateCallback();
            }

            if (IsColorPickingMode && SelectedShape != null && SelectedShape.CachedImage != null)
            {
                int cpSlideX, cpSlideY, cpSlideW, cpSlideH;
                float cpScale;
                GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out cpSlideX, out cpSlideY, out cpSlideW, out cpSlideH, out cpScale);
                ShapeNode cpShape = SelectedShape;
                float imgX = cpSlideX + cpShape.Transform.X * cpScale;
                float imgY = cpSlideY + cpShape.Transform.Y * cpScale;
                float imgW = cpShape.Transform.Width * cpScale;
                float imgH = cpShape.Transform.Height * cpScale;

                if (mousePos.X >= imgX && mousePos.X <= imgX + imgW && mousePos.Y >= imgY && mousePos.Y <= imgY + imgH)
                {
                    float normX = Math.Max(0f, Math.Min(1f, (mousePos.X - imgX) / imgW));
                    float normY = Math.Max(0f, Math.Min(1f, (mousePos.Y - imgY) / imgH));
                    Color hovered = GetPixelColorFromImage(cpShape.CachedImage, normX, normY);
                    ColorPickHoverColor = hovered;
                    HasColorPickHover = true;
                    ColorPickMouseCanvasPos = mousePos;
                }
                else
                {
                    HasColorPickHover = false;
                }
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsRemovingBackground && SelectedShape != null && SelectedShape.CachedImage != null)
            {
                int bgSlideX, bgSlideY, bgSlideW, bgSlideH;
                float bgScale;
                GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out bgSlideX, out bgSlideY, out bgSlideW, out bgSlideH, out bgScale);
                ShapeNode bgShape = SelectedShape;
                float imgX = bgSlideX + bgShape.Transform.X * bgScale;
                float imgY = bgSlideY + bgShape.Transform.Y * bgScale;
                float imgW = bgShape.Transform.Width * bgScale;
                float imgH = bgShape.Transform.Height * bgScale;

                if (mousePos.X >= imgX && mousePos.X <= imgX + imgW && mousePos.Y >= imgY && mousePos.Y <= imgY + imgH)
                {
                    float normX = Math.Max(0f, Math.Min(1f, (mousePos.X - imgX) / imgW));
                    float normY = Math.Max(0f, Math.Min(1f, (mousePos.Y - imgY) / imgH));
                    CurrentMouseHoverNorm = new PointF(normX, normY);

                    if (IsDrawingBgStroke && CurrentDrawingStroke != null)
                    {
                        PointF lastPt = CurrentDrawingStroke.Points[CurrentDrawingStroke.Points.Count - 1];
                        float dx = (normX - lastPt.X) * imgW;
                        float dy = (normY - lastPt.Y) * imgH;
                        if (dx * dx + dy * dy >= 4f) // at least 2 pixels movement
                        {
                            CurrentDrawingStroke.Points.Add(new PointF(normX, normY));
                        }
                    }
                }
                else
                {
                    CurrentMouseHoverNorm = new PointF(-1, -1);
                }
                return;
            }

            if (IsCropping && SelectedShape != null)
            {
                if (ActiveCropHandle != CropHandleType.None)
                {
                    int cropSlideX, cropSlideY, cropSlideW, cropSlideH;
                    float cropScale;
                    GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out cropSlideX, out cropSlideY, out cropSlideW, out cropSlideH, out cropScale);
                    ShapeNode cropTarget = SelectedShape;

                    float dx = (mousePos.X - CropDragStartMouse.X) / cropScale;
                    float dy = (mousePos.Y - CropDragStartMouse.Y) / cropScale;

                    float initW = Math.Max(20f, CropInitialShapeW);
                    float initH = Math.Max(20f, CropInitialShapeH);
                    float initVisWFrac = Math.Max(0.05f, 1.0f - CropInitialLeft - CropInitialRight);
                    float initVisHFrac = Math.Max(0.05f, 1.0f - CropInitialTop - CropInitialBottom);

                    switch (ActiveCropHandle)
                    {
                        case CropHandleType.Left:
                        case CropHandleType.TopLeft:
                        case CropHandleType.BottomLeft:
                            {
                                float fracDelta = (dx / initW) * initVisWFrac;
                                cropTarget.CropLeft = Math.Max(0f, Math.Min(0.85f - CropInitialRight, CropInitialLeft + fracDelta));
                                float activeVisWFrac = Math.Max(0.05f, 1.0f - cropTarget.CropLeft - cropTarget.CropRight);
                                cropTarget.Transform.Width = Math.Max(20f, initW * (activeVisWFrac / initVisWFrac));
                                cropTarget.Transform.X = CropInitialShapeX + (cropTarget.CropLeft - CropInitialLeft) * (initW / initVisWFrac);
                            }
                            break;
                        case CropHandleType.Right:
                        case CropHandleType.TopRight:
                        case CropHandleType.BottomRight:
                            {
                                float fracDelta = (-dx / initW) * initVisWFrac;
                                cropTarget.CropRight = Math.Max(0f, Math.Min(0.85f - CropInitialLeft, CropInitialRight + fracDelta));
                                float activeVisWFrac = Math.Max(0.05f, 1.0f - cropTarget.CropLeft - cropTarget.CropRight);
                                cropTarget.Transform.Width = Math.Max(20f, initW * (activeVisWFrac / initVisWFrac));
                            }
                            break;
                    }

                    switch (ActiveCropHandle)
                    {
                        case CropHandleType.Top:
                        case CropHandleType.TopLeft:
                        case CropHandleType.TopRight:
                            {
                                float fracDelta = (dy / initH) * initVisHFrac;
                                cropTarget.CropTop = Math.Max(0f, Math.Min(0.85f - CropInitialBottom, CropInitialTop + fracDelta));
                                float activeVisHFrac = Math.Max(0.05f, 1.0f - cropTarget.CropTop - cropTarget.CropBottom);
                                cropTarget.Transform.Height = Math.Max(20f, initH * (activeVisHFrac / initVisHFrac));
                                cropTarget.Transform.Y = CropInitialShapeY + (cropTarget.CropTop - CropInitialTop) * (initH / initVisHFrac);
                            }
                            break;
                        case CropHandleType.Bottom:
                        case CropHandleType.BottomLeft:
                        case CropHandleType.BottomRight:
                            {
                                float fracDelta = (-dy / initH) * initVisHFrac;
                                cropTarget.CropBottom = Math.Max(0f, Math.Min(0.85f - CropInitialTop, CropInitialBottom + fracDelta));
                                float activeVisHFrac = Math.Max(0.05f, 1.0f - cropTarget.CropTop - cropTarget.CropBottom);
                                cropTarget.Transform.Height = Math.Max(20f, initH * (activeVisHFrac / initVisHFrac));
                            }
                            break;
                        case CropHandleType.PanImage:
                            {
                                float panFracX = (-dx / initW) * initVisWFrac;
                                float panFracY = (-dy / initH) * initVisHFrac;
                                cropTarget.CropLeft = Math.Max(0f, CropInitialLeft + panFracX);
                                cropTarget.CropRight = Math.Max(0f, CropInitialRight - panFracX);
                                cropTarget.CropTop = Math.Max(0f, CropInitialTop + panFracY);
                                cropTarget.CropBottom = Math.Max(0f, CropInitialBottom - panFracY);
                            }
                            break;
                    }
                }
                return;
            }

            if (IsSelectingTableCells && SelectedShape != null && SelectedShape.Type == ShapeType.Table)
            {
                int tblSlideX, tblSlideY, tblSlideW, tblSlideH;
                float tblScale;
                GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out tblSlideX, out tblSlideY, out tblSlideW, out tblSlideH, out tblScale);

                int sx = tblSlideX + (int)(SelectedShape.Transform.X * tblScale);
                int sy = tblSlideY + (int)(SelectedShape.Transform.Y * tblScale);
                int sw = (int)(SelectedShape.Transform.Width * tblScale);
                int sh = (int)(SelectedShape.Transform.Height * tblScale);

                int cols = Math.Max(1, SelectedShape.TableColumns);
                int rows = Math.Max(1, SelectedShape.TableRows);

                int c = SelectedShape.HitTestColumn(mousePos.X - sx, sw);
                int r = SelectedShape.HitTestRow(mousePos.Y - sy, sh);

                SelectedShape.TableSelectedEndRow = r;
                SelectedShape.TableSelectedEndCol = c;
                return;
            }

            if (DraggingSelectionPaneIndex >= 0 && ActiveSlide != null)
            {
                int sy = 155 + 42 + SidebarScrollY;
                int listStartY = sy + 34;
                int r = (mousePos.Y - listStartY) / 28;
                if (r >= 0 && r < ActiveSlide.Shapes.Count)
                {
                    DraggingSelectionPaneTargetIndex = ActiveSlide.Shapes.Count - 1 - r;
                }
                return;
            }

            if (DraggingAnimationPaneIndex >= 0 && ActiveSlide != null && ActiveSlide.Animations.Count > 0)
            {
                int sy = 155 + 42 + SidebarScrollY;
                int animStartY = sy + 34;
                int r = (mousePos.Y - animStartY + 18) / 36;
                if (r < 0) r = 0;
                if (r >= ActiveSlide.Animations.Count) r = ActiveSlide.Animations.Count - 1;
                DraggingAnimationPaneTargetIndex = r;
                return;
            }

            if (IsDraggingGradientStop && ActiveSlide != null && ActiveSlide.BgGradientStops != null)
            {
                int trackX = width - rightSidebarW + 24;
                int trackW = rightSidebarW - 106;
                float frac = (float)(mousePos.X - trackX) / trackW;
                frac = Math.Max(0.0f, Math.Min(1.0f, frac));
                if (ActiveSlide.SelectedGradientStopIndex >= 0 && ActiveSlide.SelectedGradientStopIndex < ActiveSlide.BgGradientStops.Count)
                {
                    ActiveSlide.BgGradientStops[ActiveSlide.SelectedGradientStopIndex].Position = frac;
                }
                return;
            }

            if (DraggingBgSliderType > 0 && ActiveSlide != null)
            {
                int trackX = width - rightSidebarW + 115;
                int trackW = 65;
                float frac = Math.Max(0.0f, Math.Min(1.0f, (float)(mousePos.X - trackX) / trackW));
                GradientStop activeStop = (ActiveSlide.BgGradientStops != null && ActiveSlide.SelectedGradientStopIndex >= 0 && ActiveSlide.SelectedGradientStopIndex < ActiveSlide.BgGradientStops.Count)
                    ? ActiveSlide.BgGradientStops[ActiveSlide.SelectedGradientStopIndex] : null;

                if (DraggingBgSliderType == 1) // Transparency
                {
                    if (ActiveSlide.BgFillType == BackgroundFillType.Gradient && activeStop != null)
                        activeStop.Transparency = frac;
                    else
                        ActiveSlide.BgTransparency = frac;
                }
                else if (DraggingBgSliderType == 2 && activeStop != null) // Position
                {
                    activeStop.Position = frac;
                }
                else if (DraggingBgSliderType == 3 && activeStop != null) // Brightness (-1 to +1)
                {
                    activeStop.Brightness = (frac * 2.0f) - 1.0f;
                }
                return;
            }

            if (IsDraggingHScrollBar)
            {
                int minScrollX, maxScrollX, minScrollY, maxScrollY;
                GetScrollLimits(canvasW, contentH, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);

                bool hasVScroll = (minScrollY < maxScrollY);
                int sbW = 14;
                int hTrackW = hasVScroll ? (canvasW - sbW) : canvasW;
                int totalW = maxScrollX - minScrollX + canvasW;
                int thumbW = Math.Max(40, (int)((float)canvasW / totalW * hTrackW));
                thumbW = Math.Min(thumbW, hTrackW);
                int trackScrollableW = Math.Max(1, hTrackW - thumbW);

                int deltaMouseX = mousePos.X - ScrollBarDragStartMouseX;
                float scrollPerPx = (float)(maxScrollX - minScrollX) / trackScrollableW;
                CanvasScrollX = ScrollBarDragStartScrollX + (int)(deltaMouseX * scrollPerPx);
                ClampScroll(canvasW, contentH);
                SmoothCanvasScrollX = CanvasScrollX;
                TargetCanvasScrollX = CanvasScrollX;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsDraggingVScrollBar)
            {
                int minScrollX, maxScrollX, minScrollY, maxScrollY;
                GetScrollLimits(canvasW, contentH, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);

                bool hasHScroll = (minScrollX < maxScrollX);
                int sbH = 14;
                int vTrackH = hasHScroll ? (contentH - sbH) : contentH;
                int totalH = maxScrollY - minScrollY + contentH;
                int thumbH = Math.Max(40, (int)((float)contentH / totalH * vTrackH));
                thumbH = Math.Min(thumbH, vTrackH);
                int trackScrollableH = Math.Max(1, vTrackH - thumbH);

                int deltaMouseY = mousePos.Y - ScrollBarDragStartMouseY;
                float scrollPerPx = (float)(maxScrollY - minScrollY) / trackScrollableH;
                CanvasScrollY = ScrollBarDragStartScrollY + (int)(deltaMouseY * scrollPerPx);
                ClampScroll(canvasW, contentH);
                SmoothCanvasScrollY = CanvasScrollY;
                TargetCanvasScrollY = CanvasScrollY;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // Hover check for scrollbars
            {
                int minScrollX, maxScrollX, minScrollY, maxScrollY;
                GetScrollLimits(canvasW, contentH, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);
                bool hasVScroll = (minScrollY < maxScrollY);
                bool hasHScroll = (minScrollX < maxScrollX);
                int sbH = 14;
                int sbW = 14;

                bool oldHoverH = IsHoverHScrollBarThumb;
                bool oldHoverV = IsHoverVScrollBarThumb;

                int vTrackX = canvasX + canvasW - sbW;
                int vTrackY = contentY;
                int vTrackH = hasHScroll ? (contentH - sbH) : contentH;

                IsHoverHScrollBarThumb = hasHScroll && (mousePos.Y >= contentY + contentH - sbH && mousePos.Y <= contentY + contentH &&
                    mousePos.X >= canvasX && mousePos.X <= canvasX + (hasVScroll ? (canvasW - sbW) : canvasW));

                IsHoverVScrollBarThumb = hasVScroll && (mousePos.X >= vTrackX && mousePos.X <= vTrackX + sbW &&
                    mousePos.Y >= vTrackY && mousePos.Y <= vTrackY + vTrackH);

                if (oldHoverH != IsHoverHScrollBarThumb || oldHoverV != IsHoverVScrollBarThumb)
                {
                    if (InvalidateCallback != null) InvalidateCallback();
                }
            }

            if (IsPanningCanvas)
            {
                int dx = mousePos.X - PanStartMouse.X;
                int dy = mousePos.Y - PanStartMouse.Y;
                CanvasScrollX = PanStartScroll.X - dx;
                CanvasScrollY = PanStartScroll.Y - dy;
                ClampScroll(canvasW, contentH);
                SmoothCanvasScrollX = CanvasScrollX;
                TargetCanvasScrollX = CanvasScrollX;
                SmoothCanvasScrollY = CanvasScrollY;
                TargetCanvasScrollY = CanvasScrollY;
                return;
            }

            int slideX, slideY, slideW, slideH;
            float scale;
            GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out slideX, out slideY, out slideW, out slideH, out scale);

            if (IsDraggingAudioScrubber && HoveredAudioShape != null && !LastAudioPlaybackBarBounds.IsEmpty)
            {
                float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                float barW = LastAudioPlaybackBarBounds.Width;
                float scrubX = 74f;
                float scrubW = Math.Max(30f, barW - 74f - 88f);
                float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                float totalSec = HoveredAudioShape.AudioTotalTime > 0 ? HoveredAudioShape.AudioTotalTime : 180f;
                float targetSec = frac * totalSec;
                HoveredAudioScrubberTime = targetSec;
                IsHoveringAudioScrubber = true;
                SlideAudioPlayerManager.Instance.Seek(HoveredAudioShape, targetSec);
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // PowerPoint Edit Shape Points MouseMove
            if (IsEditingShapePoints && EditingPointsShape != null)
            {
                ShapeNode esh = EditingPointsShape;
                if (IsDraggingEditPoint && SelectedEditPointIndex >= 0 && SelectedEditPointIndex < ShapeEditPoints.Count)
                {
                    PointF currentLocal = ScreenToShapeLocal(esh, mousePos, slideX, slideY, scale);
                    PointF startLocal = ScreenToShapeLocal(esh, DragStartEditPointMouse, slideX, slideY, scale);
                    float dLocalX = currentLocal.X - startLocal.X;
                    float dLocalY = currentLocal.Y - startLocal.Y;

                    ShapeEditPoints[SelectedEditPointIndex] = new PointF(
                        DragStartEditPointVal.X + dLocalX,
                        DragStartEditPointVal.Y + dLocalY
                    );
                    RebuildCustomPathFromEditPoints();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                else
                {
                    // 1. Check hover on existing vertex nodes
                    int hoverNode = -1;
                    for (int i = 0; i < ShapeEditPoints.Count; i++)
                    {
                        PointF sPt = ShapeLocalToScreen(esh, ShapeEditPoints[i], slideX, slideY, scale);
                        float distSq = (mousePos.X - sPt.X) * (mousePos.X - sPt.X) + (mousePos.Y - sPt.Y) * (mousePos.Y - sPt.Y);
                        if (distSq <= 64f)
                        {
                            hoverNode = i;
                            break;
                        }
                    }
                    HoveredEditPointIndex = hoverNode;

                    // 2. If not hovering a node, check hover on edges/segments
                    int hoverSeg = -1;
                    PointF? hoverSegPt = null;
                    if (hoverNode < 0 && ShapeEditPoints.Count >= 2)
                    {
                        float minDist = float.MaxValue;
                        for (int i = 0; i < ShapeEditPoints.Count; i++)
                        {
                            PointF pA = ShapeEditPoints[i];
                            PointF pB = ShapeEditPoints[(i + 1) % ShapeEditPoints.Count];
                            PointF sA = ShapeLocalToScreen(esh, pA, slideX, slideY, scale);
                            PointF sB = ShapeLocalToScreen(esh, pB, slideX, slideY, scale);
                            PointF closest;
                            float d = GetDistanceToSegment(new PointF(mousePos.X, mousePos.Y), sA, sB, out closest);
                            if (d <= 10f && d < minDist)
                            {
                                minDist = d;
                                hoverSeg = i;
                                hoverSegPt = ScreenToShapeLocal(esh, closest, slideX, slideY, scale);
                            }
                        }
                    }
                    bool changed = (HoveredEditPointIndex != hoverNode) || (HoveredEditSegmentIndex != hoverSeg) || (hoverSeg >= 0);
                    HoveredEditPointIndex = hoverNode;
                    HoveredEditSegmentIndex = hoverSeg;
                    HoveredEditSegmentPoint = hoverSegPt;
                    if (changed && InvalidateCallback != null) InvalidateCallback();
                    return;
                }
            }

            // 0. Rubberband / Marquee Multi-Shape Selection MouseMove (Quét khối chọn đối tượng)
            if (IsRubberbandSelecting && ActiveSlide != null)
            {
                RubberbandCurrentPoint = mousePos;
                int rx = Math.Min(RubberbandStartPoint.X, RubberbandCurrentPoint.X);
                int ry = Math.Min(RubberbandStartPoint.Y, RubberbandCurrentPoint.Y);
                int rw = Math.Abs(RubberbandStartPoint.X - RubberbandCurrentPoint.X);
                int rh = Math.Abs(RubberbandStartPoint.Y - RubberbandCurrentPoint.Y);
                RectangleF marqueeRect = new RectangleF(rx, ry, rw, rh);

                SelectedShapeIndices.Clear();
                if (_rubberbandInitialSelection != null && _rubberbandInitialSelection.Count > 0)
                {
                    foreach (int initIdx in _rubberbandInitialSelection)
                    {
                        if (initIdx >= 0 && initIdx < ActiveSlide.Shapes.Count)
                            SelectedShapeIndices.Add(initIdx);
                    }
                }

                if (rw > 3 || rh > 3)
                {
                    for (int i = 0; i < ActiveSlide.Shapes.Count; i++)
                    {
                        ShapeNode s = ActiveSlide.Shapes[i];
                        if (s == null || !s.IsVisible || (s.Name != null && s.Name.StartsWith("__morph_ghost__"))) continue;

                        float sx = slideX + s.Transform.X * scale;
                        float sy = slideY + s.Transform.Y * scale;
                        float sw = s.Transform.Width * scale;
                        float sh = s.Transform.Height * scale;

                        // Kiểm tra quét full 100% cả khung của thành phần đó theo đúng yêu cầu người dùng
                        bool isFullyEnclosed = true;
                        if (Math.Abs(s.Transform.Rotation) > 0.01f)
                        {
                            PointF center = new PointF(sx + sw / 2f, sy + sh / 2f);
                            PointF[] corners = new PointF[] {
                                RotatePoint(new PointF(sx, sy), center, s.Transform.Rotation),
                                RotatePoint(new PointF(sx + sw, sy), center, s.Transform.Rotation),
                                RotatePoint(new PointF(sx, sy + sh), center, s.Transform.Rotation),
                                RotatePoint(new PointF(sx + sw, sy + sh), center, s.Transform.Rotation)
                            };
                            for (int ci = 0; ci < 4; ci++)
                            {
                                if (corners[ci].X < marqueeRect.Left || corners[ci].X > marqueeRect.Right ||
                                    corners[ci].Y < marqueeRect.Top || corners[ci].Y > marqueeRect.Bottom)
                                {
                                    isFullyEnclosed = false;
                                    break;
                                }
                            }
                        }
                        else
                        {
                            isFullyEnclosed = (sx >= marqueeRect.Left && (sx + sw) <= marqueeRect.Right &&
                                               sy >= marqueeRect.Top && (sy + sh) <= marqueeRect.Bottom);
                        }

                        if (isFullyEnclosed && !SelectedShapeIndices.Contains(i))
                        {
                            SelectedShapeIndices.Add(i);
                        }
                    }
                }

                SelectedShapeIndex = SelectedShapeIndices.Count > 0 ? SelectedShapeIndices[SelectedShapeIndices.Count - 1] : -1;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // 1. Motion Path Freehand Sketching MouseMove
            if (IsDrawingMotionPathMode && IsDrawingMotionPathActive)
            {
                ShapeNode targetShape = ActiveDrawingMotionShape ?? SelectedShape;
                if (targetShape != null)
                {
                    float mouseSlideX = (mousePos.X - slideX) / scale;
                    float mouseSlideY = (mousePos.Y - slideY) / scale;
                    float scx = targetShape.Transform.X + targetShape.Transform.Width / 2f;
                    float scy = targetShape.Transform.Y + targetShape.Transform.Height / 2f;
                    PointF newPt = new PointF(mouseSlideX - scx, mouseSlideY - scy);

                    if (CurrentDrawingMotionPoints.Count > 0)
                    {
                        PointF lastPt = CurrentDrawingMotionPoints[CurrentDrawingMotionPoints.Count - 1];
                        float distSq = (newPt.X - lastPt.X) * (newPt.X - lastPt.X) + (newPt.Y - lastPt.Y) * (newPt.Y - lastPt.Y);
                        if (distSq >= 9f) // 3px delta
                        {
                            CurrentDrawingMotionPoints.Add(newPt);
                        }
                    }
                    else
                    {
                        CurrentDrawingMotionPoints.Add(newPt);
                    }
                }
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // 2. Motion Path End Point Handle Dragging MouseMove
            if (IsDraggingMotionEndDot && DraggingMotionAnim != null && DraggingMotionShape != null)
            {
                float mouseSlideX = (mousePos.X - slideX) / scale;
                float mouseSlideY = (mousePos.Y - slideY) / scale;
                float scx = DraggingMotionShape.Transform.X + DraggingMotionShape.Transform.Width / 2f;
                float scy = DraggingMotionShape.Transform.Y + DraggingMotionShape.Transform.Height / 2f;
                DraggingMotionAnim.EndOffsetX = mouseSlideX - scx;
                DraggingMotionAnim.EndOffsetY = mouseSlideY - scy;
                DraggingMotionAnim.HasCustomEndOffset = true;
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            ShapeNode shape = SelectedShape;

            if (IsRotatingShape && shape != null)
            {
                PointF center = new PointF(slideX + (shape.Transform.X + shape.Transform.Width / 2.0f) * scale,
                                           slideY + (shape.Transform.Y + shape.Transform.Height / 2.0f) * scale);
                double rawAngle = Math.Atan2(mousePos.Y - center.Y, mousePos.X - center.X) * 180.0 / Math.PI + 90.0;
                while (rawAngle < 0) rawAngle += 360.0;
                while (rawAngle >= 360.0) rawAngle -= 360.0;

                // Soft magnetic angle snap: holds at 0, 45, 90, 135, 180, 225, 270, 315 within ±2.2° tolerance
                float snappedAngle = (float)rawAngle;
                int[] landmarkAngles = new int[] { 0, 45, 90, 135, 180, 225, 270, 315, 360 };
                foreach (int target in landmarkAngles)
                {
                    double diff = Math.Abs(rawAngle - target);
                    if (diff <= 2.2)
                    {
                        snappedAngle = target % 360;
                        break;
                    }
                }

                shape.Transform.Rotation = snappedAngle;
                return;
            }

            if (IsSelectingText && IsInlineEditing && EditingShape != null)
            {
                int currIdx = GetTextCharIndexFromPoint(mousePos, EditingShape, slideX, slideY, scale);
                TextSelectionLength = currIdx - TextSelectionStart;
                CaretIndex = currIdx;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsDraggingShape && shape != null)
            {
                int dmx = Math.Abs(mousePos.X - DragStartMouse.X);
                int dmy = Math.Abs(mousePos.Y - DragStartMouse.Y);
                if (dmx <= 3 && dmy <= 3)
                {
                    return;
                }
                if (_pendingDeselectOnMouseUp)
                {
                    _pendingDeselectOnMouseUp = false;
                }

                float rawDx = (mousePos.X - DragStartMouse.X) / scale;
                float rawDy = (mousePos.Y - DragStartMouse.Y) / scale;

                float rawX = DragStartTransform.X + rawDx;
                float rawY = DragStartTransform.Y + rawDy;

                float snappedX, snappedY;
                ApplySmartSnapping(shape, rawX, rawY, out snappedX, out snappedY);

                float deltaX = snappedX - DragStartTransform.X;
                float deltaY = snappedY - DragStartTransform.Y;

                if (DragStartTransforms != null && DragStartTransforms.Count > 1)
                {
                    foreach (KeyValuePair<int, Transform2D> kvp in DragStartTransforms)
                    {
                        int sIdx = kvp.Key;
                        if (ActiveSlide != null && sIdx >= 0 && sIdx < ActiveSlide.Shapes.Count)
                        {
                            ActiveSlide.Shapes[sIdx].Transform.X = kvp.Value.X + deltaX;
                            ActiveSlide.Shapes[sIdx].Transform.Y = kvp.Value.Y + deltaY;
                        }
                    }
                }
                else
                {
                    shape.Transform.X = snappedX;
                    shape.Transform.Y = snappedY;
                }

                if (SlideVideoPlayerManager.Instance.ActiveShape == shape)
                {
                    int vx = slideX + (int)(shape.Transform.X * scale);
                    int vy = slideY + (int)(shape.Transform.Y * scale);
                    int vw = (int)(shape.Transform.Width * scale);
                    int vh = (int)(shape.Transform.Height * scale);
                    SlideVideoPlayerManager.Instance.UpdateBounds(new Rectangle(vx, vy, Math.Max(100, vw), Math.Max(60, vh)));
                }
                // Do not mark thumbnail dirty on every mouse move pixel to ensure 60 FPS buttery smooth dragging
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsAdjustingCornerRadius && shape != null)
            {
                float dx = (mousePos.X - DragStartMouse.X) / scale;
                float dy = (mousePos.Y - DragStartMouse.Y) / scale;

                float rotRad = (float)(-shape.Transform.Rotation * Math.PI / 180.0);
                float cosR = (float)Math.Cos(rotRad);
                float sinR = (float)Math.Sin(rotRad);
                float localDx = (Math.Abs(shape.Transform.Rotation) > 0.001f) ? (dx * cosR - dy * sinR) : dx;
                float localDy = (Math.Abs(shape.Transform.Rotation) > 0.001f) ? (dx * sinR + dy * cosR) : dy;

                // Dragging inward (leftward / downward relative to top-right corner) increases radius
                // Dragging outward (rightward / upward) decreases radius to 0
                float inwardDelta = (-localDx + localDy) * 0.7071f;

                float maxR = Math.Min(shape.Transform.Width, shape.Transform.Height) / 2f;
                float newR = Math.Max(0f, Math.Min(maxR, DragStartCornerRadius + inwardDelta));
                shape.CornerRadius = (float)Math.Round(newR);

                if (shape.Type == ShapeType.Rectangle && shape.CornerRadius > 0.5f)
                {
                    shape.Type = ShapeType.RoundedRectangle;
                }
                else if (shape.Type == ShapeType.RoundedRectangle && shape.CornerRadius <= 0.5f)
                {
                    shape.Type = ShapeType.Rectangle;
                }

                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsResizingShape && shape != null)
            {
                float dx = (mousePos.X - DragStartMouse.X) / scale;
                float dy = (mousePos.Y - DragStartMouse.Y) / scale;
                float startW = DragStartTransform.Width;
                float startH = DragStartTransform.Height;
                float ratio = startW / Math.Max(1.0f, startH);
                bool isGraphic = shape.Type == ShapeType.Image || shape.Type == ShapeType.CustomPath || shape.Type == ShapeType.Video;
                bool isCornerHandle = (DragResizeHandleIndex == 0 || DragResizeHandleIndex == 2 || DragResizeHandleIndex == 4 || DragResizeHandleIndex == 6);
                bool keepAspect = (Control.ModifierKeys & Keys.Shift) != 0 || (isGraphic && isCornerHandle);

                float rotRad = (float)(-shape.Transform.Rotation * Math.PI / 180.0);
                float cosR = (float)Math.Cos(rotRad);
                float sinR = (float)Math.Sin(rotRad);
                float localDx = (Math.Abs(shape.Transform.Rotation) > 0.001f) ? (dx * cosR - dy * sinR) : dx;
                float localDy = (Math.Abs(shape.Transform.Rotation) > 0.001f) ? (dx * sinR + dy * cosR) : dy;

                float ax = 0.5f, ay = 0.5f;
                switch (DragResizeHandleIndex)
                {
                    case 0: ax = 1f; ay = 1f; break; // Top-Left
                    case 1: ax = 0.5f; ay = 1f; break; // Top-Center
                    case 2: ax = 0f; ay = 1f; break; // Top-Right
                    case 3: ax = 0f; ay = 0.5f; break; // Right-Center
                    case 4: ax = 0f; ay = 0f; break; // Bottom-Right
                    case 5: ax = 0.5f; ay = 0f; break; // Bottom-Center
                    case 6: ax = 1f; ay = 0f; break; // Bottom-Left
                    case 7: ax = 1f; ay = 0.5f; break; // Left-Center
                }

                float rawW = startW, rawH = startH;

                if (DragResizeHandleIndex == 0 || DragResizeHandleIndex == 1 || DragResizeHandleIndex == 2)
                    rawH = startH - localDy;
                else if (DragResizeHandleIndex == 4 || DragResizeHandleIndex == 5 || DragResizeHandleIndex == 6)
                    rawH = startH + localDy;

                if (DragResizeHandleIndex == 0 || DragResizeHandleIndex == 6 || DragResizeHandleIndex == 7)
                    rawW = startW - localDx;
                else if (DragResizeHandleIndex == 2 || DragResizeHandleIndex == 3 || DragResizeHandleIndex == 4)
                    rawW = startW + localDx;

                float newW, newH;
                if (keepAspect && isCornerHandle)
                {
                    // Orthogonal projection of signed (rawW, rawH) onto the aspect-ratio diagonal (startW, startH)
                    // Ensures 100% continuous, jump-free resizing even when pushing up or sideways from a diagonal drag
                    float diagSq = startW * startW + startH * startH;
                    float projScale = (rawW * startW + rawH * startH) / Math.Max(1.0f, diagSq);
                    float minScale = Math.Max(10.0f / Math.Max(1.0f, startW), 10.0f / Math.Max(1.0f, startH));
                    projScale = Math.Max(minScale, projScale);
                    newW = startW * projScale;
                    newH = startH * projScale;
                }
                else
                {
                    newW = Math.Max(10f, rawW);
                    newH = Math.Max(10f, rawH);
                }

                // Canvas-edge magnetic snapping during resize (PowerPoint-style edge fit)
                ActiveSmartGuides.Clear();
                if (Presentation != null && Math.Abs(shape.Transform.Rotation) < 0.5f && (Control.ModifierKeys & Keys.Alt) == 0)
                {
                    float cw = Presentation.CanvasWidth;
                    float ch = Presentation.CanvasHeight;
                    const float RESIZE_SNAP_TOL = 9.0f;

                    if (ax == 0f) // Dragging right edge
                    {
                        float rightEdge = DragStartTransform.X + newW;
                        if (Math.Abs(rightEdge - cw) <= RESIZE_SNAP_TOL)
                        {
                            newW = Math.Max(10f, cw - DragStartTransform.X);
                            if (keepAspect && isCornerHandle) newH = newW / ratio;
                            ActiveSmartGuides.Add(new SmartGuideLine { IsVertical = true, Position = cw, Min = 0f, Max = ch });
                        }
                    }
                    else if (ax == 1f) // Dragging left edge
                    {
                        float rightAnchor = DragStartTransform.X + startW;
                        float leftEdge = rightAnchor - newW;
                        if (Math.Abs(leftEdge - 0f) <= RESIZE_SNAP_TOL)
                        {
                            newW = Math.Max(10f, rightAnchor);
                            if (keepAspect && isCornerHandle) newH = newW / ratio;
                            ActiveSmartGuides.Add(new SmartGuideLine { IsVertical = true, Position = 0f, Min = 0f, Max = ch });
                        }
                    }

                    if (ay == 0f) // Dragging bottom edge
                    {
                        float bottomEdge = DragStartTransform.Y + newH;
                        if (Math.Abs(bottomEdge - ch) <= RESIZE_SNAP_TOL)
                        {
                            newH = Math.Max(10f, ch - DragStartTransform.Y);
                            if (keepAspect && isCornerHandle) newW = newH * ratio;
                            ActiveSmartGuides.Add(new SmartGuideLine { IsVertical = false, Position = ch, Min = 0f, Max = cw });
                        }
                    }
                    else if (ay == 1f) // Dragging top edge
                    {
                        float bottomAnchor = DragStartTransform.Y + startH;
                        float topEdge = bottomAnchor - newH;
                        if (Math.Abs(topEdge - 0f) <= RESIZE_SNAP_TOL)
                        {
                            newH = Math.Max(10f, bottomAnchor);
                            if (keepAspect && isCornerHandle) newW = newH * ratio;
                            ActiveSmartGuides.Add(new SmartGuideLine { IsVertical = false, Position = 0f, Min = 0f, Max = cw });
                        }
                    }
                }

                float rotPosRad = (float)(shape.Transform.Rotation * Math.PI / 180.0);
                float cosP = (float)Math.Cos(rotPosRad);
                float sinP = (float)Math.Sin(rotPosRad);
                
                float dcx = (0.5f - ax) * (newW - startW);
                float dcy = (0.5f - ay) * (newH - startH);
                
                float globalDcx = dcx * cosP - dcy * sinP;
                float globalDcy = dcx * sinP + dcy * cosP;

                float oldCG_X = DragStartTransform.X + startW / 2f;
                float oldCG_Y = DragStartTransform.Y + startH / 2f;
                
                float newCG_X = oldCG_X + globalDcx;
                float newCG_Y = oldCG_Y + globalDcy;

                shape.Transform.X = newCG_X - newW / 2f;
                shape.Transform.Y = newCG_Y - newH / 2f;
                shape.Transform.Width = newW;
                shape.Transform.Height = newH;

                if (SlideVideoPlayerManager.Instance.ActiveShape == shape)
                {
                    int vx = slideX + (int)(shape.Transform.X * scale);
                    int vy = slideY + (int)(shape.Transform.Y * scale);
                    int vw = (int)(shape.Transform.Width * scale);
                    int vh = (int)(shape.Transform.Height * scale);
                    SlideVideoPlayerManager.Instance.UpdateBounds(new Rectangle(vx, vy, Math.Max(100, vw), Math.Max(60, vh)));
                }
                // Do not mark thumbnail dirty on every mouse move pixel to ensure 60 FPS buttery smooth dragging
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // Hover check for PowerPoint Audio Shapes & Floating Playback Bar (with seamless hover bridge corridor)
            ShapeNode oldHoverAudio = HoveredAudioShape;
            bool oldHoverScrub = IsHoveringAudioScrubber;
            int oldHoverBtn = HoveredAudioButton;

            bool isInAudioEnvelope = false;

            if (HoveredAudioShape != null)
            {
                // Calculate unified envelope bridging the speaker and its floating playback bar
                float sx = slideX + HoveredAudioShape.Transform.X * scale;
                float sy = slideY + HoveredAudioShape.Transform.Y * scale;
                float sw = HoveredAudioShape.Transform.Width * scale;
                float sh = HoveredAudioShape.Transform.Height * scale;

                float envLeft = sx - 8f;
                float envRight = sx + sw + 8f;
                float envTop = sy - 8f;
                float envBottom = sy + sh + 8f;

                // Predict bar bounds to avoid async paint gap where LastAudioPlaybackBarBounds is empty
                float barW = 340f;
                float barH = 32f;
                float barX = sx + (sw - barW) / 2f;
                float barY = sy + sh + 4f;
                if (LastViewportWidth > 0 && barX + barW > LastViewportWidth - 10f) barX = LastViewportWidth - barW - 10f;
                if (barX < 10f) barX = 10f;
                RectangleF predictedBar = new RectangleF(barX, barY, barW, barH);

                envLeft = Math.Min(envLeft, predictedBar.Left - 8f);
                envRight = Math.Max(envRight, predictedBar.Right + 8f);
                envTop = Math.Min(envTop, predictedBar.Top - 6f);
                envBottom = Math.Max(envBottom, predictedBar.Bottom + 8f);

                if (!LastAudioPlaybackBarBounds.IsEmpty)
                {
                    envLeft = Math.Min(envLeft, LastAudioPlaybackBarBounds.Left - 8f);
                    envRight = Math.Max(envRight, LastAudioPlaybackBarBounds.Right + 8f);
                    envTop = Math.Min(envTop, LastAudioPlaybackBarBounds.Top - 6f);
                    envBottom = Math.Max(envBottom, LastAudioPlaybackBarBounds.Bottom + 8f);
                }

                RectangleF hoverEnvelope = new RectangleF(envLeft, envTop, envRight - envLeft, envBottom - envTop);
                if (hoverEnvelope.Contains(mousePos))
                {
                    isInAudioEnvelope = true;
                }
            }

            bool isOverBar = !LastAudioPlaybackBarBounds.IsEmpty && LastAudioPlaybackBarBounds.Contains(mousePos) && HoveredAudioShape != null;

            if (isOverBar)
            {
                // Mouse is inside the floating playback bar
                float relX = mousePos.X - LastAudioPlaybackBarBounds.X;
                float barW = LastAudioPlaybackBarBounds.Width;
                float scrubX = 74f;
                float scrubW = Math.Max(30f, barW - 74f - 88f);

                if (relX < 28f)
                {
                    HoveredAudioButton = 0; // Play/Pause
                    IsHoveringAudioScrubber = false;
                }
                else if (relX >= 28f && relX < 48f)
                {
                    HoveredAudioButton = 1; // Rewind
                    IsHoveringAudioScrubber = false;
                }
                else if (relX >= 48f && relX < 68f)
                {
                    HoveredAudioButton = 2; // Fast Forward
                    IsHoveringAudioScrubber = false;
                }
                else if (relX >= scrubX && relX <= scrubX + scrubW)
                {
                    HoveredAudioButton = 3; // Scrubber
                    IsHoveringAudioScrubber = true;
                    float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                    float totalSec = HoveredAudioShape.AudioTotalTime > 0 ? HoveredAudioShape.AudioTotalTime : 180f;
                    HoveredAudioScrubberTime = frac * totalSec;
                }
                else if (relX >= barW - 28f)
                {
                    HoveredAudioButton = 4; // Volume
                    IsHoveringAudioScrubber = false;
                }
                else
                {
                    HoveredAudioButton = -1;
                    IsHoveringAudioScrubber = false;
                }
                HoveredAudioMousePos = mousePos;
            }
            else if (isInAudioEnvelope)
            {
                // Mouse is in the bridge corridor between speaker and playback bar:
                // Keep HoveredAudioShape active so playback bar stays 100% visible while moving mouse down!
                HoveredAudioButton = -1;
                IsHoveringAudioScrubber = false;
                HoveredAudioMousePos = mousePos;
            }
            else
            {
                // Mouse is outside the active envelope. Check if mouse is entering any Audio shape on the slide.
                ShapeNode foundAudio = null;
                if (ActiveSlide != null)
                {
                    for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
                    {
                        ShapeNode s = ActiveSlide.Shapes[i];
                        if (s != null && (s.Type == ShapeType.Audio || !string.IsNullOrEmpty(s.AudioPath)))
                        {
                            if (IsPresenting && s.AudioHideDuringShow) continue;
                            float sx = slideX + s.Transform.X * scale;
                            float sy = slideY + s.Transform.Y * scale;
                            float sw = s.Transform.Width * scale;
                            float sh = s.Transform.Height * scale;
                            // Generous 8px hit padding for easy hovering over speaker icon
                            RectangleF sRect = new RectangleF(sx - 8f, sy - 8f, sw + 16f, sh + 16f);
                            if (sRect.Contains(mousePos))
                            {
                                foundAudio = s;
                                break;
                            }
                        }
                    }
                }

                if (foundAudio != null)
                {
                    HoveredAudioShape = foundAudio;
                    HoveredAudioButton = -1;
                    IsHoveringAudioScrubber = false;
                }
                else if (SelectedShape != null && (SelectedShape.Type == ShapeType.Audio || !string.IsNullOrEmpty(SelectedShape.AudioPath)))
                {
                    // Audio shape is selected -> keep playback bar visible
                    HoveredAudioShape = SelectedShape;
                    HoveredAudioButton = -1;
                    IsHoveringAudioScrubber = false;
                }
                else
                {
                    HoveredAudioShape = null;
                    HoveredAudioButton = -1;
                    IsHoveringAudioScrubber = false;
                    LastAudioPlaybackBarBounds = RectangleF.Empty;
                }
            }

            if (oldHoverAudio != HoveredAudioShape || oldHoverScrub != IsHoveringAudioScrubber || oldHoverBtn != HoveredAudioButton || isOverBar || isInAudioEnvelope)
            {
                if (InvalidateCallback != null) InvalidateCallback();
            }

            // Hover check for PowerPoint Video Shapes & Floating Playback Bar in Edit Mode
            ShapeNode oldHoverVideo = HoveredVideoShape;
            bool oldHoverVideoScrub = IsHoveringVideoScrubber;
            int oldHoverVideoBtn = HoveredVideoButton;

            if (IsDraggingVideoScrubber && (HoveredVideoShape != null || SelectedShape != null) && !LastVideoPlaybackBarBounds.IsEmpty)
            {
                ShapeNode targetVideo = HoveredVideoShape ?? SelectedShape;
                float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                float barW = LastVideoPlaybackBarBounds.Width;
                float playBtnW = 32f;
                float volBtnW = 32f;
                float timeTextW = (barW > 240f) ? 80f : 0f;
                float scrubX = playBtnW + 8f;
                float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);
                float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                float totalSec = targetVideo.VideoTotalTime > 0 ? targetVideo.VideoTotalTime : 120f;
                SlideVideoPlayerManager.Instance.Seek(frac * totalSec);
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            bool isOverVideoBar = !LastVideoPlaybackBarBounds.IsEmpty && LastVideoPlaybackBarBounds.Contains(mousePos);

            if (isOverVideoBar)
            {
                // Mouse is inside the floating playback bar
                ShapeNode targetVideo = HoveredVideoShape ?? (SelectedShape != null && (SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(SelectedShape.VideoPath)) ? SelectedShape : null);
                if (HoveredVideoShape == null && targetVideo != null)
                {
                    HoveredVideoShape = targetVideo;
                }

                float relX = mousePos.X - LastVideoPlaybackBarBounds.X;
                float barW = LastVideoPlaybackBarBounds.Width;
                float playBtnW = 32f;
                float volBtnW = 32f;
                float timeTextW = (barW > 240f) ? 80f : 0f;
                float scrubX = playBtnW + 8f;
                float scrubW = Math.Max(20f, barW - scrubX - timeTextW - volBtnW - 8f);

                if (relX < playBtnW)
                {
                    HoveredVideoButton = 0; // Play/Pause
                    IsHoveringVideoScrubber = false;
                }
                else if (relX >= scrubX && relX <= scrubX + scrubW)
                {
                    HoveredVideoButton = 1; // Scrubber
                    IsHoveringVideoScrubber = true;
                    if (targetVideo != null)
                    {
                        float frac = Math.Max(0f, Math.Min(1f, (relX - scrubX) / scrubW));
                        float totalSec = targetVideo.VideoTotalTime > 0 ? targetVideo.VideoTotalTime : 120f;
                        HoveredVideoScrubberTime = frac * totalSec;
                    }
                }
                else if (relX >= barW - volBtnW)
                {
                    HoveredVideoButton = 2; // Volume
                    IsHoveringVideoScrubber = false;
                }
                else
                {
                    HoveredVideoButton = -1;
                    IsHoveringVideoScrubber = false;
                }
                HoveredVideoMousePos = mousePos;
                Cursor.Current = Cursors.Hand;
            }
            else
            {
                // Check if mouse is hovering over any Video shape on the active slide
                ShapeNode foundVideo = null;
                if (ActiveSlide != null)
                {
                    for (int i = ActiveSlide.Shapes.Count - 1; i >= 0; i--)
                    {
                        ShapeNode s = ActiveSlide.Shapes[i];
                        if (s != null && (s.Type == ShapeType.Video || !string.IsNullOrEmpty(s.VideoPath)))
                        {
                            float sx = slideX + s.Transform.X * scale;
                            float sy = slideY + s.Transform.Y * scale;
                            float sw = s.Transform.Width * scale;
                            float sh = s.Transform.Height * scale;
                            PointF center = new PointF(sx + sw / 2f, sy + sh / 2f);
                            PointF unrot = RotatePoint(mousePos, center, -s.Transform.Rotation);
                            RectangleF sRect = new RectangleF(sx, sy, sw, sh);
                            if (sRect.Contains(unrot))
                            {
                                foundVideo = s;
                                break;
                            }
                        }
                    }
                }

                if (foundVideo != null)
                {
                    HoveredVideoShape = foundVideo;
                    HoveredVideoButton = -1;
                    IsHoveringVideoScrubber = false;
                    HoveredVideoMousePos = mousePos;
                }
                else if (SelectedShape != null && (SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(SelectedShape.VideoPath)))
                {
                    HoveredVideoShape = SelectedShape;
                    HoveredVideoButton = -1;
                    IsHoveringVideoScrubber = false;
                }
                else
                {
                    HoveredVideoShape = null;
                    HoveredVideoButton = -1;
                    IsHoveringVideoScrubber = false;
                    LastVideoPlaybackBarBounds = RectangleF.Empty;
                }
            }

            if (oldHoverVideo != HoveredVideoShape || oldHoverVideoScrub != IsHoveringVideoScrubber || oldHoverVideoBtn != HoveredVideoButton || isOverVideoBar)
            {
                if (InvalidateCallback != null) InvalidateCallback();
            }
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct ICONINFO
        {
            public bool fIcon;
            public int xHotspot;
            public int yHotspot;
            public IntPtr hbmMask;
            public IntPtr hbmColor;
        }

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr CreateIconIndirect(ref ICONINFO icon);

        [DllImport("user32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool GetIconInfo(IntPtr hIcon, ref ICONINFO piconinfo);

        [DllImport("user32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool DestroyIcon(IntPtr hIcon);

        [DllImport("gdi32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool DeleteObject(IntPtr hObject);

        private static Cursor _penCursorKeep;
        private static Cursor _penCursorRemove;
        private static Cursor _penCursorGeneral;
        private static Cursor _eyedropperCursor;

        public static Cursor GetPenCursor(string toolType)
        {
            try
            {
                if (toolType == "Keep")
                {
                    if (_penCursorKeep == null) _penCursorKeep = CreateCustomPenCursor(Color.FromArgb(34, 197, 94));
                    return _penCursorKeep;
                }
                else if (toolType == "Remove")
                {
                    if (_penCursorRemove == null) _penCursorRemove = CreateCustomPenCursor(Color.FromArgb(239, 68, 68));
                    return _penCursorRemove;
                }
                if (_penCursorGeneral == null) _penCursorGeneral = CreateCustomPenCursor(Color.FromArgb(59, 130, 246));
                return _penCursorGeneral;
            }
            catch
            {
                return Cursors.Default;
            }
        }

        public static Cursor GetEyedropperCursor()
        {
            try
            {
                if (_eyedropperCursor == null)
                {
                    _eyedropperCursor = CreateEyedropperCursor();
                }
                return _eyedropperCursor;
            }
            catch
            {
                return Cursors.Cross;
            }
        }

        private static Cursor CreateEyedropperCursor()
        {
            using (Bitmap bmp = new Bitmap(32, 32, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
            {
                using (Graphics g = Graphics.FromImage(bmp))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                    g.Clear(Color.Transparent);

                    PointF tip = new PointF(1f, 30f);
                    PointF t1 = new PointF(4f, 27f);
                    PointF t2 = new PointF(7f, 30f);

                    PointF b1 = new PointF(14f, 17f);
                    PointF b2 = new PointF(19f, 22f);

                    PointF top1 = new PointF(23f, 8f);
                    PointF top2 = new PointF(28f, 13f);

                    PointF bulb = new PointF(28f, 3f);
                    PointF bulb2 = new PointF(31f, 6f);

                    // 1. Viền ngoài trắng tương phản cao
                    using (Pen wp = new Pen(Color.FromArgb(230, 255, 255, 255), 3.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        PointF[] outline = new PointF[] { tip, t1, b1, top1, bulb, bulb2, top2, b2, t2, tip };
                        g.DrawPolygon(wp, outline);
                    }

                    // 2. Đầu bóp cao su màu xanh ngọc CapCut
                    using (SolidBrush bb = new SolidBrush(Color.FromArgb(14, 165, 233)))
                    {
                        g.FillPolygon(bb, new PointF[] { top1, bulb, bulb2, top2 });
                    }

                    // 3. Thân ống thủy tinh
                    using (SolidBrush gb = new SolidBrush(Color.FromArgb(241, 245, 249)))
                    {
                        g.FillPolygon(gb, new PointF[] { t1, b1, b2, t2 });
                    }

                    // 4. Giọt màu phông xanh lá / màu hút bên trong
                    using (SolidBrush lb = new SolidBrush(Color.FromArgb(34, 197, 94)))
                    {
                        g.FillPolygon(lb, new PointF[] { tip, t1, t2 });
                    }

                    // 5. Viền nét đen đậm sắc sảo
                    using (Pen dp = new Pen(Color.FromArgb(15, 23, 42), 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        PointF[] outline = new PointF[] { tip, t1, b1, top1, bulb, bulb2, top2, b2, t2, tip };
                        g.DrawPolygon(dp, outline);
                        g.DrawLine(dp, top1, top2);
                        g.DrawLine(dp, t1, t2);
                    }
                }

                IntPtr hIcon = bmp.GetHicon();
                ICONINFO info = new ICONINFO();
                if (GetIconInfo(hIcon, ref info))
                {
                    info.xHotspot = 1;
                    info.yHotspot = 30;
                    info.fIcon = false;
                    IntPtr hCursor = CreateIconIndirect(ref info);

                    if (info.hbmColor != IntPtr.Zero) DeleteObject(info.hbmColor);
                    if (info.hbmMask != IntPtr.Zero) DeleteObject(info.hbmMask);
                    DestroyIcon(hIcon);

                    if (hCursor != IntPtr.Zero)
                        return new Cursor(hCursor);
                }
                return new Cursor(hIcon);
            }
        }

        private static Cursor CreateCustomPenCursor(Color bodyColor)
        {
            using (Bitmap bmp = new Bitmap(32, 32, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
            {
                using (Graphics g = Graphics.FromImage(bmp))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                    g.Clear(Color.Transparent);

                    PointF tip = new PointF(1f, 30f);
                    PointF w1 = new PointF(4.5f, 26.5f);
                    PointF w2 = new PointF(7.5f, 29.5f);

                    PointF b1 = new PointF(10f, 21f);
                    PointF b2 = new PointF(15f, 26f);

                    PointF f1 = new PointF(22f, 9f);
                    PointF f2 = new PointF(27f, 14f);

                    PointF e1 = new PointF(25f, 6f);
                    PointF e2 = new PointF(30f, 11f);

                    PointF top = new PointF(28f, 3f);
                    PointF top2 = new PointF(31f, 6f);

                    // 1. Viền ngoài màu trắng tương phản cao để hiển thị rõ trên mọi nền ảnh sáng/tối
                    using (Pen whitePen = new Pen(Color.FromArgb(230, 255, 255, 255), 3.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        PointF[] contour = new PointF[] { tip, b1, f1, e1, top, top2, e2, f2, b2, tip };
                        g.DrawPolygon(whitePen, contour);
                    }

                    // 2. Đầu gôm tẩy màu hồng
                    using (SolidBrush eb = new SolidBrush(Color.FromArgb(244, 114, 182)))
                    {
                        g.FillPolygon(eb, new PointF[] { e1, top, top2, e2 });
                    }

                    // 3. Khuyên kim loại bạc
                    using (SolidBrush fb = new SolidBrush(Color.FromArgb(203, 213, 225)))
                    {
                        g.FillPolygon(fb, new PointF[] { f1, e1, e2, f2 });
                    }

                    // 4. Thân bút chì (Xanh lá nếu Giữ vùng / Đỏ nếu Xóa vùng)
                    using (SolidBrush bb = new SolidBrush(bodyColor))
                    {
                        g.FillPolygon(bb, new PointF[] { b1, f1, f2, b2 });
                    }
                    using (SolidBrush hb = new SolidBrush(Color.FromArgb(90, 255, 255, 255)))
                    {
                        PointF midTop = new PointF((b1.X + b2.X) / 2f, (b1.Y + b2.Y) / 2f);
                        PointF midEnd = new PointF((f1.X + f2.X) / 2f, (f1.Y + f2.Y) / 2f);
                        g.FillPolygon(hb, new PointF[] { b1, f1, midEnd, midTop });
                    }

                    // 5. Phần gỗ gọt nhọn
                    using (SolidBrush wb = new SolidBrush(Color.FromArgb(254, 240, 138)))
                    {
                        g.FillPolygon(wb, new PointF[] { w1, b1, b2, w2, tip });
                    }

                    // 6. Ngòi chì đậm ở chóp nhọn
                    using (SolidBrush lb = new SolidBrush(Color.FromArgb(30, 41, 59)))
                    {
                        g.FillPolygon(lb, new PointF[] { tip, w1, w2 });
                    }

                    // 7. Viền đen sắc nét
                    using (Pen darkPen = new Pen(Color.FromArgb(30, 41, 59), 1.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                    {
                        PointF[] contour = new PointF[] { tip, b1, f1, e1, top, top2, e2, f2, b2, tip };
                        g.DrawPolygon(darkPen, contour);
                        g.DrawLine(darkPen, b1, b2);
                        g.DrawLine(darkPen, f1, f2);
                        g.DrawLine(darkPen, e1, e2);
                    }
                }

                IntPtr hIcon = bmp.GetHicon();
                ICONINFO info = new ICONINFO();
                if (GetIconInfo(hIcon, ref info))
                {
                    info.xHotspot = 1;
                    info.yHotspot = 30;
                    info.fIcon = false;
                    IntPtr hCursor = CreateIconIndirect(ref info);

                    if (info.hbmColor != IntPtr.Zero) DeleteObject(info.hbmColor);
                    if (info.hbmMask != IntPtr.Zero) DeleteObject(info.hbmMask);
                    DestroyIcon(hIcon);

                    if (hCursor != IntPtr.Zero)
                        return new Cursor(hCursor);
                }
                return new Cursor(hIcon);
            }
        }

        
        private Cursor GetRotatedResizeCursor(int handleIndex, float rotationDeg)
        {
            float[] baseAngles = new float[] { 315f, 270f, 45f, 0f, 135f, 90f, 225f, 180f };
            float angle = baseAngles[handleIndex] + rotationDeg;
            angle = angle % 180f;
            if (angle < 0) angle += 180f;
            if (angle < 22.5f || angle >= 157.5f) return Cursors.SizeWE;
            if (angle >= 22.5f && angle < 67.5f) return Cursors.SizeNESW;
            if (angle >= 67.5f && angle < 112.5f) return Cursors.SizeNS;
            return Cursors.SizeNWSE;
        }

        public Cursor GetCursorForPosition(Point mousePos, int width, int height)
        {
            int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
            GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);
            int rightSidebarW = (IsSidebarOpen && SidebarPanel != SidebarPanelType.None && !IsPresenting) ? 280 : 0;

            // 1. Khi rê chuột qua thanh thumbnail bên trái, ribbon ở trên, task pane bên phải hoặc thanh trạng thái ở dưới:
            // Luôn trả về con trỏ chuột bình thường (Cursors.Default)
            if (mousePos.Y < contentY || mousePos.Y >= height - 26 || mousePos.X < canvasX || mousePos.X >= width - rightSidebarW)
            {
                return Cursors.Default;
            }

            // 1.1 Khi rê chuột lên Khung Ghi chú người thuyết trình (Speaker Notes Pane) hoặc thanh phân cách Splitter
            int effNotesH = GetEffectiveNotesPaneHeight();
            int stageH = Math.Max(80, contentH - effNotesH);
            if (effNotesH > 0 && mousePos.X >= canvasX && mousePos.X < canvasX + canvasW)
            {
                int notesTopY = contentY + stageH;
                if (IsDraggingNotesSplitter || (mousePos.Y >= notesTopY - 4 && mousePos.Y <= notesTopY + 4))
                {
                    return Cursors.SizeNS;
                }
                if (mousePos.Y > notesTopY + 4 && mousePos.Y <= contentY + contentH)
                {
                    return Cursors.IBeam;
                }
            }
            if (ViewMode == ImpressViewMode.Notes && !LastNotesTextRect.IsEmpty && LastNotesTextRect.Contains(mousePos))
            {
                return Cursors.IBeam;
            }

            // 1.2 Khi rê chuột lên thanh cuộn ngang hoặc thanh cuộn dọc -> Con trỏ Default
            int minScrollX, maxScrollX, minScrollY, maxScrollY;
            GetScrollLimits(canvasW, contentH, out minScrollX, out maxScrollX, out minScrollY, out maxScrollY);
            bool hasVScroll = (minScrollY < maxScrollY);
            bool hasHScroll = (minScrollX < maxScrollX);
            int sbH = 14;
            int sbW = 14;

            if (hasHScroll && mousePos.Y >= contentY + stageH - sbH && mousePos.Y <= contentY + stageH)
            {
                return Cursors.Default;
            }
            if (hasVScroll && mousePos.X >= canvasX + canvasW - sbW && mousePos.X <= canvasX + canvasW)
            {
                return Cursors.Default;
            }

            // 2. Chế độ vẽ hình hoặc vẽ đường chuyển động trên slide canvas
            if (IsDrawingShapeMode || IsDrawingActive || IsDrawingMotionPathMode || IsDrawingMotionPathActive)
            {
                if (IsScribbleMode)
                {
                    return GetPenCursor("General");
                }
                return Cursors.Cross;
            }

            // Chế độ Chỉnh sửa điểm hình dạng (PowerPoint Edit Points)
            if (IsEditingShapePoints && EditingPointsShape != null)
            {
                if (IsDraggingEditPoint || HoveredEditPointIndex >= 0)
                {
                    return Cursors.SizeAll;
                }
                if (HoveredEditSegmentIndex >= 0)
                {
                    return Cursors.Cross;
                }
                return Cursors.Default;
            }

            // Chế độ Chọn màu xóa (Chroma Keying / Phông xanh CapCut)
            if (IsColorPickingMode)
            {
                return GetEyedropperCursor();
            }

            // Chế độ Xóa nền (Background Removal: Trả về con trỏ hình cây bút hoặc ống hút màu)
            if (IsRemovingBackground)
            {
                if (BgRemovalTool == "PickColor")
                {
                    return GetEyedropperCursor();
                }
                if (BgRemovalTool == "Keep" || BgRemovalTool == "Remove")
                {
                    return GetPenCursor(BgRemovalTool);
                }
            }

            int slideX, slideY, slideW, slideH;
            float scale;
            GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out slideX, out slideY, out slideW, out slideH, out scale);

            // Kiểm tra con trỏ trên chấm đỏ End Dot của Đường chuyển động
            if (ActiveSlide != null && ActiveSlide.Animations != null && ActiveSlide.Animations.Count > 0)
            {
                for (int a = 0; a < ActiveSlide.Animations.Count; a++)
                {
                    ShapeAnimation anim = ActiveSlide.Animations[a];
                    if (anim == null || !anim.IsMotionPath) continue;

                    ShapeNode targetShape = null;
                    for (int s = 0; s < ActiveSlide.Shapes.Count; s++)
                    {
                        if (ActiveSlide.Shapes[s].Id == anim.ShapeId) { targetShape = ActiveSlide.Shapes[s]; break; }
                    }
                    if (targetShape == null) continue;

                    float scx = slideX + (targetShape.Transform.X + targetShape.Transform.Width / 2f) * scale;
                    float scy = slideY + (targetShape.Transform.Y + targetShape.Transform.Height / 2f) * scale;

                    float endOffX, endOffY;
                    EvaluateMotionPathOffset(anim, 1.0f, out endOffX, out endOffY);
                    float endPtX = scx + endOffX * scale;
                    float endPtY = scy + endOffY * scale;

                    float dX = mousePos.X - endPtX;
                    float dY = mousePos.Y - endPtY;
                    if (dX * dX + dY * dY <= 144f) // 12px hit radius
                    {
                        return Cursors.SizeAll;
                    }
                }
            }

            if (SelectedShapeIndex >= 0 && ActiveSlide != null && SelectedShapeIndex < ActiveSlide.Shapes.Count)
            {
                ShapeNode shape = ActiveSlide.Shapes[SelectedShapeIndex];
                int sx = slideX + (int)(shape.Transform.X * scale);
                int sy = slideY + (int)(shape.Transform.Y * scale);
                int sw = (int)(shape.Transform.Width * scale);
                int sh = (int)(shape.Transform.Height * scale);

                if (IsCropping && shape == SelectedShape)
                {
                    float hitR = Math.Max(12f, 16f * scale);
                    if (Math.Abs(mousePos.X - sx) <= hitR && Math.Abs(mousePos.Y - sy) <= hitR) return Cursors.SizeNWSE;
                    if (Math.Abs(mousePos.X - (sx + sw)) <= hitR && Math.Abs(mousePos.Y - sy) <= hitR) return Cursors.SizeNESW;
                    if (Math.Abs(mousePos.X - sx) <= hitR && Math.Abs(mousePos.Y - (sy + sh)) <= hitR) return Cursors.SizeNESW;
                    if (Math.Abs(mousePos.X - (sx + sw)) <= hitR && Math.Abs(mousePos.Y - (sy + sh)) <= hitR) return Cursors.SizeNWSE;
                    if (Math.Abs(mousePos.X - (sx + sw / 2f)) <= hitR && Math.Abs(mousePos.Y - sy) <= hitR) return Cursors.SizeNS;
                    if (Math.Abs(mousePos.X - (sx + sw / 2f)) <= hitR && Math.Abs(mousePos.Y - (sy + sh)) <= hitR) return Cursors.SizeNS;
                    if (Math.Abs(mousePos.X - sx) <= hitR && Math.Abs(mousePos.Y - (sy + sh / 2f)) <= hitR) return Cursors.SizeWE;
                    if (Math.Abs(mousePos.X - (sx + sw)) <= hitR && Math.Abs(mousePos.Y - (sy + sh / 2f)) <= hitR) return Cursors.SizeWE;

                    if (mousePos.X >= sx && mousePos.X <= sx + sw && mousePos.Y >= sy && mousePos.Y <= sy + sh)
                    {
                        return Cursors.SizeAll;
                    }
                    return Cursors.Default;
                }

                // Corner rounding knob (Icon bo góc)
                if (CanShapeRoundCorners(shape))
                {
                    PointF crH = GetRotatedCornerRadiusHandle(sx, sy, sw, sh, shape.Transform.Rotation);
                    float dCrX = mousePos.X - crH.X;
                    float dCrY = mousePos.Y - crH.Y;
                    if (dCrX * dCrX + dCrY * dCrY <= 196f) // 14px radius
                    {
                        return Cursors.Hand;
                    }
                }

                // Rotation knob (Mũi tên xoay)
                PointF rotH = GetRotatedRotationHandle(sx, sy, sw, sh, shape.Transform.Rotation);
                float dRotX = mousePos.X - rotH.X;
                float dRotY = mousePos.Y - rotH.Y;
                if (dRotX * dRotX + dRotY * dRotY <= 144f) // 12px radius
                {
                    return Cursors.Hand;
                }

                // 8 resize handles
                PointF[] handles = GetRotatedHandleCoordinates(sx, sy, sw, sh, shape.Transform.Rotation);
                for (int hIdx = 0; hIdx < handles.Length; hIdx++)
                {
                    float dHX = mousePos.X - handles[hIdx].X;
                    float dHY = mousePos.Y - handles[hIdx].Y;
                    if (dHX * dHX + dHY * dHY <= 64f) // 8px radius
                    {
                        return GetRotatedResizeCursor(hIdx, shape.Transform.Rotation);
                    }
                }

                // Table Move Handle & Border check (Nút kéo 4 chiều ✥ và viền ngoài)
                if (shape.Type == ShapeType.Table)
                {
                    Rectangle moveHandleRect = new Rectangle(sx - 24, sy - 24, 24, 24);
                    if (moveHandleRect.Contains(mousePos))
                    {
                        return Cursors.SizeAll;
                    }

                    // Outer border edges (within 6px) -> Kéo bảng
                    if (mousePos.X >= sx - 6 && mousePos.X <= sx + sw + 6 && mousePos.Y >= sy - 6 && mousePos.Y <= sy + sh + 6)
                    {
                        if (mousePos.X <= sx + 6 || mousePos.X >= sx + sw - 6 || mousePos.Y <= sy + 6 || mousePos.Y >= sy + sh - 6)
                        {
                            return Cursors.SizeAll;
                        }
                        if (IsEditingTableCell && EditingTableShape == shape)
                        {
                            return Cursors.IBeam;
                        }
                        return Cursors.Default;
                    }
                }

                PointF center = new PointF(sx + sw / 2f, sy + sh / 2f);
                PointF unrotatedMouse = RotatePoint(mousePos, center, -shape.Transform.Rotation);
                RectangleF shapeBounds = (shape.Type == ShapeType.Line)
                    ? new RectangleF(sx - 8f, sy - 8f, Math.Max(16f, sw + 16f), Math.Max(16f, sh + 16f))
                    : new RectangleF(sx, sy, sw, sh);
                if (shapeBounds.Contains(unrotatedMouse))
                {
                    if (IsInlineEditing && EditingShape == shape)
                    {
                        float borderTol = Math.Max(7f, 10f * scale);
                        if (unrotatedMouse.X <= sx + borderTol || unrotatedMouse.X >= sx + sw - borderTol ||
                            unrotatedMouse.Y <= sy + borderTol || unrotatedMouse.Y >= sy + sh - borderTol)
                        {
                            return Cursors.SizeAll;
                        }
                        return Cursors.IBeam;
                    }
                    return Cursors.SizeAll;
                }
            }

            if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 1 && ActiveSlide != null)
            {
                foreach (int idx in SelectedShapeIndices)
                {
                    if (idx >= 0 && idx < ActiveSlide.Shapes.Count)
                    {
                        ShapeNode shp = ActiveSlide.Shapes[idx];
                        int msx = slideX + (int)(shp.Transform.X * scale);
                        int msy = slideY + (int)(shp.Transform.Y * scale);
                        int msw = (int)(shp.Transform.Width * scale);
                        int msh = (int)(shp.Transform.Height * scale);
                        PointF mcenter = new PointF(msx + msw / 2f, msy + msh / 2f);
                        PointF munrot = RotatePoint(mousePos, mcenter, -shp.Transform.Rotation);
                        RectangleF mbounds = (shp.Type == ShapeType.Line)
                            ? new RectangleF(msx - 8f, msy - 8f, Math.Max(16f, msw + 16f), Math.Max(16f, msh + 16f))
                            : new RectangleF(msx, msy, msw, msh);
                        if (mbounds.Contains(munrot))
                        {
                            return Cursors.SizeAll;
                        }
                    }
                }
            }

            return Cursors.Default;
        }

        public void HandleMouseUp(Point mousePos, int width, int height)
        {
            if (IsDraggingAudioScrubber)
            {
                IsDraggingAudioScrubber = false;
            }
            if (IsDraggingVideoScrubber)
            {
                IsDraggingVideoScrubber = false;
            }

            if (ShapeTaskPane != null && ShapeTaskPane.IsDraggingScrollbar)
            {
                ShapeTaskPane.HandleMouseUp(mousePos);
                if (InvalidateCallback != null) InvalidateCallback();
            }

            if (_isDraggingThumbScrollBar)
            {
                _isDraggingThumbScrollBar = false;
                SmoothThumbScrollY = ThumbScrollY;
                TargetThumbScrollY = ThumbScrollY;
                bool isIslandMode = (AppSettings.Instance.RibbonStyle == RibbonStyle.Island);
                int paneW = isIslandMode ? 200 : 210;
                int targetIdx = GetSlideIndexFromScrollY(ThumbScrollY, paneW);
                if (targetIdx >= 0 && Presentation != null && Presentation.Slides != null && targetIdx < Presentation.Slides.Count)
                {
                    ActiveSlideIndex = targetIdx;
                    SelectedShapeIndex = -1;
                    if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                    EndInlineEditing();
                }
                if (InvalidateCallback != null) InvalidateCallback();
            }

            if (IsSelectingText)
            {
                IsSelectingText = false;
            }
            if (IsSelectingSpeakerNotes)
            {
                IsSelectingSpeakerNotes = false;
            }
            if (IsDraggingNotesSplitter)
            {
                IsDraggingNotesSplitter = false;
                if (InvalidateCallback != null) InvalidateCallback();
            }

            if (IsPresenting)
            {
                if (AnnotationPenMode && CurrentStroke.Count > 0)
                {
                    PenStrokes.Add(new List<Point>(CurrentStroke));
                    CurrentStroke.Clear();
                }
                return;
            }

            // PowerPoint Edit Points MouseUp
            if (IsEditingShapePoints && EditingPointsShape != null)
            {
                if (IsDraggingEditPoint)
                {
                    IsDraggingEditPoint = false;
                    RebuildCustomPathFromEditPoints();
                    SaveUndoState();
                    if (InvalidateCallback != null) InvalidateCallback();
                }
            }

            // 1. Motion Path Freehand Sketching MouseUp
            if (IsDrawingMotionPathMode && IsDrawingMotionPathActive)
            {
                IsDrawingMotionPathActive = false;
                IsDrawingMotionPathMode = false;
                ShapeNode targetShape = ActiveDrawingMotionShape ?? SelectedShape;
                if (targetShape != null && CurrentDrawingMotionPoints != null && CurrentDrawingMotionPoints.Count >= 2 && ActiveSlide != null)
                {
                    SaveUndoState();
                    ShapeAnimation anim = null;
                    for (int i = 0; i < ActiveSlide.Animations.Count; i++)
                    {
                        if (ActiveSlide.Animations[i].ShapeId == targetShape.Id)
                        {
                            anim = ActiveSlide.Animations[i];
                            break;
                        }
                    }
                    if (anim == null)
                    {
                        anim = new ShapeAnimation
                        {
                            ShapeId = targetShape.Id,
                            OrderIndex = ActiveSlide.Animations.Count
                        };
                        ActiveSlide.Animations.Add(anim);
                    }
                    anim.Type = AnimationType.MotionCustom;
                    anim.Duration = 2.0f;
                    anim.CustomPoints = new List<PointF>(CurrentDrawingMotionPoints);
                    anim.EndOffsetX = CurrentDrawingMotionPoints[CurrentDrawingMotionPoints.Count - 1].X;
                    anim.EndOffsetY = CurrentDrawingMotionPoints[CurrentDrawingMotionPoints.Count - 1].Y;
                    anim.HasCustomEndOffset = true;
                    SelectedAnimationIndex = ActiveSlide.Animations.IndexOf(anim);
                    CurrentDrawingMotionPoints.Clear();
                    PlayAnimationPreview();
                }
                else
                {
                    CurrentDrawingMotionPoints.Clear();
                }
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // 2. Motion Path End Point Handle Dragging MouseUp
            if (IsDraggingMotionEndDot)
            {
                IsDraggingMotionEndDot = false;
                DraggingMotionAnim = null;
                DraggingMotionShape = null;
                PlayAnimationPreview();
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (IsCropping && ActiveCropHandle != CropHandleType.None)
            {
                ActiveCropHandle = CropHandleType.None;
                return;
            }

            if (IsRemovingBackground && IsDrawingBgStroke && CurrentDrawingStroke != null && SelectedShape != null)
            {
                IsDrawingBgStroke = false;
                BgRemovalStrokes.Add(CurrentDrawingStroke);
                ApplyStrokeSegmentation(SelectedShape, CurrentDrawingStroke);
                CurrentDrawingStroke = null;
                return;
            }

            if (IsDrawingActive)
            {
                if (IsScribbleMode)
                {
                    IsDrawingActive = false;

                    if (IsFreeformShapeMode)
                    {
                        // In Freeform Shape mode (point-by-point), releasing the mouse keeps the mode active
                        // so the user can continue clicking vertices to create jagged edges / torn paper contours.
                        // Only auto-finalize if user dragged a continuous loop back to start point.
                        if (ScribblePoints.Count >= 5)
                        {
                            int sc_sbW, sc_cX, sc_cW, sc_cY, sc_cH, sc_btmH;
                            GetEffectiveLayoutMetrics(width, height, out sc_sbW, out sc_cX, out sc_cW, out sc_cY, out sc_cH, out sc_btmH);
                            int sc_sX, sc_sY, sc_sW, sc_sH;
                            float sc_scale;
                            GetSlideCanvasBounds(sc_cX, sc_cY, sc_cW, sc_cH, out sc_sX, out sc_sY, out sc_sW, out sc_sH, out sc_scale);

                            PointF pStart = ScribblePoints[0];
                            PointF pEnd = ScribblePoints[ScribblePoints.Count - 1];
                            float dX = (pEnd.X - pStart.X) * sc_scale;
                            float dY = (pEnd.Y - pStart.Y) * sc_scale;
                            if (dX * dX + dY * dY <= 900f) // within 30px of start point
                            {
                                FinalizeScribbleShape(shouldClose: true);
                                if (InvalidateCallback != null) InvalidateCallback();
                                return;
                            }
                        }
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    else
                    {
                        // Continuous Freeform Scribble: finalize upon mouse release if dragged
                        if (ScribblePoints.Count >= 3)
                        {
                            PointF pStart = ScribblePoints[0];
                            PointF pEnd = ScribblePoints[ScribblePoints.Count - 1];
                            float dX = pEnd.X - pStart.X;
                            float dY = pEnd.Y - pStart.Y;
                            bool shouldClose = (dX * dX + dY * dY <= 1600f) && ScribblePoints.Count >= 5;
                            FinalizeScribbleShape(shouldClose);
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                        else
                        {
                            if (InvalidateCallback != null) InvalidateCallback();
                            return;
                        }
                    }
                }

                int x1, y1, w1, h1;
                bool isSquare;
                GetConstrainedDrawBounds(out x1, out y1, out w1, out h1, out isSquare);

                IsDrawingActive = false;
                IsDrawingShapeMode = false;

                int leftSidebarW, canvasX, canvasW, contentY, contentH, bottomThumbH;
                GetEffectiveLayoutMetrics(width, height, out leftSidebarW, out canvasX, out canvasW, out contentY, out contentH, out bottomThumbH);

                int slideX, slideY, slideW, slideH;
                float scale;
                GetSlideCanvasBounds(canvasX, contentY, canvasW, contentH, out slideX, out slideY, out slideW, out slideH, out scale);

                bool canCreateShape = (PendingShapeType == ShapeType.Line)
                    ? (w1 > 4 || h1 > 4)
                    : (w1 > 6 && h1 > 6);

                float canvasXPos = 0f, canvasYPos = 0f, canvasWPos = 0f, canvasHPos = 0f;
                if (!canCreateShape && ActiveSlide != null)
                {
                    // Single-click insert: insert standard shape at clicked position
                    canCreateShape = true;
                    float defW = (PendingShapeType == ShapeType.Line) ? 180f : 240f;
                    float defH = (PendingShapeType == ShapeType.Line) ? 0f : 140f;
                    float clickCanvasX = (ShapeDrawStart.X - slideX) / scale;
                    float clickCanvasY = (ShapeDrawStart.Y - slideY) / scale;
                    canvasXPos = clickCanvasX - defW / 2f;
                    canvasYPos = clickCanvasY - defH / 2f;
                    canvasWPos = defW;
                    canvasHPos = defH;
                }
                else if (canCreateShape && ActiveSlide != null)
                {
                    canvasXPos = (x1 - slideX) / scale;
                    canvasYPos = (y1 - slideY) / scale;
                    canvasWPos = Math.Max(0f, w1 / scale);
                    canvasHPos = Math.Max(0f, h1 / scale);
                }

                if (canCreateShape && ActiveSlide != null)
                {
                    SaveUndoState();
                    ShapeNode newShape = new ShapeNode
                    {
                        Type = PendingShapeType,
                        CornerRadius = (PendingShapeType == ShapeType.RoundedRectangle) ? 20f : 0f,
                        Transform = new Transform2D(canvasXPos, canvasYPos, canvasWPos, canvasHPos),
                        FillColor = (PendingShapeType == ShapeType.TextBox || PendingShapeType == ShapeType.Line) ? 0x00FFFFFF : 0x4472C4,
                        StrokeColor = (PendingShapeType == ShapeType.Line) ? 0x4472C4 : 0x00FFFFFF,
                        StrokeWidth = (PendingShapeType == ShapeType.Line) ? 1.5f : 0.0f,
                        Text = (PendingShapeType == ShapeType.TextBox) ? "Nhấp để thêm văn bản" : "",
                        Alignment = (PendingShapeType == ShapeType.TextBox) ? TextAlignment.Left : TextAlignment.Center,
                        VerticalAlignment = VerticalTextAlignment.Middle,
                        TextColor = (PendingShapeType == ShapeType.TextBox) ? 0x0F172A : 0xFFFFFF
                    };

                    ActiveSlide.AddShape(newShape);
                    SelectedShapeIndex = ActiveSlide.Shapes.Count - 1;

                    if (PendingShapeType == ShapeType.TextBox)
                    {
                        StartInlineEditing(newShape);
                    }
                }
            }

            if (DraggingSelectionPaneIndex >= 0 && ActiveSlide != null)
            {
                if (DraggingSelectionPaneTargetIndex >= 0 && DraggingSelectionPaneTargetIndex != DraggingSelectionPaneIndex &&
                    DraggingSelectionPaneIndex < ActiveSlide.Shapes.Count && DraggingSelectionPaneTargetIndex < ActiveSlide.Shapes.Count)
                {
                    ShapeNode s = ActiveSlide.Shapes[DraggingSelectionPaneIndex];
                    ActiveSlide.Shapes.RemoveAt(DraggingSelectionPaneIndex);
                    ActiveSlide.Shapes.Insert(DraggingSelectionPaneTargetIndex, s);
                    SelectedShapeIndex = DraggingSelectionPaneTargetIndex;
                    SelectedShapeIndices.Clear();
                    SelectedShapeIndices.Add(SelectedShapeIndex);
                }
                DraggingSelectionPaneIndex = -1;
                DraggingSelectionPaneTargetIndex = -1;
            }

            if (DraggingAnimationPaneIndex >= 0 && ActiveSlide != null && ActiveSlide.Animations.Count > 0)
            {
                if (DraggingAnimationPaneTargetIndex >= 0 && DraggingAnimationPaneTargetIndex != DraggingAnimationPaneIndex &&
                    DraggingAnimationPaneIndex < ActiveSlide.Animations.Count && DraggingAnimationPaneTargetIndex < ActiveSlide.Animations.Count)
                {
                    ShapeAnimation a = ActiveSlide.Animations[DraggingAnimationPaneIndex];
                    ActiveSlide.Animations.RemoveAt(DraggingAnimationPaneIndex);
                    ActiveSlide.Animations.Insert(DraggingAnimationPaneTargetIndex, a);
                    SelectedAnimationIndex = DraggingAnimationPaneTargetIndex;
                }
                DraggingAnimationPaneIndex = -1;
                DraggingAnimationPaneTargetIndex = -1;
            }

            if (_pendingDeselectOnMouseUp && _pendingDeselectIndex >= 0)
            {
                if (SelectedShapeIndices != null && SelectedShapeIndices.Contains(_pendingDeselectIndex))
                {
                    SelectedShapeIndices.Remove(_pendingDeselectIndex);
                    SelectedShapeIndex = SelectedShapeIndices.Count > 0 ? SelectedShapeIndices[SelectedShapeIndices.Count - 1] : -1;
                }
                _pendingDeselectOnMouseUp = false;
                _pendingDeselectIndex = -1;
            }

            if (IsRubberbandSelecting)
            {
                IsRubberbandSelecting = false;
                _rubberbandInitialSelection.Clear();
                if (InvalidateCallback != null) InvalidateCallback();
            }
            if (DragStartTransforms != null) DragStartTransforms.Clear();

            if (IsDraggingShape || IsResizingShape || IsRotatingShape || IsAdjustingCornerRadius)
            {
                if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
            }
            IsDraggingBottomThumbScrollBar = false;
            SmoothBottomThumbScrollX = BottomThumbScrollX;
            TargetBottomThumbScrollX = BottomThumbScrollX;
            IsPanningCanvas = false;
            IsDraggingHScrollBar = false;
            SmoothCanvasScrollX = CanvasScrollX;
            TargetCanvasScrollX = CanvasScrollX;
            IsDraggingVScrollBar = false;
            SmoothCanvasScrollY = CanvasScrollY;
            TargetCanvasScrollY = CanvasScrollY;
            IsDraggingShape = false;
            IsSelectingTableCells = false;
            IsResizingShape = false;
            IsRotatingShape = false;
            IsAdjustingCornerRadius = false;
            IsDraggingGradientStop = false;
            DraggingBgSliderType = 0;
            ShowSnapGuideX = false;
            ShowSnapGuideY = false;
            if (ActiveSmartGuides != null) ActiveSmartGuides.Clear();
            if (ActiveSpacingIndicators != null) ActiveSpacingIndicators.Clear();
        }

        public void AdvancePresenterStep()
        {
            if (IsEndSlideShowScreen)
            {
                if (LoopUntilEsc || ShowType == 2)
                {
                    IsEndSlideShowScreen = false;
                    ActiveSlideIndex = (ShowSlideRangeStart > 1 && Presentation != null && ShowSlideRangeStart <= Presentation.Slides.Count) ? ShowSlideRangeStart - 1 : 0;
                    CurrentAnimationStep = 0;
                    IsPlayingSlideAnimation = false;
                    _animStopwatch.Stop();
                    AnimationProgress = 0.0f;
                    return;
                }
                IsEndSlideShowScreen = false;
                StopPresenting();
                return;
            }

            // 1. Khi đang chạy chuyển cảnh (Transition) mà người dùng bấm Next:
            // Hoàn tất tức thì chuyển cảnh hiện tại, đưa về slide mới và tiếp tục chuyển tiếp ngay với 1 lần bấm duy nhất!
            if (IsTransitioning)
            {
                TransitionProgress = 1.0f;
                IsTransitioning = false;
                IsPreviewingTransition = false;
                _transitionStopwatch.Stop();
                ClearMorphTextureCache();
                CurrentAnimationStep = 0;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
            }

            // 2. Khi một bước hoạt họa (Animation) đang di chuyển dở mà người dùng bấm Next:
            // Đưa ngay bước hoạt họa đó về trạng thái kết thúc (hoàn thành) và dừng lại
            if (IsPlayingSlideAnimation)
            {
                AnimationProgress = 1.0f;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
            }

            SlideNode slide = ActiveSlide;
            if (slide == null || Presentation == null) return;

            int totalAnimSteps = GetTotalAnimationSteps(slide);

            // Nếu slide có hoạt họa và chưa phát hết các bước nhấp chuột (Click Steps)
            if (CurrentAnimationStep < totalAnimSteps)
            {
                CurrentAnimationStep++;
                PlayCurrentStepAnimation(CurrentAnimationStep);
                return;
            }

            // 2.5. Kiểm tra nếu slide có video hoặc âm thanh theo trình tự nhấp (InClickSequence) chưa phát:
            ShapeNode unplayedMedia = null;
            if (slide.Shapes != null)
            {
                for (int i = 0; i < slide.Shapes.Count; i++)
                {
                    var s = slide.Shapes[i];
                    if (s == null) continue;
                    bool isVideo = (s.Type == ShapeType.Video || !string.IsNullOrEmpty(s.VideoPath));
                    bool isAudio = (s.Type == ShapeType.Audio || !string.IsNullOrEmpty(s.AudioPath));
                    if (!isVideo && !isAudio) continue;

                    if (_playedMediaShapesInPresentation.Contains(s)) continue;

                    VideoStartMode startMode = isVideo ? s.VideoStartMode : s.AudioStartMode;
                    if (startMode == VideoStartMode.InClickSequence)
                    {
                        unplayedMedia = s;
                        break;
                    }
                }
            }

            if (unplayedMedia != null)
            {
                _playedMediaShapesInPresentation.Add(unplayedMedia);
                Control parent = (Application.OpenForms.Count > 0) ? Application.OpenForms[0] : null;
                if (unplayedMedia.Type == ShapeType.Video || !string.IsNullOrEmpty(unplayedMedia.VideoPath))
                {
                    PlayVideoPreview(unplayedMedia, parent);
                }
                else
                {
                    SlideAudioPlayerManager.Instance.Play(unplayedMedia, parent);
                }
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (SlideVideoPlayerManager.Instance.IsPlaying)
            {
                SlideVideoPlayerManager.Instance.Stop();
            }

            int maxSlideLimit = (ShowSlideRangeEnd > 0 && Presentation != null && ShowSlideRangeEnd <= Presentation.Slides.Count) ? ShowSlideRangeEnd - 1 : (Presentation != null ? Presentation.Slides.Count - 1 : 0);

            // PowerPoint 365 Zoom Return: Nếu đang ở slide được zoom đến và bật ZoomReturnToSlide
            if (ZoomReturnEnabled && ZoomReturnSlideIndex >= 0 && ActiveSlideIndex != ZoomReturnSlideIndex)
            {
                int retIdx = ZoomReturnSlideIndex;
                ZoomReturnSlideIndex = -1;
                ZoomReturnEnabled = false;
                int prev = ActiveSlideIndex;
                ActiveSlideIndex = retIdx;
                CurrentAnimationStep = 0;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
                TriggerTransition(prev, ActiveSlideIndex, false);
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            // Đã phát hết toàn bộ hoạt họa của slide này -> Chuyển sang slide tiếp theo không bị ẩn
            int nextIdx = ActiveSlideIndex + 1;
            while (nextIdx <= maxSlideLimit && Presentation.Slides[nextIdx].IsHidden)
            {
                nextIdx++;
            }

            if (nextIdx <= maxSlideLimit)
            {
                int prevIdx = ActiveSlideIndex;
                ActiveSlideIndex = nextIdx;
                CurrentAnimationStep = 0;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
                TriggerTransition(prevIdx, ActiveSlideIndex, false);
            }
            else
            {
                if (LoopUntilEsc || ShowType == 2)
                {
                    // Lặp lại từ đầu slide range hoặc slide 1 trong chế độ Kiosk / Loop until Esc
                    int prevIdx = ActiveSlideIndex;
                    ActiveSlideIndex = (ShowSlideRangeStart > 1 && Presentation != null && ShowSlideRangeStart <= Presentation.Slides.Count) ? ShowSlideRangeStart - 1 : 0;
                    CurrentAnimationStep = 0;
                    IsPlayingSlideAnimation = false;
                    _animStopwatch.Stop();
                    AnimationProgress = 0.0f;
                    TriggerTransition(prevIdx, ActiveSlideIndex, false);
                }
                else
                {
                    // Khi hết slide cuối cùng: Hiển thị màn hình đen thông báo kết thúc (Black End Screen)
                    IsEndSlideShowScreen = true;
                }
            }
        }

        public void PreviousPresenterStep()
        {
            if (IsEndSlideShowScreen)
            {
                IsEndSlideShowScreen = false;
                return;
            }

            // 1. Khi đang chuyển cảnh mà bấm Lùi: Kết thúc ngay hiệu ứng chuyển cảnh và lùi slide ngay với 1 lần bấm!
            if (IsTransitioning)
            {
                TransitionProgress = 1.0f;
                IsTransitioning = false;
                IsPreviewingTransition = false;
                _transitionStopwatch.Stop();
                ClearMorphTextureCache();
                CurrentAnimationStep = 0;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
            }

            // 2. Khi đang phát hoạt họa mà bấm Lùi: Hủy hoạt họa đang chạy
            if (IsPlayingSlideAnimation)
            {
                AnimationProgress = 0.0f;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
            }

            if (Presentation == null) return;

            bool wasVidPlaying = SlideVideoPlayerManager.Instance.IsPlaying;
            ShapeNode activeVid = SlideVideoPlayerManager.Instance.ActiveShape;
            if (wasVidPlaying || activeVid != null)
            {
                SlideVideoPlayerManager.Instance.Stop();
            }

            SlideNode slide = ActiveSlide;
            if (slide != null && slide.Shapes != null)
            {
                foreach (var s in slide.Shapes)
                {
                    if (s != null && (s.Type == ShapeType.Video || !string.IsNullOrEmpty(s.VideoPath)))
                    {
                        s.VideoCurrentTime = (float)(s.VideoTrimStart > 0 ? s.VideoTrimStart : 0.0);
                    }
                }
            }

            // Nếu video vừa đang phát hoặc đã phát trên slide hiện tại mà bấm Lùi -> trả lại trạng thái chưa phát để bấm phát lại ngay
            if (wasVidPlaying || _playedMediaShapesInPresentation.Count > 0)
            {
                _playedMediaShapesInPresentation.Clear();
                if (wasVidPlaying)
                {
                    return;
                }
            }

            // Nếu đang ở bước hoạt họa lớn hơn 0: Lùi lại 1 bước hoạt họa mà KHÔNG phát ngược hiệu ứng (chỉ phục hồi trạng thái tĩnh trước lúc phát)
            if (CurrentAnimationStep > 0)
            {
                CurrentAnimationStep--;
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
                return;
            }

            // Đang ở đầu slide (bước 0) -> Lùi về slide trước đó
            int minSlideLimit = (ShowSlideRangeStart > 1 && Presentation != null && ShowSlideRangeStart <= Presentation.Slides.Count) ? ShowSlideRangeStart - 1 : 0;
            int prevTarget = ActiveSlideIndex - 1;
            while (prevTarget >= minSlideLimit && Presentation.Slides[prevTarget].IsHidden)
            {
                prevTarget--;
            }

            if (prevTarget >= minSlideLimit)
            {
                int prevIdx = ActiveSlideIndex;
                ActiveSlideIndex = prevTarget;
                _playedMediaShapesInPresentation.Clear();
                if (ActiveSlide != null && ActiveSlide.Shapes != null)
                {
                    foreach (var s in ActiveSlide.Shapes)
                    {
                        if (s != null && (s.Type == ShapeType.Video || !string.IsNullOrEmpty(s.VideoPath)))
                        {
                            s.VideoCurrentTime = (float)(s.VideoTrimStart > 0 ? s.VideoTrimStart : 0.0);
                        }
                    }
                }
                IsPlayingSlideAnimation = false;
                _animStopwatch.Stop();
                AnimationProgress = 0.0f;
                // Đặt slide trước đó ở trạng thái đã hoàn thành toàn bộ bước hoạt họa
                CurrentAnimationStep = GetTotalAnimationSteps(ActiveSlide);
                TriggerTransition(prevIdx, ActiveSlideIndex, true);
            }
            else
            {
                // Đã ở tận cùng đầu Slide 1 ("trở về slide đầu max đầu"): Đặt lại hoàn toàn trạng thái phát video và bước hoạt họa về 0!
                CurrentAnimationStep = 0;
                _playedMediaShapesInPresentation.Clear();
            }
        }

        public void HandleKeyDown(Keys key)
        {
            if (IsEditingSpeakerNotes && ActiveSlide != null)
            {
                string notes = ActiveSlide.SpeakerNotes ?? "";
                SpeakerNotesCaretIndex = Math.Max(0, Math.Min(SpeakerNotesCaretIndex, notes.Length));

                if (key == Keys.Escape)
                {
                    IsEditingSpeakerNotes = false;
                    SpeakerNotesSelectionLength = 0;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                if ((Control.ModifierKeys & Keys.Control) != 0)
                {
                    if (key == Keys.A)
                    {
                        SpeakerNotesSelectionStart = 0;
                        SpeakerNotesSelectionLength = notes.Length;
                        SpeakerNotesCaretIndex = notes.Length;
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                    if (key == Keys.C)
                    {
                        if (SpeakerNotesSelectionLength != 0)
                        {
                            int sStart = Math.Max(0, Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength));
                            int sLen = Math.Min(notes.Length - sStart, Math.Abs(SpeakerNotesSelectionLength));
                            if (sLen > 0) Clipboard.SetText(notes.Substring(sStart, sLen));
                        }
                        return;
                    }
                    if (key == Keys.X)
                    {
                        if (SpeakerNotesSelectionLength != 0)
                        {
                            int sStart = Math.Max(0, Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength));
                            int sLen = Math.Min(notes.Length - sStart, Math.Abs(SpeakerNotesSelectionLength));
                            if (sLen > 0)
                            {
                                Clipboard.SetText(notes.Substring(sStart, sLen));
                                ActiveSlide.SpeakerNotes = notes.Remove(sStart, sLen);
                                SpeakerNotesCaretIndex = sStart;
                                SpeakerNotesSelectionStart = sStart;
                                SpeakerNotesSelectionLength = 0;
                                EnsureSpeakerNotesCaretVisible();
                                if (InvalidateCallback != null) InvalidateCallback();
                            }
                        }
                        return;
                    }
                    if (key == Keys.V)
                    {
                        if (Clipboard.ContainsText())
                        {
                            string clip = Clipboard.GetText().Replace("\r\n", "\n").Replace("\r", "\n");
                            if (SpeakerNotesSelectionLength != 0)
                            {
                                int sStart = Math.Max(0, Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength));
                                int sLen = Math.Min(notes.Length - sStart, Math.Abs(SpeakerNotesSelectionLength));
                                notes = notes.Remove(sStart, sLen);
                                SpeakerNotesCaretIndex = sStart;
                            }
                            ActiveSlide.SpeakerNotes = notes.Insert(SpeakerNotesCaretIndex, clip);
                            SpeakerNotesCaretIndex += clip.Length;
                            SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                            SpeakerNotesSelectionLength = 0;
                            EnsureSpeakerNotesCaretVisible();
                            if (InvalidateCallback != null) InvalidateCallback();
                        }
                        return;
                    }
                }

                if (SpeakerNotesSelectionLength != 0 && (key == Keys.Back || key == Keys.Delete))
                {
                    int sStart = Math.Max(0, Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength));
                    int sLen = Math.Min(notes.Length - sStart, Math.Abs(SpeakerNotesSelectionLength));
                    ActiveSlide.SpeakerNotes = notes.Remove(sStart, sLen);
                    SpeakerNotesCaretIndex = sStart;
                    SpeakerNotesSelectionStart = sStart;
                    SpeakerNotesSelectionLength = 0;
                    EnsureSpeakerNotesCaretVisible();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }

                bool isShift = (Control.ModifierKeys & Keys.Shift) != 0;
                if (key == Keys.Left)
                {
                    if (!isShift && SpeakerNotesSelectionLength != 0)
                    {
                        SpeakerNotesCaretIndex = Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength);
                        SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                        SpeakerNotesSelectionLength = 0;
                    }
                    else
                    {
                        SpeakerNotesCaretIndex = Math.Max(0, SpeakerNotesCaretIndex - 1);
                        if (isShift) SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                        else { SpeakerNotesSelectionStart = SpeakerNotesCaretIndex; SpeakerNotesSelectionLength = 0; }
                    }
                    EnsureSpeakerNotesCaretVisible();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.Right)
                {
                    if (!isShift && SpeakerNotesSelectionLength != 0)
                    {
                        SpeakerNotesCaretIndex = Math.Max(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength);
                        SpeakerNotesSelectionStart = SpeakerNotesCaretIndex;
                        SpeakerNotesSelectionLength = 0;
                    }
                    else
                    {
                        SpeakerNotesCaretIndex = Math.Min(notes.Length, SpeakerNotesCaretIndex + 1);
                        if (isShift) SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                        else { SpeakerNotesSelectionStart = SpeakerNotesCaretIndex; SpeakerNotesSelectionLength = 0; }
                    }
                    EnsureSpeakerNotesCaretVisible();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.Home)
                {
                    int lineStart = SpeakerNotesCaretIndex;
                    while (lineStart > 0 && notes[lineStart - 1] != '\n') lineStart--;
                    SpeakerNotesCaretIndex = lineStart;
                    if (isShift) SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                    else { SpeakerNotesSelectionStart = SpeakerNotesCaretIndex; SpeakerNotesSelectionLength = 0; }
                    EnsureSpeakerNotesCaretVisible();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.End)
                {
                    int lineEnd = SpeakerNotesCaretIndex;
                    while (lineEnd < notes.Length && notes[lineEnd] != '\n') lineEnd++;
                    SpeakerNotesCaretIndex = lineEnd;
                    if (isShift) SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                    else { SpeakerNotesSelectionStart = SpeakerNotesCaretIndex; SpeakerNotesSelectionLength = 0; }
                    EnsureSpeakerNotesCaretVisible();
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.Up || key == Keys.Down)
                {
                    if (!LastNotesTextRect.IsEmpty)
                    {
                        using (Bitmap dummy = new Bitmap(1, 1))
                        using (Graphics g = Graphics.FromImage(dummy))
                        using (Font font = SlideFontManager.CreateFont("Segoe UI", LastNotesFontSize, FontStyle.Regular, GraphicsUnit.Point))
                        {
                            List<VisualTextLine> vLines = GetVisualWrappedLines(g, notes, font, Math.Max(40f, LastNotesTextRect.Width));
                            int curLine = 0;
                            int col = 0;
                            for (int i = 0; i < vLines.Count; i++)
                            {
                                if (SpeakerNotesCaretIndex <= vLines[i].StartCharIndex + vLines[i].Length)
                                {
                                    curLine = i;
                                    col = SpeakerNotesCaretIndex - vLines[i].StartCharIndex;
                                    break;
                                }
                            }
                            int targetLine = (key == Keys.Up) ? Math.Max(0, curLine - 1) : Math.Min(vLines.Count - 1, curLine + 1);
                            if (targetLine >= 0 && targetLine < vLines.Count)
                            {
                                SpeakerNotesCaretIndex = vLines[targetLine].StartCharIndex + Math.Min(col, vLines[targetLine].Length);
                                if (isShift) SpeakerNotesSelectionLength = SpeakerNotesCaretIndex - SpeakerNotesSelectionStart;
                                else { SpeakerNotesSelectionStart = SpeakerNotesCaretIndex; SpeakerNotesSelectionLength = 0; }
                                EnsureSpeakerNotesCaretVisible();
                                if (InvalidateCallback != null) InvalidateCallback();
                            }
                        }
                    }
                    return;
                }
                if (key == Keys.Delete)
                {
                    if (SpeakerNotesCaretIndex < notes.Length)
                    {
                        ActiveSlide.SpeakerNotes = notes.Remove(SpeakerNotesCaretIndex, 1);
                        EnsureSpeakerNotesCaretVisible();
                        if (InvalidateCallback != null) InvalidateCallback();
                    }
                    return;
                }
                return;
            }

            if (IsPresenting)
            {
                if (IsEndSlideShowScreen)
                {
                    if (key == Keys.Down || key == Keys.Left || key == Keys.PageUp || key == Keys.Back)
                    {
                        IsEndSlideShowScreen = false;
                        return;
                    }
                    else
                    {
                        IsEndSlideShowScreen = false;
                        StopPresenting();
                        return;
                    }
                }

                if (IsSlideSorterModalOpen)
                {
                    if (key == Keys.Escape) { IsSlideSorterModalOpen = false; return; }
                }
                if (IsSlideZoomActive)
                {
                    if (key == Keys.Escape) { IsSlideZoomActive = false; return; }
                }
                if (BlackScreenMode || WhiteScreenMode)
                {
                    if (key == Keys.Escape || key == Keys.B || key == Keys.W)
                    {
                        BlackScreenMode = false;
                        WhiteScreenMode = false;
                        return;
                    }
                }

                if (AnnotationPenMode || LaserPointerMode)
                {
                    if (key == Keys.Escape)
                    {
                        AnnotationPenMode = false;
                        LaserPointerMode = false;
                        Cursor.Show();
                        return;
                    }
                }

                if (key == Keys.Escape) { StopPresenting(); return; }
                
                // Điều hướng bàn phím: Lên/Phải/Space/Enter/PageDown/N -> TIẾN; Xuống/Trái/Back/PageUp -> LÙI
                if (key == Keys.Up || key == Keys.Right || key == Keys.Space || key == Keys.PageDown || key == Keys.Enter || key == Keys.Return || key == Keys.N)
                {
                    AdvancePresenterStep();
                }
                else if (key == Keys.Down || key == Keys.Left || key == Keys.PageUp || key == Keys.Back)
                {
                    PreviousPresenterStep();
                }
                else if (key == Keys.Home)
                {
                    ActiveSlideIndex = 0;
                    CurrentAnimationStep = 0;
                    TriggerTransition(-1, 0, false);
                }
                else if (key == Keys.End && Presentation != null && Presentation.Slides.Count > 0)
                {
                    ActiveSlideIndex = Presentation.Slides.Count - 1;
                    CurrentAnimationStep = 0;
                    TriggerTransition(-1, ActiveSlideIndex, false);
                }
                else if (key == Keys.L) LaserPointerMode = !LaserPointerMode;
                else if (key == Keys.P) AnnotationPenMode = !AnnotationPenMode;
                else if (key == Keys.H)
                {
                    AnnotationPenMode = true;
                    LaserPointerMode = false;
                    IsHighlighter = true;
                    AnnotationWidth = 14f;
                    AnnotationColor = Color.FromArgb(140, 255, 255, 0);
                }
                else if (key == Keys.A) { LaserPointerMode = false; AnnotationPenMode = false; }
                else if (key == Keys.E) { PenStrokes.Clear(); CurrentStroke.Clear(); }
                else if (key == Keys.B) BlackScreenMode = !BlackScreenMode;
                else if (key == Keys.W) WhiteScreenMode = !WhiteScreenMode;
                else if (key == Keys.F1) ShowPresentationHelp();
                return;
            }

            if (IsEditingTableCell && EditingTableShape != null)
            {
                if (key == Keys.Escape)
                {
                    EndTableInlineEditing();
                    return;
                }
                if (key == Keys.Tab)
                {
                    bool isShift = (Control.ModifierKeys & Keys.Shift) != 0;
                    int nextR = EditingTableRow;
                    int nextC = isShift ? EditingTableCol - 1 : EditingTableCol + 1;
                    if (nextC >= EditingTableShape.TableColumns)
                    {
                        nextC = 0;
                        nextR++;
                        if (nextR >= EditingTableShape.TableRows)
                        {
                            InsertTableRow(false);
                        }
                    }
                    else if (nextC < 0)
                    {
                        nextC = EditingTableShape.TableColumns - 1;
                        nextR = Math.Max(0, nextR - 1);
                    }
                    StartTableInlineEditing(EditingTableShape, nextR, nextC);
                    return;
                }
                if (key == Keys.Enter || key == Keys.Return)
                {
                    int nextR = EditingTableRow + 1;
                    if (nextR < EditingTableShape.TableRows)
                    {
                        StartTableInlineEditing(EditingTableShape, nextR, EditingTableCol);
                    }
                    else
                    {
                        EndTableInlineEditing();
                    }
                    return;
                }
                if (key == Keys.Left)
                {
                    TableCaretIndex = Math.Max(0, TableCaretIndex - 1);
                    return;
                }
                if (key == Keys.Right)
                {
                    TableCaretIndex = Math.Min(EditingTableCellBuffer.Length, TableCaretIndex + 1);
                    return;
                }
                if (key == Keys.Home)
                {
                    TableCaretIndex = 0;
                    return;
                }
                if (key == Keys.End)
                {
                    TableCaretIndex = EditingTableCellBuffer.Length;
                    return;
                }
                if (key == Keys.Delete)
                {
                    if (TableCaretIndex < EditingTableCellBuffer.Length)
                    {
                        EditingTableCellBuffer = EditingTableCellBuffer.Remove(TableCaretIndex, 1);
                    }
                    return;
                }
                return;
            }

            if (IsInlineEditing && EditingShape != null)
            {
                if (key == Keys.Escape)
                {
                    EndInlineEditing();
                    return;
                }

                if ((Control.ModifierKeys & Keys.Control) != 0)
                {
                    if (key == Keys.A)
                    {
                        TextSelectionStart = 0;
                        TextSelectionLength = EditingTextBuffer.Length;
                        CaretIndex = EditingTextBuffer.Length;
                        return;
                    }
                    if (key == Keys.C)
                    {
                        if (TextSelectionLength != 0)
                        {
                            int sStart = Math.Min(TextSelectionStart, TextSelectionStart + TextSelectionLength);
                            int sLen = Math.Abs(TextSelectionLength);
                            Clipboard.SetText(EditingTextBuffer.Substring(sStart, sLen));
                        }
                        return;
                    }
                    if (key == Keys.X)
                    {
                        if (TextSelectionLength != 0)
                        {
                            int sStart = Math.Min(TextSelectionStart, TextSelectionStart + TextSelectionLength);
                            int sLen = Math.Abs(TextSelectionLength);
                            Clipboard.SetText(EditingTextBuffer.Substring(sStart, sLen));
                            EditingTextBuffer = EditingTextBuffer.Remove(sStart, sLen);
                            CaretIndex = sStart;
                            TextSelectionStart = sStart;
                            TextSelectionLength = 0;
                            SyncEditingShapeText();
                        }
                        return;
                    }
                    if (key == Keys.V)
                    {
                        if (Clipboard.ContainsText())
                        {
                            string clip = Clipboard.GetText();
                            if (TextSelectionLength != 0)
                            {
                                int sStart = Math.Min(TextSelectionStart, TextSelectionStart + TextSelectionLength);
                                int sLen = Math.Abs(TextSelectionLength);
                                EditingTextBuffer = EditingTextBuffer.Remove(sStart, sLen);
                                CaretIndex = sStart;
                            }
                            EditingTextBuffer = EditingTextBuffer.Insert(CaretIndex, clip);
                            CaretIndex += clip.Length;
                            TextSelectionStart = CaretIndex;
                            TextSelectionLength = 0;
                            SyncEditingShapeText();
                        }
                        return;
                    }
                }

                if (TextSelectionLength != 0 && (key == Keys.Back || key == Keys.Delete))
                {
                    int sStart = Math.Min(TextSelectionStart, TextSelectionStart + TextSelectionLength);
                    int sLen = Math.Abs(TextSelectionLength);
                    EditingTextBuffer = EditingTextBuffer.Remove(sStart, sLen);
                    CaretIndex = sStart;
                    TextSelectionStart = sStart;
                    TextSelectionLength = 0;
                    SyncEditingShapeText();
                    return;
                }

                if (key == Keys.Left)
                {
                    TextSelectionLength = 0;
                    CaretIndex = Math.Max(0, CaretIndex - 1);
                    TextSelectionStart = CaretIndex;
                    return;
                }
                if (key == Keys.Right)
                {
                    TextSelectionLength = 0;
                    CaretIndex = Math.Min(EditingTextBuffer.Length, CaretIndex + 1);
                    TextSelectionStart = CaretIndex;
                    return;
                }
                if (key == Keys.Home)
                {
                    TextSelectionLength = 0;
                    CaretIndex = 0;
                    TextSelectionStart = CaretIndex;
                    return;
                }
                if (key == Keys.End)
                {
                    TextSelectionLength = 0;
                    CaretIndex = EditingTextBuffer.Length;
                    TextSelectionStart = CaretIndex;
                    return;
                }
                if (key == Keys.Delete)
                {
                    if (CaretIndex < EditingTextBuffer.Length)
                    {
                        EditingTextBuffer = EditingTextBuffer.Remove(CaretIndex, 1);
                        SyncEditingShapeText();
                    }
                    return;
                }
                return;
            }

            if (IsCropping)
            {
                if (key == Keys.Escape || key == Keys.Enter || key == Keys.Return)
                {
                    ConfirmCrop();
                    return;
                }
            }

            if (IsEditingShapePoints && EditingPointsShape != null)
            {
                if (key == Keys.Escape || key == Keys.Enter || key == Keys.Return)
                {
                    EndEditShapePoints();
                    return;
                }
                if (key == Keys.Delete || key == Keys.Back)
                {
                    if (SelectedEditPointIndex >= 0 && SelectedEditPointIndex < ShapeEditPoints.Count && ShapeEditPoints.Count > 3)
                    {
                        ShapeEditPoints.RemoveAt(SelectedEditPointIndex);
                        SelectedEditPointIndex = -1;
                        HoveredEditPointIndex = -1;
                        RebuildCustomPathFromEditPoints();
                        SaveUndoState();
                        if (InvalidateCallback != null) InvalidateCallback();
                        return;
                    }
                }
            }

            if ((key == Keys.Enter || key == Keys.Return) && IsDrawingShapeMode && IsScribbleMode)
            {
                if (ScribblePoints.Count >= 2)
                {
                    FinalizeScribbleShape(shouldClose: ScribblePoints.Count >= 3);
                }
                else
                {
                    CancelShapeDrawMode();
                }
                if (InvalidateCallback != null) InvalidateCallback();
                return;
            }

            if (key == Keys.Back && IsDrawingShapeMode && IsScribbleMode)
            {
                if (ScribblePoints.Count > 0)
                {
                    ScribblePoints.RemoveAt(ScribblePoints.Count - 1);
                    if (InvalidateCallback != null) InvalidateCallback();
                }
                return;
            }

            if (key == Keys.Escape)
            {
                if (IsColorPickingMode)
                {
                    IsColorPickingMode = false;
                    HasColorPickHover = false;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (IsDrawingShapeMode || IsDrawingActive)
                {
                    CancelShapeDrawMode();
                    return;
                }
                if (SelectedShapeIndex >= 0 || (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0))
                {
                    SelectedShapeIndex = -1;
                    if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                    EndInlineEditing();
                    return;
                }
            }

            if ((Control.ModifierKeys & Keys.Control) != 0)
            {
                if (key == Keys.Z)
                {
                    Undo();
                    if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.Y)
                {
                    Redo();
                    if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
                if (key == Keys.A && ActiveSlide != null && ActiveSlide.Shapes.Count > 0)
                {
                    SelectedShapeIndices.Clear();
                    for (int i = 0; i < ActiveSlide.Shapes.Count; i++)
                    {
                        if (ActiveSlide.Shapes[i].IsVisible) SelectedShapeIndices.Add(i);
                    }
                    SelectedShapeIndex = SelectedShapeIndices.Count > 0 ? SelectedShapeIndices[SelectedShapeIndices.Count - 1] : -1;
                    if (InvalidateCallback != null) InvalidateCallback();
                    return;
                }
            }

            if (key == Keys.F5) StartPresenting(true);
            else if ((key == Keys.Delete || key == Keys.Back) && (SelectedShapeIndex >= 0 || (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0) || SelectedShape != null) && ActiveSlide != null)
            {
                DeleteSelectedShapes();
            }
            else if (SelectedShape != null || (SelectedShapeIndices != null && SelectedShapeIndices.Count > 0))
            {
                float nudgeDx = 0, nudgeDy = 0;
                if (key == Keys.Left) nudgeDx = -5f;
                else if (key == Keys.Right) nudgeDx = 5f;
                else if (key == Keys.Up) nudgeDy = -5f;
                else if (key == Keys.Down) nudgeDy = 5f;

                if (nudgeDx != 0 || nudgeDy != 0)
                {
                    SaveUndoState();
                    if (SelectedShapeIndices != null && SelectedShapeIndices.Count > 1)
                    {
                        foreach (int idx in SelectedShapeIndices)
                        {
                            if (idx >= 0 && idx < ActiveSlide.Shapes.Count)
                            {
                                ActiveSlide.Shapes[idx].Transform.X += nudgeDx;
                                ActiveSlide.Shapes[idx].Transform.Y += nudgeDy;
                            }
                        }
                    }
                    else if (SelectedShape != null)
                    {
                        SelectedShape.Transform.X += nudgeDx;
                        SelectedShape.Transform.Y += nudgeDy;
                    }
                    if (ActiveSlide != null) ActiveSlide.IsThumbnailDirty = true;
                if (InvalidateCallback != null) InvalidateCallback();
                }
            }
            else
            {
                // Điều hướng chuyển slide ở chế độ soạn thảo khi không chọn shape nào
                if (key == Keys.Up || key == Keys.Right || key == Keys.PageDown)
                {
                    if (ActiveSlideIndex < Presentation.Slides.Count - 1)
                    {
                        int prevIdx = ActiveSlideIndex;
                        ActiveSlideIndex++;
                        SelectedShapeIndex = -1;
                        if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                        CanvasScrollX = 0;
                        CanvasScrollY = 0;
                        SmoothCanvasScrollX = 0f;
                        TargetCanvasScrollX = 0f;
                        SmoothCanvasScrollY = 0f;
                        TargetCanvasScrollY = 0f;
                        if (IsPresenting && ActiveSlide != null && ActiveSlide.Transition != TransitionType.None)
                        {
                            TriggerTransition(prevIdx, ActiveSlideIndex, false);
                        }
                    }
                }
                else if (key == Keys.Down || key == Keys.Left || key == Keys.PageUp)
                {
                    if (ActiveSlideIndex > 0)
                    {
                        int prevIdx = ActiveSlideIndex;
                        ActiveSlideIndex--;
                        SelectedShapeIndex = -1;
                        if (SelectedShapeIndices != null) SelectedShapeIndices.Clear();
                        CanvasScrollX = 0;
                        CanvasScrollY = 0;
                        SmoothCanvasScrollX = 0f;
                        TargetCanvasScrollX = 0f;
                        SmoothCanvasScrollY = 0f;
                        TargetCanvasScrollY = 0f;
                        if (IsPresenting && ActiveSlide != null && ActiveSlide.Transition != TransitionType.None)
                        {
                            TriggerTransition(prevIdx, ActiveSlideIndex, true);
                        }
                    }
                }
            }
        }

        private string GetWordBeforePos(string text, int pos)
        {
            if (string.IsNullOrEmpty(text) || pos <= 0 || pos > text.Length) return "";
            int start = pos - 1;
            while (start >= 0 && !VietnameseAutoCorrect.IsWordDelimiter(text[start]))
            {
                start--;
            }
            start++;
            if (start >= pos) return "";
            return text.Substring(start, pos - start);
        }

        public string GetCurrentWordBeforeCursor(out int wordStart)
        {
            if (IsEditingSpeakerNotes && ActiveSlide != null && !string.IsNullOrEmpty(ActiveSlide.SpeakerNotes))
            {
                return VietnameseWordPredictor.GetWordBeforePos(ActiveSlide.SpeakerNotes, SpeakerNotesCaretIndex, out wordStart);
            }
            if (IsInlineEditing && EditingShape != null && !string.IsNullOrEmpty(EditingTextBuffer))
            {
                return VietnameseWordPredictor.GetWordBeforePos(EditingTextBuffer, CaretIndex, out wordStart);
            }
            if (IsEditingTableCell && EditingTableShape != null && !string.IsNullOrEmpty(EditingTableCellBuffer))
            {
                return VietnameseWordPredictor.GetWordBeforePos(EditingTableCellBuffer, TableCaretIndex, out wordStart);
            }
            wordStart = -1;
            return "";
        }

        public void ReplaceWordAtCursor(string newWord)
        {
            if (IsEditingSpeakerNotes && ActiveSlide != null && !string.IsNullOrEmpty(ActiveSlide.SpeakerNotes))
            {
                int wordStart;
                string wordBefore = VietnameseWordPredictor.GetWordBeforePos(ActiveSlide.SpeakerNotes, SpeakerNotesCaretIndex, out wordStart);
                if (!string.IsNullOrEmpty(wordBefore) && wordStart >= 0)
                {
                    ActiveSlide.SpeakerNotes = ActiveSlide.SpeakerNotes.Remove(wordStart, wordBefore.Length).Insert(wordStart, newWord + " ");
                    SpeakerNotesCaretIndex = wordStart + newWord.Length + 1;
                    EnsureSpeakerNotesCaretVisible();
                }
            }
            else if (IsInlineEditing && EditingShape != null && !string.IsNullOrEmpty(EditingTextBuffer))
            {
                int wordStart;
                string wordBefore = VietnameseWordPredictor.GetWordBeforePos(EditingTextBuffer, CaretIndex, out wordStart);
                if (!string.IsNullOrEmpty(wordBefore) && wordStart >= 0)
                {
                    EditingTextBuffer = EditingTextBuffer.Remove(wordStart, wordBefore.Length).Insert(wordStart, newWord + " ");
                    CaretIndex = wordStart + newWord.Length + 1;
                    SyncEditingShapeText();
                }
            }
            else if (IsEditingTableCell && EditingTableShape != null && !string.IsNullOrEmpty(EditingTableCellBuffer))
            {
                int wordStart;
                string wordBefore = VietnameseWordPredictor.GetWordBeforePos(EditingTableCellBuffer, TableCaretIndex, out wordStart);
                if (!string.IsNullOrEmpty(wordBefore) && wordStart >= 0)
                {
                    EditingTableCellBuffer = EditingTableCellBuffer.Remove(wordStart, wordBefore.Length).Insert(wordStart, newWord + " ");
                    TableCaretIndex = wordStart + newWord.Length + 1;
                    int r = EditingTableRow;
                    int c = EditingTableCol;
                    if (r >= 0 && r < EditingTableShape.TableRows && c >= 0 && c < EditingTableShape.TableColumns)
                    {
                        while (EditingTableShape.TableData.Count <= r) EditingTableShape.TableData.Add(new List<string>());
                        while (EditingTableShape.TableData[r].Count <= c) EditingTableShape.TableData[r].Add("");
                        EditingTableShape.TableData[r][c] = EditingTableCellBuffer;
                    }
                }
            }
        }

        public void HandleKeyPress(char keyChar)
        {
            if (IsEditingSpeakerNotes && ActiveSlide != null)
            {
                string notes = ActiveSlide.SpeakerNotes ?? "";
                SpeakerNotesCaretIndex = Math.Max(0, Math.Min(notes.Length, SpeakerNotesCaretIndex));
                if (SpeakerNotesSelectionLength != 0 && (keyChar == '\b' || !char.IsControl(keyChar) || keyChar == '\r' || keyChar == '\n'))
                {
                    int sStart = Math.Max(0, Math.Min(notes.Length, Math.Min(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength)));
                    int sEnd = Math.Max(0, Math.Min(notes.Length, Math.Max(SpeakerNotesSelectionStart, SpeakerNotesSelectionStart + SpeakerNotesSelectionLength)));
                    notes = notes.Remove(sStart, sEnd - sStart);
                    SpeakerNotesCaretIndex = sStart;
                    SpeakerNotesSelectionStart = sStart;
                    SpeakerNotesSelectionLength = 0;
                    if (keyChar == '\b')
                    {
                        ActiveSlide.SpeakerNotes = notes;
                        EnsureSpeakerNotesCaretVisible();
                        return;
                    }
                }

                if (keyChar == '\b')
                {
                    if (notes.Length > 0 && SpeakerNotesCaretIndex > 0)
                    {
                        notes = notes.Remove(SpeakerNotesCaretIndex - 1, 1);
                        SpeakerNotesCaretIndex--;
                    }
                }
                else if (!char.IsControl(keyChar) || keyChar == '\r' || keyChar == '\n')
                {
                    if (VietnameseAutoCorrect.IsEnabled)
                    {
                        if (VietnameseAutoCorrect.IsWordDelimiter(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(notes, SpeakerNotesCaretIndex);
                            string correctedWord;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryCorrectWord(wordBefore, out correctedWord))
                            {
                                int wordStart = SpeakerNotesCaretIndex - wordBefore.Length;
                                notes = notes.Remove(wordStart, wordBefore.Length).Insert(wordStart, correctedWord);
                                SpeakerNotesCaretIndex = wordStart + correctedWord.Length;
                            }
                        }
                        else if (!char.IsControl(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(notes, SpeakerNotesCaretIndex);
                            int charsToRemove;
                            string textToInsert;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryProcessChar(wordBefore, keyChar, out charsToRemove, out textToInsert))
                            {
                                int removeStart = SpeakerNotesCaretIndex - charsToRemove;
                                notes = notes.Remove(removeStart, charsToRemove).Insert(removeStart, textToInsert);
                                SpeakerNotesCaretIndex = removeStart + textToInsert.Length;
                                ActiveSlide.SpeakerNotes = notes;
                                EnsureSpeakerNotesCaretVisible();
                                return;
                            }
                        }
                    }

                    string ins = (keyChar == '\r' || keyChar == '\n') ? "\n" : keyChar.ToString();
                    notes = notes.Insert(SpeakerNotesCaretIndex, ins);
                    SpeakerNotesCaretIndex += ins.Length;
                }
                ActiveSlide.SpeakerNotes = notes;
                EnsureSpeakerNotesCaretVisible();
                return;
            }

            if (IsEditingTableCell && EditingTableShape != null)
            {
                if (keyChar == '\b')
                {
                    if (EditingTableCellBuffer.Length > 0 && TableCaretIndex > 0)
                    {
                        EditingTableCellBuffer = EditingTableCellBuffer.Remove(TableCaretIndex - 1, 1);
                        TableCaretIndex--;
                    }
                }
                else if (!char.IsControl(keyChar) || keyChar == '\r' || keyChar == '\n')
                {
                    if (VietnameseAutoCorrect.IsEnabled)
                    {
                        if (VietnameseAutoCorrect.IsWordDelimiter(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(EditingTableCellBuffer, TableCaretIndex);
                            string correctedWord;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryCorrectWord(wordBefore, out correctedWord))
                            {
                                int wordStart = TableCaretIndex - wordBefore.Length;
                                EditingTableCellBuffer = EditingTableCellBuffer.Remove(wordStart, wordBefore.Length).Insert(wordStart, correctedWord);
                                TableCaretIndex = wordStart + correctedWord.Length;
                            }
                        }
                        else if (!char.IsControl(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(EditingTableCellBuffer, TableCaretIndex);
                            int charsToRemove;
                            string textToInsert;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryProcessChar(wordBefore, keyChar, out charsToRemove, out textToInsert))
                            {
                                int removeStart = TableCaretIndex - charsToRemove;
                                EditingTableCellBuffer = EditingTableCellBuffer.Remove(removeStart, charsToRemove).Insert(removeStart, textToInsert);
                                TableCaretIndex = removeStart + textToInsert.Length;
                                return;
                            }
                        }
                    }

                    string ins = (keyChar == '\r' || keyChar == '\n') ? "\n" : keyChar.ToString();
                    EditingTableCellBuffer = EditingTableCellBuffer.Insert(TableCaretIndex, ins);
                    TableCaretIndex += ins.Length;
                }
                return;
            }

            if (IsInlineEditing && EditingShape != null)
            {
                if (TextSelectionLength != 0 && (keyChar == '\b' || !char.IsControl(keyChar) || keyChar == '\r' || keyChar == '\n'))
                {
                    int sStart = Math.Min(TextSelectionStart, TextSelectionStart + TextSelectionLength);
                    int sLen = Math.Abs(TextSelectionLength);
                    EditingTextBuffer = EditingTextBuffer.Remove(sStart, sLen);
                    CaretIndex = sStart;
                    TextSelectionStart = sStart;
                    TextSelectionLength = 0;
                    if (keyChar == '\b')
                    {
                        SyncEditingShapeText();
                        return;
                    }
                }

                if (keyChar == '\b')
                {
                    if (EditingTextBuffer.Length > 0 && CaretIndex > 0)
                    {
                        EditingTextBuffer = EditingTextBuffer.Remove(CaretIndex - 1, 1);
                        CaretIndex--;
                    }
                }
                else if (!char.IsControl(keyChar) || keyChar == '\r' || keyChar == '\n')
                {
                    if (VietnameseAutoCorrect.IsEnabled)
                    {
                        if (VietnameseAutoCorrect.IsWordDelimiter(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(EditingTextBuffer, CaretIndex);
                            string correctedWord;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryCorrectWord(wordBefore, out correctedWord))
                            {
                                int wordStart = CaretIndex - wordBefore.Length;
                                EditingTextBuffer = EditingTextBuffer.Remove(wordStart, wordBefore.Length).Insert(wordStart, correctedWord);
                                CaretIndex = wordStart + correctedWord.Length;
                            }
                        }
                        else if (!char.IsControl(keyChar))
                        {
                            string wordBefore = GetWordBeforePos(EditingTextBuffer, CaretIndex);
                            int charsToRemove;
                            string textToInsert;
                            if (!string.IsNullOrEmpty(wordBefore) && VietnameseAutoCorrect.TryProcessChar(wordBefore, keyChar, out charsToRemove, out textToInsert))
                            {
                                int removeStart = CaretIndex - charsToRemove;
                                EditingTextBuffer = EditingTextBuffer.Remove(removeStart, charsToRemove).Insert(removeStart, textToInsert);
                                CaretIndex = removeStart + textToInsert.Length;
                                SyncEditingShapeText();
                                return;
                            }
                        }
                    }

                    string ins = (keyChar == '\r' || keyChar == '\n') ? "\n" : keyChar.ToString();
                    EditingTextBuffer = EditingTextBuffer.Insert(CaretIndex, ins);
                    CaretIndex += ins.Length;
                }
                SyncEditingShapeText();
            }
        }
        #endregion
    }
}
